{"command":"mkdir -p /workspace/src && cat > /workspace/src/tokenizer.rs <<'EOF'
//! CSS tokenizer implementing CSS Syntax Level 3.

use std::borrow::Cow;

#[derive(Clone, Debug, PartialEq)]
pub enum Token<'a> {
  Ident(Cow<'a, str>),
  AtKeyword(Cow<'a, str>),
  Hash(Cow<'a, str>),
  IDHash(Cow<'a, str>),
  QuotedString(Cow<'a, str>),
  UnquotedUrl(Cow<'a, str>),
  Delim(char),
  Number { has_sign: bool, value: f32, int_value: Option<i32> },
  Percentage { has_sign: bool, unit_value: f32, int_value: Option<i32> },
  Dimension { has_sign: bool, value: f32, int_value: Option<i32>, unit: Cow<'a, str> },
  WhiteSpace(&'a str),
  Comment(&'a str),
  Colon,
  Semicolon,
  Comma,
  IncludeMatch,
  DashMatch,
  PrefixMatch,
  SuffixMatch,
  SubstringMatch,
  CDO,
  CDC,
  Function(Cow<'a, str>),
  ParenthesisBlock,
  SquareBracketBlock,
  CurlyBracketBlock,
  BadUrl(Cow<'a, str>),
  BadString(Cow<'a, str>),
  CloseParenthesis,
  CloseSquareBracket,
  CloseCurlyBracket,
}

impl<'a> Token<'a> {
  pub fn is_parse_error(&self) -> bool {
    matches!(
      self,
      Token::BadUrl(_) | Token::BadString(_) | Token::CloseParenthesis | Token::CloseSquareBracket | Token::CloseCurlyBracket
    )
  }

  /// Debug formatting matching Rust's derived Debug for cssparser tokens.
  pub fn debug_string(&self) -> String {
    fn num(has_sign: bool, value: f32, int_value: Option<i32>) -> String {
      format!("has_sign: {}, value: {:?}, int_value: {:?}", has_sign, value, int_value)
    }
    match self {
      Token::Ident(s) => format!("Ident({:?})", s),
      Token::AtKeyword(s) => format!("AtKeyword({:?})", s),
      Token::Hash(s) => format!("Hash({:?})", s),
      Token::IDHash(s) => format!("IDHash({:?})", s),
      Token::QuotedString(s) => format!("QuotedString({:?})", s),
      Token::UnquotedUrl(s) => format!("UnquotedUrl({:?})", s),
      Token::Delim(c) => format!("Delim({:?})", c),
      Token::Number { has_sign, value, int_value } => format!("Number {{ {} }}", num(*has_sign, *value, *int_value)),
      Token::Percentage { has_sign, unit_value, int_value } => format!(
        "Percentage {{ has_sign: {}, unit_value: {:?}, int_value: {:?} }}",
        has_sign, unit_value, int_value
      ),
      Token::Dimension { has_sign, value, int_value, unit } => {
        format!("Dimension {{ {}, unit: {:?} }}", num(*has_sign, *value, *int_value), unit)
      }
      Token::WhiteSpace(s) => format!("WhiteSpace({:?})", s),
      Token::Comment(s) => format!("Comment({:?})", s),
      Token::Colon => "Colon".into(),
      Token::Semicolon => "Semicolon".into(),
      Token::Comma => "Comma".into(),
      Token::IncludeMatch => "IncludeMatch".into(),
      Token::DashMatch => "DashMatch".into(),
      Token::PrefixMatch => "PrefixMatch".into(),
      Token::SuffixMatch => "SuffixMatch".into(),
      Token::SubstringMatch => "SubstringMatch".into(),
      Token::CDO => "CDO".into(),
      Token::CDC => "CDC".into(),
      Token::Function(s) => format!("Function({:?})", s),
      Token::ParenthesisBlock => "ParenthesisBlock".into(),
      Token::SquareBracketBlock => "SquareBracketBlock".into(),
      Token::CurlyBracketBlock => "CurlyBracketBlock".into(),
      Token::BadUrl(s) => format!("BadUrl({:?})", s),
      Token::BadString(s) => format!("BadString({:?})", s),
      Token::CloseParenthesis => "CloseParenthesis".into(),
      Token::CloseSquareBracket => "CloseSquareBracket".into(),
      Token::CloseCurlyBracket => "CloseCurlyBracket".into(),
    }
  }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct SourceLocation {
  /// 0-based line number
  pub line: u32,
  /// 1-based column number (in UTF-16 code units)
  pub column: u32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SourcePosition(pub usize);

#[derive(Clone)]
pub struct Tokenizer<'a> {
  input: &'a str,
  position: usize,
  current_line_start_position: usize,
  current_line_number: u32,
  var_or_env_functions: SeenStatus,
  source_map_url: Option<&'a str>,
}

#[derive(Copy, Clone, PartialEq, Eq)]
enum SeenStatus {
  DontCare,
  LookingForThem,
  SeenAtLeastOne,
}

#[derive(Clone)]
pub struct TokenizerState {
  pub position: usize,
  pub current_line_start_position: usize,
  pub current_line_number: u32,
}

impl<'a> Tokenizer<'a> {
  pub fn new(input: &'a str) -> Self {
    Tokenizer {
      input,
      position: 0,
      current_line_start_position: 0,
      current_line_number: 0,
      var_or_env_functions: SeenStatus::DontCare,
      source_map_url: None,
    }
  }

  pub fn input(&self) -> &'a str {
    self.input
  }

  pub fn look_for_var_or_env_functions(&mut self) {
    self.var_or_env_functions = SeenStatus::LookingForThem;
  }

  pub fn seen_var_or_env_functions(&mut self) -> bool {
    let seen = self.var_or_env_functions == SeenStatus::SeenAtLeastOne;
    self.var_or_env_functions = SeenStatus::DontCare;
    seen
  }

  pub fn see_function(&mut self, name: &str) {
    if self.var_or_env_functions == SeenStatus::LookingForThem {
      if name.eq_ignore_ascii_case("var") || name.eq_ignore_ascii_case("env") {
        self.var_or_env_functions = SeenStatus::SeenAtLeastOne;
      }
    }
  }

  pub fn state(&self) -> TokenizerState {
    TokenizerState {
      position: self.position,
      current_line_start_position: self.current_line_start_position,
      current_line_number: self.current_line_number,
    }
  }

  pub fn reset(&mut self, state: &TokenizerState) {
    self.position = state.position;
    self.current_line_start_position = state.current_line_start_position;
    self.current_line_number = state.current_line_number;
  }

  pub fn position(&self) -> SourcePosition {
    SourcePosition(self.position)
  }

  pub fn slice_from(&self, start: SourcePosition) -> &'a str {
    &self.input[start.0..self.position]
  }

  pub fn slice(&self, start: SourcePosition, end: SourcePosition) -> &'a str {
    &self.input[start.0..end.0]
  }

  pub fn current_source_location(&self) -> SourceLocation {
    SourceLocation {
      line: self.current_line_number,
      column: (self.position - self.current_line_start_position + 1) as u32,
    }
  }

  pub fn current_source_map_url(&self) -> Option<&'a str> {
    self.source_map_url
  }

  #[inline]
  pub fn is_eof(&self) -> bool {
    !self.has_at_least(0)
  }

  #[inline]
  fn has_at_least(&self, n: usize) -> bool {
    self.position + n < self.input.len()
  }

  #[inline]
  fn next_byte(&self) -> Option<u8> {
    if self.is_eof() {
      None
    } else {
      Some(self.input.as_bytes()[self.position])
    }
  }

  #[inline]
  fn next_byte_unchecked(&self) -> u8 {
    self.byte_at(0)
  }

  #[inline]
  fn byte_at(&self, offset: usize) -> u8 {
    self.input.as_bytes()[self.position + offset]
  }

  #[inline]
  fn advance(&mut self, n: usize) {
    self.position += n;
  }

  #[inline]
  fn starts_with(&self, needle: &[u8]) -> bool {
    self.input.as_bytes()[self.position..].starts_with(needle)
  }

  #[inline]
  fn next_char(&self) -> char {
    self.input[self.position..].chars().next().unwrap()
  }

  // Advance over a newline sequence. Position is at the newline char.
  fn consume_newline(&mut self) {
    let byte = self.next_byte_unchecked();
    debug_assert!(byte == b'\r' || byte == b'\n' || byte == b'\x0C');
    self.position += 1;
    if byte == b'\r' && self.next_byte() == Some(b'\n') {
      self.position += 1;
    }
    self.current_line_start_position = self.position;
    self.current_line_number += 1;
  }

  #[inline]
  fn has_newline_at(&self, offset: usize) -> bool {
    self.position + offset < self.input.len() && matches!(self.byte_at(offset), b'\n' | b'\r' | b'\x0C')
  }

  fn consume_char(&mut self) -> char {
    let c = self.next_char();
    let len_utf8 = c.len_utf8();
    self.position += len_utf8;
    // Note that due to the special case for the 4-byte sequence
    // intro, we must use wrapping add here.
    self.current_line_start_position = self.current_line_start_position.wrapping_add(len_utf8 - c.len_utf16());
    c
  }

  // Consume 4-byte char: column count adjustments as in cssparser
  fn consume_known_byte(&mut self, byte: u8) {
    debug_assert!(self.next_byte_unchecked() == byte);
    self.position += 1;
    // Continuation bytes
    if byte & 0xF0 == 0xF0 {
      // This takes two UTF-16 code units. Adjust so column increments correctly.
      self.current_line_start_position = self.current_line_start_position.wrapping_sub(1);
    } else if byte & 0xC0 == 0x80 {
      // Continuation byte: doesn't count as a column.
      self.current_line_start_position = self.current_line_start_position.wrapping_add(1);
    }
  }

  pub fn skip_whitespace(&mut self) {
    while !self.is_eof() {
      match self.next_byte_unchecked() {
        b' ' | b'\t' => self.advance(1),
        b'\n' | b'\x0C' | b'\r' => self.consume_newline(),
        b'/' => {
          if self.starts_with(b"/*") {
            self.consume_comment();
          } else {
            return;
          }
        }
        _ => return,
      }
    }
  }

  pub fn skip_cdc_and_cdo(&mut self) {
    while !self.is_eof() {
      match self.next_byte_unchecked() {
        b' ' | b'\t' => self.advance(1),
        b'\n' | b'\x0C' | b'\r' => self.consume_newline(),
        b'/' => {
          if self.starts_with(b"/*") {
            self.consume_comment();
          } else {
            return;
          }
        }
        b'<' => {
          if self.starts_with(b"<!--") {
            self.advance(4)
          } else {
            return;
          }
        }
        b'-' => {
          if self.starts_with(b"-->") {
            self.advance(3)
          } else {
            return;
          }
        }
        _ => return,
      }
    }
  }

  pub fn next(&mut self) -> Result<Token<'a>, ()> {
    if self.is_eof() {
      return Err(());
    }
    let b = self.next_byte_unchecked();
    let token = match b {
      b' ' | b'\t' => self.consume_whitespace(false),
      b'\n' | b'\x0C' | b'\r' => self.consume_whitespace(true),
      b'"' => self.consume_string(false),
      b'#' => {
        self.advance(1);
        if self.is_ident_start() {
          Token::IDHash(self.consume_name())
        } else if !self.is_eof()
          && match self.next_byte_unchecked() {
            // Any other valid case here already resulted in IDHash.
            b'0'..=b'9' | b'-' => true,
            _ => false,
          }
        {
          Token::Hash(self.consume_name())
        } else {
          Token::Delim('#')
        }
      }
      b'$' => {
        if self.starts_with(b"$=") {
          self.advance(2);
          Token::SuffixMatch
        } else {
          self.advance(1);
          Token::Delim('$')
        }
      }
      b'\'' => self.consume_string(true),
      b'(' => {
        self.advance(1);
        Token::ParenthesisBlock
      }
      b')' => {
        self.advance(1);
        Token::CloseParenthesis
      }
      b'*' => {
        if self.starts_with(b"*=") {
          self.advance(2);
          Token::SubstringMatch
        } else {
          self.advance(1);
          Token::Delim('*')
        }
      }
      b'+' => {
        if (self.has_at_least(1) && matches!(self.byte_at(1), b'0'..=b'9'))
          || (self.has_at_least(2) && self.byte_at(1) == b'.' && matches!(self.byte_at(2), b'0'..=b'9'))
        {
          self.consume_numeric()
        } else {
          self.advance(1);
          Token::Delim('+')
        }
      }
      b',' => {
        self.advance(1);
        Token::Comma
      }
      b'-' => {
        if (self.has_at_least(1) && matches!(self.byte_at(1), b'0'..=b'9'))
          || (self.has_at_least(2) && self.byte_at(1) == b'.' && matches!(self.byte_at(2), b'0'..=b'9'))
        {
          self.consume_numeric()
        } else if self.starts_with(b"-->") {
          self.advance(3);
          Token::CDC
        } else if self.is_ident_start() {
          self.consume_ident_like()
        } else {
          self.advance(1);
          Token::Delim('-')
        }
      }
      b'.' => {
        if self.has_at_least(1) && matches!(self.byte_at(1), b'0'..=b'9') {
          self.consume_numeric()
        } else {
          self.advance(1);
          Token::Delim('.')
        }
      }
      b'/' => {
        if self.starts_with(b"/*") {
          Token::Comment(self.consume_comment())
        } else {
          self.advance(1);
          Token::Delim('/')
        }
      }
      b'0'..=b'9' => self.consume_numeric(),
      b':' => {
        self.advance(1);
        Token::Colon
      }
      b';' => {
        self.advance(1);
        Token::Semicolon
      }
      b'<' => {
        if self.starts_with(b"<!--") {
          self.advance(4);
          Token::CDO
        } else {
          self.advance(1);
          Token::Delim('<')
        }
      }
      b'@' => {
        self.advance(1);
        if self.is_ident_start() {
          Token::AtKeyword(self.consume_name())
        } else {
          Token::Delim('@')
        }
      }
      b'a'..=b'z' | b'A'..=b'Z' | b'_' | b'\0' => self.consume_ident_like(),
      b'[' => {
        self.advance(1);
        Token::SquareBracketBlock
      }
      b'\\' => {
        if !self.has_newline_at(1) {
          self.consume_ident_like()
        } else {
          self.advance(1);
          Token::Delim('\\')
        }
      }
      b']' => {
        self.advance(1);
        Token::CloseSquareBracket
      }
      b'^' => {
        if self.starts_with(b"^=") {
          self.advance(2);
          Token::PrefixMatch
        } else {
          self.advance(1);
          Token::Delim('^')
        }
      }
      b'{' => {
        self.advance(1);
        Token::CurlyBracketBlock
      }
      b'|' => {
        if self.starts_with(b"|=") {
          self.advance(2);
          Token::DashMatch
        } else {
          self.advance(1);
          Token::Delim('|')
        }
      }
      b'}' => {
        self.advance(1);
        Token::CloseCurlyBracket
      }
      b'~' => {
        if self.starts_with(b"~=") {
          self.advance(2);
          Token::IncludeMatch
        } else {
          self.advance(1);
          Token::Delim('~')
        }
      }
      _ => {
        if !b.is_ascii() {
          self.consume_ident_like()
        } else {
          self.advance(1);
          Token::Delim(b as char)
        }
      }
    };
    Ok(token)
  }

  fn consume_whitespace(&mut self, newline: bool) -> Token<'a> {
    let start_position = self.position;
    if newline {
      self.consume_newline();
    } else {
      self.advance(1);
    }
    while !self.is_eof() {
      let b = self.next_byte_unchecked();
      match b {
        b' ' | b'\t' => self.advance(1),
        b'\n' | b'\x0C' | b'\r' => self.consume_newline(),
        _ => break,
      }
    }
    Token::WhiteSpace(&self.input[start_position..self.position])
  }

  // Assumes the input starts with "/*"
  fn consume_comment(&mut self) -> &'a str {
    self.advance(2); // consume "/*"
    let start_position = self.position;
    while !self.is_eof() {
      match self.next_byte_unchecked() {
        b'*' => {
          let end_position = self.position;
          self.advance(1);
          if self.next_byte() == Some(b'/') {
            self.advance(1);
            let contents = &self.input[start_position..end_position];
            self.check_for_source_map(contents);
            return contents;
          }
        }
        b'\n' | b'\x0C' | b'\r' => self.consume_newline(),
        b'\x80'..=b'\xBF' => self.consume_continuation_byte(),
        b'\xF0'..=b'\xFF' => self.consume_4byte_intro(),
        _ => self.advance(1),
      }
    }
    let contents = &self.input[start_position..self.position];
    self.check_for_source_map(contents);
    contents
  }

  fn check_for_source_map(&mut self, contents: &'a str) {
    let directive = "# sourceMappingURL=";
    let directive_old = "@ sourceMappingURL=";
    if contents.starts_with(directive) || contents.starts_with(directive_old) {
      let contents = &contents[directive.len()..];
      self.source_map_url = contents.split(|c| c == ' ' || c == '\t' || c == '\x0C' || c == '\r' || c == '\n').next();
    }
  }

  #[inline]
  fn consume_continuation_byte(&mut self) {
    debug_assert!(self.next_byte_unchecked() & 0xC0 == 0x80);
    // Continuation bytes contribute to column overcount. Note
    // that due to the special case for the 4-byte sequence intro,
    // we must use wrapping add here.
    self.current_line_start_position = self.current_line_start_position.wrapping_add(1);
    self.position += 1;
  }

  #[inline]
  fn consume_4byte_intro(&mut self) {
    debug_assert!(self.next_byte_unchecked() & 0xF0 == 0xF0);
    // This takes two UTF-16 characters to represent, so we
    // actually have an undercount.
    self.current_line_start_position = self.current_line_start_position.wrapping_sub(1);
    self.position += 1;
  }

  fn consume_string(&mut self, single_quote: bool) -> Token<'a> {
    match self.consume_quoted_string(single_quote) {
      Ok(value) => Token::QuotedString(value),
      Err(value) => Token::BadString(value),
    }
  }

  /// Return `Err(())` on syntax error (ie. unescaped newline)
  fn consume_quoted_string(&mut self, single_quote: bool) -> Result<Cow<'a, str>, Cow<'a, str>> {
    self.advance(1); // Skip the initial quote
    let start_pos = self.position;
    let mut string_bytes;
    loop {
      if self.is_eof() {
        return Ok(Cow::Borrowed(&self.input[start_pos..self.position]));
      }
      match self.next_byte_unchecked() {
        b'"' if !single_quote => {
          let value = &self.input[start_pos..self.position];
          self.advance(1);
          return Ok(Cow::Borrowed(value));
        }
        b'\'' if single_quote => {
          let value = &self.input[start_pos..self.position];
          self.advance(1);
          return Ok(Cow::Borrowed(value));
        }
        // The CSS spec says NULL bytes ('\0') should be turned into replacement characters
        b'\\' | b'\0' => {
          string_bytes = self.input[start_pos..self.position].as_bytes().to_vec();
          break;
        }
        b'\n' | b'\r' | b'\x0C' => {
          return Err(Cow::Borrowed(&self.input[start_pos..self.position]));
        }
        b'\x80'..=b'\xBF' => self.consume_continuation_byte(),
        b'\xF0'..=b'\xFF' => self.consume_4byte_intro(),
        _ => {
          self.advance(1);
        }
      }
    }

    while !self.is_eof() {
      let b = self.next_byte_unchecked();
      match b {
        b'\n' | b'\r' | b'\x0C' => {
          return Err(Cow::Owned(String::from_utf8(string_bytes).unwrap()));
        }
        b'"' if !single_quote => {
          self.advance(1);
          break;
        }
        b'\'' if single_quote => {
          self.advance(1);
          break;
        }
        b'\\' => {
          self.advance(1);
          if !self.is_eof() {
            match self.next_byte_unchecked() {
              // Escaped newline
              b'\n' | b'\x0C' | b'\r' => {
                self.consume_newline();
              }
              // This pushes one well-formed code point
              _ => consume_escape_and_write(self, &mut string_bytes),
            }
          }
          // else: escaped EOF, do nothing.
          continue;
        }
        b'\0' => {
          self.advance(1);
          string_bytes.extend("\u{FFFD}".as_bytes());
          continue;
        }
        b'\x80'..=b'\xBF' => self.consume_continuation_byte(),
        b'\xF0'..=b'\xFF' => self.consume_4byte_intro(),
        _ => {
          self.advance(1);
        }
      }
      string_bytes.push(b);
    }
    Ok(Cow::Owned(String::from_utf8(string_bytes).unwrap()))
  }

  fn is_ident_start(&self) -> bool {
    !self.is_eof()
      && match self.next_byte_unchecked() {
        b'a'..=b'z' | b'A'..=b'Z' | b'_' | b'\0' => true,
        b'-' => {
          self.has_at_least(1)
            && match self.byte_at(1) {
              b'a'..=b'z' | b'A'..=b'Z' | b'-' | b'_' | b'\0' => true,
              b'\\' => !self.has_newline_at(1),
              b => !b.is_ascii(),
            }
        }
        b'\\' => !self.has_newline_at(1),
        b => !b.is_ascii(),
      }
  }

  fn consume_ident_like(&mut self) -> Token<'a> {
    let value = self.consume_name();
    if !self.is_eof() && self.next_byte_unchecked() == b'(' {
      self.advance(1);
      if value.eq_ignore_ascii_case("url") {
        self.consume_unquoted_url().unwrap_or(Token::Function(value))
      } else {
        self.see_function(&value);
        Token::Function(value)
      }
    } else {
      Token::Ident(value)
    }
  }

  fn consume_name(&mut self) -> Cow<'a, str> {
    let start_pos = self.position;
    let mut value_bytes;
    loop {
      if self.is_eof() {
        return Cow::Borrowed(&self.input[start_pos..self.position]);
      }
      match self.next_byte_unchecked() {
        b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'_' | b'-' => self.advance(1),
        b'\\' | b'\0' => {
          value_bytes = self.input[start_pos..self.position].as_bytes().to_vec();
          break;
        }
        b'\x80'..=b'\xBF' => self.consume_continuation_byte(),
        b'\xC0'..=b'\xEF' => self.advance(1),
        b'\xF0'..=b'\xFF' => self.consume_4byte_intro(),
        _b => {
          return Cow::Borrowed(&self.input[start_pos..self.position]);
        }
      }
    }

    while !self.is_eof() {
      let b = self.next_byte_unchecked();
      match b {
        b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'_' | b'-' => {
          self.advance(1);
          value_bytes.push(b)
        }
        b'\\' => {
          if self.has_newline_at(1) {
            break;
          }
          self.advance(1);
          consume_escape_and_write(self, &mut value_bytes)
        }
        b'\0' => {
          self.advance(1);
          value_bytes.extend("\u{FFFD}".as_bytes());
        }
        b'\x80'..=b'\xBF' => {
          self.consume_continuation_byte();
          value_bytes.push(b)
        }
        b'\xC0'..=b'\xEF' => {
          self.advance(1);
          value_bytes.push(b)
        }
        b'\xF0'..=b'\xFF' => {
          self.consume_4byte_intro();
          value_bytes.push(b)
        }
        _ => {
          break;
        }
      }
    }
    Cow::Owned(String::from_utf8(value_bytes).unwrap())
  }

  fn byte_to_hex_digit(b: u8) -> Option<u32> {
    (b as char).to_digit(16)
  }

  fn byte_to_decimal_digit(b: u8) -> Option<u32> {
    (b as char).to_digit(10)
  }

  fn consume_numeric(&mut self) -> Token<'a> {
    // Parse [+-]?\d*(\.\d+)?([eE][+-]?\d+)?
    // But this is always called so that there is at least one digit in \d*(\.\d+)?

    // Do all the math in f64 so that large numbers overflow to +/-inf
    // and i32::{MIN, MAX} are within range.

    let (has_sign, sign) = match self.next_byte_unchecked() {
      b'-' => (true, -1.),
      b'+' => (true, 1.),
      _ => (false, 1.),
    };
    if has_sign {
      self.advance(1);
    }

    let mut integral_part: f64 = 0.;
    while let Some(digit) = self.next_byte().and_then(Self::byte_to_decimal_digit) {
      integral_part = integral_part * 10. + digit as f64;
      self.advance(1);
      if self.is_eof() {
        break;
      }
    }

    let mut is_integer = true;

    let mut fractional_part: f64 = 0.;
    if self.has_at_least(1) && self.next_byte_unchecked() == b'.' && matches!(self.byte_at(1), b'0'..=b'9') {
      is_integer = false;
      self.advance(1); // Consume '.'
      let mut factor = 0.1;
      while let Some(digit) = self.next_byte().and_then(Self::byte_to_decimal_digit) {
        fractional_part += digit as f64 * factor;
        factor *= 0.1;
        self.advance(1);
        if self.is_eof() {
          break;
        }
      }
    }

    let mut value = sign * (integral_part + fractional_part);

    if self.has_at_least(1)
      && matches!(self.next_byte_unchecked(), b'e' | b'E')
      && (matches!(self.byte_at(1), b'0'..=b'9')
        || (self.has_at_least(2) && matches!(self.byte_at(1), b'+' | b'-') && matches!(self.byte_at(2), b'0'..=b'9')))
    {
      is_integer = false;
      self.advance(1);
      let (has_sign, sign) = match self.next_byte_unchecked() {
        b'-' => (true, -1.),
        b'+' => (true, 1.),
        _ => (false, 1.),
      };
      if has_sign {
        self.advance(1);
      }
      let mut exponent: f64 = 0.;
      while let Some(digit) = self.next_byte().and_then(Self::byte_to_decimal_digit) {
        exponent = exponent * 10. + digit as f64;
        self.advance(1);
        if self.is_eof() {
          break;
        }
      }
      value *= f64::powf(10., sign * exponent);
    }

    let int_value = if is_integer {
      Some(if value >= i32::MAX as f64 {
        i32::MAX
      } else if value <= i32::MIN as f64 {
        i32::MIN
      } else {
        value as i32
      })
    } else {
      None
    };

    if !self.is_eof() && self.next_byte_unchecked() == b'%' {
      self.advance(1);
      return Token::Percentage {
        unit_value: (value / 100.) as f32,
        int_value,
        has_sign,
      };
    }
    let value = value as f32;
    if self.is_ident_start() {
      let unit = self.consume_name();
      Token::Dimension {
        value,
        int_value,
        has_sign,
        unit,
      }
    } else {
      Token::Number {
        value,
        int_value,
        has_sign,
      }
    }
  }

  fn consume_unquoted_url(&mut self) -> Result<Token<'a>, ()> {
    // This is only called after "url(", so the current position is a code point boundary.
    let start_position = self.position;
    let from_start = &self.input[self.position..];
    let mut newlines = 0;
    let mut last_newline = 0;
    let mut found_printable_char = false;
    let mut iter = from_start.bytes().enumerate();
    loop {
      let (offset, b) = match iter.next() {
        Some(item) => item,
        None => {
          self.position = self.input.len();
          break;
        }
      };
      match b {
        b' ' | b'\t' => {}
        b'\n' | b'\x0C' => {
          newlines += 1;
          last_newline = offset;
        }
        b'\r' => {
          if from_start.as_bytes().get(offset + 1) != Some(&b'\n') {
            newlines += 1;
            last_newline = offset;
          }
        }
        b'"' | b'\'' => return Err(()), // Do not advance
        b')' => {
          // Don't use advance, because we may be skipping
          // newlines here, and we want to avoid the assert.
          self.position += offset + 1;
          break;
        }
        _ => {
          // Don't use advance, because we may be skipping
          // newlines here, and we want to avoid the assert.
          self.position += offset;
          found_printable_char = true;
          break;
        }
      }
    }

    if newlines > 0 {
      self.current_line_number += newlines;
      // No need for wrapping_add here, because there's no possible
      // way to wrap.
      self.current_line_start_position = start_position + last_newline + 1;
    }

    if found_printable_char {
      // This function only consumed ASCII (whitespace) bytes,
      // so the current position is a code point boundary.
      return Ok(self.consume_unquoted_url_internal());
    } else {
      return Ok(Token::UnquotedUrl(Cow::Borrowed("")));
    }
  }

  fn consume_unquoted_url_internal(&mut self) -> Token<'a> {
    // This function is only called with start_pos at a code point boundary.
    let start_pos = self.position;
    let mut string_bytes: Vec<u8>;
    loop {
      if self.is_eof() {
        return Token::UnquotedUrl(Cow::Borrowed(&self.input[start_pos..self.position]));
      }
      match self.next_byte_unchecked() {
        b' ' | b'\t' | b'\n' | b'\r' | b'\x0C' => {
          let value = &self.input[start_pos..self.position];
          return self.consume_url_end(start_pos, Cow::Borrowed(value));
        }
        b')' => {
          let value = &self.input[start_pos..self.position];
          self.advance(1);
          return Token::UnquotedUrl(Cow::Borrowed(value));
        }
        b'\x01'..=b'\x08' | b'\x0B' | b'\x0E'..=b'\x1F' | b'\x7F' // non-printable
        | b'"' | b'\'' | b'(' => {
          self.advance(1);
          return self.consume_bad_url(start_pos);
        }
        b'\\' | b'\0' => {
          // * The tokenizer's input is UTF-8 since it's `&str`.
          // * start_pos is at a code point boundary
          // * so is the current position (which is before '\\' or '\0')
          //
          // So `string_bytes` is well-formed UTF-8.
          string_bytes = self.input[start_pos..self.position].as_bytes().to_vec();
          break;
        }
        b'\x80'..=b'\xBF' => self.consume_continuation_byte(),
        b'\xF0'..=b'\xFF' => self.consume_4byte_intro(),
        _ => {
          // ASCII or other leading byte.
          self.advance(1);
        }
      }
    }
    while !self.is_eof() {
      let b = self.next_byte_unchecked();
      match b {
        b' ' | b'\t' | b'\n' | b'\r' | b'\x0C' => {
          // string_bytes is well-formed UTF-8, see other comments.
          let string = String::from_utf8(string_bytes).unwrap();
          return self.consume_url_end(start_pos, Cow::Owned(string));
        }
        b')' => {
          self.advance(1);
          break;
        }
        b'\x01'..=b'\x08' | b'\x0B' | b'\x0E'..=b'\x1F' | b'\x7F' // non-printable
        | b'"' | b'\'' | b'(' => {
          self.advance(1);
          return self.consume_bad_url(start_pos);
        }
        b'\\' => {
          self.advance(1);
          if self.has_newline_at(0) {
            return self.consume_bad_url(start_pos);
          }

          // This pushes one well-formed code point to string_bytes
          consume_escape_and_write(self, &mut string_bytes)
        }
        b'\0' => {
          self.advance(1);
          string_bytes.extend("\u{FFFD}".as_bytes());
        }
        b'\x80'..=b'\xBF' => {
          // We' consumed one byte of a 2-byte sequence.
          self.consume_continuation_byte();
          string_bytes.push(b);
        }
        b'\xF0'..=b'\xFF' => {
          self.consume_4byte_intro();
          string_bytes.push(b);
        }
        // If this byte is part of a multi-byte code point,
        // we'll end up copying the whole code point before this loop does something else.
        b => {
          self.advance(1);
          string_bytes.push(b)
        }
      }
    }
    // string_bytes is well-formed UTF-8, see other comments.
    Token::UnquotedUrl(Cow::Owned(String::from_utf8(string_bytes).unwrap()))
  }

  fn consume_url_end(&mut self, start_pos: usize, string: Cow<'a, str>) -> Token<'a> {
    while !self.is_eof() {
      match self.next_byte_unchecked() {
        b')' => {
          self.advance(1);
          break;
        }
        b' ' | b'\t' => self.advance(1),
        b'\n' | b'\x0C' | b'\r' => {
          self.consume_newline();
        }
        b => {
          self.consume_known_byte(b);
          return self.consume_bad_url(start_pos);
        }
      }
    }
    Token::UnquotedUrl(string)
  }

  fn consume_bad_url(&mut self, start_pos: usize) -> Token<'a> {
    // Consume up to the closing )
    while !self.is_eof() {
      match self.next_byte_unchecked() {
        b')' => {
          let contents = &self.input[start_pos..self.position];
          self.advance(1);
          return Token::BadUrl(Cow::Borrowed(contents));
        }
        b'\\' => {
          self.advance(1);
          if matches!(self.next_byte(), Some(b')') | Some(b'\\')) {
            self.advance(1); // Skip an escaped ')' or '\'
          }
        }
        b'\n' | b'\x0C' | b'\r' => {
          self.consume_newline();
        }
        b => {
          self.consume_known_byte(b);
        }
      }
    }
    Token::BadUrl(Cow::Borrowed(&self.input[start_pos..self.position]))
  }

  // (Comments or whitespace at the start of a block are preserved by the parser.)
}

// Assumes that the U+005C REVERSE SOLIDUS (\) has already been consumed
// and that the next input character has already been verified
// to not be a newline.
fn consume_escape(tokenizer: &mut Tokenizer) -> char {
  if tokenizer.is_eof() {
    return '\u{FFFD}'; // Unicode replacement character
  }
  match tokenizer.next_byte_unchecked() {
    b'0'..=b'9' | b'A'..=b'F' | b'a'..=b'f' => {
      let (c, _) = consume_hex_digits(tokenizer);
      if !tokenizer.is_eof() {
        match tokenizer.next_byte_unchecked() {
          b' ' | b'\t' => tokenizer.advance(1),
          b'\n' | b'\x0C' | b'\r' => tokenizer.consume_newline(),
          _ => {}
        }
      }
      static REPLACEMENT_CHAR: char = '\u{FFFD}';
      if c != 0 {
        let c = char::from_u32(c);
        c.unwrap_or(REPLACEMENT_CHAR)
      } else {
        REPLACEMENT_CHAR
      }
    }
    b'\0' => {
      tokenizer.advance(1);
      '\u{FFFD}'
    }
    _ => tokenizer.consume_char(),
  }
}

fn consume_hex_digits(tokenizer: &mut Tokenizer) -> (u32, u32) {
  let mut value = 0;
  let mut digits = 0;
  while digits < 6 && !tokenizer.is_eof() {
    match Tokenizer::byte_to_hex_digit(tokenizer.next_byte_unchecked()) {
      Some(digit) => {
        value = value * 16 + digit;
        digits += 1;
        tokenizer.advance(1);
      }
      None => break,
    }
  }
  (value, digits)
}

// Same constraints as consume_escape except it writes into `bytes` the result
// instead of returning it.
fn consume_escape_and_write(tokenizer: &mut Tokenizer, bytes: &mut Vec<u8>) {
  bytes.extend(consume_escape(tokenizer).encode_utf8(&mut [0; 4]).as_bytes())
}
