      t => Err(start_location.new_basic_unexpected_token_error(t)),
    }
  }

  pub fn expect_colon(&mut self) -> Result<(), BasicParseError<'i>> {
    let start_location = self.current_source_location();
    match self.next()? {
      Token::Colon => Ok(()),
      t => Err(start_location.new_basic_unexpected_token_error(t)),
