            self.parse_nested_block(|input| input.expect_no_error_token().map_err(|e| Into::<ParseError<()>>::into(e)))
              .map_err(ParseError::<()>::basic)?
          }
        }
        Err(_) => return Ok(()),
      }
    }
  }
