pub type PrintResult = Result<(), PrinterError>;

#[derive(Clone, Copy, Debug, Default)]
pub struct PrinterOptions {
  pub minify: bool,
}

pub struct Printer<'a> {
  dest: &'a mut String,
  pub minify: bool,
  indent: u8,
  pub targets: Targets,
  pub vendor_prefix: u8,
  pub in_calc: bool,
  pub css_module: Option<&'a mut crate::css_modules::CssModule>,
