    }
    Ok(())
  }

  pub fn indent(&mut self) {
    self.indent += 2;
  }

  pub fn dedent(&mut self) {
    self.indent -= 2;
  }

  pub fn indent_by(&mut self, amt: u8) {
    self.indent += amt;
  }

  pub fn dedent_by(&mut self, amt: u8) {
    self.indent -= amt;
  }

  pub fn is_nested(&self) -> bool {
    self.indent > 2
  }

  pub fn add_mapping(&mut self, loc: crate::rules::Location) {
    if let Some(sm) = &mut self.source_map {
      sm.add_mapping(self.line, self.col, loc);
    }
  }

  pub fn len(&self) -> usize {
    self.dest.len()
  }

  pub fn context(&self) -> Option<&crate::selector::SelectorList> {
    self.context.map(|p| unsafe { &*p })
  }

  pub fn with_context<T, F: FnOnce(&mut Printer<'a>) -> Result<T, PrinterError>>(
    &mut self,
    selectors: &crate::selector::SelectorList,
    f: F,
  ) -> Result<T, PrinterError> {
    let parent = self.context.take();
    self.context = Some(selectors as *const _);
    let res = f(self);
    self.context = parent;
    res
  }

  pub fn with_cleared_context<T, F: FnOnce(&mut Printer<'a>) -> Result<T, PrinterError>>(
    &mut self,
    f: F,
  ) -> Result<T, PrinterError> {
    let parent = self.context.take();
    let res = f(self);
    self.context = parent;
    res
  }
}

impl<'a> std::fmt::Write for Printer<'a> {
  fn write_str(&mut self, s: &str) -> std::fmt::Result {
    Printer::write_str(self, s).map_err(|_| std::fmt::Error)
  }
}

/// Trait for things that can be serialized to CSS.
pub trait ToCss {
  fn to_css(&self, dest: &mut Printer) -> PrintResult;

  fn to_css_string(&self, minify: bool, targets: Targets) -> Result<String, PrinterError> {
    let mut s = String::new();
    let mut printer = Printer::new(&mut s, minify, targets);
    self.to_css(&mut printer)?;
    Ok(s)
  }
}

impl<'a, T: ToCss> ToCss for &'a T {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    (*self).to_css(dest)
  }
}

/// Serialize an identifier according to the CSS spec (cssparser semantics).
pub fn serialize_identifier(value: &str, dest: &mut Printer) -> PrintResult {
  let mut s = String::new();
  serialize_identifier_to_string(value, &mut s);
  dest.write_str(&s)
}

pub fn serialize_identifier_to_string(mut value: &str, dest: &mut String) {
  if value.is_empty() {
    return;
  }
  if value.starts_with("--") {
    dest.push_str("--");
    serialize_name(&value[2..], dest);
    return;
  }
  if value == "-" {
    dest.push_str("\\-");
    return;
  }
  if value.as_bytes()[0] == b'-' {
    dest.push('-');
    value = &value[1..];
  }
  if let Some(digit) = value.bytes().next().filter(|b| b.is_ascii_digit()) {
    hex_escape(digit, dest);
    value = &value[1..];
  }
  serialize_name(value, dest);
}

pub fn serialize_name(value: &str, dest: &mut String) {
  let mut chunk_start = 0;
  for (i, b) in value.bytes().enumerate() {
    let escaped = match b {
      b'0'..=b'9' | b'A'..=b'Z' | b'a'..=b'z' | b'_' | b'-' => continue,
      _ if !b.is_ascii() => continue,
      b'\0' => Some("\u{FFFD}"),
      _ => None,
    };
    dest.push_str(&value[chunk_start..i]);
    if let Some(escaped) = escaped {
      dest.push_str(escaped);
    } else if (b >= b'\x01' && b <= b'\x1F') || b == b'\x7F' {
      hex_escape(b, dest);
    } else {
      char_escape(b, dest);
    }
    chunk_start = i + 1;
  }
  dest.push_str(&value[chunk_start..]);
}

fn hex_escape(ascii_byte: u8, dest: &mut String) {
  static HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";
  let b3;
  let b4;
  let bytes = if ascii_byte > 0x0F {
    let high = (ascii_byte >> 4) as usize;
    let low = (ascii_byte & 0x0F) as usize;
    b4 = [b'\\', HEX_DIGITS[high], HEX_DIGITS[low], b' '];
    &b4[..]
  } else {
    b3 = [b'\\', HEX_DIGITS[ascii_byte as usize], b' '];
    &b3[..]
  };
  dest.push_str(std::str::from_utf8(bytes).unwrap());
}

fn char_escape(ascii_byte: u8, dest: &mut String) {
  let bytes = [b'\\', ascii_byte];
  dest.push_str(std::str::from_utf8(&bytes).unwrap());
}

/// Serialize a string with double quotes (cssparser semantics).
pub fn serialize_string(value: &str, dest: &mut Printer) -> PrintResult {
  let mut s = String::new();
  serialize_string_to_string(value, &mut s);
  dest.write_str(&s)
}

pub fn serialize_string_to_string(value: &str, dest: &mut String) {
  dest.push('"');
  let mut chunk_start = 0;
  for (i, b) in value.bytes().enumerate() {
    let escaped = match b {
      b'"' => Some("\\\""),
      b'\\' => Some("\\\\"),
      b'\0' => Some("\u{FFFD}"),
      b'\x01'..=b'\x1F' | b'\x7F' => None,
      _ => continue,
    };
    dest.push_str(&value[chunk_start..i]);
    match escaped {
      Some(x) => dest.push_str(x),
      None => hex_escape(b, dest),
    }
    chunk_start = i + 1;
  }
  dest.push_str(&value[chunk_start..]);
  dest.push('"');
}

/// Serialize an unquoted url
pub fn serialize_unquoted_url(value: &str, dest: &mut String) {
  let mut chunk_start = 0;
  for (i, b) in value.bytes().enumerate() {
    let hex = match b {
      b'\0'..=b' ' | b'\x7F' => true,
      b'(' | b')' | b'"' | b'\'' | b'\\' => false,
      _ => continue,
    };
    dest.push_str(&value[chunk_start..i]);
    if hex {
      hex_escape(b, dest);
    } else {
      char_escape(b, dest);
    }
    chunk_start = i + 1;
  }
  dest.push_str(&value[chunk_start..]);
}

/// Serialize a dimension unit (handles the e-notation ambiguity).
pub fn serialize_dimension_unit(unit: &str, dest: &mut String) {
  if unit == "e" || unit == "E" || unit.starts_with("e-") || unit.starts_with("E-") {
    dest.push_str("\\65 ");
    serialize_name(&unit[1..], dest);
  } else {
    serialize_identifier_to_string(unit, dest);
  }
}
