/// A location within a source file.
#[derive(Clone, Debug, PartialEq)]
pub struct ErrorLocation {
  pub filename: String,
  pub line: u32,
  pub column: u32,
}

impl fmt::Display for ErrorLocation {
  fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    write!(f, "{}:{}:{}", self.filename, self.line, self.column)
  }
}

/// An error with a location.
#[derive(Clone, Debug, PartialEq)]
pub struct Error<T> {
  pub kind: T,
  pub loc: Option<ErrorLocation>,
}

impl<T: fmt::Display> fmt::Display for Error<T> {
  fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    self.kind.fmt(f)?;
    if let Some(loc) = &self.loc {
      write!(f, " at {}", loc)?;
    }
    Ok(())
  }
}

impl<'i> Error<ParserError<'i>> {
  pub fn from_parse_error(err: ParseError<'i, ParserError<'i>>, filename: String) -> Self {
    let kind = match err.kind {
      ParseErrorKind::Basic(b) => ParserError::from_basic(b),
      ParseErrorKind::Custom(c) => c,
    };
    Error {
      kind,
      loc: Some(ErrorLocation {
        filename,
        line: err.location.line,
        column: err.location.column,
      }),
    }
  }
}

pub type ParseResult<'i, T> = Result<T, ParseError<'i, ParserError<'i>>>;

/// Helper trait so that basic parse errors convert into our error type.
impl<'i> From<crate::parser::BasicParseError<'i>> for ParseError<'i, ParserError<'i>> {
  fn from(e: crate::parser::BasicParseError<'i>) -> Self {
    ParseError {
      kind: ParseErrorKind::Basic(e.kind),
      location: e.location,
    }
  }
}
