//! Number serialization and parsing.

use crate::error::{ParseResult, ParserError};
use crate::parser::Parser;
use crate::printer::{serialize_dimension_unit, PrintResult, Printer};
use crate::tokenizer::Token;

pub type CSSNumber = f32;
pub type CSSInteger = i32;

/// Formats a positive, non-zero finite number with at most 6 significant digits,
/// using JavaScript-like exponent thresholds. Returns the string without sign.
fn format_positive(value: f32) -> String {
  debug_assert!(value > 0.0);
  // Exact decimal expansion in scientific notation with many digits.
  let s = format!("{:.60e}", value);
  let (mant, exp) = s.split_once('e').unwrap();
  let exp: i32 = exp.parse().unwrap();
  let mut digits: Vec<u8> = mant.bytes().filter(|b| *b != b'.').collect();
  // Round half up to 6 significant digits.
  let mut exp = exp;
  if digits.len() > 6 {
    let round_up = digits[6] >= b'5';
    digits.truncate(6);
    if round_up {
      let mut i = 6;
      loop {
        if i == 0 {
          digits.insert(0, b'1');
          digits.truncate(6);
          exp += 1;
          break;
        }
        i -= 1;
        if digits[i] == b'9' {
          digits[i] = b'0';
        } else {
          digits[i] += 1;
          break;
        }
      }
    }
  }
  // Strip trailing zeros.
  while digits.len() > 1 && *digits.last().unwrap() == b'0' {
    digits.pop();
  }
  let len = digits.len() as i32;
  let kk = exp + 1; // decimal point position
  let digits = std::str::from_utf8(&digits).unwrap();
  let mut out = String::new();
  if len <= kk && kk <= 21 {
    out.push_str(digits);
    for _ in 0..(kk - len) {
      out.push('0');
    }
  } else if 0 < kk && kk <= 21 {
    out.push_str(&digits[..kk as usize]);
    out.push('.');
    out.push_str(&digits[kk as usize..]);
  } else if -6 < kk && kk <= 0 {
    out.push_str("0.");
    for _ in 0..(-kk) {
      out.push('0');
    }
    out.push_str(digits);
  } else if len == 1 {
    out.push_str(digits);
    out.push('e');
    out.push_str(&(kk - 1).to_string());
  } else {
    out.push_str(&digits[..1]);
    out.push('.');
    out.push_str(&digits[1..]);
    out.push('e');
    out.push_str(&(kk - 1).to_string());
  }
  out
}

/// Formats a number the way the CSS serializer does for plain numbers.
pub fn number_to_string(value: f32) -> String {
  if value == 0.0 {
    return "0".into();
  }
  if value.is_nan() {
    return "NaN".into();
  }
  if value.is_infinite() {
    return if value < 0.0 { "-inf".into() } else { "inf".into() };
  }
  let mut s = format_positive(value.abs());
  if value.abs() < 1.0 {
    // Remove leading zero
    s = s.trim_start_matches('0').to_string();
  }
  if value < 0.0 {
    format!("-{}", s)
  } else {
    s
  }
}

/// Formats a number for use in a dimension (preserves negative zero).
pub fn dimension_number_to_string(value: f32) -> String {
  if value == 0.0 {
    return if value.is_sign_negative() { "-0".into() } else { "0".into() };
  }
  number_to_string(value)
}

pub fn serialize_number(value: f32, dest: &mut Printer) -> PrintResult {
  dest.write_str(&number_to_string(value))
}

pub fn serialize_dimension(value: f32, unit: &str, dest: &mut Printer) -> PrintResult {
  let mut s = dimension_number_to_string(value);
  serialize_dimension_unit(unit, &mut s);
  dest.write_str(&s)
}

pub fn serialize_percentage(value: f32, dest: &mut Printer) -> PrintResult {
  let mut s = dimension_number_to_string(value);
  s.push('%');
  dest.write_str(&s)
}

/// Parses a plain number, including math functions.
pub fn parse_number<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if let Ok(v) = input.try_parse(|input| crate::values::calc::Calc::<f32>::parse(input)) {
    match v {
      crate::values::calc::Calc::Value(v) => return Ok(*v),
      crate::values::calc::Calc::Number(n) => return Ok(n),
      // Numbers are always compatible, so they will always compute to a value.
      _ => return Err(input.new_custom_error(ParserError::InvalidValue)),
    }
  }
  let loc = input.current_source_location();
  match input.next()? {
    Token::Number { value, .. } => Ok(value),
    t => Err(loc.new_unexpected_token_error(t)),
  }
}

pub fn parse_integer<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, i32> {
  // TODO: calc??
  let loc = input.current_source_location();
  match input.next()? {
    Token::Number {
      int_value: Some(value), ..
    } => Ok(value),
    t => Err(loc.new_unexpected_token_error(t)),
  }
}
