//! Vendor prefixes.

use crate::printer::{PrintResult, Printer};

#[derive(Clone, Copy, PartialEq, Eq, Hash, Default)]
pub struct VendorPrefix(u8);

impl std::fmt::Debug for VendorPrefix {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    write!(f, "VendorPrefix({:#x})", self.0)
  }
}

#[allow(non_upper_case_globals)]
impl VendorPrefix {
  pub const None: VendorPrefix = VendorPrefix(1 << 0);
  pub const WebKit: VendorPrefix = VendorPrefix(1 << 1);
  pub const Moz: VendorPrefix = VendorPrefix(1 << 2);
  pub const Ms: VendorPrefix = VendorPrefix(1 << 3);
  pub const O: VendorPrefix = VendorPrefix(1 << 4);

  pub const fn empty() -> Self {
    VendorPrefix(0)
  }

  pub const fn all() -> Self {
    VendorPrefix(0b11111)
  }

  pub fn is_empty(&self) -> bool {
    self.0 == 0
  }

  pub fn contains(&self, other: VendorPrefix) -> bool {
    (self.0 & other.0) == other.0 && other.0 != 0
  }

  pub fn intersects(&self, other: VendorPrefix) -> bool {
    (self.0 & other.0) != 0
  }

  pub fn bits(&self) -> u8 {
    self.0
  }

  pub fn from_bits(bits: u8) -> Self {
    VendorPrefix(bits)
  }

  pub fn insert(&mut self, other: VendorPrefix) {
    self.0 |= other.0;
  }

  pub fn remove(&mut self, other: VendorPrefix) {
    self.0 &= !other.0;
  }

  /// Returns VendorPrefix::None if the prefix is empty, otherwise the prefix.
  pub fn or_none(self) -> Self {
    if self.is_empty() {
      VendorPrefix::None
    } else {
      self
    }
  }

  pub fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.write_str(self.as_str())
  }

  pub fn as_str(&self) -> &'static str {
    match *self {
      VendorPrefix::WebKit => "-webkit-",
      VendorPrefix::Moz => "-moz-",
      VendorPrefix::Ms => "-ms-",
      VendorPrefix::O => "-o-",
      _ => "",
    }
  }

  /// Iterate over individual prefixes in order: WebKit, Moz, Ms, O, None
  pub fn iter(&self) -> impl Iterator<Item = VendorPrefix> {
    let v = *self;
    [
      VendorPrefix::WebKit,
      VendorPrefix::Moz,
      VendorPrefix::Ms,
      VendorPrefix::O,
      VendorPrefix::None,
    ]
    .into_iter()
    .filter(move |p| v.contains(*p))
  }

  pub fn parse_prefixed_name(name: &str) -> (VendorPrefix, &str) {
    if let Some(rest) = name.strip_prefix("-webkit-") {
      (VendorPrefix::WebKit, rest)
    } else if let Some(rest) = name.strip_prefix("-moz-") {
      (VendorPrefix::Moz, rest)
    } else if let Some(rest) = name.strip_prefix("-ms-") {
      (VendorPrefix::Ms, rest)
    } else if let Some(rest) = name.strip_prefix("-o-") {
      (VendorPrefix::O, rest)
    } else {
      (VendorPrefix::None, name)
    }
  }
}

impl std::ops::BitOr for VendorPrefix {
  type Output = VendorPrefix;
  fn bitor(self, rhs: VendorPrefix) -> VendorPrefix {
    VendorPrefix(self.0 | rhs.0)
  }
}

impl std::ops::BitOrAssign for VendorPrefix {
  fn bitor_assign(&mut self, rhs: VendorPrefix) {
    self.0 |= rhs.0;
  }
}

impl std::ops::BitAnd for VendorPrefix {
  type Output = VendorPrefix;
  fn bitand(self, rhs: VendorPrefix) -> VendorPrefix {
    VendorPrefix(self.0 & rhs.0)
  }
}

impl std::ops::Not for VendorPrefix {
  type Output = VendorPrefix;
  fn not(self) -> VendorPrefix {
    VendorPrefix(!self.0 & 0b11111)
  }
}
