/// A CSS color value.
#[derive(Clone, Debug, PartialEq)]
pub enum CssColor {
  CurrentColor,
  RGBA(RGBA),
  Float(FloatColor),
  LightDark(Box<CssColor>, Box<CssColor>),
  System(SystemColor),
}

impl CssColor {
  pub fn current_color() -> Self {
    CssColor::CurrentColor
  }

  pub fn transparent() -> Self {
    CssColor::RGBA(RGBA::transparent())
  }

  pub fn is_transparent(&self) -> bool {
    matches!(self, CssColor::RGBA(RGBA { alpha: 0, .. }))
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let token = input.next()?;
    match token {
      Token::Hash(ref value) | Token::IDHash(ref value) => {
        parse_hash(value.as_bytes()).map(|rgba| CssColor::RGBA(rgba)).map_err(|()| location.new_unexpected_token_error(token.clone()))
      }
      Token::Ident(ref value) => parse_color_keyword(value).ok_or_else(|| location.new_unexpected_token_error(token.clone())),
      Token::Function(ref name) => {
        let name = name.clone();
        input.parse_nested_block(|input| parse_color_function(location, &name, input))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  /// Converts the color to RGBA (sRGB, 8-bit) if possible.
  pub fn to_rgb(&self) -> Option<RGBA> {
    match self {
      CssColor::RGBA(rgba) => Some(*rgba),
      CssColor::Float(f) => {
        let srgb = f.to_space(ColorSpace::SRGB);
        Some(RGBA::from_floats(
          nan_to_zero(srgb.a),
          nan_to_zero(srgb.b),
          nan_to_zero(srgb.c),
          nan_to_zero(srgb.alpha),
        ))
      }
      _ => None,
    }
  }

  pub fn to_float(&self) -> Option<FloatColor> {
    match self {
      CssColor::RGBA(rgba) => Some(FloatColor {
        space: ColorSpace::SRGB,
        a: rgba.red_f32(),
        b: rgba.green_f32(),
        c: rgba.blue_f32(),
        alpha: rgba.alpha_f32(),
      }),
      CssColor::Float(f) => Some(*f),
      _ => None,
    }
  }
}

fn nan_to_zero(v: f32) -> f32 {
  if v.is_nan() {
    0.0
  } else {
    v
  }
}

impl ToCss for CssColor {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      CssColor::CurrentColor => dest.write_str("currentColor"),
      CssColor::RGBA(color) => color.to_css(dest),
      CssColor::Float(f) => f.to_css(dest),
      CssColor::LightDark(light, dark) => {
        dest.write_str("light-dark(")?;
        light.to_css(dest)?;
        dest.delim(',', false)?;
        dark.to_css(dest)?;
        dest.write_char(')')
      }
      CssColor::System(s) => dest.write_str(s.as_str()),
    }
  }
}

impl ToCss for RGBA {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    // Serialize as hex, or a named color if shorter.
    let hex = if self.alpha == 255 {
      let hex: u32 = ((self.red as u32) << 16) | ((self.green as u32) << 8) | (self.blue as u32);
      let compact = compact_hex(hex);
      if hex == expand_hex(compact) {
        format!("#{:03x}", compact)
      } else {
        format!("#{:06x}", hex)
      }
    } else {
      let hex: u32 = ((self.red as u32) << 24) | ((self.green as u32) << 16) | ((self.blue as u32) << 8) | (self.alpha as u32);
      let compact = compact_hex(hex);
      if hex == expand_hex(compact) {
        format!("#{:04x}", compact)
      } else {
        format!("#{:08x}", hex)
      }
    };
    if self.alpha == 255 {
      if let Some(name) = short_color_name(self.red, self.green, self.blue) {
        if name.len() < hex.len() {
          return dest.write_str(name);
        }
      }
    }
    dest.write_str(&hex)
  }
}

fn compact_hex(v: u32) -> u32 {
  // Reduce a 6 (or 8) digit hex to 3 (or 4) digits by taking the high nibble of each byte.
  let mut res = 0u32;
  let mut shift = 0;
  let mut v2 = v;
  while v2 > 0 {
    let nibble = (v2 >> 4) & 0xf;
    res |= nibble << shift;
    shift += 4;
    v2 >>= 8;
  }
  res
}

fn expand_hex(v: u32) -> u32 {
  let mut res = 0u32;
  let mut shift = 0;
  let mut v2 = v;
  let mut count = 0;
  while v2 > 0 || count < 3 {
    let nibble = v2 & 0xf;
    res |= (nibble | (nibble << 4)) << shift;
    shift += 8;
    v2 >>= 4;
    count += 1;
    if count >= 4 {
      break;
    }
  }
  res
}

pub fn short_color_name(r: u8, g: u8, b: u8) -> Option<&'static str> {
  let v = ((r as u32) << 16) | ((g as u32) << 8) | (b as u32);
  for (name, value) in NAMED_COLORS {
    if *value == v {
      return Some(name);
    }
  }
  None
}

