pub fn parse_color_keyword(ident: &str) -> Option<CssColor> {
  let lower = ident.to_ascii_lowercase();
  if lower == "transparent" {
    return Some(CssColor::RGBA(RGBA::transparent()));
  }
  if lower == "currentcolor" {
    return Some(CssColor::CurrentColor);
  }
  for (name, value) in NAMED_COLORS {
    if *name == lower {
      return Some(CssColor::RGBA(RGBA::new(
        ((*value >> 16) & 0xff) as u8,
        ((*value >> 8) & 0xff) as u8,
        (*value & 0xff) as u8,
        255,
      )));
    }
  }
  SystemColor::parse_name(&lower).map(CssColor::System)
}

pub fn parse_hash(value: &[u8]) -> Result<RGBA, ()> {
  match value.len() {
    8 => Ok(RGBA::new(
      from_hex(value[0])? * 16 + from_hex(value[1])?,
      from_hex(value[2])? * 16 + from_hex(value[3])?,
      from_hex(value[4])? * 16 + from_hex(value[5])?,
      from_hex(value[6])? * 16 + from_hex(value[7])?,
    )),
    6 => Ok(RGBA::new(
      from_hex(value[0])? * 16 + from_hex(value[1])?,
      from_hex(value[2])? * 16 + from_hex(value[3])?,
      from_hex(value[4])? * 16 + from_hex(value[5])?,
      255,
    )),
    4 => Ok(RGBA::new(
      from_hex(value[0])? * 17,
      from_hex(value[1])? * 17,
      from_hex(value[2])? * 17,
      from_hex(value[3])? * 17,
    )),
    3 => Ok(RGBA::new(
      from_hex(value[0])? * 17,
      from_hex(value[1])? * 17,
      from_hex(value[2])? * 17,
      255,
    )),
    _ => Err(()),
  }
}

fn from_hex(c: u8) -> Result<u8, ()> {
  match c {
    b'0'..=b'9' => Ok(c - b'0'),
    b'a'..=b'f' => Ok(c - b'a' + 10),
    b'A'..=b'F' => Ok(c - b'A' + 10),
    _ => Err(()),
  }
}

// ---------------------------------------------------------------------------
// Function parsing

fn parse_color_function<'i, 't>(
  location: crate::tokenizer::SourceLocation,
  name: &str,
  input: &mut Parser<'i, 't>,
) -> ParseResult<'i, CssColor> {
  let lower = name.to_ascii_lowercase();
  match lower.as_str() {
    "rgb" | "rgba" => parse_rgb(input),
    "hsl" | "hsla" => parse_hsl_hwb(input, ColorSpace::HSL),
    "hwb" => parse_hsl_hwb(input, ColorSpace::HWB),
    "lab" => parse_lab_like(input, ColorSpace::Lab),
    "lch" => parse_lab_like(input, ColorSpace::Lch),
    "oklab" => parse_lab_like(input, ColorSpace::OKLab),
    "oklch" => parse_lab_like(input, ColorSpace::OKLch),
    "color" => parse_predefined(input),
    "color-mix" => parse_color_mix(input),
    "light-dark" => {
      let light = CssColor::parse(input)?;
      input.expect_comma()?;
      let dark = CssColor::parse(input)?;
      Ok(CssColor::LightDark(Box::new(light), Box::new(dark)))
    }
    _ => Err(location.new_unexpected_token_error(Token::Ident(name.to_string().into()))),
  }
}

/// Parses an optional `from <color>` for relative color syntax.
fn parse_from<'i, 't>(input: &mut Parser<'i, 't>, space: ColorSpace) -> ParseResult<'i, Option<FloatColor>> {
  if input.try_parse(|input| input.expect_ident_matching("from")).is_ok() {
    let color = CssColor::parse(input)?;
    let f = match color.to_float() {
      Some(f) => f,
      None => return Err(input.new_custom_error(ParserError::InvalidValue)),
    };
    Ok(Some(f.to_space(space)))
  } else {
    Ok(None)
  }
}

#[derive(Clone, Copy)]
struct ComponentCtx {
  /// Variable names and values available in relative color syntax.
  names: [(&'static str, f32); 4],
  /// Whether percentages map to these values (for 100%).
  percent_base: f32,
  /// Whether the component accepts unitless numbers interpreted as percentages (hsl s/l).
  number_is_percent: bool,
}

/// Parses a number or percentage, possibly with relative color keywords.
fn parse_component<'i, 't>(
  input: &mut Parser<'i, 't>,
  ctx: &ComponentCtx,
  from: Option<&FloatColor>,
) -> ParseResult<'i, f32> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(f32::NAN);
  }
  if from.is_some() {
    // relative color keyword or calc with keywords
    let state = input.state();
    if let Ok(ident) = input.try_parse(|input| input.expect_ident()) {
      for (n, v) in ctx.names.iter() {
        if ident.eq_ignore_ascii_case(n) {
          return Ok(*v);
        }
      }
      input.reset(&state);
    }
    if let Ok(v) = input.try_parse(|input| parse_relative_calc(input, ctx)) {
      return Ok(v);
    }
  }
  let v = NumberOrPercentage::parse(input)?;
  Ok(match v {
    NumberOrPercentage::Number(n) => {
      if ctx.number_is_percent {
        n / 100.0 * ctx.percent_base
      } else {
        n
      }
    }
    NumberOrPercentage::Percentage(p) => p.0 * ctx.percent_base,
  })
}

/// Parses a `calc()` expression that may contain relative color keywords.
fn parse_relative_calc<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ComponentCtx) -> ParseResult<'i, f32> {
  input.expect_function_matching("calc")?;
  input.parse_nested_block(|input| {
    let v = parse_calc_sum(input, ctx)?;
    Ok(v)
  })
}

fn parse_calc_sum<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ComponentCtx) -> ParseResult<'i, f32> {
  let mut value = parse_calc_product(input, ctx)?;
  loop {
    let state = input.state();
    match input.next_including_whitespace() {
      Ok(Token::WhiteSpace(_)) => {
        if input.is_exhausted() {
          break;
        }
        match input.next()? {
          Token::Delim('+') => {
            let rhs = parse_calc_product(input, ctx)?;
            value += rhs;
          }
          Token::Delim('-') => {
            let rhs = parse_calc_product(input, ctx)?;
            value -= rhs;
          }
          t => return Err(input.new_unexpected_token_error(t)),
        }
      }
      _ => {
        input.reset(&state);
        break;
      }
    }
  }
  Ok(value)
}

fn parse_calc_product<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ComponentCtx) -> ParseResult<'i, f32> {
  let mut value = parse_calc_value(input, ctx)?;
  loop {
    let state = input.state();
    match input.next() {
      Ok(Token::Delim('*')) => {
        let rhs = parse_calc_value(input, ctx)?;
        value *= rhs;
      }
      Ok(Token::Delim('/')) => {
        let rhs = parse_calc_value(input, ctx)?;
        if rhs == 0.0 {
          return Err(input.new_custom_error(ParserError::InvalidValue));
        }
        value /= rhs;
      }
      _ => {
        input.reset(&state);
        break;
      }
    }
  }
  Ok(value)
}

fn parse_calc_value<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ComponentCtx) -> ParseResult<'i, f32> {
  let location = input.current_source_location();
  match input.next()? {
    Token::Number { value, .. } => Ok(value),
    Token::Percentage { unit_value, .. } => Ok(unit_value * ctx.percent_base),
    Token::Dimension { value, ref unit, .. } => {
      // angle for hue
      if let Some(deg) = Angle::parse_unit(value, unit) {
        Ok(deg.to_degrees())
      } else {
        Err(location.new_custom_error(ParserError::InvalidValue))
      }
    }
    Token::Ident(ref ident) => {
      for (n, v) in ctx.names.iter() {
        if ident.eq_ignore_ascii_case(n) {
          return Ok(*v);
        }
      }
      Err(location.new_custom_error(ParserError::InvalidValue))
    }
    Token::ParenthesisBlock => input.parse_nested_block(|input| parse_calc_sum(input, ctx)),
    Token::Function(ref f) if f.eq_ignore_ascii_case("calc") => {
      input.parse_nested_block(|input| parse_calc_sum(input, ctx))
    }
    t => Err(location.new_unexpected_token_error(t)),
  }
}

fn parse_alpha<'i, 't>(input: &mut Parser<'i, 't>, from: Option<&FloatColor>) -> ParseResult<'i, f32> {
  if input.is_exhausted() {
    return Ok(from.map(|f| f.alpha).unwrap_or(1.0));
  }
  input.expect_delim('/')?;
  let ctx = ComponentCtx {
    names: [("alpha", from.map(|f| f.alpha).unwrap_or(1.0)), ("", 0.), ("", 0.), ("", 0.)],
    percent_base: 1.0,
    number_is_percent: false,
  };
  let v = parse_component(input, &ctx, from)?;
  Ok(v)
}

fn parse_rgb<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, CssColor> {
  let from = parse_from(input, ColorSpace::SRGB)?;
  if let Some(from) = from {
    let f = from;
    let ctx = |_: usize| ComponentCtx {
      names: [("r", f.a * 255.0), ("g", f.b * 255.0), ("b", f.c * 255.0), ("alpha", f.alpha)],
      percent_base: 255.0,
      number_is_percent: false,
    };
    let r = parse_component(input, &ctx(0), Some(&f))?;
    let g = parse_component(input, &ctx(1), Some(&f))?;
    let b = parse_component(input, &ctx(2), Some(&f))?;
    let alpha = parse_alpha(input, Some(&f))?;
    return Ok(CssColor::RGBA(RGBA::from_floats(
      nan_to_zero(r) / 255.0,
      nan_to_zero(g) / 255.0,
      nan_to_zero(b) / 255.0,
      nan_to_zero(alpha),
    )));
  }

  // Legacy syntax (comma separated) or modern.
  let location = input.current_source_location();
  let first = parse_number_or_percentage_or_none(input)?;
  let is_legacy = input.try_parse(|input| input.expect_comma()).is_ok();
  if is_legacy {
    if first.is_none() {
      return Err(location.new_custom_error(ParserError::InvalidValue));
    }
    let (r, g, b) = match first {
      NumOrPct::Number(r) => {
        let g = parse_number(input)?;
        input.expect_comma()?;
        let b = parse_number(input)?;
        (r / 255.0, g / 255.0, b / 255.0)
      }
      NumOrPct::Percentage(r) => {
        let g = input.expect_percentage()?;
        input.expect_comma()?;
        let b = input.expect_percentage()?;
        (r, g, b)
      }
      NumOrPct::None => unreachable!(),
    };
    let alpha = if input.try_parse(|input| input.expect_comma()).is_ok() {
      match NumberOrPercentage::parse(input)? {
        NumberOrPercentage::Number(n) => n,
        NumberOrPercentage::Percentage(p) => p.0,
      }
    } else {
      1.0
    };
    input.expect_exhausted()?;
    return Ok(CssColor::RGBA(RGBA::from_floats(r, g, b, alpha)));
  }

  // Modern syntax: numbers or percentages can be mixed.
  let to_unit = |v: NumOrPct| match v {
    NumOrPct::Number(n) => n / 255.0,
    NumOrPct::Percentage(p) => p,
    NumOrPct::None => 0.0,
  };
  let r = to_unit(first);
  let g = to_unit(parse_number_or_percentage_or_none(input)?);
  let b = to_unit(parse_number_or_percentage_or_none(input)?);
  let alpha = parse_alpha_modern(input)?;
  input.expect_exhausted()?;
  Ok(CssColor::RGBA(RGBA::from_floats(r, g, b, alpha)))
}

enum NumOrPct {
  Number(f32),
  Percentage(f32),
  None,
}

impl NumOrPct {
  fn is_none(&self) -> bool {
    matches!(self, NumOrPct::None)
  }
}

fn parse_number<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  crate::values::number::parse_number(input)
}

fn parse_number_or_percentage_or_none<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, NumOrPct> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(NumOrPct::None);
  }
  match NumberOrPercentage::parse(input)? {
    NumberOrPercentage::Number(n) => Ok(NumOrPct::Number(n)),
    NumberOrPercentage::Percentage(p) => Ok(NumOrPct::Percentage(p.0)),
  }
}

fn parse_alpha_modern<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if input.is_exhausted() {
    return Ok(1.0);
  }
  input.expect_delim('/')?;
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(0.0);
  }
  match NumberOrPercentage::parse(input)? {
    NumberOrPercentage::Number(n) => Ok(n),
    NumberOrPercentage::Percentage(p) => Ok(p.0),
  }
}

fn parse_hue<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(0.0);
  }
  let angle = Angle::parse_with_unitless(input)?;
  Ok(angle.to_degrees())
}

fn parse_hsl_hwb<'i, 't>(input: &mut Parser<'i, 't>, space: ColorSpace) -> ParseResult<'i, CssColor> {
  let from = parse_from(input, space)?;
  if let Some(f) = from {
    let names: [(&'static str, f32); 4] = if space == ColorSpace::HSL {
      [("h", f.a), ("s", f.b * 100.0), ("l", f.c * 100.0), ("alpha", f.alpha)]
    } else {
      [("h", f.a), ("w", f.b * 100.0), ("b", f.c * 100.0), ("alpha", f.alpha)]
    };
    let hctx = ComponentCtx {
      names,
      percent_base: 1.0,
      number_is_percent: false,
    };
    let pctx = ComponentCtx {
      names,
      percent_base: 100.0,
      number_is_percent: false,
    };
    let h = parse_hue_component(input, &hctx, &f)?;
    let s = parse_component(input, &pctx, Some(&f))?;
    let l = parse_component(input, &pctx, Some(&f))?;
    let alpha = parse_alpha(input, Some(&f))?;
    let (r, g, b) = if space == ColorSpace::HSL {
      hsl_to_rgb(nan_to_zero(h), nan_to_zero(s) / 100.0, nan_to_zero(l) / 100.0)
    } else {
      hwb_to_rgb(nan_to_zero(h), nan_to_zero(s) / 100.0, nan_to_zero(l) / 100.0)
    };
    return Ok(CssColor::RGBA(RGBA::from_floats(r, g, b, nan_to_zero(alpha))));
  }

  let h = parse_hue(input)?;
  let is_legacy = input.try_parse(|input| input.expect_comma()).is_ok();
  let (s, l, alpha) = if is_legacy {
    if space == ColorSpace::HWB {
      return Err(input.new_custom_error(ParserError::InvalidValue));
    }
    let s = input.expect_percentage()?;
    input.expect_comma()?;
    let l = input.expect_percentage()?;
    let alpha = if input.try_parse(|input| input.expect_comma()).is_ok() {
      match NumberOrPercentage::parse(input)? {
        NumberOrPercentage::Number(n) => n,
        NumberOrPercentage::Percentage(p) => p.0,
      }
    } else {
      1.0
    };
    (s, l, alpha)
  } else {
    let s = parse_percentage_or_number_component(input)?;
    let l = parse_percentage_or_number_component(input)?;
    let alpha = parse_alpha_modern(input)?;
    (s, l, alpha)
  };
  input.expect_exhausted()?;
  let s = s.max(0.0);
  let (r, g, b) = if space == ColorSpace::HSL {
    hsl_to_rgb(h, s.min(1.0), l.max(0.0).min(1.0))
  } else {
    hwb_to_rgb(h, s, l)
  };
  Ok(CssColor::RGBA(RGBA::from_floats(r, g, b, alpha)))
}

fn parse_hue_component<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ComponentCtx, from: &FloatColor) -> ParseResult<'i, f32> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(f32::NAN);
  }
  let state = input.state();
  if let Ok(ident) = input.try_parse(|input| input.expect_ident()) {
    for (n, v) in ctx.names.iter() {
      if ident.eq_ignore_ascii_case(n) {
        return Ok(*v);
      }
    }
    input.reset(&state);
  }
  if let Ok(v) = input.try_parse(|input| parse_relative_calc(input, ctx)) {
    return Ok(v);
  }
  let _ = from;
  let angle = Angle::parse_with_unitless(input)?;
  Ok(angle.to_degrees())
}

/// Percentage or number (number interpreted as percentage value) -> unit value
fn parse_percentage_or_number_component<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(0.0);
  }
  match NumberOrPercentage::parse(input)? {
    NumberOrPercentage::Number(n) => Ok(n / 100.0),
    NumberOrPercentage::Percentage(p) => Ok(p.0),
  }
}

fn parse_lab_like<'i, 't>(input: &mut Parser<'i, 't>, space: ColorSpace) -> ParseResult<'i, CssColor> {
  let from = parse_from(input, space)?;
  let (l_base, ab_base, is_polar) = match space {
    ColorSpace::Lab => (100.0, 125.0, false),
    ColorSpace::Lch => (100.0, 150.0, true),
    ColorSpace::OKLab => (1.0, 0.4, false),
    ColorSpace::OKLch => (1.0, 0.4, true),
    _ => unreachable!(),
  };
  let names: [(&'static str, f32); 4] = match (from, is_polar) {
    (Some(f), false) => [("l", f.a), ("a", f.b), ("b", f.c), ("alpha", f.alpha)],
    (Some(f), true) => [("l", f.a), ("c", f.b), ("h", f.c), ("alpha", f.alpha)],
    (None, _) => [("", 0.), ("", 0.), ("", 0.), ("", 0.)],
  };
  let lctx = ComponentCtx {
    names,
    percent_base: l_base,
    number_is_percent: false,
  };
  let abctx = ComponentCtx {
    names,
    percent_base: ab_base,
    number_is_percent: false,
  };
  let hctx = ComponentCtx {
    names,
    percent_base: 1.0,
    number_is_percent: false,
  };
  let l = parse_component(input, &lctx, from.as_ref())?;
  let b_;
  let c_;
  if is_polar {
    c_ = parse_component(input, &abctx, from.as_ref())?;
    b_ = if let Some(f) = from.as_ref() {
      parse_hue_component(input, &hctx, f)?
    } else {
      parse_hue_or_none(input)?
    };
  } else {
    c_ = parse_component(input, &abctx, from.as_ref())?;
    b_ = parse_component(input, &abctx, from.as_ref())?;
  }
  let alpha = if from.is_some() {
    parse_alpha(input, from.as_ref())?
  } else {
    parse_alpha_modern_none(input)?
  };
  input.expect_exhausted()?;
  // Clamp lightness and chroma
  let l = if l.is_nan() { l } else { l.max(0.0) };
  let c_ = if is_polar && !c_.is_nan() { c_.max(0.0) } else { c_ };
  Ok(CssColor::Float(FloatColor {
    space,
    a: l,
    b: c_,
    c: b_,
    alpha,
  }))
}

fn parse_hue_or_none<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(f32::NAN);
  }
  let angle = Angle::parse_with_unitless(input)?;
  Ok(angle.to_degrees())
}

fn parse_alpha_modern_none<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  if input.is_exhausted() {
    return Ok(1.0);
  }
  input.expect_delim('/')?;
  if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
    return Ok(f32::NAN);
  }
  match NumberOrPercentage::parse(input)? {
    NumberOrPercentage::Number(n) => Ok(n),
    NumberOrPercentage::Percentage(p) => Ok(p.0),
  }
}

fn parse_predefined<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, CssColor> {
  // color( [from <color>]? <colorspace> c1 c2 c3 [/ alpha]? )
  let from_state = input.state();
  let has_from = input.try_parse(|input| input.expect_ident_matching("from")).is_ok();
  let from_color = if has_from { Some(CssColor::parse(input)?) } else { None };
  let _ = from_state;
  let location = input.current_source_location();
  let ident = input.expect_ident()?;
  let space = match ident.to_ascii_lowercase().as_str() {
    "srgb" => ColorSpace::SRGB,
    "srgb-linear" => ColorSpace::SRGBLinear,
    "display-p3" => ColorSpace::DisplayP3,
    "a98-rgb" => ColorSpace::A98,
    "prophoto-rgb" => ColorSpace::ProPhoto,
    "rec2020" => ColorSpace::Rec2020,
    "xyz-d50" => ColorSpace::XYZd50,
    "xyz" | "xyz-d65" => ColorSpace::XYZd65,
    _ => return Err(location.new_unexpected_token_error(Token::Ident(ident))),
  };
  let from = match from_color {
    Some(c) => match c.to_float() {
      Some(f) => Some(f.to_space(space)),
      None => return Err(input.new_custom_error(ParserError::InvalidValue)),
    },
    None => None,
  };
  let names: [(&'static str, f32); 4] = match (from, space) {
    (Some(f), ColorSpace::XYZd50) | (Some(f), ColorSpace::XYZd65) => {
      [("x", f.a), ("y", f.b), ("z", f.c), ("alpha", f.alpha)]
    }
    (Some(f), _) => [("r", f.a), ("g", f.b), ("b", f.c), ("alpha", f.alpha)],
    (None, _) => [("", 0.), ("", 0.), ("", 0.), ("", 0.)],
  };
  let ctx = ComponentCtx {
    names,
    percent_base: 1.0,
    number_is_percent: false,
  };
  let a = parse_component(input, &ctx, from.as_ref())?;
  let b = parse_component(input, &ctx, from.as_ref())?;
  let c = parse_component(input, &ctx, from.as_ref())?;
  let alpha = if from.is_some() {
    parse_alpha(input, from.as_ref())?
  } else {
    parse_alpha_modern_none(input)?
  };
  input.expect_exhausted()?;
  Ok(CssColor::Float(FloatColor { space, a, b, c, alpha }))
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum HueInterpolationMethod {
  Shorter,
  Longer,
  Increasing,
  Decreasing,
  Specified,
}

fn parse_color_mix<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, CssColor> {
  input.expect_ident_matching("in")?;
  let location = input.current_source_location();
  let ident = input.expect_ident()?;
  let space = match ident.to_ascii_lowercase().as_str() {
    "srgb" => ColorSpace::SRGB,
    "srgb-linear" => ColorSpace::SRGBLinear,
    "display-p3" => ColorSpace::DisplayP3,
    "a98-rgb" => ColorSpace::A98,
    "prophoto-rgb" => ColorSpace::ProPhoto,
    "rec2020" => ColorSpace::Rec2020,
    "xyz-d50" => ColorSpace::XYZd50,
    "xyz" | "xyz-d65" => ColorSpace::XYZd65,
    "lab" => ColorSpace::Lab,
    "lch" => ColorSpace::Lch,
    "oklab" => ColorSpace::OKLab,
    "oklch" => ColorSpace::OKLch,
    "hsl" => ColorSpace::HSL,
    "hwb" => ColorSpace::HWB,
    _ => return Err(location.new_unexpected_token_error(Token::Ident(ident))),
  };
  let mut hue_method = HueInterpolationMethod::Shorter;
  if matches!(
    space,
    ColorSpace::Lch | ColorSpace::OKLch | ColorSpace::HSL | ColorSpace::HWB
  ) {
    if let Ok(m) = input.try_parse(|input| {
      let loc = input.current_source_location();
      let ident = input.expect_ident()?;
      let m = match ident.to_ascii_lowercase().as_str() {
        "shorter" => HueInterpolationMethod::Shorter,
        "longer" => HueInterpolationMethod::Longer,
        "increasing" => HueInterpolationMethod::Increasing,
        "decreasing" => HueInterpolationMethod::Decreasing,
        "specified" => HueInterpolationMethod::Specified,
        _ => return Err(loc.new_unexpected_token_error::<ParserError>(Token::Ident(ident))),
      };
      input.expect_ident_matching("hue")?;
      Ok(m)
    }) {
      hue_method = m;
    }
  }
  input.expect_comma()?;
  let (c1, p1) = parse_color_mix_component(input)?;
  input.expect_comma()?;
  let (c2, p2) = parse_color_mix_component(input)?;
  input.expect_exhausted()?;

  // Resolve percentages
  let (p1, p2) = match (p1, p2) {
    (None, None) => (0.5, 0.5),
    (Some(p1), None) => (p1, 1.0 - p1),
    (None, Some(p2)) => (1.0 - p2, p2),
    (Some(p1), Some(p2)) => (p1, p2),
  };
  if p1 + p2 == 0.0 {
    return Err(input.new_custom_error(ParserError::InvalidValue));
  }
  let (f1, f2) = match (c1.to_float(), c2.to_float()) {
    (Some(a), Some(b)) => (a, b),
    _ => return Err(input.new_custom_error(ParserError::InvalidValue)),
  };
  let result = interpolate(f1, f2, p1, p2, space, hue_method);
  Ok(float_to_color(result))
}

fn float_to_color(f: FloatColor) -> CssColor {
  match f.space {
    ColorSpace::SRGB | ColorSpace::HSL | ColorSpace::HWB => {
      let srgb = f.to_space(ColorSpace::SRGB);
      CssColor::RGBA(RGBA::from_floats(
        nan_to_zero(srgb.a),
        nan_to_zero(srgb.b),
        nan_to_zero(srgb.c),
        nan_to_zero(srgb.alpha),
      ))
    }
    _ => CssColor::Float(f),
  }
}

fn parse_color_mix_component<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, (CssColor, Option<f32>)> {
  let mut percent = input.try_parse(|input| Percentage::parse(input)).ok().map(|p| p.0);
  let color = CssColor::parse(input)?;
  if percent.is_none() {
    percent = input.try_parse(|input| Percentage::parse(input)).ok().map(|p| p.0);
  }
  if let Some(p) = percent {
    if p < 0.0 || p > 1.0 {
      return Err(input.new_custom_error(ParserError::InvalidValue));
    }
  }
  Ok((color, percent))
}

fn interpolate(
  c1: FloatColor,
  c2: FloatColor,
  p1: f32,
  p2: f32,
  space: ColorSpace,
  hue_method: HueInterpolationMethod,
) -> FloatColor {
  let alpha_multiplier = p1 + p2;
  let (p1, p2) = if alpha_multiplier != 1.0 {
    (p1 / alpha_multiplier, p2 / alpha_multiplier)
  } else {
    (p1, p2)
  };
  let mut a = c1.to_space(space);
  let mut b = c2.to_space(space);

  // Fill missing components (none) from the other color.
  fill_missing(&mut a, &mut b);

  // Premultiply
  let (pa, pb) = (premultiply(&a), premultiply(&b));
  let mut a = pa;
  let mut b = pb;

  // Hue adjustment
  let hue_index = match space {
    ColorSpace::HSL | ColorSpace::HWB => Some(0),
    ColorSpace::Lch | ColorSpace::OKLch => Some(2),
    _ => None,
  };
  if let Some(idx) = hue_index {
    let (h1, h2) = adjust_hue(a.component(idx), b.component(idx), hue_method);
    a.set_component(idx, h1);
    b.set_component(idx, h2);
  }

  let alpha = if a.alpha.is_nan() && b.alpha.is_nan() {
    f32::NAN
  } else {
    nan_to_zero(a.alpha) * p1 + nan_to_zero(b.alpha) * p2
  };
  let mix = |x: f32, y: f32| -> f32 {
    if x.is_nan() && y.is_nan() {
      f32::NAN
    } else {
      x * p1 + y * p2
    }
  };
  let mut result = FloatColor {
    space,
    a: mix(a.a, b.a),
    b: mix(a.b, b.b),
    c: mix(a.c, b.c),
    alpha,
  };
  // Un-premultiply
  if !result.alpha.is_nan() && result.alpha != 0.0 {
    for i in 0..3 {
      if Some(i) == hue_index {
        continue;
      }
      let v = result.component(i);
      result.set_component(i, v / result.alpha);
    }
  }
  if alpha_multiplier != 1.0 && !result.alpha.is_nan() {
    result.alpha *= alpha_multiplier;
  }
  result
}

fn fill_missing(a: &mut FloatColor, b: &mut FloatColor) {
  for i in 0..3 {
    let x = a.component(i);
    let y = b.component(i);
    if x.is_nan() && !y.is_nan() {
      a.set_component(i, y);
    } else if y.is_nan() && !x.is_nan() {
      b.set_component(i, x);
    }
  }
  if a.alpha.is_nan() && !b.alpha.is_nan() {
    a.alpha = b.alpha;
  } else if b.alpha.is_nan() && !a.alpha.is_nan() {
    b.alpha = a.alpha;
  }
}

fn premultiply(c: &FloatColor) -> FloatColor {
  let alpha = if c.alpha.is_nan() { 1.0 } else { c.alpha };
  let hue_index = match c.space {
    ColorSpace::HSL | ColorSpace::HWB => Some(0),
    ColorSpace::Lch | ColorSpace::OKLch => Some(2),
    _ => None,
  };
  let mut r = *c;
  for i in 0..3 {
    if Some(i) == hue_index {
      continue;
    }
    let v = r.component(i);
    if !v.is_nan() {
      r.set_component(i, v * alpha);
    }
  }
  r
}

fn adjust_hue(mut h1: f32, mut h2: f32, method: HueInterpolationMethod) -> (f32, f32) {
  if h1.is_nan() || h2.is_nan() {
    return (h1, h2);
  }
  h1 = h1.rem_euclid(360.0);
  h2 = h2.rem_euclid(360.0);
  match method {
    HueInterpolationMethod::Shorter => {
      let d = h2 - h1;
      if d > 180.0 {
        h1 += 360.0;
      } else if d < -180.0 {
        h2 += 360.0;
      }
    }
    HueInterpolationMethod::Longer => {
      let d = h2 - h1;
      if 0.0 < d && d < 180.0 {
        h1 += 360.0;
      } else if -180.0 < d && d <= 0.0 {
        h2 += 360.0;
      }
    }
    HueInterpolationMethod::Increasing => {
      if h2 < h1 {
        h2 += 360.0;
      }
    }
    HueInterpolationMethod::Decreasing => {
      if h1 < h2 {
        h1 += 360.0;
      }
    }
    HueInterpolationMethod::Specified => {}
  }
  (h1, h2)
}

// ---------------------------------------------------------------------------
// Color space conversions

impl FloatColor {
  pub fn component(&self, i: usize) -> f32 {
    match i {
      0 => self.a,
      1 => self.b,
      _ => self.c,
    }
  }

  pub fn set_component(&mut self, i: usize, v: f32) {
    match i {
      0 => self.a = v,
      1 => self.b = v,
      _ => self.c = v,
    }
  }

  /// Convert to XYZ D65.
  fn to_xyz_d65(&self) -> (f32, f32, f32) {
    let a = nan_to_zero(self.a);
    let b = nan_to_zero(self.b);
    let c = nan_to_zero(self.c);
    match self.space {
      ColorSpace::XYZd65 => (a, b, c),
      ColorSpace::XYZd50 => d50_to_d65(a, b, c),
      ColorSpace::SRGB => {
        let (r, g, b) = (srgb_to_linear(a), srgb_to_linear(b), srgb_to_linear(c));
        lin_srgb_to_xyz(r, g, b)
      }
      ColorSpace::SRGBLinear => lin_srgb_to_xyz(a, b, c),
      ColorSpace::HSL => {
        let (r, g, bb) = hsl_to_rgb(a, b, c);
        lin_srgb_to_xyz(srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(bb))
      }
      ColorSpace::HWB => {
        let (r, g, bb) = hwb_to_rgb(a, b, c);
        lin_srgb_to_xyz(srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(bb))
      }
      ColorSpace::DisplayP3 => {
        let (r, g, b) = (srgb_to_linear(a), srgb_to_linear(b), srgb_to_linear(c));
        lin_p3_to_xyz(r, g, b)
      }
      ColorSpace::A98 => {
        let (r, g, b) = (a98_to_linear(a), a98_to_linear(b), a98_to_linear(c));
        lin_a98_to_xyz(r, g, b)
      }
      ColorSpace::ProPhoto => {
        let (r, g, b) = (prophoto_to_linear(a), prophoto_to_linear(b), prophoto_to_linear(c));
        let (x, y, z) = lin_prophoto_to_xyz_d50(r, g, b);
        d50_to_d65(x, y, z)
      }
      ColorSpace::Rec2020 => {
        let (r, g, b) = (rec2020_to_linear(a), rec2020_to_linear(b), rec2020_to_linear(c));
        lin_2020_to_xyz(r, g, b)
      }
      ColorSpace::Lab => {
        let (x, y, z) = lab_to_xyz_d50(a, b, c);
        d50_to_d65(x, y, z)
      }
      ColorSpace::Lch => {
        let (l, aa, bb) = lch_to_lab(a, b, c);
        let (x, y, z) = lab_to_xyz_d50(l, aa, bb);
        d50_to_d65(x, y, z)
      }
      ColorSpace::OKLab => oklab_to_xyz(a, b, c),
      ColorSpace::OKLch => {
        let (l, aa, bb) = lch_to_lab(a, b, c);
        oklab_to_xyz(l, aa, bb)
      }
    }
  }

  fn from_xyz_d65(space: ColorSpace, x: f32, y: f32, z: f32, alpha: f32) -> FloatColor {
    let (a, b, c) = match space {
      ColorSpace::XYZd65 => (x, y, z),
      ColorSpace::XYZd50 => d65_to_d50(x, y, z),
      ColorSpace::SRGB => {
        let (r, g, b) = xyz_to_lin_srgb(x, y, z);
        (linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b))
      }
      ColorSpace::SRGBLinear => xyz_to_lin_srgb(x, y, z),
      ColorSpace::HSL => {
        let (r, g, b) = xyz_to_lin_srgb(x, y, z);
        rgb_to_hsl(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b))
      }
      ColorSpace::HWB => {
        let (r, g, b) = xyz_to_lin_srgb(x, y, z);
        rgb_to_hwb(linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b))
      }
      ColorSpace::DisplayP3 => {
        let (r, g, b) = xyz_to_lin_p3(x, y, z);
        (linear_to_srgb(r), linear_to_srgb(g), linear_to_srgb(b))
      }
      ColorSpace::A98 => {
        let (r, g, b) = xyz_to_lin_a98(x, y, z);
        (linear_to_a98(r), linear_to_a98(g), linear_to_a98(b))
      }
      ColorSpace::ProPhoto => {
        let (x, y, z) = d65_to_d50(x, y, z);
        let (r, g, b) = xyz_d50_to_lin_prophoto(x, y, z);
        (linear_to_prophoto(r), linear_to_prophoto(g), linear_to_prophoto(b))
      }
      ColorSpace::Rec2020 => {
        let (r, g, b) = xyz_to_lin_2020(x, y, z);
        (linear_to_rec2020(r), linear_to_rec2020(g), linear_to_rec2020(b))
      }
      ColorSpace::Lab => {
        let (x, y, z) = d65_to_d50(x, y, z);
        xyz_d50_to_lab(x, y, z)
      }
      ColorSpace::Lch => {
        let (x, y, z) = d65_to_d50(x, y, z);
        let (l, a, b) = xyz_d50_to_lab(x, y, z);
        lab_to_lch(l, a, b)
      }
      ColorSpace::OKLab => xyz_to_oklab(x, y, z),
      ColorSpace::OKLch => {
        let (l, a, b) = xyz_to_oklab(x, y, z);
        lab_to_lch(l, a, b)
      }
    };
    FloatColor { space, a, b, c, alpha }
  }

  pub fn to_space(&self, space: ColorSpace) -> FloatColor {
    if self.space == space {
      return *self;
    }
    // Shortcuts for common conversions that avoid going through XYZ.
    match (self.space, space) {
      (ColorSpace::SRGB, ColorSpace::HSL) => {
        let (h, s, l) = rgb_to_hsl(self.a, self.b, self.c);
        return FloatColor { space, a: h, b: s, c: l, alpha: self.alpha };
      }
      (ColorSpace::SRGB, ColorSpace::HWB) => {
        let (h, w, b) = rgb_to_hwb(self.a, self.b, self.c);
        return FloatColor { space, a: h, b: w, c: b, alpha: self.alpha };
      }
      (ColorSpace::HSL, ColorSpace::SRGB) => {
        let (r, g, b) = hsl_to_rgb(nan_to_zero(self.a), nan_to_zero(self.b), nan_to_zero(self.c));
        return FloatColor { space, a: r, b: g, c: b, alpha: self.alpha };
      }
      (ColorSpace::HWB, ColorSpace::SRGB) => {
        let (r, g, b) = hwb_to_rgb(nan_to_zero(self.a), nan_to_zero(self.b), nan_to_zero(self.c));
        return FloatColor { space, a: r, b: g, c: b, alpha: self.alpha };
      }
      (ColorSpace::Lab, ColorSpace::Lch) | (ColorSpace::OKLab, ColorSpace::OKLch) => {
        let (l, c, h) = lab_to_lch(nan_to_zero(self.a), nan_to_zero(self.b), nan_to_zero(self.c));
        return FloatColor { space, a: l, b: c, c: h, alpha: self.alpha };
      }
      (ColorSpace::Lch, ColorSpace::Lab) | (ColorSpace::OKLch, ColorSpace::OKLab) => {
        let (l, a, b) = lch_to_lab(nan_to_zero(self.a), nan_to_zero(self.b), nan_to_zero(self.c));
        return FloatColor { space, a: l, b: a, c: b, alpha: self.alpha };
      }
      (ColorSpace::SRGB, ColorSpace::SRGBLinear) => {
        return FloatColor {
          space,
          a: srgb_to_linear(self.a),
          b: srgb_to_linear(self.b),
          c: srgb_to_linear(self.c),
          alpha: self.alpha,
        };
      }
      (ColorSpace::SRGBLinear, ColorSpace::SRGB) => {
        return FloatColor {
          space,
          a: linear_to_srgb(self.a),
          b: linear_to_srgb(self.b),
          c: linear_to_srgb(self.c),
          alpha: self.alpha,
        };
      }
      _ => {}
    }
    let (x, y, z) = self.to_xyz_d65();
    FloatColor::from_xyz_d65(space, x, y, z, self.alpha)
  }
}

pub fn srgb_to_linear(c: f32) -> f32 {
  let abs = c.abs();
  if abs <= 0.04045 {
    c / 12.92
  } else {
    c.signum() * ((abs + 0.055) / 1.055).powf(2.4)
  }
}

pub fn linear_to_srgb(c: f32) -> f32 {
  let abs = c.abs();
  if abs > 0.0031308 {
    c.signum() * (1.055 * abs.powf(1.0 / 2.4) - 0.055)
  } else {
    12.92 * c
  }
}

fn a98_to_linear(c: f32) -> f32 {
  c.signum() * c.abs().powf(563.0 / 256.0)
}

fn linear_to_a98(c: f32) -> f32 {
  c.signum() * c.abs().powf(256.0 / 563.0)
}

fn prophoto_to_linear(c: f32) -> f32 {
  let et2 = 16.0 / 512.0;
  if c.abs() <= et2 {
    c / 16.0
  } else {
    c.signum() * c.abs().powf(1.8)
  }
}

fn linear_to_prophoto(c: f32) -> f32 {
  let et = 1.0 / 512.0;
  if c.abs() >= et {
    c.signum() * c.abs().powf(1.0 / 1.8)
  } else {
    16.0 * c
  }
}

fn rec2020_to_linear(c: f32) -> f32 {
  let alpha = 1.09929682680944;
  let beta = 0.018053968510807;
  if c.abs() < beta * 4.5 {
    c / 4.5
  } else {
    c.signum() * ((c.abs() + alpha - 1.0) / alpha).powf(1.0 / 0.45)
  }
}

fn linear_to_rec2020(c: f32) -> f32 {
  let alpha = 1.09929682680944;
  let beta = 0.018053968510807;
  if c.abs() > beta {
    c.signum() * (alpha * c.abs().powf(0.45) - (alpha - 1.0))
  } else {
    4.5 * c
  }
}

fn mul3(m: &[[f32; 3]; 3], a: f32, b: f32, c: f32) -> (f32, f32, f32) {
  (
    m[0][0] * a + m[0][1] * b + m[0][2] * c,
    m[1][0] * a + m[1][1] * b + m[1][2] * c,
    m[2][0] * a + m[2][1] * b + m[2][2] * c,
  )
}

