const D50: [f32; 3] = [0.3457 / 0.3585, 1.00000, (1.0 - 0.3457 - 0.3585) / 0.3585];

fn xyz_d50_to_lab(x: f32, y: f32, z: f32) -> (f32, f32, f32) {
  let e: f32 = 216.0 / 24389.0;
  let k: f32 = 24389.0 / 27.0;
  let xyz = [x / D50[0], y / D50[1], z / D50[2]];
  let f: Vec<f32> = xyz
    .iter()
    .map(|v| if *v > e { v.cbrt() } else { (k * v + 16.0) / 116.0 })
    .collect();
  (116.0 * f[1] - 16.0, 500.0 * (f[0] - f[1]), 200.0 * (f[1] - f[2]))
}

fn lab_to_xyz_d50(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
  let k: f32 = 24389.0 / 27.0;
  let e: f32 = 216.0 / 24389.0;
  let f1 = (l + 16.0) / 116.0;
  let f0 = a / 500.0 + f1;
  let f2 = f1 - b / 200.0;
  let x = if f0.powi(3) > e { f0.powi(3) } else { (116.0 * f0 - 16.0) / k };
  let y = if l > k * e { ((l + 16.0) / 116.0).powi(3) } else { l / k };
  let z = if f2.powi(3) > e { f2.powi(3) } else { (116.0 * f2 - 16.0) / k };
  (x * D50[0], y * D50[1], z * D50[2])
}

fn lab_to_lch(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
  let hue = b.atan2(a) * 180.0 / PI;
  let hue = if hue >= 0.0 { hue } else { hue + 360.0 };
  (l, (a * a + b * b).sqrt(), hue)
}

fn lch_to_lab(l: f32, c: f32, h: f32) -> (f32, f32, f32) {
  (l, c * (h * PI / 180.0).cos(), c * (h * PI / 180.0).sin())
}

fn xyz_to_oklab(x: f32, y: f32, z: f32) -> (f32, f32, f32) {
  let (l, m, s) = mul3(
    &[
      [0.8190224379967030, 0.3619062600528904, -0.1288737815209879],
      [0.0329836539323885, 0.9292868615863434, 0.0361446663506424],
      [0.0481771893596242, 0.2642395317527308, 0.6335478284694309],
    ],
    x,
    y,
    z,
  );
  mul3(
    &[
      [0.2104542683093140, 0.7936177747023054, -0.0040720430116193],
      [1.9779985324311684, -2.4285922420485799, 0.4505937096174110],
      [0.0259040424655478, 0.7827717124575296, -0.8086757549230774],
    ],
    l.cbrt(),
    m.cbrt(),
    s.cbrt(),
  )
}

fn oklab_to_xyz(l: f32, a: f32, b: f32) -> (f32, f32, f32) {
  let (l, m, s) = mul3(
    &[
      [1.0000000000000000, 0.3963377773761749, 0.2158037573099136],
      [1.0000000000000000, -0.1055613458156586, -0.0638541728258133],
      [1.0000000000000000, -0.0894841775298119, -1.2914855480194092],
    ],
    l,
    a,
    b,
  );
  mul3(
    &[
      [1.2268798758459243, -0.5578149944602171, 0.2813910456659647],
      [-0.0405757452148008, 1.1122868032803170, -0.0717110580655164],
      [-0.0763729366746601, -0.4214933324022432, 1.5869240198367816],
    ],
    l.powi(3),
    m.powi(3),
    s.powi(3),
  )
}

pub fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
  let h = h.rem_euclid(360.0) / 360.0;
  let t2 = if l <= 0.5 { l * (s + 1.0) } else { l + s - l * s };
  let t1 = l * 2.0 - t2;
  let hue_to_rgb = |mut h: f32| -> f32 {
    if h < 0.0 {
      h += 1.0;
    }
    if h > 1.0 {
      h -= 1.0;
    }
    if h * 6.0 < 1.0 {
      t1 + (t2 - t1) * h * 6.0
    } else if h * 2.0 < 1.0 {
      t2
    } else if h * 3.0 < 2.0 {
      t1 + (t2 - t1) * (2.0 / 3.0 - h) * 6.0
    } else {
      t1
    }
  };
  (hue_to_rgb(h + 1.0 / 3.0), hue_to_rgb(h), hue_to_rgb(h - 1.0 / 3.0))
}

pub fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
  let max = r.max(g).max(b);
  let min = r.min(g).min(b);
  let mut h = f32::NAN;
  let mut s = 0.0;
  let l = (min + max) / 2.0;
  let d = max - min;
  if d != 0.0 {
    s = if l == 0.0 || l == 1.0 { 0.0 } else { (max - l) / l.min(1.0 - l) };
    if max == r {
      h = (g - b) / d + (if g < b { 6.0 } else { 0.0 });
    } else if max == g {
      h = (b - r) / d + 2.0;
    } else {
      h = (r - g) / d + 4.0;
    }
    h *= 60.0;
  }
  (h, s, l)
}

pub fn hwb_to_rgb(h: f32, w: f32, b: f32) -> (f32, f32, f32) {
  if w + b >= 1.0 {
    let gray = w / (w + b);
    return (gray, gray, gray);
  }
  let (r, g, bb) = hsl_to_rgb(h, 1.0, 0.5);
  let f = |c: f32| c * (1.0 - w - b) + w;
  (f(r), f(g), f(bb))
}

pub fn rgb_to_hwb(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
  let (h, _, _) = rgb_to_hsl(r, g, b);
  let white = r.min(g).min(b);
  let black = 1.0 - r.max(g).max(b);
  (h, white, black)
}

// ---------------------------------------------------------------------------
// Serialization

fn write_component(v: f32, dest: &mut Printer) -> PrintResult {
  if v.is_nan() {
    dest.write_str("none")
  } else {
    serialize_number(v, dest)
  }
}

fn write_percent_component(v: f32, dest: &mut Printer) -> PrintResult {
  if v.is_nan() {
    dest.write_str("none")
  } else {
    crate::values::number::serialize_percentage(v, dest)
  }
}

impl ToCss for FloatColor {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self.space {
      ColorSpace::SRGB | ColorSpace::HSL | ColorSpace::HWB => {
        // Convert to RGBA
        let srgb = self.to_space(ColorSpace::SRGB);
        RGBA::from_floats(
          nan_to_zero(srgb.a),
          nan_to_zero(srgb.b),
          nan_to_zero(srgb.c),
          nan_to_zero(srgb.alpha),
        )
        .to_css(dest)
      }
      ColorSpace::Lab | ColorSpace::Lch | ColorSpace::OKLab | ColorSpace::OKLch => {
        let (name, l_scale) = match self.space {
          ColorSpace::Lab => ("lab(", 1.0),
          ColorSpace::Lch => ("lch(", 1.0),
          ColorSpace::OKLab => ("oklab(", 100.0),
          _ => ("oklch(", 100.0),
        };
        dest.write_str(name)?;
        if self.a.is_nan() {
          dest.write_str("none")?;
        } else {
          crate::values::number::serialize_percentage(self.a * l_scale / 100.0, dest)?;
        }
        dest.write_char(' ')?;
        write_component(self.b, dest)?;
        dest.write_char(' ')?;
        write_component(self.c, dest)?;
        write_alpha(self.alpha, dest)?;
        dest.write_char(')')
      }
      _ => {
        let name = match self.space {
          ColorSpace::SRGBLinear => "srgb-linear",
          ColorSpace::DisplayP3 => "display-p3",
          ColorSpace::A98 => "a98-rgb",
          ColorSpace::ProPhoto => "prophoto-rgb",
          ColorSpace::Rec2020 => "rec2020",
          ColorSpace::XYZd50 => "xyz-d50",
          ColorSpace::XYZd65 => "xyz",
          _ => unreachable!(),
        };
        dest.write_str("color(")?;
        dest.write_str(name)?;
        dest.write_char(' ')?;
        write_component(self.a, dest)?;
        dest.write_char(' ')?;
        write_component(self.b, dest)?;
        dest.write_char(' ')?;
        write_component(self.c, dest)?;
        write_alpha(self.alpha, dest)?;
        dest.write_char(')')
      }
    }
  }
}

fn write_alpha(alpha: f32, dest: &mut Printer) -> PrintResult {
  if alpha.is_nan() {
    dest.delim('/', true)?;
    return dest.write_str("none");
  }
  if alpha != 1.0 {
    dest.delim('/', true)?;
    serialize_number(alpha, dest)?;
  }
  Ok(())
}

pub fn _unused(_: &dyn Fn(f32) -> f32) {
  let _ = write_percent_component;
}
