/// A CSS color value.
#[derive(Clone, Debug, PartialEq)]
pub enum CssColor {
  CurrentColor,
  RGBA(RGBA),
  Float(FloatColor),
  LightDark(Box<CssColor>, Box<CssColor>),
  System(SystemColor),
}

impl CssColor {
  pub fn current_color() -> Self {
    CssColor::CurrentColor
  }

  pub fn transparent() -> Self {
    CssColor::RGBA(RGBA::transparent())
  }

  pub fn is_transparent(&self) -> bool {
    matches!(self, CssColor::RGBA(RGBA { alpha: 0, .. }))
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let token = input.next()?;
    match token {
      Token::Hash(ref value) | Token::IDHash(ref value) => {
        parse_hash(value.as_bytes()).map(|rgba| CssColor::RGBA(rgba)).map_err(|()| location.new_unexpected_token_error(token.clone()))
      }
      Token::Ident(ref value) => parse_color_keyword(value).ok_or_else(|| location.new_unexpected_token_error(token.clone())),
      Token::Function(ref name) => {
        let name = name.clone();
        input.parse_nested_block(|input| parse_color_function(location, &name, input))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  /// Converts the color to RGBA (sRGB, 8-bit) if possible.
  pub fn to_rgb(&self) -> Option<RGBA> {
    match self {
      CssColor::RGBA(rgba) => Some(*rgba),
      CssColor::Float(f) => {
        let srgb = f.to_space(ColorSpace::SRGB);
        Some(RGBA::from_floats(
          nan_to_zero(srgb.a),
          nan_to_zero(srgb.b),
          nan_to_zero(srgb.c),
          nan_to_zero(srgb.alpha),
        ))
      }
      _ => None,
    }
  }

  pub fn to_float(&self) -> Option<FloatColor> {
    match self {
      CssColor::RGBA(rgba) => Some(FloatColor {
        space: ColorSpace::SRGB,
        a: rgba.red_f32(),
        b: rgba.green_f32(),
        c: rgba.blue_f32(),
        alpha: rgba.alpha_f32(),
      }),
      CssColor::Float(f) => Some(*f),
      _ => None,
    }
  }
}

