pub fn hsl_to_rgb(h: f32, s: f32, l: f32) -> (f32, f32, f32) {
  let h = h.rem_euclid(360.0) / 360.0;
  let t2 = if l <= 0.5 { l * (s + 1.0) } else { l + s - l * s };
  let t1 = l * 2.0 - t2;
  let hue_to_rgb = |mut h: f32| -> f32 {
    if h < 0.0 {
      h += 1.0;
    }
    if h > 1.0 {
      h -= 1.0;
    }
    if h * 6.0 < 1.0 {
      t1 + (t2 - t1) * h * 6.0
    } else if h * 2.0 < 1.0 {
      t2
    } else if h * 3.0 < 2.0 {
      t1 + (t2 - t1) * (2.0 / 3.0 - h) * 6.0
    } else {
      t1
    }
  };
  (hue_to_rgb(h + 1.0 / 3.0), hue_to_rgb(h), hue_to_rgb(h - 1.0 / 3.0))
}

pub fn rgb_to_hsl(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
  let max = r.max(g).max(b);
  let min = r.min(g).min(b);
  let mut h = f32::NAN;
  let mut s = 0.0;
  let l = (min + max) / 2.0;
  let d = max - min;
  if d != 0.0 {
    s = if l == 0.0 || l == 1.0 { 0.0 } else { (max - l) / l.min(1.0 - l) };
    if max == r {
      h = (g - b) / d + (if g < b { 6.0 } else { 0.0 });
    } else if max == g {
      h = (b - r) / d + 2.0;
    } else {
      h = (r - g) / d + 4.0;
    }
    h *= 60.0;
  }
  (h, s, l)
}

pub fn hwb_to_rgb(h: f32, w: f32, b: f32) -> (f32, f32, f32) {
  if w + b >= 1.0 {
    let gray = w / (w + b);
    return (gray, gray, gray);
  }
  let (r, g, bb) = hsl_to_rgb(h, 1.0, 0.5);
  let f = |c: f32| c * (1.0 - w - b) + w;
  (f(r), f(g), f(bb))
}

pub fn rgb_to_hwb(r: f32, g: f32, b: f32) -> (f32, f32, f32) {
  let (h, _, _) = rgb_to_hsl(r, g, b);
  let white = r.min(g).min(b);
  let black = 1.0 - r.max(g).max(b);
  (h, white, black)
}

