fn write_component(v: f32, dest: &mut Printer) -> PrintResult {
  if v.is_nan() {
    dest.write_str("none")
  } else {
    serialize_number(v, dest)
  }
}

fn write_percent_component(v: f32, dest: &mut Printer) -> PrintResult {
  if v.is_nan() {
    dest.write_str("none")
  } else {
    crate::values::number::serialize_percentage(v, dest)
  }
}

impl ToCss for FloatColor {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self.space {
      ColorSpace::SRGB | ColorSpace::HSL | ColorSpace::HWB => {
        // Convert to RGBA
        let srgb = self.to_space(ColorSpace::SRGB);
        RGBA::from_floats(
          nan_to_zero(srgb.a),
          nan_to_zero(srgb.b),
          nan_to_zero(srgb.c),
          nan_to_zero(srgb.alpha),
        )
        .to_css(dest)
      }
      ColorSpace::Lab | ColorSpace::Lch | ColorSpace::OKLab | ColorSpace::OKLch => {
        let (name, l_scale) = match self.space {
          ColorSpace::Lab => ("lab(", 1.0),
          ColorSpace::Lch => ("lch(", 1.0),
          ColorSpace::OKLab => ("oklab(", 100.0),
          _ => ("oklch(", 100.0),
        };
        dest.write_str(name)?;
        if self.a.is_nan() {
          dest.write_str("none")?;
        } else {
          crate::values::number::serialize_percentage(self.a * l_scale / 100.0, dest)?;
        }
        dest.write_char(' ')?;
        write_component(self.b, dest)?;
        dest.write_char(' ')?;
        write_component(self.c, dest)?;
        write_alpha(self.alpha, dest)?;
        dest.write_char(')')
      }
      _ => {
        let name = match self.space {
          ColorSpace::SRGBLinear => "srgb-linear",
          ColorSpace::DisplayP3 => "display-p3",
          ColorSpace::A98 => "a98-rgb",
          ColorSpace::ProPhoto => "prophoto-rgb",
          ColorSpace::Rec2020 => "rec2020",
          ColorSpace::XYZd50 => "xyz-d50",
          ColorSpace::XYZd65 => "xyz",
          _ => unreachable!(),
        };
        dest.write_str("color(")?;
        dest.write_str(name)?;
        dest.write_char(' ')?;
        write_component(self.a, dest)?;
        dest.write_char(' ')?;
        write_component(self.b, dest)?;
        dest.write_char(' ')?;
        write_component(self.c, dest)?;
        write_alpha(self.alpha, dest)?;
        dest.write_char(')')
      }
    }
  }
}

fn write_alpha(alpha: f32, dest: &mut Printer) -> PrintResult {
  if alpha.is_nan() {
    dest.delim('/', true)?;
    return dest.write_str("none");
  }
  if alpha != 1.0 {
    dest.delim('/', true)?;
    serialize_number(alpha, dest)?;
  }
  Ok(())
}

pub fn _unused(_: &dyn Fn(f32) -> f32) {
  let _ = write_percent_component;
}
