/// A trait for values that can appear in calc().
pub trait CalcValue: Sized + Clone + PartialEq + std::fmt::Debug + ToCss {
  /// Parse a plain (non-calc) value.
  fn parse_value<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self>;
  /// Add two values if they have compatible units.
  fn try_add(&self, other: &Self) -> Option<Self>;
  fn mul_f32(self, f: f32) -> Self;
  fn is_sign_negative(&self) -> bool;
  fn is_sign_positive(&self) -> bool;
  fn is_zero(&self) -> bool;
  fn cmp_value(&self, other: &Self) -> Option<Ordering>;
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self>;
  fn try_map(&self, op: &dyn Fn(f32) -> f32) -> Option<Self>;
  fn try_sign(&self) -> Option<f32>;
  /// Wrap a calc expression in this type.
