  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Calc<V> {
  Value(Box<V>),
  Number(f32),
  Sum(Box<Calc<V>>, Box<Calc<V>>),
  Product(f32, Box<Calc<V>>),
  Function(Box<MathFunction<V>>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum MathFunction<V> {
  Calc(Calc<V>),
  Min(Vec<Calc<V>>),
  Max(Vec<Calc<V>>),
  Clamp(Calc<V>, Calc<V>, Calc<V>),
  Round(RoundingStrategy, Calc<V>, Calc<V>),
  Rem(Calc<V>, Calc<V>),
  Mod(Calc<V>, Calc<V>),
  Abs(Calc<V>),
  Sign(Calc<V>),
  Hypot(Vec<Calc<V>>),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum RoundingStrategy {
  Nearest,
  Up,
  Down,
  ToZero,
}

impl RoundingStrategy {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "nearest" => Ok(RoundingStrategy::Nearest),
      "up" => Ok(RoundingStrategy::Up),
      "down" => Ok(RoundingStrategy::Down),
      "to-zero" => Ok(RoundingStrategy::ToZero),
      _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
    }
  }

  fn as_str(&self) -> &'static str {
    match self {
      RoundingStrategy::Nearest => "nearest",
      RoundingStrategy::Up => "up",
      RoundingStrategy::Down => "down",
      RoundingStrategy::ToZero => "to-zero",
    }
  }
}

fn round(value: f32, to: f32, strategy: RoundingStrategy) -> f32 {
  let v = value / to;
  match strategy {
    RoundingStrategy::Down => v.floor() * to,
    RoundingStrategy::Up => v.ceil() * to,
    RoundingStrategy::Nearest => v.round() * to,
    RoundingStrategy::ToZero => v.trunc() * to,
  }
}

fn rem(a: f32, b: f32) -> f32 {
  a % b
}

fn modulo(a: f32, b: f32) -> f32 {
  ((a % b) + b) % b
}

fn parse_constant(name: &str) -> Option<f32> {
  match name.to_ascii_lowercase().as_str() {
    "pi" => Some(std::f32::consts::PI),
    "e" => Some(std::f32::consts::E),
    "infinity" => Some(f32::INFINITY),
    "-infinity" => Some(f32::NEG_INFINITY),
    "nan" => Some(f32::NAN),
    _ => None,
  }
}

impl<V: CalcValue> Calc<V> {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let f = input.expect_function()?;
    match f.to_ascii_lowercase().as_str() {
      "calc" => {
        let calc = input.parse_nested_block(|input| Calc::parse_sum(input))?;
        match calc {
          Calc::Value(_) | Calc::Number(_) => Ok(calc),
          Calc::Function(ref func) if matches!(**func, MathFunction::Calc(_)) => Ok(calc),
          _ => Ok(Calc::Function(Box::new(MathFunction::Calc(calc)))),
        }
      }
      "min" => {
        let mut args = input.parse_nested_block(|input| input.parse_comma_separated(|input| Calc::parse_sum(input)))?;
        let mut reduced = Calc::reduce_args(&mut args, Ordering::Less);
        if reduced.len() == 1 {
          return Ok(reduced.remove(0));
        }
        Ok(Calc::Function(Box::new(MathFunction::Min(reduced))))
      }
      "max" => {
        let mut args = input.parse_nested_block(|input| input.parse_comma_separated(|input| Calc::parse_sum(input)))?;
        let mut reduced = Calc::reduce_args(&mut args, Ordering::Greater);
        if reduced.len() == 1 {
          return Ok(reduced.remove(0));
        }
        Ok(Calc::Function(Box::new(MathFunction::Max(reduced))))
      }
      "clamp" => {
        let (mut min, mut center, mut max) = input.parse_nested_block(|input| {
          let min = Some(Calc::parse_sum(input)?);
          input.expect_comma()?;
          let center: Calc<V> = Calc::parse_sum(input)?;
          input.expect_comma()?;
          let max = Some(Calc::parse_sum(input)?);
          Ok((min, center, max))
        })?;

        // According to the spec, the minimum should "win" over the maximum if they are in the wrong order.
        let cmp = if let (Some(Calc::Value(max_val)), Calc::Value(center_val)) = (&max, &center) {
          center_val.cmp_value(max_val)
        } else {
          None
        };

        // If center is known to be greater than the maximum, replace it with maximum and remove the max argument.
        // Otherwise, if center is known to be less than the maximum, remove the max argument.
        match cmp {
          Some(Ordering::Greater) => {
            center = std::mem::take(&mut max).unwrap();
          }
          Some(_) => {
            max = None;
          }
          None => {}
        }

        let cmp = if let (Some(Calc::Value(min_val)), Calc::Value(center_val)) = (&min, &center) {
          center_val.cmp_value(min_val)
        } else {
          None
        };

        // If center is known to be less than the minimum, replace it with minimum and remove the min argument.
        // Otherwise, if center is known to be greater than the minimum, remove the min argument.
        match cmp {
          Some(Ordering::Less) => {
            center = std::mem::take(&mut min).unwrap();
          }
          Some(_) => {
            min = None;
          }
          None => {}
        }

        // Generate clamp(), min(), max(), or value depending on which arguments are left.
        match (min, max) {
          (None, None) => Ok(center),
          (Some(min), None) => Ok(Calc::Function(Box::new(MathFunction::Max(vec![min, center])))),
          (None, Some(max)) => Ok(Calc::Function(Box::new(MathFunction::Min(vec![center, max])))),
          (Some(min), Some(max)) => Ok(Calc::Function(Box::new(MathFunction::Clamp(min, center, max)))),
        }
      }
      "round" => {
        input.parse_nested_block(|input| {
          let strategy = if let Ok(s) = input.try_parse(RoundingStrategy::parse) {
            input.expect_comma()?;
            s
          } else {
            RoundingStrategy::Nearest
          };
          let a: Calc<V> = Calc::parse_sum(input)?;
          input.expect_comma()?;
          let b: Calc<V> = Calc::parse_sum(input)?;
          if let (Calc::Value(a), Calc::Value(b)) = (&a, &b) {
            if let Some(v) = a.try_op(b, &|a, b| round(a, b, strategy)) {
              return Ok(Calc::Value(Box::new(v)));
            }
          } else if let (Calc::Number(a), Calc::Number(b)) = (&a, &b) {
            return Ok(Calc::Number(round(*a, *b, strategy)));
          }
          Ok(Calc::Function(Box::new(MathFunction::Round(strategy, a, b))))
        })
      }
      "rem" => {
        input.parse_nested_block(|input| {
          let a: Calc<V> = Calc::parse_sum(input)?;
          input.expect_comma()?;
          let b: Calc<V> = Calc::parse_sum(input)?;
          if let (Calc::Value(a), Calc::Value(b)) = (&a, &b) {
            if let Some(v) = a.try_op(b, &rem) {
              return Ok(Calc::Value(Box::new(v)));
            }
          } else if let (Calc::Number(a), Calc::Number(b)) = (&a, &b) {
            return Ok(Calc::Number(rem(*a, *b)));
          }
          Ok(Calc::Function(Box::new(MathFunction::Rem(a, b))))
        })
      }
      "mod" => {
        input.parse_nested_block(|input| {
          let a: Calc<V> = Calc::parse_sum(input)?;
          input.expect_comma()?;
          let b: Calc<V> = Calc::parse_sum(input)?;
          if let (Calc::Value(a), Calc::Value(b)) = (&a, &b) {
            if let Some(v) = a.try_op(b, &modulo) {
              return Ok(Calc::Value(Box::new(v)));
            }
          } else if let (Calc::Number(a), Calc::Number(b)) = (&a, &b) {
            return Ok(Calc::Number(modulo(*a, *b)));
          }
          Ok(Calc::Function(Box::new(MathFunction::Mod(a, b))))
        })
      }
      "abs" => {
        input.parse_nested_block(|input| {
          let v: Calc<V> = Calc::parse_sum(input)?;
          Ok(match v {
            Calc::Value(v) => match v.try_map(&f32::abs) {
              Some(r) => Calc::Value(Box::new(r)),
              None => Calc::Function(Box::new(MathFunction::Abs(Calc::Value(v)))),
            },
            Calc::Number(n) => Calc::Number(n.abs()),
            v => Calc::Function(Box::new(MathFunction::Abs(v))),
          })
        })
      }
      "sign" => {
        input.parse_nested_block(|input| {
          let v: Calc<V> = Calc::parse_sum(input)?;
          match &v {
            Calc::Number(n) => return Ok(Calc::Number(n.signum_zero())),
            Calc::Value(v) => {
              if let Some(s) = v.try_sign() {
                return Ok(Calc::Number(s));
              }
            }
            _ => {}
          }
          Ok(Calc::Function(Box::new(MathFunction::Sign(v))))
        })
      }
      "hypot" => {
        let mut args = input.parse_nested_block(|input| input.parse_comma_separated(|input| Calc::parse_sum(input)))?;
        if let Some(v) = Calc::parse_hypot(&mut args)? {
          return Ok(v);
        }
        Ok(Calc::Function(Box::new(MathFunction::Hypot(args))))
      }
      _ => Err(location.new_unexpected_token_error(Token::Ident(f))),
    }
  }

  fn parse_hypot<'i>(args: &mut Vec<Calc<V>>) -> ParseResult<'i, Option<Calc<V>>> {
    if args.len() == 1 {
      return Ok(Some(args.remove(0)));
    }
    if args.len() == 2 {
      if let (Calc::Value(a), Calc::Value(b)) = (&args[0], &args[1]) {
        if let Some(v) = a.try_op(b, &|a, b| a.hypot(b)) {
          return Ok(Some(Calc::Value(Box::new(v))));
        }
      } else if let (Calc::Number(a), Calc::Number(b)) = (&args[0], &args[1]) {
        return Ok(Some(Calc::Number(a.hypot(*b))));
      }
      return Ok(None);
    }
    let mut i = 0;
    let first = match &args[0] {
      Calc::Value(v) => match v.try_map(&|v| v.powi(2)) {
        Some(v) => v,
        None => return Ok(None),
      },
      _ => return Ok(None),
    };
    let mut sum = first;
    i += 1;
    while i < args.len() {
      let v = match &args[i] {
        Calc::Value(v) => match sum.try_op(v, &|a, b| a + b.powi(2)) {
          Some(v) => v,
          None => return Ok(None),
        },
        _ => return Ok(None),
      };
      sum = v;
      i += 1;
    }
    match sum.try_map(&f32::sqrt) {
      Some(v) => Ok(Some(Calc::Value(Box::new(v)))),
      None => Ok(None),
    }
  }

  fn reduce_args(args: &mut Vec<Calc<V>>, cmp: Ordering) -> Vec<Calc<V>> {
    let mut reduced: Vec<Calc<V>> = vec![];
    for arg in args.drain(..) {
      let mut found: Option<Option<usize>> = None;
      match &arg {
        Calc::Value(val) => {
          for (i, b) in reduced.iter().enumerate() {
            if let Calc::Value(v) = b {
              match val.cmp_value(v) {
                Some(ord) if ord == cmp => {
                  found = Some(Some(i));
                  break;
                }
                Some(_) => {
                  found = Some(None);
                  break;
                }
                None => {}
              }
            }
          }
        }
        Calc::Number(val) => {
          for (i, b) in reduced.iter().enumerate() {
            if let Calc::Number(v) = b {
              match val.partial_cmp(v) {
                Some(ord) if ord == cmp => {
                  found = Some(Some(i));
                  break;
                }
                Some(_) => {
                  found = Some(None);
                  break;
                }
                None => {}
              }
            }
          }
        }
        _ => {}
      }
      if let Some(r) = found {
        if let Some(i) = r {
          reduced[i] = arg;
        }
      } else {
        reduced.push(arg);
      }
    }
    reduced
  }

  pub fn parse_sum<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut cur: Calc<V> = Calc::parse_product(input)?;
    loop {
      let start = input.state();
      match input.next_including_whitespace() {
        Ok(Token::WhiteSpace(_)) => {
          if input.is_exhausted() {
            break; // allow trailing whitespace
          }
          match input.next()? {
            Token::Delim('+') => {
              let next = Calc::parse_product(input)?;
              cur = cur.add(next);
            }
            Token::Delim('-') => {
              let mut rhs = Calc::parse_product(input)?;
              rhs = rhs.mul(-1.0);
              cur = cur.add(rhs);
            }
            t => return Err(input.new_unexpected_token_error(t)),
          }
        }
        _ => {
          input.reset(&start);
          break;
        }
      }
    }
    Ok(cur)
  }

  fn parse_product<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut node = Calc::parse_value(input)?;
    loop {
      let start = input.state();
      match input.next() {
        Ok(Token::Delim('*')) => {
          // At least one of the operands must be a number.
          let rhs = Self::parse_value(input)?;
          if let Calc::Number(val) = rhs {
            node = node.mul(val);
          } else if let Calc::Number(val) = node {
            node = rhs;
            node = node.mul(val);
          } else {
            return Err(input.new_unexpected_token_error(Token::Delim('*')));
          }
        }
        Ok(Token::Delim('/')) => {
          let rhs = Self::parse_value(input)?;
          if let Calc::Number(val) = rhs {
            if val != 0.0 {
              node = node.mul(1.0 / val);
              continue;
            }
          }
          return Err(input.new_custom_error(ParserError::InvalidValue));
        }
        _ => {
          input.reset(&start);
          break;
        }
      }
    }
    Ok(node)
  }

  fn parse_value<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    // Parse nested calc() and other math functions.
    if let Ok(calc) = input.try_parse(|input| Self::parse(input)) {
      match calc {
        Calc::Function(f) => {
          return Ok(match *f {
            MathFunction::Calc(c) => c,
            _ => Calc::Function(f),
          })
        }
        c => return Ok(c),
      }
    }

    if input.try_parse(|input| input.expect_parenthesis_block()).is_ok() {
      return input.parse_nested_block(|input| Calc::parse_sum(input));
    }

    if let Ok(num) = input.try_parse(|input| input.expect_number()) {
      return Ok(Calc::Number(num));
    }

    if let Ok(constant) = input.try_parse(|input| {
      let loc = input.current_source_location();
      let ident = input.expect_ident()?;
      match parse_constant(&ident) {
        Some(c) => Ok(c),
        None => Err(loc.new_unexpected_token_error::<ParserError>(Token::Ident(ident))),
      }
    }) {
      return Ok(Calc::Number(constant));
    }

    if let Ok(value) = input.try_parse(V::parse_value) {
      return Ok(Calc::Value(Box::new(value)));
    }

    Err(input.new_error_for_next_token())
  }

  pub fn add(self, other: Calc<V>) -> Calc<V> {
    match (self, other) {
      (Calc::Value(a), Calc::Value(b)) => add_values(*a, *b).into_calc(),
      (Calc::Number(a), Calc::Number(b)) => Calc::Number(a + b),
      (Calc::Value(a), Calc::Number(b)) => match V::from_number(b) {
        Some(b) => add_values(*a, b).into_calc(),
        None => Calc::Sum(Box::new(Calc::Value(a)), Box::new(Calc::Number(b))),
      },
      (Calc::Number(a), Calc::Value(b)) => match V::from_number(a) {
        Some(a) => add_values(a, *b).into_calc(),
        None => Calc::Sum(Box::new(Calc::Number(a)), Box::new(Calc::Value(b))),
      },
      (Calc::Value(a), b) => add_values(*a, V::from_calc(b)).into_calc(),
      (a, Calc::Value(b)) => add_values(V::from_calc(a), *b).into_calc(),
      (Calc::Function(a), b) => Calc::Sum(Box::new(Calc::Function(a)), Box::new(b)),
      (a, Calc::Function(b)) => Calc::Sum(Box::new(a), Box::new(Calc::Function(b))),
      (a, b) => add_values(V::from_calc(a), V::from_calc(b)).into_calc(),
    }
  }

  pub fn mul(self, other: f32) -> Self {
    if other == 1.0 {
      return self;
    }
    match self {
      Calc::Value(v) => Calc::Value(Box::new(v.mul_f32(other))),
      Calc::Number(n) => Calc::Number(n * other),
      Calc::Sum(a, b) => Calc::Sum(Box::new(a.mul(other)), Box::new(b.mul(other))),
      Calc::Product(num, calc) => {
        let num = num * other;
        if num == 1.0 {
          return *calc;
        }
        Calc::Product(num, calc)
      }
      Calc::Function(f) => match *f {
        MathFunction::Calc(c) => Calc::Function(Box::new(MathFunction::Calc(c.mul(other)))),
        _ => Calc::Product(other, Box::new(Calc::Function(f))),
      },
    }
  }

  pub fn is_sign_negative(&self) -> bool {
    match self {
      Calc::Number(n) => *n < 0.0,
      Calc::Value(v) => v.is_sign_negative(),
      Calc::Product(n, _) => *n < 0.0,
      _ => false,
    }
  }
}

trait SignumZero {
  fn signum_zero(self) -> f32;
}
impl SignumZero for f32 {
  fn signum_zero(self) -> f32 {
    if self == 0.0 {
      0.0
    } else {
      self.signum()
    }
  }
}

fn unwrap_calc<V: CalcValue>(v: V) -> V {
  if let Some(c) = v.as_calc() {
    if let Calc::Function(f) = c {
      if let MathFunction::Calc(inner) = &**f {
        return V::from_calc(inner.clone());
      }
    }
  }
  v
}

/// Adds two values, combining compatible terms.
pub fn add_values<V: CalcValue>(a: V, b: V) -> V {
  if a.is_zero() {
    return b;
  }
  if b.is_zero() {
    return a;
  }
  let (a, b) = if a.is_sign_negative() && b.is_sign_positive() {
    (b, a)
  } else {
    (a, b)
  };
  let a = unwrap_calc(a);
  let b = unwrap_calc(b);
  let res = match add_recursive(&a, &b) {
    Some(r) => r,
    None => V::from_calc(Calc::Sum(Box::new(a.into_calc()), Box::new(b.into_calc()))),
  };
  match res.as_calc() {
    Some(Calc::Value(l)) => (**l).clone(),
    Some(Calc::Function(f)) if !matches!(**f, MathFunction::Calc(_)) => res,
    Some(c) => V::from_calc(Calc::Function(Box::new(MathFunction::Calc(c.clone())))),
    None => res,
  }
}

fn add_recursive<V: CalcValue>(a: &V, b: &V) -> Option<V> {
  match (a.as_calc(), b.as_calc()) {
    (None, None) => a.try_add(b),
    (Some(ca), _) => match ca {
      Calc::Value(v) => add_recursive(v, b),
      Calc::Sum(a1, a2) => {
        let a1v = V::from_calc((**a1).clone());
        let a2v = V::from_calc((**a2).clone());
        if let Some(res) = add_recursive(&a1v, b) {
          return Some(add_values(res, a2v));
        }
        if let Some(res) = add_recursive(&a2v, b) {
          return Some(add_values(a1v, res));
        }
        None
      }
      _ => None,
    },
    (None, Some(cb)) => match cb {
      Calc::Value(v) => add_recursive(a, v),
      Calc::Sum(b1, b2) => {
        let b1v = V::from_calc((**b1).clone());
        let b2v = V::from_calc((**b2).clone());
        if let Some(res) = add_recursive(a, &b1v) {
          return Some(add_values(res, b2v));
        }
        if let Some(res) = add_recursive(a, &b2v) {
          return Some(add_values(b1v, res));
        }
        None
      }
      _ => None,
    },
  }
}

impl<V: CalcValue> ToCss for Calc<V> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let was_in_calc = dest.in_calc;
    dest.in_calc = true;
    let res = match self {
      Calc::Value(v) => v.to_css(dest),
      Calc::Number(n) => serialize_number(*n, dest),
      Calc::Sum(a, b) => {
        a.to_css(dest)?;
        // White space is always required.
        if b.is_sign_negative() {
          dest.write_str(" - ")?;
          let b = (**b).clone().mul(-1.0);
          b.to_css(dest)?;
        } else {
          dest.write_str(" + ")?;
          b.to_css(dest)?;
        }
        Ok(())
      }
      Calc::Product(num, calc) => {
        if num.abs() < 1.0 {
          let div = 1.0 / num;
          calc.to_css(dest)?;
          dest.delim('/', true)?;
          serialize_number(div, dest)?;
        } else {
          serialize_number(*num, dest)?;
          dest.delim('*', true)?;
          calc.to_css(dest)?;
        }
        Ok(())
      }
      Calc::Function(f) => f.to_css(dest),
    };
    dest.in_calc = was_in_calc;
    res
  }
}

impl<V: CalcValue> ToCss for MathFunction<V> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      MathFunction::Calc(calc) => {
        dest.write_str("calc(")?;
        calc.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Min(args) => {
        dest.write_str("min(")?;
        let mut first = true;
        for arg in args {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          arg.to_css(dest)?;
        }
        dest.write_char(')')
      }
      MathFunction::Max(args) => {
        dest.write_str("max(")?;
        let mut first = true;
        for arg in args {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          arg.to_css(dest)?;
        }
        dest.write_char(')')
      }
      MathFunction::Clamp(a, b, c) => {
        dest.write_str("clamp(")?;
        a.to_css(dest)?;
        dest.delim(',', false)?;
        b.to_css(dest)?;
        dest.delim(',', false)?;
        c.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Round(strategy, a, b) => {
        dest.write_str("round(")?;
        if *strategy != RoundingStrategy::Nearest {
          dest.write_str(strategy.as_str())?;
          dest.delim(',', false)?;
        }
        a.to_css(dest)?;
        dest.delim(',', false)?;
        b.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Rem(a, b) => {
        dest.write_str("rem(")?;
        a.to_css(dest)?;
        dest.delim(',', false)?;
        b.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Mod(a, b) => {
        dest.write_str("mod(")?;
        a.to_css(dest)?;
        dest.delim(',', false)?;
        b.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Abs(v) => {
        dest.write_str("abs(")?;
        v.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Sign(v) => {
        dest.write_str("sign(")?;
        v.to_css(dest)?;
        dest.write_char(')')
      }
      MathFunction::Hypot(args) => {
        dest.write_str("hypot(")?;
        let mut first = true;
        for arg in args {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          arg.to_css(dest)?;
        }
        dest.write_char(')')
      }
    }
  }
}

/// Implements CalcValue for a plain f32 (numbers).
impl CalcValue for f32 {
  fn parse_value<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    match input.next()? {
      Token::Number { value, .. } => Ok(value),
      t => Err(loc.new_unexpected_token_error(t)),
    }
  }
  fn try_add(&self, other: &Self) -> Option<Self> {
    Some(self + other)
  }
  fn mul_f32(self, f: f32) -> Self {
    self * f
  }
  fn is_sign_negative(&self) -> bool {
    *self < 0.0
  }
  fn is_sign_positive(&self) -> bool {
    *self >= 0.0
  }
  fn is_zero(&self) -> bool {
    *self == 0.0
  }
  fn cmp_value(&self, other: &Self) -> Option<Ordering> {
    self.partial_cmp(other)
  }
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self> {
    Some(op(*self, *other))
  }
  fn try_map(&self, op: &dyn Fn(f32) -> f32) -> Option<Self> {
    Some(op(*self))
  }
  fn try_sign(&self) -> Option<f32> {
    Some(self.signum_zero())
  }
  fn from_calc(_c: Calc<Self>) -> Self {
    // Numbers can't contain unresolved calcs; this shouldn't be reached.
    f32::NAN
  }
  fn as_calc(&self) -> Option<&Calc<Self>> {
    None
  }
  fn from_number(n: f32) -> Option<Self> {
    Some(n)
  }
}

impl ToCss for f32 {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    serialize_number(*self, dest)
  }
}
