    match self {
      DimensionPercentage::Dimension(d) => DimensionPercentage::Dimension(d.mul_f32(f)),
      DimensionPercentage::Percentage(p) => DimensionPercentage::Percentage(Percentage(p.0 * f)),
      DimensionPercentage::Calc(c) => DimensionPercentage::Calc(Box::new(c.mul(f))),
