      DimensionPercentage::Percentage(a) => Some(if a.0 == 0.0 { 0.0 } else { a.0.signum() }),
      _ => None,
    }
  }
  fn from_calc(c: Calc<Self>) -> Self {
    match c {
      Calc::Value(v) => *v,
      c => DimensionPercentage::Calc(Box::new(c)),
    }
  }
  fn as_calc(&self) -> Option<&Calc<Self>> {
