//! Length values.

use crate::error::{ParseResult, ParserError};
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::tokenizer::Token;
use crate::values::calc::{Calc, CalcValue};
use crate::values::number::serialize_dimension;
use crate::values::percentage::{Dimension, DimensionPercentage, Percentage};
use std::cmp::Ordering;

pub const PX_PER_IN: f32 = 96.0;
pub const PX_PER_CM: f32 = PX_PER_IN / 2.54;
pub const PX_PER_MM: f32 = PX_PER_CM / 10.0;
pub const PX_PER_Q: f32 = PX_PER_CM / 40.0;
pub const PX_PER_PT: f32 = PX_PER_IN / 72.0;
pub const PX_PER_PC: f32 = PX_PER_IN / 6.0;

macro_rules! define_length_units {
  ($($name: ident => $unit: literal),* $(,)?) => {
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub enum LengthValue {
      $($name(f32),)*
    }

    impl LengthValue {
      pub fn from_unit(value: f32, unit: &str) -> Option<LengthValue> {
        let lower = unit.to_ascii_lowercase();
        match lower.as_str() {
          $($unit => Some(LengthValue::$name(value)),)*
          _ => None,
        }
      }

      pub fn to_unit_value(&self) -> (f32, &'static str) {
        match self {
          $(LengthValue::$name(v) => (*v, $unit),)*
        }
      }

      pub fn map(&self, f: impl Fn(f32) -> f32) -> LengthValue {
        match self {
          $(LengthValue::$name(v) => LengthValue::$name(f(*v)),)*
        }
      }

      pub fn same_unit(&self, other: &LengthValue) -> bool {
        match (self, other) {
          $((LengthValue::$name(_), LengthValue::$name(_)) => true,)*
          _ => false,
        }
      }
    }
  };
}

