impl LengthValue {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    match input.next()? {
      Token::Dimension { value, ref unit, .. } => match LengthValue::from_unit(value, unit) {
        Some(v) => Ok(v),
        None => Err(location.new_unexpected_token_error(Token::Ident(unit.clone()))),
      },
      Token::Number { value, .. } => {
        // TODO: quirks mode only?
        Ok(LengthValue::Px(value))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  pub fn zero() -> Self {
    LengthValue::Px(0.0)
  }

  pub fn is_zero(&self) -> bool {
    self.to_unit_value().0 == 0.0
  }

  pub fn value(&self) -> f32 {
    self.to_unit_value().0
  }

  pub fn to_px(&self) -> Option<f32> {
    match self {
      LengthValue::Px(v) => Some(*v),
      LengthValue::In(v) => Some(v * PX_PER_IN),
      LengthValue::Cm(v) => Some(v * PX_PER_CM),
      LengthValue::Mm(v) => Some(v * PX_PER_MM),
      LengthValue::Q(v) => Some(v * PX_PER_Q),
      LengthValue::Pt(v) => Some(v * PX_PER_PT),
      LengthValue::Pc(v) => Some(v * PX_PER_PC),
      _ => None,
    }
  }

  pub fn try_add_value(&self, other: &LengthValue) -> Option<LengthValue> {
    if self.same_unit(other) {
      Some(self.map(|v| v + other.value()))
    } else if let (Some(a), Some(b)) = (self.to_px(), other.to_px()) {
      Some(LengthValue::Px(a + b))
    } else {
      None
    }
  }

  pub fn try_cmp(&self, other: &LengthValue) -> Option<Ordering> {
    if self.same_unit(other) {
      self.value().partial_cmp(&other.value())
    } else if let (Some(a), Some(b)) = (self.to_px(), other.to_px()) {
      a.partial_cmp(&b)
    } else {
      None
    }
  }

  pub fn try_op_value(&self, other: &LengthValue, op: &dyn Fn(f32, f32) -> f32) -> Option<LengthValue> {
    if self.same_unit(other) {
      Some(self.map(|v| op(v, other.value())))
    } else if let (Some(a), Some(b)) = (self.to_px(), other.to_px()) {
      Some(LengthValue::Px(op(a, b)))
    } else {
      None
    }
  }
}

impl ToCss for LengthValue {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let (value, unit) = self.to_unit_value();
    // The unit can be omitted if the value is zero, except inside calc()
    // expressions, where unitless numbers won't be parsed as dimensions.
    if !dest.in_calc && value == 0.0 {
      return dest.write_char('0');
    }
    serialize_dimension(value, unit, dest)
  }
}

