impl<D: Dimension> DimensionPercentage<D> {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    match input.try_parse(|input| Calc::<DimensionPercentage<D>>::parse(input)) {
      Ok(Calc::Value(v)) => return Ok(*v),
      Ok(calc) => return Ok(DimensionPercentage::Calc(Box::new(calc))),
      _ => {}
    }
    if let Ok(d) = input.try_parse(D::parse_dimension) {
      return Ok(DimensionPercentage::Dimension(d));
    }
    if let Ok(p) = input.try_parse(Percentage::parse) {
      return Ok(DimensionPercentage::Percentage(p));
    }
    Err(input.new_error_for_next_token())
  }

  pub fn zero() -> Self {
    DimensionPercentage::Dimension(D::zero())
  }

  pub fn is_zero(&self) -> bool {
    match self {
      DimensionPercentage::Dimension(d) => d.is_zero(),
      DimensionPercentage::Percentage(p) => p.0 == 0.0,
      _ => false,
    }
  }

  pub fn is_calc(&self) -> bool {
    matches!(self, DimensionPercentage::Calc(_))
  }
}

impl<D: Dimension> CalcValue for DimensionPercentage<D> {
  fn parse_value<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(d) = input.try_parse(D::parse_dimension) {
      return Ok(DimensionPercentage::Dimension(d));
    }
    let loc = input.current_source_location();
    match input.next()? {
      Token::Percentage { unit_value, .. } => Ok(DimensionPercentage::Percentage(Percentage(unit_value))),
      t => Err(loc.new_unexpected_token_error(t)),
    }
  }
  fn try_add(&self, other: &Self) -> Option<Self> {
    match (self, other) {
      (DimensionPercentage::Dimension(a), DimensionPercentage::Dimension(b)) => a.try_add(b).map(DimensionPercentage::Dimension),
      (DimensionPercentage::Percentage(a), DimensionPercentage::Percentage(b)) => {
        Some(DimensionPercentage::Percentage(Percentage(a.0 + b.0)))
      }
      _ => None,
    }
  }
  fn mul_f32(self, f: f32) -> Self {
    match self {
      DimensionPercentage::Dimension(d) => DimensionPercentage::Dimension(d.mul_f32(f)),
      DimensionPercentage::Percentage(p) => DimensionPercentage::Percentage(Percentage(p.0 * f)),
      DimensionPercentage::Calc(c) => DimensionPercentage::Calc(Box::new(c.mul(f))),
    }
  }
  fn is_sign_negative(&self) -> bool {
    match self {
      DimensionPercentage::Dimension(d) => d.is_sign_negative(),
      DimensionPercentage::Percentage(p) => p.0 < 0.0,
      DimensionPercentage::Calc(_) => false,
    }
  }
  fn is_sign_positive(&self) -> bool {
    match self {
      DimensionPercentage::Dimension(d) => !d.is_sign_negative(),
      DimensionPercentage::Percentage(p) => p.0 >= 0.0,
      DimensionPercentage::Calc(_) => false,
    }
  }
  fn is_zero(&self) -> bool {
    DimensionPercentage::is_zero(self)
  }
  fn cmp_value(&self, other: &Self) -> Option<Ordering> {
    match (self, other) {
      (DimensionPercentage::Dimension(a), DimensionPercentage::Dimension(b)) => a.cmp_value(b),
      (DimensionPercentage::Percentage(a), DimensionPercentage::Percentage(b)) => a.0.partial_cmp(&b.0),
      _ => None,
    }
  }
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self> {
    match (self, other) {
      (DimensionPercentage::Dimension(a), DimensionPercentage::Dimension(b)) => a.try_op(b, op).map(DimensionPercentage::Dimension),
      (DimensionPercentage::Percentage(a), DimensionPercentage::Percentage(b)) => {
        Some(DimensionPercentage::Percentage(Percentage(op(a.0, b.0))))
      }
      _ => None,
    }
  }
  fn try_map(&self, op: &dyn Fn(f32) -> f32) -> Option<Self> {
    match self {
      DimensionPercentage::Dimension(a) => a.try_map(op).map(DimensionPercentage::Dimension),
      DimensionPercentage::Percentage(a) => Some(DimensionPercentage::Percentage(Percentage(op(a.0)))),
      _ => None,
    }
  }
  fn try_sign(&self) -> Option<f32> {
    match self {
      DimensionPercentage::Dimension(a) => a.try_sign(),
      DimensionPercentage::Percentage(a) => Some(if a.0 == 0.0 { 0.0 } else { a.0.signum() }),
      _ => None,
    }
  }
  fn from_calc(c: Calc<Self>) -> Self {
    match c {
      Calc::Value(v) => *v,
      c => DimensionPercentage::Calc(Box::new(c)),
    }
  }
  fn as_calc(&self) -> Option<&Calc<Self>> {
    match self {
      DimensionPercentage::Calc(c) => Some(c),
      _ => None,
    }
  }
}

