    self.try_add_value(other)
  }
  fn mul_f32(self, f: f32) -> Self {
    self.map(|v| v * f)
  }
  fn is_sign_negative(&self) -> bool {
    self.value() < 0.0
  }
  fn is_zero(&self) -> bool {
    LengthValue::is_zero(self)
  }
  fn cmp_value(&self, other: &Self) -> Option<Ordering> {
    self.try_cmp(other)
  }
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self> {
    self.try_op_value(other, op)
  }
  fn try_map(&self, op: &dyn Fn(f32) -> f32) -> Option<Self> {
    Some(self.map(op))
  }
  fn try_sign(&self) -> Option<f32> {
    let v = self.value();
    Some(if v == 0.0 { 0.0 } else { v.signum() })
  }
  fn zero() -> Self {
    LengthValue::Px(0.0)
  }
}

/// A length, possibly a calc() expression.
#[derive(Clone, Debug, PartialEq)]
pub enum Length {
  Value(LengthValue),
  Calc(Box<Calc<Length>>),
}

impl Length {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    match input.try_parse(|input| Calc::<Length>::parse(input)) {
      Ok(Calc::Value(v)) => return Ok(*v),
      Ok(calc) => return Ok(Length::Calc(Box::new(calc))),
      _ => {}
    }
