    Length::Value(LengthValue::Px(px))
  }

  pub fn zero() -> Length {
    Length::px(0.0)
  }

  pub fn is_zero(&self) -> bool {
    match self {
      Length::Value(v) => v.is_zero(),
      _ => false,
    }
  }

  pub fn to_px(&self) -> Option<f32> {
