#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Angle {
  Deg(f32),
  Grad(f32),
  Rad(f32),
  Turn(f32),
}

impl Angle {
  pub fn parse_unit(value: f32, unit: &str) -> Option<Angle> {
    match unit.to_ascii_lowercase().as_str() {
      "deg" => Some(Angle::Deg(value)),
      "grad" => Some(Angle::Grad(value)),
      "turn" => Some(Angle::Turn(value)),
      "rad" => Some(Angle::Rad(value)),
      _ => None,
    }
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    Self::parse_internal(input, false)
  }

  pub fn parse_with_unitless<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    Self::parse_internal(input, true)
  }

  fn parse_internal<'i, 't>(input: &mut Parser<'i, 't>, allow_unitless_zero: bool) -> ParseResult<'i, Self> {
    match input.try_parse(|input| Calc::<Angle>::parse(input)) {
      Ok(Calc::Value(v)) => return Ok(*v),
      // Angles are always compatible, so they will always compute to a value.
      Ok(_) => return Err(input.new_custom_error(ParserError::InvalidValue)),
      _ => {}
    }

    let location = input.current_source_location();
    let token = input.next()?;
    match token {
      Token::Dimension { value, ref unit, .. } => match Angle::parse_unit(value, unit) {
        Some(a) => Ok(a),
        None => Err(location.new_unexpected_token_error(token.clone())),
      },
      Token::Number { value, .. } if allow_unitless_zero || value == 0.0 => {
        if allow_unitless_zero {
          Ok(Angle::Deg(value))
        } else {
          Ok(Angle::Deg(0.0))
        }
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  pub fn is_zero(&self) -> bool {
    self.value() == 0.0
  }

  pub fn value(&self) -> f32 {
    match self {
      Angle::Deg(v) | Angle::Grad(v) | Angle::Rad(v) | Angle::Turn(v) => *v,
    }
  }

  pub fn to_degrees(&self) -> f32 {
    const RAD_TO_DEG: f32 = 180.0 / PI;
    match self {
      Angle::Deg(deg) => *deg,
      Angle::Rad(rad) => rad * RAD_TO_DEG,
      Angle::Grad(grad) => grad * 180.0 / 200.0,
      Angle::Turn(turn) => turn * 360.0,
    }
  }

  pub fn to_radians(&self) -> f32 {
    const DEG_TO_RAD: f32 = PI / 180.0;
    match self {
      Angle::Deg(deg) => deg * DEG_TO_RAD,
      Angle::Rad(rad) => *rad,
      Angle::Grad(grad) => grad * 180.0 / 200.0 * DEG_TO_RAD,
      Angle::Turn(turn) => turn * 360.0 * DEG_TO_RAD,
    }
  }

  fn map(&self, f: impl Fn(f32) -> f32) -> Angle {
    match self {
      Angle::Deg(v) => Angle::Deg(f(*v)),
      Angle::Grad(v) => Angle::Grad(f(*v)),
      Angle::Rad(v) => Angle::Rad(f(*v)),
      Angle::Turn(v) => Angle::Turn(f(*v)),
    }
  }

  fn same_unit(&self, other: &Angle) -> bool {
    matches!(
