      },
      t => Err(location.new_unexpected_token_error(t)),
    }
  }
  fn try_add(&self, other: &Self) -> Option<Self> {
    if self.same_unit(other) {
      Some(self.map(|v| v + other.value()))
    } else {
      Some(Angle::Deg(self.to_degrees() + other.to_degrees()))
    }
  }
  fn mul_f32(self, f: f32) -> Self {
    self.map(|v| v * f)
  }
  fn is_sign_negative(&self) -> bool {
    self.value() < 0.0
  }
  fn is_sign_positive(&self) -> bool {
    self.value() >= 0.0
  }
  fn is_zero(&self) -> bool {
    self.value() == 0.0
  }
  fn cmp_value(&self, other: &Self) -> Option<Ordering> {
    self.to_degrees().partial_cmp(&other.to_degrees())
  }
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self> {
    if self.same_unit(other) {
