    match (self, other) {
      (Time::Seconds(a), Time::Seconds(b)) => Some(Time::Seconds(a + b)),
      (Time::Milliseconds(a), Time::Milliseconds(b)) => Some(Time::Milliseconds(a + b)),
      _ => Some(Time::Seconds(self.to_s() + other.to_s())),
    }
  }
