//! Time values.

use crate::error::{ParseResult, ParserError};
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::tokenizer::Token;
use crate::values::calc::{Calc, CalcValue};
use crate::values::number::serialize_dimension;
use std::cmp::Ordering;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Time {
  Seconds(f32),
  Milliseconds(f32),
}

impl Time {
  pub fn parse_unit(value: f32, unit: &str) -> Option<Time> {
    match unit.to_ascii_lowercase().as_str() {
      "s" => Some(Time::Seconds(value)),
      "ms" => Some(Time::Milliseconds(value)),
      _ => None,
    }
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    match input.try_parse(|input| Calc::<Time>::parse(input)) {
      Ok(Calc::Value(v)) => return Ok(*v),
      Ok(_) => return Err(input.new_custom_error(ParserError::InvalidValue)),
      _ => {}
    }
    Self::parse_value(input)
  }

  pub fn to_ms(&self) -> f32 {
    match self {
      Time::Seconds(s) => s * 1000.0,
      Time::Milliseconds(ms) => *ms,
    }
  }

  pub fn to_s(&self) -> f32 {
    match self {
      Time::Seconds(s) => *s,
      Time::Milliseconds(ms) => ms / 1000.0,
    }
  }

  pub fn is_zero(&self) -> bool {
    self.value() == 0.0
  }

  fn value(&self) -> f32 {
    match self {
      Time::Seconds(v) | Time::Milliseconds(v) => *v,
    }
  }

  fn map(&self, f: impl Fn(f32) -> f32) -> Time {
    match self {
      Time::Seconds(v) => Time::Seconds(f(*v)),
      Time::Milliseconds(v) => Time::Milliseconds(f(*v)),
    }
  }
}

impl ToCss for Time {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    // 0.1s is shorter than 100ms
    // anything smaller is longer
    match self {
      Time::Seconds(s) => {
        if *s > 0.0 && *s < 0.1 {
          serialize_dimension(s * 1000.0, "ms", dest)
        } else {
          serialize_dimension(*s, "s", dest)
        }
      }
      Time::Milliseconds(ms) => {
        if *ms == 0.0 || *ms >= 100.0 {
          serialize_dimension(ms / 1000.0, "s", dest)
        } else {
          serialize_dimension(*ms, "ms", dest)
        }
      }
    }
  }
}

impl CalcValue for Time {
  fn parse_value<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let token = input.next()?;
    match token {
      Token::Dimension { value, ref unit, .. } => match Time::parse_unit(value, unit) {
        Some(t) => Ok(t),
        None => Err(location.new_unexpected_token_error(token.clone())),
      },
      t => Err(location.new_unexpected_token_error(t)),
    }
  }
  fn try_add(&self, other: &Self) -> Option<Self> {
    match (self, other) {
      (Time::Seconds(a), Time::Seconds(b)) => Some(Time::Seconds(a + b)),
      (Time::Milliseconds(a), Time::Milliseconds(b)) => Some(Time::Milliseconds(a + b)),
      _ => Some(Time::Seconds(self.to_s() + other.to_s())),
    }
  }
  fn mul_f32(self, f: f32) -> Self {
    self.map(|v| v * f)
  }
  fn is_sign_negative(&self) -> bool {
    self.value() < 0.0
  }
  fn is_sign_positive(&self) -> bool {
    self.value() >= 0.0
  }
  fn is_zero(&self) -> bool {
    self.value() == 0.0
  }
  fn cmp_value(&self, other: &Self) -> Option<Ordering> {
    self.to_ms().partial_cmp(&other.to_ms())
  }
  fn try_op(&self, other: &Self, op: &dyn Fn(f32, f32) -> f32) -> Option<Self> {
    match (self, other) {
      (Time::Seconds(a), Time::Seconds(b)) => Some(Time::Seconds(op(*a, *b))),
      (Time::Milliseconds(a), Time::Milliseconds(b)) => Some(Time::Milliseconds(op(*a, *b))),
      _ => Some(Time::Seconds(op(self.to_s(), other.to_s()))),
    }
  }
  fn try_map(&self, op: &dyn Fn(f32) -> f32) -> Option<Self> {
    Some(self.map(op))
  }
  fn try_sign(&self) -> Option<f32> {
    let v = self.value();
    Some(if v == 0.0 { 0.0 } else { v.signum() })
  }
  fn from_calc(c: Calc<Self>) -> Self {
    match c {
      Calc::Value(v) => *v,
      _ => Time::Seconds(f32::NAN),
    }
  }
  fn as_calc(&self) -> Option<&Calc<Self>> {
    None
  }
}
