//! Resolution values.

use crate::error::ParseResult;
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::tokenizer::Token;
use crate::values::number::serialize_dimension;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Resolution {
  Dpi(f32),
  Dpcm(f32),
  Dppx(f32),
}

impl Resolution {
  pub fn parse_unit(value: f32, unit: &str) -> Option<Resolution> {
    match unit.to_ascii_lowercase().as_str() {
      "dpi" => Some(Resolution::Dpi(value)),
      "dpcm" => Some(Resolution::Dpcm(value)),
      "dppx" | "x" => Some(Resolution::Dppx(value)),
      _ => None,
    }
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    // TODO: calc?
    let location = input.current_source_location();
    let token = input.next()?;
    match token {
      Token::Dimension { value, ref unit, .. } => match Resolution::parse_unit(value, unit) {
        Some(r) => Ok(r),
        None => Err(location.new_unexpected_token_error(token.clone())),
      },
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  pub fn to_dppx(&self) -> f32 {
    match self {
      Resolution::Dpi(v) => v / 96.0,
      Resolution::Dpcm(v) => v / 96.0 * 2.54,
      Resolution::Dppx(v) => *v,
    }
  }
}

impl ToCss for Resolution {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let (value, unit) = match self {
      Resolution::Dpi(dpi) => (*dpi, "dpi"),
      Resolution::Dpcm(dpcm) => (*dpcm, "dpcm"),
      Resolution::Dppx(dppx) => {
        if dest.targets.should_compile_x_resolution_unit() {
          (*dppx, "dppx")
        } else {
          (*dppx, "x")
        }
      }
    };
    serialize_dimension(value, unit, dest)
  }
}
