//! Browser targets.

/// Browser versions encoded as major << 16 | minor << 8 | patch.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Browsers {
  pub android: Option<u32>,
  pub chrome: Option<u32>,
  pub edge: Option<u32>,
  pub firefox: Option<u32>,
  pub ie: Option<u32>,
  pub ios_saf: Option<u32>,
  pub opera: Option<u32>,
  pub safari: Option<u32>,
  pub samsung: Option<u32>,
}

pub const fn version(major: u32, minor: u32, patch: u32) -> u32 {
  (major << 16) | (minor << 8) | patch
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Targets {
  pub browsers: Option<Browsers>,
  pub include: u64,
  pub exclude: u64,
}

impl Targets {
  pub fn new(browsers: Option<Browsers>) -> Self {
    Targets {
      browsers,
      include: 0,
      exclude: 0,
    }
  }

  /// Returns whether the feature is supported by all targets (or there are no targets).
  pub fn is_compatible(&self, feature: crate::compat::Feature) -> bool {
    if let Some(browsers) = self.browsers {
      feature.is_compatible(browsers)
    } else {
      true
    }
  }

  /// Returns whether a feature should be compiled (lowered) for the targets.
  pub fn should_compile(&self, feature: crate::compat::Feature) -> bool {
    if let Some(browsers) = self.browsers {
      !feature.is_compatible(browsers)
    } else {
      false
    }
  }

  pub fn should_compile_x_resolution_unit(&self) -> bool {
    self.should_compile(crate::compat::Feature::XResolutionUnit)
  }

  /// Returns the vendor prefixes needed for a feature.
  pub fn prefixes(&self, prefix: crate::vendor_prefix::VendorPrefix, feature: crate::prefixes::Feature) -> crate::vendor_prefix::VendorPrefix {
    if prefix.contains(crate::vendor_prefix::VendorPrefix::None) {
      if let Some(browsers) = self.browsers {
        return feature.prefixes_for(browsers);
      }
    }
    prefix
  }
}
