//! Browser compatibility data (subset).

use crate::targets::{version, Browsers};

macro_rules! features {
  ($($name: ident => { $($browser: ident: $v: expr),* $(,)? }),* $(,)?) => {
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    #[allow(dead_code)]
    pub enum Feature {
      $($name,)*
    }

    impl Feature {
      /// Returns whether the feature is supported in all of the given browsers.
      /// A browser not listed in the feature's table is considered unsupported.
      pub fn is_compatible(&self, browsers: Browsers) -> bool {
        match self {
          $(Feature::$name => {
            let table = BrowserTable { $($browser: Some($v),)* ..BrowserTable::NONE };
            table.is_compatible(browsers)
          })*
        }
      }
    }
  };
}

#[derive(Clone, Copy)]
struct BrowserTable {
  android: Option<u32>,
  chrome: Option<u32>,
  edge: Option<u32>,
  firefox: Option<u32>,
  ie: Option<u32>,
  ios_saf: Option<u32>,
  opera: Option<u32>,
  safari: Option<u32>,
  samsung: Option<u32>,
}

impl BrowserTable {
  const NONE: BrowserTable = BrowserTable {
    android: None,
    chrome: None,
    edge: None,
    firefox: None,
    ie: None,
    ios_saf: None,
    opera: None,
    safari: None,
    samsung: None,
  };

  fn is_compatible(&self, browsers: Browsers) -> bool {
    macro_rules! check {
      ($b: ident) => {
        if let Some(v) = browsers.$b {
          match self.$b {
            Some(min) if v >= min => {}
            _ => return false,
          }
        }
      };
    }
    check!(android);
    check!(chrome);
    check!(edge);
    check!(firefox);
    check!(ie);
    check!(ios_saf);
    check!(opera);
    check!(safari);
    check!(samsung);
    true
  }
}

