//! Raw token lists, used for custom properties and unparsed values.

use crate::error::{ParseResult, ParserError};
use crate::parser::{Delimiter, Parser, ParserState};
use crate::printer::{
  serialize_dimension_unit, serialize_identifier_to_string, serialize_name, serialize_string_to_string, PrintResult,
