use crate::values::resolution::Resolution;
use crate::values::time::Time;
use crate::values::url::Url;
use std::borrow::Cow;

#[derive(Clone, Debug, PartialEq)]
pub struct TokenList<'i>(pub Vec<TokenOrValue<'i>>);

#[derive(Clone, Debug, PartialEq)]
pub enum TokenOrValue<'i> {
  Token(Token<'i>),
  Color(CssColor),
  UnresolvedColor(UnresolvedColor<'i>),
  Url(Url<'i>),
  Var(Variable<'i>),
  Env(EnvironmentVariable<'i>),
  Function(Function<'i>),
  Length(LengthValue),
  Angle(Angle),
  Time(Time),
  Resolution(Resolution),
  DashedIdent(Cow<'i, str>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Token<'i> {
  Ident(Cow<'i, str>),
  AtKeyword(Cow<'i, str>),
  Hash(Cow<'i, str>),
  IDHash(Cow<'i, str>),
  String(Cow<'i, str>),
  Number { has_sign: bool, value: f32, int_value: Option<i32> },
  Percentage { has_sign: bool, unit_value: f32, int_value: Option<i32> },
  Dimension { has_sign: bool, value: f32, int_value: Option<i32>, unit: Cow<'i, str> },
  WhiteSpace(Cow<'i, str>),
  Comment(Cow<'i, str>),
  Colon,
  Semicolon,
  Comma,
  IncludeMatch,
  DashMatch,
  PrefixMatch,
  SuffixMatch,
  SubstringMatch,
  CDO,
  CDC,
  ParenthesisBlock,
  SquareBracketBlock,
  CurlyBracketBlock,
  BadUrl(Cow<'i, str>),
  BadString(Cow<'i, str>),
  CloseParenthesis,
  CloseSquareBracket,
  CloseCurlyBracket,
  Delim(char),
}

impl<'i> Token<'i> {
  pub fn from_ctoken(t: &CToken<'i>) -> Token<'i> {
    match t {
      CToken::Ident(s) => Token::Ident(s.clone()),
      CToken::AtKeyword(s) => Token::AtKeyword(s.clone()),
      CToken::Hash(s) => Token::Hash(s.clone()),
      CToken::IDHash(s) => Token::IDHash(s.clone()),
      CToken::QuotedString(s) => Token::String(s.clone()),
      CToken::UnquotedUrl(_) => unreachable!(),
      CToken::Delim(c) => Token::Delim(*c),
      CToken::Number { has_sign, value, int_value } => Token::Number {
        has_sign: *has_sign,
        value: *value,
        int_value: *int_value,
      },
      CToken::Percentage { has_sign, unit_value, int_value } => Token::Percentage {
        has_sign: *has_sign,
        unit_value: *unit_value,
        int_value: *int_value,
      },
      CToken::Dimension { has_sign, value, int_value, unit } => Token::Dimension {
        has_sign: *has_sign,
        value: *value,
        int_value: *int_value,
        unit: unit.clone(),
      },
      CToken::WhiteSpace(s) => Token::WhiteSpace(Cow::Borrowed(s)),
      CToken::Comment(s) => Token::Comment(Cow::Borrowed(s)),
      CToken::Colon => Token::Colon,
      CToken::Semicolon => Token::Semicolon,
      CToken::Comma => Token::Comma,
      CToken::IncludeMatch => Token::IncludeMatch,
      CToken::DashMatch => Token::DashMatch,
      CToken::PrefixMatch => Token::PrefixMatch,
      CToken::SuffixMatch => Token::SuffixMatch,
      CToken::SubstringMatch => Token::SubstringMatch,
      CToken::CDO => Token::CDO,
      CToken::CDC => Token::CDC,
      CToken::Function(_) => unreachable!(),
      CToken::ParenthesisBlock => Token::ParenthesisBlock,
      CToken::SquareBracketBlock => Token::SquareBracketBlock,
      CToken::CurlyBracketBlock => Token::CurlyBracketBlock,
      CToken::BadUrl(s) => Token::BadUrl(s.clone()),
      CToken::BadString(s) => Token::BadString(s.clone()),
      CToken::CloseParenthesis => Token::CloseParenthesis,
      CToken::CloseSquareBracket => Token::CloseSquareBracket,
      CToken::CloseCurlyBracket => Token::CloseCurlyBracket,
    }
  }
}

impl<'i> ToCss for Token<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut s = String::new();
    match self {
      Token::Ident(name) => serialize_identifier_to_string(name, &mut s),
      Token::AtKeyword(name) => {
        s.push('@');
        serialize_identifier_to_string(name, &mut s);
      }
      Token::Hash(name) => {
        s.push('#');
        serialize_name(name, &mut s);
      }
      Token::IDHash(name) => {
        s.push('#');
        serialize_identifier_to_string(name, &mut s);
      }
      Token::String(v) => serialize_string_to_string(v, &mut s),
      Token::Delim(c) => s.push(*c),
      Token::Number { value, .. } => s.push_str(&number_to_string(*value)),
      Token::Percentage { unit_value, .. } => {
        s.push_str(&dimension_number_to_string(unit_value * 100.0));
        s.push('%');
      }
      Token::Dimension { value, unit, .. } => {
        s.push_str(&dimension_number_to_string(*value));
        serialize_dimension_unit(unit, &mut s);
      }
      Token::WhiteSpace(content) => {
        if dest.minify {
          s.push(' ');
        } else {
          s.push_str(content);
        }
      }
      Token::Comment(content) => {
        if !dest.minify {
          s.push_str("/*");
          s.push_str(content);
          s.push_str("*/");
        }
      }
      Token::Colon => s.push(':'),
      Token::Semicolon => s.push(';'),
      Token::Comma => s.push(','),
      Token::IncludeMatch => s.push_str("~="),
      Token::DashMatch => s.push_str("|="),
      Token::PrefixMatch => s.push_str("^="),
      Token::SuffixMatch => s.push_str("$="),
      Token::SubstringMatch => s.push_str("*="),
      Token::CDO => s.push_str("<!--"),
      Token::CDC => s.push_str("-->"),
      Token::ParenthesisBlock => s.push('('),
      Token::SquareBracketBlock => s.push('['),
      Token::CurlyBracketBlock => s.push('{'),
      Token::BadUrl(contents) => {
        s.push_str("url(");
        s.push_str(contents);
        s.push(')');
      }
      Token::BadString(value) => {
        s.push('"');
        s.push_str(value);
      }
      Token::CloseParenthesis => s.push(')'),
      Token::CloseSquareBracket => s.push(']'),
      Token::CloseCurlyBracket => s.push('}'),
    }
    dest.write_str(&s)
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Variable<'i> {
  pub name: Cow<'i, str>,
  pub fallback: Option<TokenList<'i>>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct EnvironmentVariable<'i> {
  pub name: Cow<'i, str>,
  pub indices: Vec<Token<'i>>,
  pub fallback: Option<TokenList<'i>>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Function<'i> {
  pub name: Cow<'i, str>,
  pub arguments: TokenList<'i>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum UnresolvedColor<'i> {
  RGB { r: f32, g: f32, b: f32, alpha: TokenList<'i> },
  HSL { h: f32, s: f32, l: f32, alpha: TokenList<'i> },
  LightDark { light: TokenList<'i>, dark: TokenList<'i> },
}

#[derive(Clone, Copy)]
pub struct ParserOptions {
  pub error_recovery: bool,
  pub custom_media: bool,
  pub css_modules: bool,
}

impl<'i> TokenList<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions, depth: usize) -> ParseResult<'i, Self> {
    let mut tokens = vec![];
    TokenList::parse_into(input, &mut tokens, options, depth)?;

    // Slice off leading and trailing whitespace if there are at least two tokens.
    // If there is only one token, we must preserve it. e.g. `--foo: ;` is valid.
    if tokens.len() >= 2 {
      let mut slice = &tokens[..];
      if matches!(tokens.first(), Some(TokenOrValue::Token(Token::WhiteSpace(_)))) {
        slice = &slice[1..];
      }
      if matches!(tokens.last(), Some(TokenOrValue::Token(Token::WhiteSpace(_)))) {
        slice = &slice[..slice.len() - 1];
      }
      return Ok(TokenList(slice.to_vec()));
    }

    Ok(TokenList(tokens))
  }

  pub fn parse_raw<'t>(
    input: &mut Parser<'i, 't>,
    tokens: &mut Vec<TokenOrValue<'i>>,
    options: &ParserOptions,
    depth: usize,
  ) -> ParseResult<'i, ()> {
    if depth > 500 {
      return Err(input.new_custom_error(ParserError::MaximumNestingDepth));
    }
    loop {
      let state = input.state();
      match input.next_including_whitespace_and_comments() {
        Ok(token @ CToken::ParenthesisBlock)
        | Ok(token @ CToken::SquareBracketBlock)
        | Ok(token @ CToken::CurlyBracketBlock) => {
          tokens.push(Token::from_ctoken(&token).into());
          let closing_delimiter = match token {
            CToken::ParenthesisBlock => Token::CloseParenthesis,
            CToken::SquareBracketBlock => Token::CloseSquareBracket,
            CToken::CurlyBracketBlock => Token::CloseCurlyBracket,
            _ => unreachable!(),
          };
          input.parse_nested_block(|input| TokenList::parse_raw(input, tokens, options, depth + 1))?;
          tokens.push(closing_delimiter.into());
        }
        Ok(CToken::Function(f)) => {
          tokens.push(TokenOrValue::Function(Function {
            name: f,
            arguments: TokenList(vec![]),
          }));
          let mut args = vec![];
          input.parse_nested_block(|input| TokenList::parse_raw(input, &mut args, options, depth + 1))?;
          if let Some(TokenOrValue::Function(f)) = tokens.last_mut() {
            f.arguments = TokenList(args);
          }
        }
        Ok(CToken::UnquotedUrl(_)) => {
          input.reset(&state);
          tokens.push(TokenOrValue::Url(Url::parse(input)?));
        }
        Ok(token) => {
          tokens.push(Token::from_ctoken(&token).into());
        }
        Err(_) => break,
      }
    }
    Ok(())
  }

  fn parse_into<'t>(
    input: &mut Parser<'i, 't>,
    tokens: &mut Vec<TokenOrValue<'i>>,
    options: &ParserOptions,
    depth: usize,
  ) -> ParseResult<'i, ()> {
    if depth > 500 {
      return Err(input.new_custom_error(ParserError::MaximumNestingDepth));
    }

    let mut last_is_delim = false;
    let mut last_is_whitespace = false;
    loop {
      let state = input.state();
      match input.next_including_whitespace_and_comments() {
        Ok(CToken::WhiteSpace(ws)) => {
          // Skip whitespace if the last token was a delimiter.
          // Otherwise, replace all whitespace and comments with a single space.
          if !last_is_delim {
            tokens.push(Token::WhiteSpace(Cow::Borrowed(ws)).into());
            last_is_whitespace = true;
          }
        }
        Ok(CToken::Comment(c)) => {
          tokens.push(Token::Comment(Cow::Borrowed(c)).into());
          last_is_whitespace = false;
        }
        Ok(CToken::Function(ref f)) => {
          // Attempt to parse embedded color values into hex tokens.
          let f = f.clone();
          if let Some(color) = try_parse_color_token(&f, &state, input) {
            tokens.push(TokenOrValue::Color(color));
            last_is_delim = false;
          } else if let Ok(color) = input.try_parse(|input| UnresolvedColor::parse(&f, input, options)) {
            tokens.push(TokenOrValue::UnresolvedColor(color));
            last_is_delim = false;
          } else if f == "url" {
            input.reset(&state);
            tokens.push(TokenOrValue::Url(Url::parse(input)?));
            last_is_delim = false;
          } else if f == "var" {
            let var = input.parse_nested_block(|input| {
              let var = Variable::parse(input, options, depth + 1)?;
              Ok(TokenOrValue::Var(var))
            })?;
            tokens.push(var);
            last_is_delim = true;
          } else if f == "env" {
            let env = input.parse_nested_block(|input| {
              let env = EnvironmentVariable::parse_nested(input, options, depth + 1)?;
              Ok(TokenOrValue::Env(env))
            })?;
            tokens.push(env);
            last_is_delim = true;
          } else {
            let arguments = input.parse_nested_block(|input| TokenList::parse(input, options, depth + 1))?;
            tokens.push(TokenOrValue::Function(Function { name: f, arguments }));
            last_is_delim = true; // Whitespace is not required after any of these chars.
          }
          last_is_whitespace = false;
        }
        Ok(CToken::Hash(ref h)) | Ok(CToken::IDHash(ref h)) => {
          if let Ok(color) = parse_hash(h.as_bytes()) {
            tokens.push(TokenOrValue::Color(CssColor::RGBA(color)));
          } else {
            tokens.push(Token::Hash(h.clone()).into());
          }
          last_is_delim = false;
          last_is_whitespace = false;
        }
        Ok(CToken::UnquotedUrl(_)) => {
          input.reset(&state);
          tokens.push(TokenOrValue::Url(Url::parse(input)?));
          last_is_delim = false;
          last_is_whitespace = false;
        }
        Ok(CToken::Ident(ref name)) if name.starts_with("--") => {
          tokens.push(TokenOrValue::DashedIdent(name.clone()));
          last_is_delim = false;
          last_is_whitespace = false;
        }
        Ok(token @ CToken::ParenthesisBlock)
        | Ok(token @ CToken::SquareBracketBlock)
        | Ok(token @ CToken::CurlyBracketBlock) => {
          tokens.push(Token::from_ctoken(&token).into());
          let closing_delimiter = match token {
            CToken::ParenthesisBlock => Token::CloseParenthesis,
            CToken::SquareBracketBlock => Token::CloseSquareBracket,
            CToken::CurlyBracketBlock => Token::CloseCurlyBracket,
            _ => unreachable!(),
          };
          input.parse_nested_block(|input| TokenList::parse_into(input, tokens, options, depth + 1))?;
          tokens.push(closing_delimiter.into());
          last_is_delim = true; // Whitespace is not required after any of these chars.
          last_is_whitespace = false;
        }
        Ok(token @ CToken::Dimension { .. }) => {
          let value = if let CToken::Dimension { value, ref unit, .. } = token {
            if let Some(length) = LengthValue::from_unit(value, unit) {
              TokenOrValue::Length(length)
            } else if let Some(angle) = Angle::parse_unit(value, unit) {
              TokenOrValue::Angle(angle)
            } else if let Some(time) = Time::parse_unit(value, unit) {
              TokenOrValue::Time(time)
            } else if let Some(res) = Resolution::parse_unit(value, unit) {
              TokenOrValue::Resolution(res)
            } else {
              TokenOrValue::Token(Token::from_ctoken(&token))
            }
          } else {
            unreachable!()
          };
          tokens.push(value);
          last_is_delim = false;
          last_is_whitespace = false;
        }
        Ok(token) => {
          last_is_delim = matches!(token, CToken::Delim(_) | CToken::Comma);
          tokens.push(Token::from_ctoken(&token).into());
          last_is_whitespace = false;
        }
        Err(_) => break,
      }
    }
    let _ = last_is_whitespace;
    Ok(())
  }

  pub fn to_css_internal(&self, dest: &mut Printer, is_custom_property: bool) -> PrintResult {
    if !dest.minify && self.0.len() == 1 {
      if let TokenOrValue::Token(Token::WhiteSpace(ws)) = &self.0[0] {
        // Whitespace-only value: preserve the whitespace exactly, taking into account
        // the space that was already written after the preceding delimiter.
        let s = dest.last_char_is_space();
        if s && !ws.is_empty() {
          return dest.write_str(&ws[1..]);
        }
        return dest.write_str(ws);
      }
    }
    for token_or_value in self.0.iter() {
      match token_or_value {
        TokenOrValue::Color(color) => color.to_css(dest)?,
        TokenOrValue::UnresolvedColor(color) => color.to_css(dest, is_custom_property)?,
        TokenOrValue::Url(url) => url.to_css(dest)?,
        TokenOrValue::Var(var) => var.to_css(dest, is_custom_property)?,
        TokenOrValue::Env(env) => env.to_css(dest, is_custom_property)?,
        TokenOrValue::Function(f) => f.to_css(dest, is_custom_property)?,
        TokenOrValue::Length(v) => {
          // Do not serialize unitless zero in custom properties.
          let (value, unit) = v.to_unit_value();
          if value == 0.0 {
            let mut s = dimension_number_to_string(value);
            serialize_dimension_unit(unit, &mut s);
            dest.write_str(&s)?;
          } else {
            v.to_css(dest)?;
          }
        }
        TokenOrValue::Angle(v) => v.to_css(dest)?,
        TokenOrValue::Time(v) => v.to_css(dest)?,
        TokenOrValue::Resolution(v) => v.to_css(dest)?,
        TokenOrValue::DashedIdent(v) => dest.write_dashed_ident(v, false)?,
        TokenOrValue::Token(token) => token.to_css(dest)?,
      }
    }
    Ok(())
  }

  pub fn is_empty(&self) -> bool {
    self.0.is_empty()
  }
}

impl<'i> From<Token<'i>> for TokenOrValue<'i> {
  fn from(token: Token<'i>) -> TokenOrValue<'i> {
    TokenOrValue::Token(token)
  }
}

fn try_parse_color_token<'i, 't>(f: &str, state: &ParserState, input: &mut Parser<'i, 't>) -> Option<CssColor> {
  match f.to_ascii_lowercase().as_str() {
    "rgb" | "rgba" | "hsl" | "hsla" | "hwb" | "lab" | "lch" | "oklab" | "oklch" | "color" | "color-mix" | "light-dark" => {
      let s = input.state();
      input.reset(state);
      if let Ok(color) = CssColor::parse(input) {
        return Some(color);
      }
      input.reset(&s);
    }
    _ => {}
  }
  None
}

impl<'i> Variable<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions, depth: usize) -> ParseResult<'i, Self> {
    let name = crate::values::ident::DashedIdent::parse(input)?.0;
    let fallback = if input.try_parse(|input| input.expect_comma()).is_ok() {
      Some(TokenList::parse(input, options, depth)?)
    } else {
      None
    };
    Ok(Variable { name, fallback })
  }

  pub fn to_css(&self, dest: &mut Printer, is_custom_property: bool) -> PrintResult {
    dest.write_str("var(")?;
    dest.write_dashed_ident(&self.name, false)?;
    if let Some(fallback) = &self.fallback {
      dest.delim(',', false)?;
      fallback.to_css_internal(dest, is_custom_property)?;
    }
    dest.write_char(')')
  }
}

impl<'i> EnvironmentVariable<'i> {
  pub fn parse_nested<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions, depth: usize) -> ParseResult<'i, Self> {
    let name = input.expect_ident()?;
    let mut indices = Vec::new();
    while let Ok(CToken::Number { has_sign, value, int_value }) =
      input.try_parse(|input| input.next_including_whitespace_and_comments().map(|t| t.clone()).map_err(|e| ParserError::from_basic(e.kind)))
    {
      indices.push(Token::Number { has_sign, value, int_value });
    }
    let fallback = if input.try_parse(|input| input.expect_comma()).is_ok() {
      Some(TokenList::parse(input, options, depth)?)
    } else {
      None
    };
    Ok(EnvironmentVariable { name, indices, fallback })
  }

  pub fn to_css(&self, dest: &mut Printer, is_custom_property: bool) -> PrintResult {
    dest.write_str("env(")?;
    if self.name.starts_with("--") {
      dest.write_dashed_ident(&self.name, false)?;
    } else {
      crate::printer::serialize_identifier(&self.name, dest)?;
    }
    for item in &self.indices {
      dest.write_char(' ')?;
      item.to_css(dest)?;
    }
    if let Some(fallback) = &self.fallback {
      dest.delim(',', false)?;
      fallback.to_css_internal(dest, is_custom_property)?;
    }
    dest.write_char(')')
  }
}

impl<'i> Function<'i> {
  pub fn to_css(&self, dest: &mut Printer, is_custom_property: bool) -> PrintResult {
    crate::printer::serialize_identifier(&self.name, dest)?;
    dest.write_char('(')?;
    self.arguments.to_css_internal(dest, is_custom_property)?;
    dest.write_char(')')
  }
}

impl<'i> UnresolvedColor<'i> {
  fn parse<'t>(f: &str, input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    input.parse_nested_block(|input| match f.to_ascii_lowercase().as_str() {
      "rgb" => {
        let r = crate::values::number::parse_number(input)?;
        let g = crate::values::number::parse_number(input)?;
        let b = crate::values::number::parse_number(input)?;
        input.expect_delim('/')?;
        let alpha = TokenList::parse(input, options, 0)?;
        Ok(UnresolvedColor::RGB { r, g, b, alpha })
      }
      "hsl" => {
        let h = Angle::parse_with_unitless(input)?.to_degrees();
        let s = crate::values::percentage::Percentage::parse(input)?.0;
        let l = crate::values::percentage::Percentage::parse(input)?.0;
        input.expect_delim('/')?;
        let alpha = TokenList::parse(input, options, 0)?;
        Ok(UnresolvedColor::HSL { h, s, l, alpha })
      }
      "light-dark" => {
        let light = input.parse_until_before(Delimiter::Comma, |input| TokenList::parse(input, options, 0))?;
        input.expect_comma()?;
        let dark = TokenList::parse(input, options, 0)?;
        Ok(UnresolvedColor::LightDark { light, dark })
      }
      _ => Err(input.new_custom_error(ParserError::InvalidValue)),
    })
  }

  pub fn to_css(&self, dest: &mut Printer, is_custom_property: bool) -> PrintResult {
    match self {
      UnresolvedColor::RGB { r, g, b, alpha } => {
        dest.write_str("rgb(")?;
        crate::values::number::serialize_number(*r, dest)?;
        dest.write_char(' ')?;
        crate::values::number::serialize_number(*g, dest)?;
        dest.write_char(' ')?;
        crate::values::number::serialize_number(*b, dest)?;
        dest.delim('/', true)?;
        alpha.to_css_internal(dest, is_custom_property)?;
        dest.write_char(')')
      }
      UnresolvedColor::HSL { h, s, l, alpha } => {
        dest.write_str("hsl(")?;
        crate::values::number::serialize_number(*h, dest)?;
        dest.write_char(' ')?;
        crate::values::number::serialize_percentage(s * 100.0, dest)?;
        dest.write_char(' ')?;
        crate::values::number::serialize_percentage(l * 100.0, dest)?;
        dest.delim('/', true)?;
        alpha.to_css_internal(dest, is_custom_property)?;
        dest.write_char(')')
      }
      UnresolvedColor::LightDark { light, dark } => {
        dest.write_str("light-dark(")?;
        light.to_css_internal(dest, is_custom_property)?;
        dest.delim(',', false)?;
