#[derive(Clone, Copy, Default)]
struct SelectorParsingState {
  bits: u16,
}

#[allow(non_upper_case_globals)]
impl SelectorParsingState {
  const SKIP_DEFAULT_NAMESPACE: u16 = 1 << 0;
  const AFTER_SLOTTED: u16 = 1 << 1;
  const AFTER_PART: u16 = 1 << 2;
  const AFTER_PSEUDO_ELEMENT: u16 = 1 << 3;
  const AFTER_NON_STATEFUL_PSEUDO_ELEMENT: u16 = 1 << 4;
  const DISALLOW_COMBINATORS: u16 = 1 << 5;
  const DISALLOW_PSEUDOS: u16 = 1 << 6;
  const DISALLOW_RELATIVE_SELECTOR: u16 = 1 << 7;
  const AFTER_NESTING: u16 = 1 << 8;
  const AFTER_WEBKIT_SCROLLBAR: u16 = 1 << 9;
  const AFTER_VIEW_TRANSITION: u16 = 1 << 10;
  const AFTER_UNKNOWN_PSEUDO_ELEMENT: u16 = 1 << 11;
  const AFTER_PSEUDO: u16 = Self::AFTER_PART | Self::AFTER_SLOTTED | Self::AFTER_PSEUDO_ELEMENT;

  fn intersects(&self, bits: u16) -> bool {
    (self.bits & bits) != 0
  }
  fn insert(&mut self, bits: u16) {
    self.bits |= bits;
  }
  fn with(mut self, bits: u16) -> Self {
    self.bits |= bits;
    self
  }
  fn allows_pseudos(&self) -> bool {
    !self.intersects(Self::AFTER_PSEUDO_ELEMENT | Self::DISALLOW_PSEUDOS)
  }
  fn allows_part(&self) -> bool {
    !self.intersects(Self::AFTER_PSEUDO | Self::DISALLOW_PSEUDOS)
  }
  fn allows_slotted(&self) -> bool {
    !self.intersects(Self::AFTER_PSEUDO | Self::DISALLOW_PSEUDOS)
  }
  fn allows_non_functional_pseudo_classes(&self) -> bool {
    !self.intersects(Self::AFTER_SLOTTED | Self::AFTER_NON_STATEFUL_PSEUDO_ELEMENT)
  }
  fn allows_tree_structural_pseudo_classes(&self) -> bool {
    !self.intersects(Self::AFTER_PSEUDO)
  }
  fn allows_combinators(&self) -> bool {
    !self.intersects(Self::DISALLOW_COMBINATORS)
  }
  fn allows_custom_functional_pseudo_classes(&self) -> bool {
    !self.intersects(Self::AFTER_PSEUDO)
  }
}

pub struct SelectorParser<'a, 'i> {
  pub default_namespace: Option<Cow<'i, str>>,
  pub is_nesting_allowed: bool,
  pub options: &'a ParserOptions,
  pub warnings: Option<&'a std::cell::RefCell<Vec<crate::error::Error<ParserError<'i>>>>>,
  pub filename: &'a str,
}

type SelResult<'i, T> = Result<T, ParseError<'i, ParserError<'i>>>;

fn sel_err<'i>(loc: SourceLocation, e: SelectorError<'i>) -> ParseError<'i, ParserError<'i>> {
  loc.new_custom_error(ParserError::SelectorError(e))
}

impl<'a, 'i> SelectorParser<'a, 'i> {
  fn warn(&self, err: ParseError<'i, ParserError<'i>>) {
    if let Some(w) = self.warnings {
      w.borrow_mut()
        .push(crate::error::Error::from_parse_error(err, self.filename.to_string()));
    }
  }
}

impl<'i> SelectorList<'i> {
  pub fn parse<'t>(
    parser: &SelectorParser<'_, 'i>,
    input: &mut Parser<'i, 't>,
    recovery: ParseErrorRecovery,
    nesting_requirement: NestingRequirement,
  ) -> SelResult<'i, Self> {
    let mut state = SelectorParsingState::default();
    Self::parse_with_state(parser, input, &mut state, recovery, nesting_requirement, false)
  }

  pub fn parse_relative<'t>(
    parser: &SelectorParser<'_, 'i>,
    input: &mut Parser<'i, 't>,
    recovery: ParseErrorRecovery,
    nesting_requirement: NestingRequirement,
  ) -> SelResult<'i, Self> {
    let mut state = SelectorParsingState::default();
    Self::parse_with_state(parser, input, &mut state, recovery, nesting_requirement, true)
  }

  fn parse_with_state<'t>(
    parser: &SelectorParser<'_, 'i>,
    input: &mut Parser<'i, 't>,
    state: &mut SelectorParsingState,
    recovery: ParseErrorRecovery,
    nesting_requirement: NestingRequirement,
    relative: bool,
  ) -> SelResult<'i, Self> {
    let original_state = *state;
    let mut values = Vec::new();
    loop {
      let selector = input.parse_until_before(Delimiter::Comma, |input| {
        let mut selector_state = original_state;
        let result = if relative {
          parse_relative_selector(parser, input, &mut selector_state, nesting_requirement)
        } else {
          parse_selector(parser, input, &mut selector_state, nesting_requirement)
        };
        if selector_state.intersects(SelectorParsingState::AFTER_NESTING) {
          state.insert(SelectorParsingState::AFTER_NESTING);
        }
        result
      });

      let _was_ok = selector.is_ok();
      match selector {
        Ok(selector) => values.push(selector),
        Err(err) => match recovery {
          ParseErrorRecovery::DiscardList => return Err(err),
          ParseErrorRecovery::IgnoreInvalidSelector => {}
        },
      }

      loop {
        match input.next() {
          Err(_) => return Ok(SelectorList(values)),
          Ok(Token::Comma) => break,
          Ok(_) => {}
        }
      }
    }
  }
}

fn try_parse_combinator<'i, 't>(input: &mut Parser<'i, 't>) -> Result<Combinator, ()> {
  let mut any_whitespace = false;
  loop {
    let before_this_token = input.state();
    match input.next_including_whitespace() {
      Err(_) => {
        input.reset(&before_this_token);
        return Err(());
      }
      Ok(Token::WhiteSpace(_)) => any_whitespace = true,
      Ok(Token::Delim('>')) => return Ok(Combinator::Child),
      Ok(Token::Delim('+')) => return Ok(Combinator::NextSibling),
      Ok(Token::Delim('~')) => return Ok(Combinator::LaterSibling),
      Ok(_) => {
        input.reset(&before_this_token);
        if any_whitespace {
          return Ok(Combinator::Descendant);
        } else {
          return Err(());
        }
      }
    }
  }
}

fn parse_relative_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: &mut SelectorParsingState,
  nesting_requirement: NestingRequirement,
) -> SelResult<'i, Selector<'i>> {
  let combinator = try_parse_combinator(input);
  let mut selector = parse_selector_internal(parser, input, state, NestingRequirement::None)?;
  let has_nesting = selector_has_nesting(&selector);
  match combinator {
    Ok(combinator) if combinator != Combinator::Descendant => {
      if nesting_requirement == NestingRequirement::Implicit && !has_nesting {
        let mut components = vec![Component::Nesting, Component::Combinator(combinator)];
        components.append(&mut selector.0);
        selector.0 = components;
      } else {
        selector.0.insert(0, Component::Combinator(combinator));
      }
    }
    _ => {
      if nesting_requirement == NestingRequirement::Implicit && !has_nesting {
        let mut components = vec![Component::Nesting, Component::Combinator(Combinator::Descendant)];
        components.append(&mut selector.0);
        selector.0 = components;
      } else if let Ok(c) = combinator {
        // explicit descendant combinator... only meaningful when whitespace was present
        let _ = c;
      }
    }
  }
  apply_nesting_requirement(&selector, nesting_requirement, input)?;
  Ok(selector)
}

fn selector_has_nesting(selector: &Selector) -> bool {
  selector.0.iter().any(|c| component_has_nesting(c))
}

fn component_has_nesting(c: &Component) -> bool {
  match c {
    Component::Nesting => true,
    Component::Negation(list) | Component::Is(list) | Component::Where(list) | Component::Any(_, list) | Component::Has(list) => {
      list.iter().any(selector_has_nesting)
    }
    Component::NthOf(_, list) => list.iter().any(selector_has_nesting),
    Component::Slotted(s) => selector_has_nesting(s),
    Component::Host(Some(s)) => selector_has_nesting(s),
    _ => false,
  }
}

fn apply_nesting_requirement<'i, 't>(
  selector: &Selector<'i>,
  nesting_requirement: NestingRequirement,
  input: &mut Parser<'i, 't>,
) -> SelResult<'i, ()> {
  if nesting_requirement == NestingRequirement::Contained && !selector_has_nesting(selector) {
    return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::MissingNestingSelector)));
  }
  Ok(())
}

pub fn parse_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: &mut SelectorParsingState,
  nesting_requirement: NestingRequirement,
) -> SelResult<'i, Selector<'i>> {
  let mut selector = parse_selector_internal(parser, input, state, nesting_requirement)?;
  if nesting_requirement == NestingRequirement::Implicit && !selector_has_nesting(&selector) {
    let mut components = vec![Component::Nesting, Component::Combinator(Combinator::Descendant)];
    components.append(&mut selector.0);
    selector.0 = components;
  }
  apply_nesting_requirement(&selector, nesting_requirement, input)?;
  Ok(selector)
}

fn parse_selector_internal<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: &mut SelectorParsingState,
  nesting_requirement: NestingRequirement,
) -> SelResult<'i, Selector<'i>> {
  if nesting_requirement == NestingRequirement::Prefixed {
    let start = input.state();
    if !matches!(input.next_including_whitespace(), Ok(Token::Delim('&'))) {
      return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::MissingNestingPrefix)));
    }
    input.reset(&start);
  }

  let mut components: Vec<Component<'i>> = Vec::new();
  let mut has_combinators = false;

  'outer: loop {
    let compound = parse_compound_selector(parser, state, input, &mut components)?;
    let (has_pseudo_element, slotted, part) = match compound {
      Some(c) => c,
      None => {
        if has_combinators {
          return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::DanglingCombinator)));
        } else {
          return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::EmptySelector)));
        }
      }
    };

    if has_pseudo_element || slotted || part {
      // Check for an unexpected selector after a pseudo-element.
      let loc = input.current_source_location();
      match input.next_including_whitespace() {
        Ok(Token::WhiteSpace(_)) => match input.next() {
          Ok(t) => {
            return Err(sel_err(loc, SelectorError::UnexpectedSelectorAfterPseudoElement(t)));
          }
          Err(_) => break,
        },
        Ok(t) => {
          return Err(sel_err(loc, SelectorError::UnexpectedSelectorAfterPseudoElement(t)));
        }
        Err(_) => break,
      }
    }

    // Parse a combinator.
    let combinator;
    let mut any_whitespace = false;
    loop {
      let before_this_token = input.state();
      match input.next_including_whitespace() {
        Err(_) => break 'outer,
        Ok(Token::WhiteSpace(_)) => any_whitespace = true,
        Ok(Token::Delim('>')) => {
          combinator = Combinator::Child;
          break;
        }
        Ok(Token::Delim('+')) => {
          combinator = Combinator::NextSibling;
          break;
        }
        Ok(Token::Delim('~')) => {
          combinator = Combinator::LaterSibling;
          break;
        }
        Ok(_) => {
          input.reset(&before_this_token);
          if any_whitespace {
            combinator = Combinator::Descendant;
            break;
          } else {
            break 'outer;
          }
        }
      }
    }

    if !state.allows_combinators() {
      return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
    }

    components.push(Component::Combinator(combinator));
    has_combinators = true;
  }

  Ok(Selector(components))
}

enum SimpleSelectorParseResult<'i> {
  SimpleSelector(Component<'i>),
  PseudoElement(PseudoElement<'i>),
  SlottedPseudo(Selector<'i>),
  PartPseudo(Vec<Cow<'i, str>>),
}

/// Returns Some((has_pseudo_element, slotted, part)) or None if empty.
fn parse_compound_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  state: &mut SelectorParsingState,
  input: &mut Parser<'i, 't>,
  components: &mut Vec<Component<'i>>,
) -> SelResult<'i, Option<(bool, bool, bool)>> {
  input.skip_whitespace();

  let mut empty = true;
  if parser.is_nesting_allowed && input.try_parse(|input| input.expect_delim('&')).is_ok() {
    state.insert(SelectorParsingState::AFTER_NESTING);
    components.push(Component::Nesting);
    empty = false;
  }

  if parse_type_selector(parser, input, *state, components)? {
    empty = false;
  }

  let mut has_pseudo_element = false;
  let mut slotted = false;
  let mut part = false;
  loop {
    let result = match parse_one_simple_selector(parser, input, state)? {
      None => break,
      Some(result) => result,
    };

    if empty {
      if let Some(url) = &parser.default_namespace {
        // If there was no explicit type selector, but there is a
        // default namespace, there is an implicit "<defaultns>|*" type
        // selector. Except for :host() or :not() / :is() / :where(),
        // where we ignore it.
        if !state.intersects(SelectorParsingState::SKIP_DEFAULT_NAMESPACE) {
          components.push(Component::DefaultNamespace(url.clone()));
        }
      }
    }

    empty = false;

    match result {
      SimpleSelectorParseResult::SimpleSelector(s) => {
        components.push(s);
      }
      SimpleSelectorParseResult::PartPseudo(part_names) => {
        state.insert(SelectorParsingState::AFTER_PART);
        components.push(Component::Combinator(Combinator::Part));
        components.push(Component::Part(part_names));
        part = true;
      }
      SimpleSelectorParseResult::SlottedPseudo(selector) => {
        state.insert(SelectorParsingState::AFTER_SLOTTED);
        components.push(Component::Combinator(Combinator::SlotAssignment));
        components.push(Component::Slotted(Box::new(selector)));
        slotted = true;
      }
      SimpleSelectorParseResult::PseudoElement(p) => {
        if !p.accepts_state_pseudo_classes() {
          state.insert(SelectorParsingState::AFTER_NON_STATEFUL_PSEUDO_ELEMENT);
        }
        if p.is_webkit_scrollbar() {
          state.insert(SelectorParsingState::AFTER_WEBKIT_SCROLLBAR);
        }
        if p.is_view_transition() {
          state.insert(SelectorParsingState::AFTER_VIEW_TRANSITION);
        }
        if p.is_unknown() {
          state.insert(SelectorParsingState::AFTER_UNKNOWN_PSEUDO_ELEMENT);
        }
        state.insert(SelectorParsingState::AFTER_PSEUDO_ELEMENT);
        components.push(Component::Combinator(Combinator::PseudoElement));
        components.push(Component::PseudoElement(p));
        has_pseudo_element = true;
      }
    }
  }

  if empty {
    // An empty selector is invalid.
    Ok(None)
  } else {
    Ok(Some((has_pseudo_element, slotted, part)))
  }
}

enum QNamePrefix<'i> {
  ImplicitNoNamespace,
  ImplicitAnyNamespace,
  ImplicitDefaultNamespace(Cow<'i, str>),
  ExplicitNoNamespace,
  ExplicitAnyNamespace,
  ExplicitNamespace(Cow<'i, str>),
}

fn parse_type_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
  components: &mut Vec<Component<'i>>,
) -> SelResult<'i, bool> {
  match parse_qualified_name(parser, input, false) {
    Err(ParseError {
      kind: ParseErrorKind::Basic(BasicParseErrorKind::EndOfInput),
      ..
    })
    | Ok(None) => Ok(false),
    Ok(Some((namespace, local_name))) => {
      if state.intersects(SelectorParsingState::AFTER_PSEUDO) {
        return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
      }
      match namespace {
        QNamePrefix::ImplicitAnyNamespace => {}
        QNamePrefix::ImplicitDefaultNamespace(url) => components.push(Component::DefaultNamespace(url)),
        QNamePrefix::ExplicitNamespace(prefix) => components.push(Component::Namespace(prefix.clone(), prefix)),
        QNamePrefix::ExplicitNoNamespace => components.push(Component::ExplicitNoNamespace),
        QNamePrefix::ExplicitAnyNamespace => components.push(Component::ExplicitAnyNamespace),
        QNamePrefix::ImplicitNoNamespace => unreachable!(),
      }
      match local_name {
        Some(name) => components.push(Component::LocalName {
          lower_name: Cow::Owned(name.to_ascii_lowercase()),
          name,
        }),
        None => components.push(Component::ExplicitUniversalType),
      }
      Ok(true)
    }
    Err(e) => Err(e),
  }
}

fn parse_qualified_name<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  in_attr_selector: bool,
) -> SelResult<'i, Option<(QNamePrefix<'i>, Option<Cow<'i, str>>)>> {
  let start = input.state();

  let explicit_namespace = |input: &mut Parser<'i, 't>, namespace: QNamePrefix<'i>| {
    let location = input.current_source_location();
    match input.next_including_whitespace() {
      Ok(Token::Delim('*')) if !in_attr_selector => Ok(Some((namespace, None))),
      Ok(Token::Ident(local_name)) => Ok(Some((namespace, Some(local_name)))),
      Ok(t) if in_attr_selector => Err(sel_err(location, SelectorError::InvalidQualNameInAttr(t))),
      Ok(t) => Err(sel_err(location, SelectorError::ExplicitNamespaceUnexpectedToken(t))),
      Err(e) => Err(e.into()),
    }
  };

  let default_namespace = |local_name: Option<Cow<'i, str>>| {
    let namespace = match &parser.default_namespace {
      Some(url) => QNamePrefix::ImplicitDefaultNamespace(url.clone()),
      None => QNamePrefix::ImplicitAnyNamespace,
    };
    Ok(Some((namespace, local_name)))
  };

  match input.next_including_whitespace() {
    Ok(Token::Ident(value)) => {
      let after_ident = input.state();
      match input.next_including_whitespace() {
        Ok(Token::Delim('|')) => explicit_namespace(input, QNamePrefix::ExplicitNamespace(value)),
        _ => {
          input.reset(&after_ident);
          if in_attr_selector {
            Ok(Some((QNamePrefix::ImplicitNoNamespace, Some(value))))
          } else {
            default_namespace(Some(value))
          }
        }
      }
    }
    Ok(Token::Delim('*')) => {
      let after_star = input.state();
      match input.next_including_whitespace() {
        Ok(Token::Delim('|')) => explicit_namespace(input, QNamePrefix::ExplicitAnyNamespace),
        result => {
          input.reset(&after_star);
          if in_attr_selector {
            match result {
              Ok(t) => Err(sel_err(
                after_star.source_location(),
                SelectorError::ExpectedBarInAttr(t),
              )),
              Err(e) => Err(e.into()),
            }
          } else {
            default_namespace(None)
          }
        }
      }
    }
    Ok(Token::Delim('|')) => explicit_namespace(input, QNamePrefix::ExplicitNoNamespace),
    Ok(_) | Err(_) => {
      input.reset(&start);
      Ok(None)
    }
  }
}

fn parse_attribute_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
) -> SelResult<'i, Component<'i>> {
  let namespace;
  let local_name;

  input.skip_whitespace();

  match parse_qualified_name(parser, input, true)? {
    None => {
      let loc = input.current_source_location();
      let t = input.next()?;
      return Err(sel_err(loc, SelectorError::NoQualifiedNameInAttributeSelector(t)));
    }
    Some((_, None)) => unreachable!(),
    Some((ns, Some(ln))) => {
      local_name = ln;
      namespace = match ns {
        QNamePrefix::ImplicitNoNamespace | QNamePrefix::ExplicitNoNamespace => None,
        QNamePrefix::ExplicitNamespace(prefix) => Some(NamespaceConstraint::Specific(prefix)),
        QNamePrefix::ExplicitAnyNamespace => Some(NamespaceConstraint::Any),
        QNamePrefix::ImplicitAnyNamespace | QNamePrefix::ImplicitDefaultNamespace(_) => unreachable!(),
      }
    }
  }

  let location = input.current_source_location();
  let operator = match input.next() {
    // [foo]
    Err(_) => {
      let local_name_lower = Cow::Owned(local_name.to_ascii_lowercase());
      if let Some(namespace) = namespace {
        return Ok(Component::AttributeOther(Box::new(AttrSelectorWithOptionalNamespace {
          namespace: Some(namespace),
          local_name,
          operation: None,
        })));
      } else {
        return Ok(Component::AttributeInNoNamespaceExists {
          local_name,
          local_name_lower,
        });
      }
    }

    // [foo=bar]
    Ok(Token::Delim('=')) => AttrSelectorOperator::Equal,
    // [foo~=bar]
    Ok(Token::IncludeMatch) => AttrSelectorOperator::Includes,
    // [foo|=bar]
    Ok(Token::DashMatch) => AttrSelectorOperator::DashMatch,
    // [foo^=bar]
    Ok(Token::PrefixMatch) => AttrSelectorOperator::Prefix,
    // [foo*=bar]
    Ok(Token::SubstringMatch) => AttrSelectorOperator::Substring,
    // [foo$=bar]
    Ok(Token::SuffixMatch) => AttrSelectorOperator::Suffix,
    Ok(t) => {
      return Err(sel_err(location, SelectorError::UnexpectedTokenInAttributeSelector(t)));
    }
  };

  let value = match input.expect_ident_or_string() {
    Ok(t) => t,
    Err(crate::parser::BasicParseError {
      kind: BasicParseErrorKind::UnexpectedToken(t),
      location,
    }) => return Err(sel_err(location, SelectorError::BadValueInAttr(t))),
    Err(e) => return Err(e.into()),
  };
  let never_matches = match operator {
    AttrSelectorOperator::Equal | AttrSelectorOperator::DashMatch => false,
    AttrSelectorOperator::Includes => value.is_empty() || value.contains(|c| matches!(c, ' ' | '\t' | '\n' | '\r' | '\x0C')),
    AttrSelectorOperator::Prefix | AttrSelectorOperator::Substring | AttrSelectorOperator::Suffix => value.is_empty(),
  };

  let attribute_flags = parse_attribute_flags(input)?;

  let local_name_lower = local_name.to_ascii_lowercase();
  let local_name_is_ascii_lowercase = local_name_lower == local_name;
  let case_sensitivity = attribute_flags.to_case_sensitivity(&local_name_lower, namespace.is_some());

  if namespace.is_some() || !local_name_is_ascii_lowercase {
    Ok(Component::AttributeOther(Box::new(AttrSelectorWithOptionalNamespace {
      namespace,
      local_name,
      operation: Some((operator, value, case_sensitivity)),
    })))
  } else {
    Ok(Component::AttributeInNoNamespace {
      local_name,
      operator,
      value,
      case_sensitivity,
      never_matches,
    })
  }
}

enum AttributeFlags {
  CaseSensitivityDependsOnName,
  AsciiCaseInsensitive,
  CaseSensitive,
}

impl AttributeFlags {
  fn to_case_sensitivity(self, local_name: &str, have_namespace: bool) -> CaseSensitivity {
    match self {
      AttributeFlags::CaseSensitive => CaseSensitivity::ExplicitCaseSensitive,
      AttributeFlags::AsciiCaseInsensitive => CaseSensitivity::AsciiCaseInsensitive,
      AttributeFlags::CaseSensitivityDependsOnName => {
        if !have_namespace && ASCII_CASE_INSENSITIVE_HTML_ATTRIBUTES.contains(&local_name) {
          CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument
        } else {
          CaseSensitivity::CaseSensitive
        }
      }
    }
  }
}

const ASCII_CASE_INSENSITIVE_HTML_ATTRIBUTES: &[&str] = &[
  "accept", "accept-charset", "align", "alink", "axis", "bgcolor", "charset", "checked", "clear", "codetype", "color",
  "compact", "declare", "defer", "dir", "direction", "disabled", "enctype", "face", "frame", "hreflang", "http-equiv",
  "lang", "language", "link", "media", "method", "multiple", "nohref", "noresize", "noshade", "nowrap", "readonly",
  "rel", "rev", "rules", "scope", "scrolling", "selected", "shape", "target", "text", "type", "valign", "valuetype",
  "vlink",
];

fn parse_attribute_flags<'i, 't>(input: &mut Parser<'i, 't>) -> SelResult<'i, AttributeFlags> {
  let location = input.current_source_location();
  let token = match input.next() {
    Ok(t) => t,
    Err(..) => {
      // Selectors spec says language-defined; HTML says it depends on the
      // exact attribute name.
      return Ok(AttributeFlags::CaseSensitivityDependsOnName);
    }
  };

  let ident = match token {
    Token::Ident(ref i) => i.clone(),
    ref t => return Err(location.new_unexpected_token_error(t.clone())),
  };

  match ident.to_ascii_lowercase().as_str() {
    "i" => Ok(AttributeFlags::AsciiCaseInsensitive),
    "s" => Ok(AttributeFlags::CaseSensitive),
    _ => Err(location.new_unexpected_token_error(token)),
  }
}

fn parse_one_simple_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: &mut SelectorParsingState,
) -> SelResult<'i, Option<SimpleSelectorParseResult<'i>>> {
  let start = input.state();
  let token = match input.next_including_whitespace() {
    Ok(t) => t,
    Err(..) => {
      input.reset(&start);
      return Ok(None);
    }
  };

  Ok(Some(match token {
    Token::IDHash(id) => {
      if state.intersects(SelectorParsingState::AFTER_PSEUDO) {
        return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
      }
      SimpleSelectorParseResult::SimpleSelector(Component::ID(id))
    }
    Token::Delim('.') => {
      if state.intersects(SelectorParsingState::AFTER_PSEUDO) {
        return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
      }
      let location = input.current_source_location();
      let class = match input.next_including_whitespace()? {
        Token::Ident(class) => class,
        t => {
          let e = SelectorError::ClassNeedsIdent(t);
          return Err(sel_err(location, e));
        }
      };
      SimpleSelectorParseResult::SimpleSelector(Component::Class(class))
    }
    Token::SquareBracketBlock => {
      if state.intersects(SelectorParsingState::AFTER_PSEUDO) {
        return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
      }
      let attr = input.parse_nested_block(|input| parse_attribute_selector(parser, input))?;
      SimpleSelectorParseResult::SimpleSelector(attr)
    }
    Token::Colon => {
      let location = input.current_source_location();
      let (is_single_colon, next_token) = match input.next_including_whitespace()? {
        Token::Colon => (false, input.next_including_whitespace()?),
        t => (true, t),
      };
      let (name, is_functional) = match next_token {
        Token::Ident(name) => (name, false),
        Token::Function(name) => (name, true),
        t => {
          let e = SelectorError::PseudoElementExpectedIdent(t);
          return Err(sel_err(input.current_source_location(), e));
        }
      };
      let is_pseudo_element = !is_single_colon || is_css2_pseudo_element(&name);
      if is_pseudo_element {
        if !state.allows_pseudos() {
          return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
        }
        let pseudo_element = if is_functional {
          if name.eq_ignore_ascii_case("part") {
            if !state.allows_part() {
              return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
            }
            let names = input.parse_nested_block(|input| {
              let mut result = vec![input.expect_ident()?];
              while !input.is_exhausted() {
                result.push(input.expect_ident()?);
              }
              Ok(result)
            })?;
            return Ok(Some(SimpleSelectorParseResult::PartPseudo(names)));
          }

          if name.eq_ignore_ascii_case("slotted") {
            if !state.allows_slotted() {
              return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
            }
            let selector = input.parse_nested_block(|input| parse_inner_compound_selector(parser, input, state))?;
            return Ok(Some(SimpleSelectorParseResult::SlottedPseudo(selector)));
          }

          input.parse_nested_block(|input| parse_functional_pseudo_element(parser, location, name, input))?
        } else {
          parse_pseudo_element(parser, location, name)?
        };

        if state.intersects(SelectorParsingState::AFTER_SLOTTED) && !pseudo_element.valid_after_slotted() {
          return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::NonPseudoElementAfterSlotted)));
        }

        SimpleSelectorParseResult::PseudoElement(pseudo_element)
      } else {
        let pseudo_class = if is_functional {
          input.parse_nested_block(|input| parse_functional_pseudo_class(parser, input, name, *state))?
        } else {
          parse_simple_pseudo_class(parser, location, name, *state)?
        };
        SimpleSelectorParseResult::SimpleSelector(pseudo_class)
      }
    }
    _ => {
      input.reset(&start);
      return Ok(None);
    }
  }))
}

fn is_css2_pseudo_element(name: &str) -> bool {
  name.eq_ignore_ascii_case("before")
    || name.eq_ignore_ascii_case("after")
    || name.eq_ignore_ascii_case("first-line")
    || name.eq_ignore_ascii_case("first-letter")
}

fn parse_inner_compound_selector<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: &mut SelectorParsingState,
) -> SelResult<'i, Selector<'i>> {
  let mut child_state = SelectorParsingState {
    bits: state.bits | SelectorParsingState::DISALLOW_PSEUDOS | SelectorParsingState::DISALLOW_COMBINATORS,
  };
  let result = parse_selector_internal(parser, input, &mut child_state, NestingRequirement::None)?;
  if child_state.intersects(SelectorParsingState::AFTER_NESTING) {
    state.insert(SelectorParsingState::AFTER_NESTING);
  }
  Ok(result)
}

fn parse_functional_pseudo_class<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  name: Cow<'i, str>,
  state: SelectorParsingState,
) -> SelResult<'i, Component<'i>> {
  let lower = name.to_ascii_lowercase();
  match lower.as_str() {
    "nth-child" => return parse_nth_pseudo_class(parser, input, state, NthType::Child),
    "nth-of-type" => return parse_nth_pseudo_class(parser, input, state, NthType::OfType),
    "nth-last-child" => return parse_nth_pseudo_class(parser, input, state, NthType::LastChild),
    "nth-last-of-type" => return parse_nth_pseudo_class(parser, input, state, NthType::LastOfType),
    "is" => return parse_is_or_where(parser, input, state, |list| Component::Is(list)),
    "where" => return parse_is_or_where(parser, input, state, |list| Component::Where(list)),
    "-webkit-any" => return parse_is_or_where(parser, input, state, |list| Component::Any(VendorPrefix::WebKit, list)),
    "-moz-any" => return parse_is_or_where(parser, input, state, |list| Component::Any(VendorPrefix::Moz, list)),
    "has" => return parse_has(parser, input, state),
    "host" => {
      if !state.allows_tree_structural_pseudo_classes() {
        return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
      }
      let mut st = state;
      return Ok(Component::Host(Some(Box::new(parse_inner_compound_selector(parser, input, &mut st)?))));
    }
    "not" => return parse_negation(parser, input, state),
    _ => {}
  }

  if !state.allows_custom_functional_pseudo_classes() {
    return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
  }

  parse_non_ts_functional_pseudo_class(parser, name, input, state).map(Component::NonTSPseudoClass)
}

fn parse_non_ts_functional_pseudo_class<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  name: Cow<'i, str>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
) -> SelResult<'i, PseudoClass<'i>> {
  let lower = name.to_ascii_lowercase();
  let pseudo_class = match lower.as_str() {
    "lang" => {
      let langs = input.parse_comma_separated(|input| input.expect_ident_or_string().map_err(|e| e.into()))?;
      PseudoClass::Lang(langs)
    }
    "dir" => {
      let loc = input.current_source_location();
      let ident = input.expect_ident()?;
      let dir = match ident.to_ascii_lowercase().as_str() {
        "ltr" => Direction::Ltr,
        "rtl" => Direction::Rtl,
        _ => return Err(loc.new_unexpected_token_error(Token::Ident(ident))),
      };
      PseudoClass::Dir(dir)
    }
    "local" if parser.options.css_modules => {
      let mut st = state;
      PseudoClass::Local(Box::new(parse_selector_internal(parser, input, &mut st, NestingRequirement::None)?))
    }
    "global" if parser.options.css_modules => {
      let mut st = state;
      PseudoClass::Global(Box::new(parse_selector_internal(parser, input, &mut st, NestingRequirement::None)?))
    }
    _ => {
      if !name.starts_with('-') {
        parser.warn(input.new_custom_error(ParserError::SelectorError(SelectorError::UnsupportedPseudoClass(name.clone()))));
      }
      let arguments = TokenList::parse(input, parser.options, 0)?;
      PseudoClass::CustomFunction { name, arguments }
    }
  };
  Ok(pseudo_class)
}

fn parse_negation<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
) -> SelResult<'i, Component<'i>> {
  let mut st = state.with(SelectorParsingState::SKIP_DEFAULT_NAMESPACE | SelectorParsingState::DISALLOW_PSEUDOS);
  let list = SelectorList::parse_with_state(
    parser,
    input,
    &mut st,
    ParseErrorRecovery::DiscardList,
    NestingRequirement::None,
    false,
  )?;
  Ok(Component::Negation(list.0))
}

fn parse_is_or_where<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
  component: impl FnOnce(Vec<Selector<'i>>) -> Component<'i>,
) -> SelResult<'i, Component<'i>> {
  let mut st = state.with(SelectorParsingState::SKIP_DEFAULT_NAMESPACE | SelectorParsingState::DISALLOW_PSEUDOS);
  let inner = SelectorList::parse_with_state(
    parser,
    input,
    &mut st,
    ParseErrorRecovery::IgnoreInvalidSelector,
    NestingRequirement::None,
    false,
  )?;
  Ok(component(inner.0))
}

fn parse_has<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
) -> SelResult<'i, Component<'i>> {
  let mut st = state.with(SelectorParsingState::SKIP_DEFAULT_NAMESPACE | SelectorParsingState::DISALLOW_PSEUDOS | SelectorParsingState::DISALLOW_RELATIVE_SELECTOR);
  let inner = SelectorList::parse_with_state(
    parser,
    input,
    &mut st,
    ParseErrorRecovery::IgnoreInvalidSelector,
    NestingRequirement::None,
    true,
  )?;
  Ok(Component::Has(inner.0))
}

fn parse_nth_pseudo_class<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  input: &mut Parser<'i, 't>,
  state: SelectorParsingState,
  ty: NthType,
) -> SelResult<'i, Component<'i>> {
  if !state.allows_tree_structural_pseudo_classes() {
    return Err(input.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
  }
  let (a, b) = parse_nth(input)?;
  let nth_data = NthSelectorData {
    ty,
    is_function: true,
    a,
    b,
  };
  if matches!(ty, NthType::OfType | NthType::LastOfType) {
    return Ok(Component::Nth(nth_data));
  }

  // Try to parse "of <selector-list>".
  if input.try_parse(|i| i.expect_ident_matching("of")).is_err() {
    return Ok(Component::Nth(nth_data));
  }
  // Whitespace between "of" and the selector list is optional
  // https://github.com/w3c/csswg-drafts/issues/8285
  let mut st = state.with(SelectorParsingState::SKIP_DEFAULT_NAMESPACE | SelectorParsingState::DISALLOW_PSEUDOS);
  let selectors = SelectorList::parse_with_state(
    parser,
    input,
    &mut st,
    ParseErrorRecovery::DiscardList,
    NestingRequirement::None,
    false,
  )?;
  Ok(Component::NthOf(nth_data, selectors.0))
}

pub fn parse_nth<'i, 't>(input: &mut Parser<'i, 't>) -> SelResult<'i, (i32, i32)> {
  let loc = input.current_source_location();
  match input.next()? {
    Token::Number {
      int_value: Some(b), ..
    } => Ok((0, b)),
    Token::Dimension {
      int_value: Some(a),
      ref unit,
      ..
    } => {
      let lower = unit.to_ascii_lowercase();
      match lower.as_str() {
        "n" => Ok(parse_b(input, a)?),
        "n-" => Ok(parse_signless_b(input, a, -1)?),
        _ => match parse_n_dash_digits(unit) {
          Ok(b) => Ok((a, b)),
          Err(()) => Err(loc.new_unexpected_token_error(Token::Ident(unit.clone()))),
        },
      }
    }
    Token::Ident(ref value) => {
      let lower = value.to_ascii_lowercase();
      match lower.as_str() {
        "even" => Ok((2, 0)),
        "odd" => Ok((2, 1)),
        "n" => Ok(parse_b(input, 1)?),
        "-n" => Ok(parse_b(input, -1)?),
        "n-" => Ok(parse_signless_b(input, 1, -1)?),
        "-n-" => Ok(parse_signless_b(input, -1, -1)?),
        _ => {
          let (slice, a) = if value.starts_with("-") {
            (&value[1..], -1)
          } else {
            (&**value, 1)
          };
          match parse_n_dash_digits(slice) {
            Ok(b) => Ok((a, b)),
            Err(()) => Err(loc.new_unexpected_token_error(Token::Ident(value.clone()))),
          }
        }
      }
    }
    Token::Delim('+') => {
      let loc = input.current_source_location();
      match input.next_including_whitespace()? {
        Token::Ident(ref value) => {
          let lower = value.to_ascii_lowercase();
          match lower.as_str() {
            "n" => parse_b(input, 1),
            "n-" => parse_signless_b(input, 1, -1),
            _ => match parse_n_dash_digits(value) {
              Ok(b) => Ok((1, b)),
              Err(()) => Err(loc.new_unexpected_token_error(Token::Ident(value.clone()))),
            },
          }
        }
        token => Err(loc.new_unexpected_token_error(token)),
      }
    }
    token => Err(loc.new_unexpected_token_error(token)),
  }
}

fn parse_b<'i, 't>(input: &mut Parser<'i, 't>, a: i32) -> SelResult<'i, (i32, i32)> {
  let start = input.state();
  match input.next() {
    Ok(Token::Delim('+')) => parse_signless_b(input, a, 1),
    Ok(Token::Delim('-')) => parse_signless_b(input, a, -1),
    Ok(Token::Number {
      has_sign: true,
      int_value: Some(b),
      ..
    }) => Ok((a, b)),
    _ => {
      input.reset(&start);
      Ok((a, 0))
    }
  }
}

fn parse_signless_b<'i, 't>(input: &mut Parser<'i, 't>, a: i32, b_sign: i32) -> SelResult<'i, (i32, i32)> {
  let loc = input.current_source_location();
  match input.next()? {
    Token::Number {
      has_sign: false,
      int_value: Some(b),
      ..
    } => Ok((a, b_sign * b)),
    token => Err(loc.new_unexpected_token_error(token)),
  }
}

fn parse_n_dash_digits(string: &str) -> Result<i32, ()> {
  let bytes = string.as_bytes();
  if bytes.len() >= 3 && bytes[..2].eq_ignore_ascii_case(b"n-") && bytes[2..].iter().all(|&c| matches!(c, b'0'..=b'9')) {
    Ok(parse_number_saturate(&string[1..])) // Include the minus sign
  } else {
    Err(())
  }
}

fn parse_number_saturate(string: &str) -> i32 {
  let mut result: i64 = 0;
  let neg = string.starts_with('-');
  for c in string.bytes() {
    if c.is_ascii_digit() {
      result = result * 10 + (c - b'0') as i64;
      if result > i32::MAX as i64 {
        result = i32::MAX as i64;
      }
    }
  }
  if neg {
    -(result as i32)
  } else {
    result as i32
  }
}

fn parse_simple_pseudo_class<'a, 'i>(
  parser: &SelectorParser<'a, 'i>,
  location: SourceLocation,
  name: Cow<'i, str>,
  state: SelectorParsingState,
) -> SelResult<'i, Component<'i>> {
  if !state.allows_non_functional_pseudo_classes() {
    return Err(location.new_custom_error(ParserError::SelectorError(SelectorError::InvalidState)));
  }

  if state.allows_tree_structural_pseudo_classes() {
    let lower = name.to_ascii_lowercase();
    match lower.as_str() {
      "first-child" => return Ok(Component::Nth(NthSelectorData::first(false))),
      "last-child" => return Ok(Component::Nth(NthSelectorData::last(false))),
      "only-child" => return Ok(Component::Nth(NthSelectorData::only(false))),
      "root" => return Ok(Component::Root),
      "empty" => return Ok(Component::Empty),
      "scope" => return Ok(Component::Scope),
      "host" => return Ok(Component::Host(None)),
      "first-of-type" => return Ok(Component::Nth(NthSelectorData::first(true))),
      "last-of-type" => return Ok(Component::Nth(NthSelectorData::last(true))),
      "only-of-type" => return Ok(Component::Nth(NthSelectorData::only(true))),
      _ => {}
    }
  }

  let pseudo_class = parse_non_ts_pseudo_class(parser, location, name)?;
  if state.intersects(SelectorParsingState::AFTER_WEBKIT_SCROLLBAR) {
    if !pseudo_class.is_valid_after_webkit_scrollbar() {
      return Err(location.new_custom_error(ParserError::SelectorError(
        SelectorError::InvalidPseudoClassAfterWebKitScrollbar,
      )));
    }
  } else if state.intersects(SelectorParsingState::AFTER_PSEUDO_ELEMENT) {
    if !pseudo_class.is_user_action_state() {
      return Err(location.new_custom_error(ParserError::SelectorError(
        SelectorError::InvalidPseudoClassAfterPseudoElement,
      )));
    }
  } else if pseudo_class.is_valid_before_webkit_scrollbar() {
    return Err(location.new_custom_error(ParserError::SelectorError(
      SelectorError::InvalidPseudoClassBeforeWebKitScrollbar,
    )));
  }
  Ok(Component::NonTSPseudoClass(pseudo_class))
}

impl NthSelectorData {
  pub fn first(of_type: bool) -> Self {
    NthSelectorData {
      ty: if of_type { NthType::OfType } else { NthType::Child },
      is_function: false,
      a: 0,
      b: 1,
    }
  }
  pub fn last(of_type: bool) -> Self {
    NthSelectorData {
      ty: if of_type { NthType::LastOfType } else { NthType::LastChild },
      is_function: false,
      a: 0,
      b: 1,
    }
  }
  pub fn only(of_type: bool) -> Self {
    NthSelectorData {
      ty: if of_type { NthType::OnlyOfType } else { NthType::OnlyChild },
      is_function: false,
      a: 0,
      b: 1,
    }
  }

  fn write_start(&self, dest: &mut Printer, is_function: bool) -> PrintResult {
    dest.write_str(match self.ty {
      NthType::Child if is_function => ":nth-child(",
      NthType::Child => ":first-child",
      NthType::LastChild if is_function => ":nth-last-child(",
      NthType::LastChild => ":last-child",
      NthType::OfType if is_function => ":nth-of-type(",
      NthType::OfType => ":first-of-type",
      NthType::LastOfType if is_function => ":nth-last-of-type(",
      NthType::LastOfType => ":last-of-type",
      NthType::OnlyChild => ":only-child",
      NthType::OnlyOfType => ":only-of-type",
    })
  }

  fn write_affine(&self, dest: &mut Printer) -> PrintResult {
    match (self.a, self.b) {
      (0, 0) => dest.write_char('0'),
      (1, 0) => dest.write_char('n'),
      (-1, 0) => dest.write_str("-n"),
      (_, 0) => write!(dest, "{}n", self.a),
      (0, _) => write!(dest, "{}", self.b),
      (1, _) => write!(dest, "n{:+}", self.b),
      (-1, _) => write!(dest, "-n{:+}", self.b),
      (_, _) => write!(dest, "{}n{:+}", self.a, self.b),
    }
  }

  fn to_css_with_of(&self, dest: &mut Printer, of: Option<&[Selector]>) -> PrintResult {
    let is_function = of.is_some() || self.is_function && !(self.a == 0 && self.b == 1);
    self.write_start(dest, is_function)?;
    if is_function {
      if self.a == 2 && self.b == 1 {
        dest.write_str("odd")?;
      } else {
        self.write_affine(dest)?;
      }
      if let Some(selectors) = of {
        dest.write_str(" of ")?;
        serialize_selector_list(selectors, dest)?;
      }
      dest.write_char(')')?;
    }
    Ok(())
  }
}

fn parse_non_ts_pseudo_class<'a, 'i>(
  parser: &SelectorParser<'a, 'i>,
  loc: SourceLocation,
  name: Cow<'i, str>,
) -> SelResult<'i, PseudoClass<'i>> {
  use PseudoClass::*;
  let lower = name.to_ascii_lowercase();
  let pseudo_class = match lower.as_str() {
    "hover" => Hover,
    "active" => Active,
    "focus" => Focus,
    "focus-visible" => FocusVisible,
    "focus-within" => FocusWithin,
    "current" => Current,
    "past" => Past,
    "future" => Future,
    "playing" => Playing,
    "paused" => Paused,
    "seeking" => Seeking,
    "buffering" => Buffering,
    "stalled" => Stalled,
    "muted" => Muted,
    "volume-locked" => VolumeLocked,
    "fullscreen" => Fullscreen(VendorPrefix::None),
    "-webkit-full-screen" => Fullscreen(VendorPrefix::WebKit),
    "-moz-full-screen" => Fullscreen(VendorPrefix::Moz),
    "-ms-fullscreen" => Fullscreen(VendorPrefix::Ms),
    "open" => Open,
    "closed" => Closed,
    "modal" => Modal,
    "picture-in-picture" => PictureInPicture,
    "popover-open" => PopoverOpen,
    "defined" => Defined,
    "any-link" => AnyLink(VendorPrefix::None),
    "-webkit-any-link" => AnyLink(VendorPrefix::WebKit),
    "-moz-any-link" => AnyLink(VendorPrefix::Moz),
    "link" => Link,
    "local-link" => LocalLink,
    "target" => Target,
    "target-within" => TargetWithin,
    "visited" => Visited,
    "enabled" => Enabled,
    "disabled" => Disabled,
    "read-only" => ReadOnly(VendorPrefix::None),
    "-moz-read-only" => ReadOnly(VendorPrefix::Moz),
    "read-write" => ReadWrite(VendorPrefix::None),
    "-moz-read-write" => ReadWrite(VendorPrefix::Moz),
    "placeholder-shown" => PlaceholderShown(VendorPrefix::None),
    "-moz-placeholder-shown" => PlaceholderShown(VendorPrefix::Moz),
    "-ms-input-placeholder" => PlaceholderShown(VendorPrefix::Ms),
    "default" => Default,
    "checked" => Checked,
    "indeterminate" => Indeterminate,
    "blank" => Blank,
    "valid" => Valid,
    "invalid" => Invalid,
    "in-range" => InRange,
    "out-of-range" => OutOfRange,
    "required" => Required,
    "optional" => Optional,
    "user-valid" => UserValid,
    "user-invalid" => UserInvalid,
    "autofill" => Autofill(VendorPrefix::None),
    "-webkit-autofill" => Autofill(VendorPrefix::WebKit),
    "-o-autofill" => Autofill(VendorPrefix::O),
    "horizontal" => WebKitScrollbar(WebKitScrollbarPseudoClass::Horizontal),
    "vertical" => WebKitScrollbar(WebKitScrollbarPseudoClass::Vertical),
    "decrement" => WebKitScrollbar(WebKitScrollbarPseudoClass::Decrement),
    "increment" => WebKitScrollbar(WebKitScrollbarPseudoClass::Increment),
    "start" => WebKitScrollbar(WebKitScrollbarPseudoClass::Start),
    "end" => WebKitScrollbar(WebKitScrollbarPseudoClass::End),
    "double-button" => WebKitScrollbar(WebKitScrollbarPseudoClass::DoubleButton),
    "single-button" => WebKitScrollbar(WebKitScrollbarPseudoClass::SingleButton),
    "no-button" => WebKitScrollbar(WebKitScrollbarPseudoClass::NoButton),
    "corner-present" => WebKitScrollbar(WebKitScrollbarPseudoClass::CornerPresent),
    "window-inactive" => WebKitScrollbar(WebKitScrollbarPseudoClass::WindowInactive),
    _ => {
      if !name.starts_with('-') {
        parser.warn(loc.new_custom_error(ParserError::SelectorError(SelectorError::UnsupportedPseudoClass(name.clone()))));
      }
      Custom(name)
    }
  };
  Ok(pseudo_class)
}

impl<'i> PseudoClass<'i> {
  fn is_valid_after_webkit_scrollbar(&self) -> bool {
    matches!(self, PseudoClass::WebKitScrollbar(_) | PseudoClass::Hover | PseudoClass::Active)
  }

  fn is_valid_before_webkit_scrollbar(&self) -> bool {
    matches!(self, PseudoClass::WebKitScrollbar(_))
  }

  fn is_user_action_state(&self) -> bool {
    matches!(
      self,
      PseudoClass::Active | PseudoClass::Hover | PseudoClass::Focus | PseudoClass::FocusWithin | PseudoClass::FocusVisible
    )
  }

  pub fn get_prefix(&self) -> VendorPrefix {
    match self {
      PseudoClass::Fullscreen(p)
      | PseudoClass::AnyLink(p)
      | PseudoClass::ReadOnly(p)
      | PseudoClass::ReadWrite(p)
      | PseudoClass::PlaceholderShown(p)
      | PseudoClass::Autofill(p) => *p,
      _ => VendorPrefix::empty(),
    }
  }

  pub fn is_equivalent(&self, other: &PseudoClass<'i>) -> bool {
    match (self, other) {
      (PseudoClass::Fullscreen(_), PseudoClass::Fullscreen(_))
      | (PseudoClass::AnyLink(_), PseudoClass::AnyLink(_))
      | (PseudoClass::ReadOnly(_), PseudoClass::ReadOnly(_))
      | (PseudoClass::ReadWrite(_), PseudoClass::ReadWrite(_))
      | (PseudoClass::PlaceholderShown(_), PseudoClass::PlaceholderShown(_))
      | (PseudoClass::Autofill(_), PseudoClass::Autofill(_)) => true,
      (a, b) => a == b,
    }
  }
}

fn parse_pseudo_element<'a, 'i>(
  parser: &SelectorParser<'a, 'i>,
  loc: SourceLocation,
  name: Cow<'i, str>,
) -> SelResult<'i, PseudoElement<'i>> {
  use PseudoElement::*;
  let lower = name.to_ascii_lowercase();
  let pseudo_element = match lower.as_str() {
    "before" => Before,
    "after" => After,
    "first-line" => FirstLine,
    "first-letter" => FirstLetter,
    "cue" => Cue,
    "cue-region" => CueRegion,
    "selection" => Selection(VendorPrefix::None),
    "-moz-selection" => Selection(VendorPrefix::Moz),
    "placeholder" => Placeholder(VendorPrefix::None),
    "-webkit-input-placeholder" => Placeholder(VendorPrefix::WebKit),
    "-moz-placeholder" => Placeholder(VendorPrefix::Moz),
    "-ms-input-placeholder" => Placeholder(VendorPrefix::Moz),
    "marker" => Marker,
    "backdrop" => Backdrop(VendorPrefix::None),
    "-webkit-backdrop" => Backdrop(VendorPrefix::WebKit),
    "file-selector-button" => FileSelectorButton(VendorPrefix::None),
    "-webkit-file-upload-button" => FileSelectorButton(VendorPrefix::WebKit),
    "-ms-browse" => FileSelectorButton(VendorPrefix::Ms),
    "-webkit-scrollbar" => WebKitScrollbar(WebKitScrollbarPseudoElement::Scrollbar),
    "-webkit-scrollbar-button" => WebKitScrollbar(WebKitScrollbarPseudoElement::Button),
    "-webkit-scrollbar-track" => WebKitScrollbar(WebKitScrollbarPseudoElement::Track),
    "-webkit-scrollbar-track-piece" => WebKitScrollbar(WebKitScrollbarPseudoElement::TrackPiece),
    "-webkit-scrollbar-thumb" => WebKitScrollbar(WebKitScrollbarPseudoElement::Thumb),
    "-webkit-scrollbar-corner" => WebKitScrollbar(WebKitScrollbarPseudoElement::Corner),
    "-webkit-resizer" => WebKitScrollbar(WebKitScrollbarPseudoElement::Resizer),
    "view-transition" => ViewTransition,
    _ => {
      if !name.starts_with('-') {
        parser.warn(loc.new_custom_error(ParserError::SelectorError(SelectorError::UnsupportedPseudoElement(name.clone()))));
      }
      Custom(name)
    }
  };
  Ok(pseudo_element)
}

fn parse_view_transition_part_name<'i, 't>(input: &mut Parser<'i, 't>) -> SelResult<'i, Cow<'i, str>> {
  if input.try_parse(|input| input.expect_delim('*')).is_ok() {
    return Ok(Cow::Borrowed("*"));
  }
  Ok(crate::values::ident::CustomIdent::parse(input)?.0)
}

fn parse_functional_pseudo_element<'a, 'i, 't>(
  parser: &SelectorParser<'a, 'i>,
  loc: SourceLocation,
  name: Cow<'i, str>,
  input: &mut Parser<'i, 't>,
) -> SelResult<'i, PseudoElement<'i>> {
  use PseudoElement::*;
  let lower = name.to_ascii_lowercase();
  let pseudo_element = match lower.as_str() {
    "cue" => {
      let mut st = SelectorParsingState::default();
      CueFunction(Box::new(parse_selector_internal(parser, input, &mut st, NestingRequirement::None)?))
    }
    "cue-region" => {
      let mut st = SelectorParsingState::default();
      CueRegionFunction(Box::new(parse_selector_internal(parser, input, &mut st, NestingRequirement::None)?))
    }
    "view-transition-group" => ViewTransitionGroup(parse_view_transition_part_name(input)?),
    "view-transition-image-pair" => ViewTransitionImagePair(parse_view_transition_part_name(input)?),
    "view-transition-old" => ViewTransitionOld(parse_view_transition_part_name(input)?),
    "view-transition-new" => ViewTransitionNew(parse_view_transition_part_name(input)?),
    _ => {
      if !name.starts_with('-') {
        parser.warn(loc.new_custom_error(ParserError::SelectorError(SelectorError::UnsupportedPseudoElement(name.clone()))));
      }
      let arguments = TokenList::parse(input, parser.options, 0)?;
      CustomFunction { name, arguments }
    }
  };
  Ok(pseudo_element)
}

impl<'i> PseudoElement<'i> {
  fn accepts_state_pseudo_classes(&self) -> bool {
    // Be lenient: unknown pseudo elements are treated as not accepting state pseudo-classes
    !self.is_unknown()
  }

  fn is_unknown(&self) -> bool {
    matches!(self, PseudoElement::Custom(_) | PseudoElement::CustomFunction { .. })
  }

  fn is_webkit_scrollbar(&self) -> bool {
    matches!(self, PseudoElement::WebKitScrollbar(_))
  }

  fn is_view_transition(&self) -> bool {
    matches!(
      self,
      PseudoElement::ViewTransition
        | PseudoElement::ViewTransitionGroup(_)
        | PseudoElement::ViewTransitionImagePair(_)
        | PseudoElement::ViewTransitionOld(_)
        | PseudoElement::ViewTransitionNew(_)
    )
  }

  fn valid_after_slotted(&self) -> bool {
    matches!(
      self,
      PseudoElement::Before | PseudoElement::After | PseudoElement::Marker | PseudoElement::Placeholder(_) | PseudoElement::FileSelectorButton(_)
    )
  }

  pub fn get_prefix(&self) -> VendorPrefix {
    match self {
      PseudoElement::Selection(p) | PseudoElement::Placeholder(p) | PseudoElement::Backdrop(p) | PseudoElement::FileSelectorButton(p) => *p,
      _ => VendorPrefix::empty(),
    }
  }

  pub fn is_equivalent(&self, other: &PseudoElement<'i>) -> bool {
    match (self, other) {
      (PseudoElement::Selection(_), PseudoElement::Selection(_))
      | (PseudoElement::Placeholder(_), PseudoElement::Placeholder(_))
      | (PseudoElement::Backdrop(_), PseudoElement::Backdrop(_))
      | (PseudoElement::FileSelectorButton(_), PseudoElement::FileSelectorButton(_)) => true,
      (a, b) => a == b,
    }
  }
}

// ---------------------------------------------------------------------------
// Serialization

impl<'i> ToCss for SelectorList<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    serialize_selector_list(&self.0, dest)
  }
}

pub fn serialize_selector_list(selectors: &[Selector], dest: &mut Printer) -> PrintResult {
  let mut first = true;
  for selector in selectors {
    if !first {
      dest.delim(',', false)?;
    }
    first = false;
    selector.to_css(dest)?;
  }
  Ok(())
}

impl<'i> ToCss for Selector<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    serialize_selector(self, dest)
  }
}

fn effective_prefix(prefix: VendorPrefix, dest: &Printer) -> VendorPrefix {
  let dp = VendorPrefix::from_bits(dest.vendor_prefix);
  if dp.is_empty() {
    prefix
  } else {
    prefix & dp
  }
}

fn serialize_selector(selector: &Selector, dest: &mut Printer) -> PrintResult {
  // Split into compound selectors separated by combinators.
  let components = &selector.0;
  let mut i = 0;
  // Leading combinator (relative selector)
  if let Some(Component::Combinator(c)) = components.first() {
    c.to_css(dest)?;
    i = 1;
  }
  while i < components.len() {
    // Collect compound
    let start = i;
    while i < components.len() && !components[i].is_combinator() {
      i += 1;
    }
    let compound = &components[start..i];
    let next_combinator = if i < components.len() {
      if let Component::Combinator(c) = &components[i] {
        Some(*c)
      } else {
        None
      }
    } else {
      None
    };
    serialize_compound(compound, next_combinator, dest)?;
    if let Some(c) = next_combinator {
      c.to_css(dest)?;
      i += 1;
    }
  }
  Ok(())
}

fn serialize_compound(compound: &[Component], next_combinator: Option<Combinator>, dest: &mut Printer) -> PrintResult {
  if compound.is_empty() {
    return Ok(());
  }
  let (can_elide_namespace, first_non_namespace) = match &compound[0] {
    Component::ExplicitAnyNamespace | Component::ExplicitNoNamespace | Component::Namespace(..) => (false, 1),
    Component::DefaultNamespace(..) => (true, 1),
    _ => (true, 0),
  };
  let mut perform_step_2 = true;
  if first_non_namespace == compound.len() - 1 {
    match (next_combinator, &compound[first_non_namespace]) {
      // We have to be careful here, because if there is a
      // pseudo element "combinator" there isn't really just
      // the one simple selector. Technically this compound
      // selector contains the pseudo element selector as well
      // (Combinator::PseudoElement, just like
      // Combinator::SlotAssignment, don't exist in the
      // spec).
      (Some(Combinator::PseudoElement), _) | (Some(Combinator::SlotAssignment), _) => (),
      (_, &Component::ExplicitUniversalType) => {
        // Iterate over everything so we serialize the namespace
        // too.
        for simple in compound.iter() {
          simple.to_css(dest)?;
        }
        // Skip step 2, which is an "otherwise".
        perform_step_2 = false;
      }
      _ => (),
    }
  }

  if perform_step_2 {
    for simple in compound.iter() {
      if let Component::ExplicitUniversalType = *simple {
        // Can't have a namespace followed by a pseudo-element
        // selector followed by something else in the same compound
        // selector, so we don't have to worry about this case.
        if can_elide_namespace {
          continue;
        }
      }
      simple.to_css(dest)?;
    }
  }
  Ok(())
}

impl ToCss for Combinator {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match *self {
      Combinator::Child => dest.delim('>', true),
      Combinator::Descendant => dest.write_str(" "),
      Combinator::NextSibling => dest.delim('+', true),
      Combinator::LaterSibling => dest.delim('~', true),
      Combinator::PseudoElement | Combinator::Part | Combinator::SlotAssignment => Ok(()),
      Combinator::Deep => dest.write_str(" /deep/ "),
      Combinator::DeepDescendant => dest.write_str(">>>"),
    }
  }
}

fn is_type_selector(c: Option<&Component>) -> bool {
  matches!(c, Some(Component::LocalName { .. }) | Some(Component::ExplicitUniversalType))
}

fn is_namespace(c: Option<&Component>) -> bool {
  matches!(
    c,
    Some(Component::ExplicitAnyNamespace) | Some(Component::ExplicitNoNamespace) | Some(Component::Namespace(..)) | Some(Component::DefaultNamespace(_))
  )
}

fn has_type_selector(selector: &Selector) -> bool {
  let mut iter = selector.0.iter();
  let first = iter.next();
  if is_namespace(first) {
    is_type_selector(iter.next())
  } else {
    is_type_selector(first)
  }
}

fn is_simple(selector: &Selector) -> bool {
  !selector.0.iter().any(|c| c.is_combinator())
}

fn should_unwrap_is(list: &[Selector]) -> bool {
  if list.len() == 1 {
    let first = &list[0];
    if !has_type_selector(first) && is_simple(first) {
      return true;
    }
  }
  false
}

impl<'i> ToCss for Component<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Component::Combinator(c) => c.to_css(dest),
      Component::Slotted(selector) => {
        dest.write_str("::slotted(")?;
        selector.to_css(dest)?;
        dest.write_char(')')
      }
      Component::Part(part_names) => {
        dest.write_str("::part(")?;
        for (i, name) in part_names.iter().enumerate() {
          if i != 0 {
            dest.write_char(' ')?;
          }
          serialize_identifier(name, dest)?;
        }
        dest.write_char(')')
      }
      Component::PseudoElement(p) => p.to_css(dest),
      Component::ID(s) => {
        dest.write_char('#')?;
        dest.write_ident(s, true)
      }
      Component::Class(s) => {
        dest.write_char('.')?;
        dest.write_ident(s, true)
      }
      Component::LocalName { name, .. } => serialize_identifier(name, dest),
      Component::ExplicitUniversalType => dest.write_char('*'),
      Component::DefaultNamespace(_) => Ok(()),
      Component::ExplicitNoNamespace => dest.write_char('|'),
      Component::ExplicitAnyNamespace => dest.write_str("*|"),
      Component::Namespace(prefix, _) => {
        serialize_identifier(prefix, dest)?;
        dest.write_char('|')
      }
      Component::AttributeInNoNamespaceExists { local_name, .. } => {
        dest.write_char('[')?;
        serialize_identifier(local_name, dest)?;
        dest.write_char(']')
      }
      Component::AttributeInNoNamespace {
        local_name,
        operator,
        value,
        case_sensitivity,
        ..
      } => {
        dest.write_char('[')?;
        serialize_identifier(local_name, dest)?;
        dest.write_str(operator.as_str())?;

        if dest.minify {
          // PERF: Serialize the string into a temporary buffer, and only quote if necessary.
          let mut id = String::new();
          serialize_identifier_to_string(value, &mut id);
          let mut s = String::new();
          serialize_string_to_string(value, &mut s);
          if !id.is_empty() && id.len() < s.len() {
            dest.write_str(&id)?;
          } else {
            dest.write_str(&s)?;
          }
        } else {
          crate::printer::serialize_string(value, dest)?;
        }

        match case_sensitivity {
          CaseSensitivity::CaseSensitive | CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument => {}
          CaseSensitivity::AsciiCaseInsensitive => dest.write_str(" i")?,
          CaseSensitivity::ExplicitCaseSensitive => dest.write_str(" s")?,
        }
        dest.write_char(']')
      }
      Component::AttributeOther(attr) => {
        dest.write_char('[')?;
        match &attr.namespace {
          Some(NamespaceConstraint::Specific(prefix)) => {
            serialize_identifier(prefix, dest)?;
            dest.write_char('|')?;
          }
          Some(NamespaceConstraint::Any) => dest.write_str("*|")?,
          None => {}
        }
        serialize_identifier(&attr.local_name, dest)?;
        if let Some((operator, value, case_sensitivity)) = &attr.operation {
          dest.write_str(operator.as_str())?;
          crate::printer::serialize_string(value, dest)?;
          match case_sensitivity {
            CaseSensitivity::CaseSensitive | CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument => {}
            CaseSensitivity::AsciiCaseInsensitive => dest.write_str(" i")?,
            CaseSensitivity::ExplicitCaseSensitive => dest.write_str(" s")?,
          }
        }
        dest.write_char(']')
      }
      Component::Is(list) | Component::Where(list) | Component::Negation(list) | Component::Any(_, list) => {
        match self {
          Component::Where(..) => dest.write_str(":where(")?,
          Component::Is(..) => {
            // If there's only one simple selector, serialize it directly.
            if should_unwrap_is(list) {
              return list[0].to_css(dest);
            }
            dest.write_str(":is(")?;
          }
          Component::Negation(..) => dest.write_str(":not(")?,
          Component::Any(prefix, _) => {
            dest.write_char(':')?;
            prefix.to_css(dest)?;
            dest.write_str("any(")?;
          }
          _ => unreachable!(),
        }
        serialize_selector_list(list, dest)?;
        dest.write_char(')')
      }
      Component::Has(list) => {
        dest.write_str(":has(")?;
        serialize_selector_list(list, dest)?;
        dest.write_char(')')
      }
      Component::NonTSPseudoClass(pseudo) => pseudo.to_css(dest),
      Component::Nesting => dest.write_char('&'),
      Component::Root => dest.write_str(":root"),
      Component::Empty => dest.write_str(":empty"),
      Component::Scope => dest.write_str(":scope"),
      Component::Host(selector) => {
        dest.write_str(":host")?;
        if let Some(ref selector) = *selector {
          dest.write_char('(')?;
          selector.to_css(dest)?;
          dest.write_char(')')?;
        }
        Ok(())
      }
      Component::Nth(nth) => nth.to_css_with_of(dest, None),
      Component::NthOf(nth, selectors) => nth.to_css_with_of(dest, Some(selectors)),
    }
  }
}

impl<'i> ToCss for PseudoClass<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    use PseudoClass::*;
    match self {
      Lang(langs) => {
        dest.write_str(":lang(")?;
        let mut first = true;
        for lang in langs {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          serialize_identifier(lang, dest)?;
        }
        return dest.write_str(")");
      }
      Dir(dir) => {
        dest.write_str(":dir(")?;
        dest.write_str(match dir {
          Direction::Ltr => "ltr",
          Direction::Rtl => "rtl",
        })?;
        return dest.write_str(")");
      }
      _ => {}
    }

    macro_rules! write_prefixed {
      ($prefix: ident, $val: expr) => {{
        dest.write_char(':')?;
        let vp = effective_prefix(*$prefix, dest);
        vp.to_css(dest)?;
        dest.write_str($val)
      }};
    }

    match self {
      Hover => dest.write_str(":hover"),
      Active => dest.write_str(":active"),
      Focus => dest.write_str(":focus"),
      FocusVisible => dest.write_str(":focus-visible"),
      FocusWithin => dest.write_str(":focus-within"),
      Current => dest.write_str(":current"),
      Past => dest.write_str(":past"),
      Future => dest.write_str(":future"),
      Playing => dest.write_str(":playing"),
      Paused => dest.write_str(":paused"),
      Seeking => dest.write_str(":seeking"),
      Buffering => dest.write_str(":buffering"),
      Stalled => dest.write_str(":stalled"),
      Muted => dest.write_str(":muted"),
      VolumeLocked => dest.write_str(":volume-locked"),
      Fullscreen(prefix) => {
        dest.write_char(':')?;
        let vp = effective_prefix(*prefix, dest);
        vp.to_css(dest)?;
        if vp == VendorPrefix::WebKit || vp == VendorPrefix::Moz {
          dest.write_str("full-screen")
        } else {
          dest.write_str("fullscreen")
        }
      }
      Open => dest.write_str(":open"),
      Closed => dest.write_str(":closed"),
      Modal => dest.write_str(":modal"),
      PictureInPicture => dest.write_str(":picture-in-picture"),
      PopoverOpen => dest.write_str(":popover-open"),
      Defined => dest.write_str(":defined"),
      AnyLink(prefix) => write_prefixed!(prefix, "any-link"),
      Link => dest.write_str(":link"),
      LocalLink => dest.write_str(":local-link"),
      Target => dest.write_str(":target"),
      TargetWithin => dest.write_str(":target-within"),
      Visited => dest.write_str(":visited"),
      Enabled => dest.write_str(":enabled"),
      Disabled => dest.write_str(":disabled"),
      ReadOnly(prefix) => write_prefixed!(prefix, "read-only"),
      ReadWrite(prefix) => write_prefixed!(prefix, "read-write"),
      PlaceholderShown(prefix) => write_prefixed!(prefix, "placeholder-shown"),
      Default => dest.write_str(":default"),
      Checked => dest.write_str(":checked"),
      Indeterminate => dest.write_str(":indeterminate"),
      Blank => dest.write_str(":blank"),
      Valid => dest.write_str(":valid"),
      Invalid => dest.write_str(":invalid"),
      InRange => dest.write_str(":in-range"),
      OutOfRange => dest.write_str(":out-of-range"),
      Required => dest.write_str(":required"),
      Optional => dest.write_str(":optional"),
      UserValid => dest.write_str(":user-valid"),
      UserInvalid => dest.write_str(":user-invalid"),
      Autofill(prefix) => write_prefixed!(prefix, "autofill"),
      Local(selector) => {
        dest.write_str(":local(")?;
        selector.to_css(dest)?;
        dest.write_char(')')
      }
      Global(selector) => {
        dest.write_str(":global(")?;
        selector.to_css(dest)?;
        dest.write_char(')')
      }
      WebKitScrollbar(s) => dest.write_str(match s {
        WebKitScrollbarPseudoClass::Horizontal => ":horizontal",
        WebKitScrollbarPseudoClass::Vertical => ":vertical",
        WebKitScrollbarPseudoClass::Decrement => ":decrement",
        WebKitScrollbarPseudoClass::Increment => ":increment",
        WebKitScrollbarPseudoClass::Start => ":start",
        WebKitScrollbarPseudoClass::End => ":end",
        WebKitScrollbarPseudoClass::DoubleButton => ":double-button",
        WebKitScrollbarPseudoClass::SingleButton => ":single-button",
        WebKitScrollbarPseudoClass::NoButton => ":no-button",
        WebKitScrollbarPseudoClass::CornerPresent => ":corner-present",
        WebKitScrollbarPseudoClass::WindowInactive => ":window-inactive",
      }),
      Custom(name) => {
        dest.write_char(':')?;
        dest.write_str(name)
      }
      CustomFunction { name, arguments } => {
        dest.write_char(':')?;
        dest.write_str(name)?;
        dest.write_char('(')?;
        arguments.to_css_internal(dest, false)?;
        dest.write_char(')')
      }
      Lang(_) | Dir(_) => unreachable!(),
    }
  }
}

impl<'i> ToCss for PseudoElement<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    use PseudoElement::*;

    macro_rules! write_prefixed {
      ($prefix: ident, $val: expr) => {{
        dest.write_str("::")?;
        let vp = effective_prefix(*$prefix, dest);
        vp.to_css(dest)?;
        dest.write_str($val)
      }};
    }

    match self {
      // CSS2 pseudo elements support a single colon syntax in addition
      // to the more correct double colon for other pseudo elements.
      // We use that here because it's supported everywhere and is shorter.
      After => dest.write_str(":after"),
      Before => dest.write_str(":before"),
      FirstLine => dest.write_str(":first-line"),
      FirstLetter => dest.write_str(":first-letter"),
      Marker => dest.write_str("::marker"),
      Selection(prefix) => write_prefixed!(prefix, "selection"),
      Cue => dest.write_str("::cue"),
      CueRegion => dest.write_str("::cue-region"),
      CueFunction(selector) => {
        dest.write_str("::cue(")?;
        selector.to_css(dest)?;
        dest.write_char(')')
      }
      CueRegionFunction(selector) => {
        dest.write_str("::cue-region(")?;
        selector.to_css(dest)?;
        dest.write_char(')')
      }
      Placeholder(prefix) => {
        dest.write_str("::")?;
        let vp = effective_prefix(*prefix, dest);
        vp.to_css(dest)?;
        if vp == VendorPrefix::WebKit || vp == VendorPrefix::Ms {
          dest.write_str("input-placeholder")
        } else {
          dest.write_str("placeholder")
        }
      }
      Backdrop(prefix) => write_prefixed!(prefix, "backdrop"),
      FileSelectorButton(prefix) => {
        dest.write_str("::")?;
        let vp = effective_prefix(*prefix, dest);
        vp.to_css(dest)?;
        if vp == VendorPrefix::WebKit {
          dest.write_str("file-upload-button")
        } else if vp == VendorPrefix::Ms {
          dest.write_str("browse")
        } else {
          dest.write_str("file-selector-button")
        }
      }
      WebKitScrollbar(s) => dest.write_str(match s {
        WebKitScrollbarPseudoElement::Scrollbar => "::-webkit-scrollbar",
        WebKitScrollbarPseudoElement::Button => "::-webkit-scrollbar-button",
        WebKitScrollbarPseudoElement::Track => "::-webkit-scrollbar-track",
        WebKitScrollbarPseudoElement::TrackPiece => "::-webkit-scrollbar-track-piece",
        WebKitScrollbarPseudoElement::Thumb => "::-webkit-scrollbar-thumb",
        WebKitScrollbarPseudoElement::Corner => "::-webkit-scrollbar-corner",
        WebKitScrollbarPseudoElement::Resizer => "::-webkit-resizer",
      }),
      ViewTransition => dest.write_str("::view-transition"),
      ViewTransitionGroup(name) => {
        dest.write_str("::view-transition-group(")?;
        write_part_name(name, dest)?;
        dest.write_char(')')
      }
      ViewTransitionImagePair(name) => {
        dest.write_str("::view-transition-image-pair(")?;
        write_part_name(name, dest)?;
        dest.write_char(')')
      }
      ViewTransitionOld(name) => {
        dest.write_str("::view-transition-old(")?;
        write_part_name(name, dest)?;
        dest.write_char(')')
      }
      ViewTransitionNew(name) => {
        dest.write_str("::view-transition-new(")?;
        write_part_name(name, dest)?;
        dest.write_char(')')
      }
      Custom(name) => {
        dest.write_str("::")?;
        dest.write_str(name)
      }
      CustomFunction { name, arguments } => {
        dest.write_str("::")?;
        dest.write_str(name)?;
        dest.write_char('(')?;
        arguments.to_css_internal(dest, false)?;
        dest.write_char(')')
      }
    }
  }
}

fn write_part_name(name: &str, dest: &mut Printer) -> PrintResult {
  if name == "*" {
    dest.write_char('*')
  } else {
    serialize_identifier(name, dest)
  }
}

// ---------------------------------------------------------------------------
// Analysis helpers used by minification.

/// Returns the vendor prefix (if any) used in the given selector list.
/// If multiple vendor prefixes are seen, this is invalid, and an empty result will be returned.
pub fn get_prefix(selectors: &SelectorList) -> VendorPrefix {
  let mut prefix = VendorPrefix::empty();
  for selector in &selectors.0 {
    for component in &selector.0 {
      let p = match component {
        // Return none rather than empty for these so that we call downlevel_selectors.
        Component::NonTSPseudoClass(pc) => pc.get_prefix().or_none(),
        Component::PseudoElement(pe) => pe.get_prefix().or_none(),
        _ => VendorPrefix::empty(),
      };

      if !p.is_empty() {
        if prefix.is_empty() || prefix == p {
          prefix = p;
        } else {
          return VendorPrefix::empty();
        }
      }
    }
  }
  prefix
}

/// Returns whether two selector lists are equivalent, i.e. the same minus any vendor prefix differences.
pub fn is_equivalent(selectors: &[Selector], other: &[Selector]) -> bool {
  if selectors.len() != other.len() {
    return false;
  }
  for (i, a) in selectors.iter().enumerate() {
    let b = &other[i];
    if a.0.len() != b.0.len() {
      return false;
    }
    for (a, b) in a.0.iter().zip(b.0.iter()) {
      let is_equivalent = match (a, b) {
        (Component::NonTSPseudoClass(a_ps), Component::NonTSPseudoClass(b_ps)) => a_ps.is_equivalent(b_ps),
        (Component::PseudoElement(a_pe), Component::PseudoElement(b_pe)) => a_pe.is_equivalent(b_pe),
        (a, b) => a == b,
      };
      if !is_equivalent {
        return false;
      }
    }
  }
  true
}

/// Returns whether the selectors are compatible with the given targets (and no unsupported/experimental things are used).
pub fn is_compatible(selectors: &[Selector], targets: crate::targets::Targets) -> bool {
  use crate::compat::Feature;
  for selector in selectors {
    for component in &selector.0 {
      let feature = match component {
        Component::ID(_) | Component::Class(_) | Component::LocalName { .. } => continue,
        Component::ExplicitAnyNamespace | Component::ExplicitNoNamespace | Component::DefaultNamespace(_) | Component::Namespace(..) => {
          Feature::Selectors2
        }
        Component::ExplicitUniversalType => Feature::Selectors2,
        Component::AttributeInNoNamespaceExists { .. } => Feature::Selectors2,
        Component::AttributeInNoNamespace {
          operator,
          case_sensitivity,
          ..
        } => {
          if *case_sensitivity != CaseSensitivity::CaseSensitive
            && *case_sensitivity != CaseSensitivity::AsciiCaseInsensitiveIfInHtmlElementInHtmlDocument
          {
            // case insensitive attribute selectors
            if targets.browsers.is_some() {
              return false;
            }
            continue;
          }
          match operator {
            AttrSelectorOperator::Equal | AttrSelectorOperator::Includes | AttrSelectorOperator::DashMatch => Feature::Selectors2,
            AttrSelectorOperator::Prefix | AttrSelectorOperator::Substring | AttrSelectorOperator::Suffix => Feature::Selectors3,
          }
        }
        Component::AttributeOther(attr) => match &attr.operation {
          None => Feature::Selectors2,
          Some((operator, _, _)) => match operator {
            AttrSelectorOperator::Equal | AttrSelectorOperator::Includes | AttrSelectorOperator::DashMatch => Feature::Selectors2,
            _ => Feature::Selectors3,
          },
        },
        Component::Nth(nth) => match nth.ty {
          NthType::Child if nth.a == 0 && nth.b == 1 => Feature::Selectors2,
          _ => Feature::Selectors3,
        },
        Component::NthOf(..) => {
          if targets.browsers.is_some() {
            return false;
          }
          continue;
        }
        Component::Negation(selectors) => {
          if !is_compatible(selectors, targets) {
            return false;
          }
          Feature::Selectors3
        }
        Component::NonTSPseudoClass(pseudo) => {
          use PseudoClass::*;
          match pseudo {
            Link | Visited | Active | Hover | Focus | Lang(..) => Feature::Selectors2,
            Checked | Disabled | Enabled | Target => Feature::Selectors3,
            AnyLink(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            Indeterminate => Feature::Selectors3,
            Fullscreen(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            FocusVisible | FocusWithin | Default | Dir(_) | Optional | Valid | Invalid | Required | InRange | OutOfRange => {
              Feature::Selectors3
            }
            PlaceholderShown(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            ReadOnly(prefix) | ReadWrite(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            Autofill(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            // Experimental, no browser support.
            Current | Past | Future | Playing | Paused | Seeking | Stalled | Buffering | Muted | VolumeLocked | TargetWithin
            | LocalLink | Blank | UserInvalid | UserValid | Defined | Open | Closed | Modal | PictureInPicture | PopoverOpen => {
              return false
            }
            Custom(..) | CustomFunction { .. } | Local(..) | Global(..) | WebKitScrollbar(..) => return false,
            _ => return false,
          }
        }
        Component::PseudoElement(pseudo) => {
          use PseudoElement::*;
          match pseudo {
            After | Before => Feature::Selectors2,
            FirstLine | FirstLetter => Feature::Selectors2,
            Selection(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            Placeholder(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            Marker => Feature::Selectors3,
            Backdrop(prefix) if *prefix == VendorPrefix::None => Feature::Selectors3,
            Cue => Feature::Selectors3,
            CueFunction(..) => Feature::Selectors3,
            ViewTransition | ViewTransitionGroup(..) | ViewTransitionImagePair(..) | ViewTransitionOld(..) | ViewTransitionNew(..) => {
              Feature::Selectors3
            }
            _ => return false,
          }
        }
        Component::Is(selectors) | Component::Where(selectors) | Component::Has(selectors) => {
          if !is_compatible(selectors, targets) {
            return false;
          }
          match component {
            Component::Is(_) => Feature::IsSelector,
            Component::Where(_) => Feature::WhereSelector,
            _ => Feature::HasSelector,
          }
        }
        Component::Any(..) => return false,
        Component::Scope | Component::Host(_) | Component::Slotted(_) | Component::Part(_) => Feature::Selectors3,
        Component::Root | Component::Empty => Feature::Selectors3,
        Component::Nesting => Feature::Nesting,
        Component::Combinator(c) => match c {
          Combinator::Child | Combinator::NextSibling => Feature::Selectors2,
          Combinator::LaterSibling => Feature::Selectors3,
          _ => continue,
        },
      };

      if !targets.is_compatible(feature) {
        return false;
      }
    }
  }
  true
}

/// Returns whether the selector list contains a pseudo element that is unknown or prefixed (can't be merged).
