#[derive(Clone, Debug, PartialEq)]
pub struct MediaList<'i> {
  pub media_queries: Vec<MediaQuery<'i>>,
}

impl<'i> MediaList<'i> {
  pub fn new() -> Self {
    MediaList { media_queries: vec![] }
  }

  pub fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let mut media_queries = vec![];
    loop {
      match input.parse_until_before(crate::parser::Delimiter::Comma, |i| MediaQuery::parse(i, options)) {
        Ok(mq) => {
          media_queries.push(mq);
        }
        Err(err) => match err.kind {
          crate::parser::ParseErrorKind::Basic(crate::parser::BasicParseErrorKind::EndOfInput) => {
            // Empty media query (e.g. trailing comma)
            if !media_queries.is_empty() || !input.is_exhausted() {
              return Err(err);
            }
            break;
          }
          _ => return Err(err),
        },
      }

      match input.next() {
        Ok(Token::Comma) => {}
        Ok(_) => unreachable!(),
        Err(_) => break,
      }
    }

    Ok(MediaList { media_queries })
  }

  pub fn always_matches(&self) -> bool {
    // If the media list is empty, it always matches.
    self.media_queries.is_empty() || self.media_queries.iter().all(|mq| mq.always_matches())
  }

  pub fn never_matches(&self) -> bool {
    !self.media_queries.is_empty() && self.media_queries.iter().all(|mq| mq.never_matches())
  }

  /// Merges the given media list into this one with "and".
  pub fn and(&mut self, b: &MediaList<'i>) -> Result<(), ()> {
    if self.media_queries.is_empty() {
      self.media_queries.extend(b.media_queries.iter().cloned());
      return Ok(());
    }
    for mq in &mut self.media_queries {
      for b in &b.media_queries {
        mq.and(b)?;
      }
    }
    Ok(())
  }
}

impl<'i> ToCss for MediaList<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.media_queries.is_empty() {
      dest.write_str("not all")?;
      return Ok(());
    }
    let mut first = true;
    for query in &self.media_queries {
      if !first {
        dest.delim(',', false)?;
      }
      first = false;
      query.to_css(dest)?;
    }
    Ok(())
  }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Qualifier {
  Only,
  Not,
}

#[derive(Clone, Debug, PartialEq)]
pub enum MediaType<'i> {
  All,
  Print,
  Screen,
  Custom(Cow<'i, str>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct MediaQuery<'i> {
  pub qualifier: Option<Qualifier>,
  pub media_type: MediaType<'i>,
  pub condition: Option<MediaCondition<'i>>,
}

impl<'i> MediaQuery<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let (qualifier, explicit_media_type) = input
      .try_parse(|input| -> Result<_, ()> {
        let qualifier = input
          .try_parse(|input| {
            let loc = input.current_source_location();
            let ident = input.expect_ident()?;
            match ident.to_ascii_lowercase().as_str() {
              "only" => Ok(Qualifier::Only),
              "not" => Ok(Qualifier::Not),
              _ => Err(loc.new_unexpected_token_error::<ParserError>(Token::Ident(ident))),
            }
          })
          .ok();
        let ident = input.expect_ident().map_err(|_| ())?;
        let media_type = match ident.to_ascii_lowercase().as_str() {
          "all" => MediaType::All,
          "print" => MediaType::Print,
          "screen" => MediaType::Screen,
          _ => MediaType::Custom(ident),
        };
        Ok((qualifier, Some(media_type)))
      })
      .unwrap_or_default();

    let condition = if explicit_media_type.is_none() {
      Some(MediaCondition::parse(input, true, options)?)
    } else if input.try_parse(|i| i.expect_ident_matching("and")).is_ok() {
      Some(MediaCondition::parse(input, false, options)?)
    } else {
      None
    };

    let media_type = explicit_media_type.unwrap_or(MediaType::All);
    Ok(MediaQuery {
      qualifier,
      media_type,
      condition,
    })
  }

  pub fn always_matches(&self) -> bool {
    self.qualifier.is_none() && self.media_type == MediaType::All && self.condition.is_none()
  }

  pub fn never_matches(&self) -> bool {
    self.qualifier == Some(Qualifier::Not) && self.media_type == MediaType::All && self.condition.is_none()
  }

  pub fn and(&mut self, b: &MediaQuery<'i>) -> Result<(), ()> {
    let at = (&self.qualifier, &self.media_type);
    let bt = (&b.qualifier, &b.media_type);
    let (qualifier, media_type) = if at == bt {
      (self.qualifier.clone(), self.media_type.clone())
    } else if at == (&None, &MediaType::All) {
      (b.qualifier.clone(), b.media_type.clone())
    } else if bt == (&None, &MediaType::All) {
      (self.qualifier.clone(), self.media_type.clone())
    } else {
      return Err(());
    };
    self.qualifier = qualifier;
    self.media_type = media_type;
    if let Some(cond) = &b.condition {
      self.condition = Some(if let Some(a) = &self.condition {
        MediaCondition::Operation {
          operator: Operator::And,
          conditions: vec![a.clone(), cond.clone()],
        }
      } else {
        cond.clone()
      });
    }
    Ok(())
  }
}

impl<'i> ToCss for MediaQuery<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if let Some(qual) = self.qualifier {
      dest.write_str(match qual {
        Qualifier::Only => "only",
        Qualifier::Not => "not",
      })?;
      dest.write_char(' ')?;
    }

    match &self.media_type {
      MediaType::All => {
        // Only print "all" if there's no condition.
        if self.qualifier.is_some() || self.condition.is_none() {
          dest.write_str("all")?;
        }
      }
      MediaType::Print => dest.write_str("print")?,
      MediaType::Screen => dest.write_str("screen")?,
      MediaType::Custom(desc) => dest.write_str(desc)?,
    }

    let condition = if let Some(condition) = &self.condition {
      condition
    } else {
      return Ok(());
    };

    let needs_parens = if self.media_type != MediaType::All || self.qualifier.is_some() {
      dest.write_str(" and ")?;
      matches!(condition, MediaCondition::Operation { operator, .. } if *operator != Operator::And)
    } else {
      false
    };

    to_css_with_parens_if_needed(condition, dest, needs_parens)
  }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Operator {
  And,
  Or,
}

impl Operator {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "and" => Ok(Operator::And),
      "or" => Ok(Operator::Or),
      _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum MediaCondition<'i> {
  Feature(MediaFeature<'i>),
  Not(Box<MediaCondition<'i>>),
  Operation {
    conditions: Vec<MediaCondition<'i>>,
    operator: Operator,
  },
}

impl<'i> MediaCondition<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>, allow_or: bool, options: &ParserOptions) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let first_condition = Self::parse_parens_or_function(input, allow_or, options)?;
    let operator = match input.try_parse(Operator::parse) {
      Ok(op) => op,
      Err(..) => return Ok(first_condition),
    };

    if !allow_or && operator == Operator::Or {
      return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
    }

    let mut conditions = vec![];
    conditions.push(first_condition);
    conditions.push(Self::parse_parens_or_function(input, allow_or, options)?);

    loop {
      if let Ok(op) = input.try_parse(Operator::parse) {
        if op != operator {
          return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
        }
        conditions.push(Self::parse_parens_or_function(input, allow_or, options)?);
      } else {
        return Ok(MediaCondition::Operation { conditions, operator });
      }
    }
  }

  fn parse_parens_or_function<'t>(
    input: &mut Parser<'i, 't>,
    allow_or: bool,
    options: &ParserOptions,
  ) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    match input.next()? {
      Token::ParenthesisBlock => Self::parse_paren_block(input, allow_or, options),
      Token::Ident(ref ident) if ident.eq_ignore_ascii_case("not") => {
        let inner = Self::parse_parens_or_function(input, allow_or, options)?;
        Ok(MediaCondition::Not(Box::new(inner)))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  fn parse_paren_block<'t>(input: &mut Parser<'i, 't>, _allow_or: bool, options: &ParserOptions) -> ParseResult<'i, Self> {
    input.parse_nested_block(|input| {
      if let Ok(inner) = input.try_parse(|i| Self::parse(i, true, options)) {
        return Ok(inner);
      }
      Ok(MediaCondition::Feature(MediaFeature::parse(input, options)?))
    })
  }
}

fn needs_parens(condition: &MediaCondition, parent_operator: Option<Operator>) -> bool {
  match condition {
    MediaCondition::Not(_) => true,
    MediaCondition::Operation { operator, .. } => Some(*operator) != parent_operator,
    MediaCondition::Feature(_) => false,
  }
}

fn to_css_with_parens_if_needed(condition: &MediaCondition, dest: &mut Printer, needs_parens: bool) -> PrintResult {
  if needs_parens {
    dest.write_char('(')?;
  }
  condition.to_css(dest)?;
  if needs_parens {
    dest.write_char(')')?;
  }
  Ok(())
}

impl<'i> ToCss for MediaCondition<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      MediaCondition::Feature(f) => f.to_css(dest),
      MediaCondition::Not(c) => {
        // Simplify `not (width >= 100px)` to `(width < 100px)`.
        if let MediaCondition::Feature(MediaFeature::Range { name, operator, value }) = &**c {
          if let Some(op) = operator.negate() {
            return MediaFeature::Range {
              name: name.clone(),
              operator: op,
              value: value.clone(),
            }
            .to_css(dest);
          }
        }
        dest.write_str("not ")?;
        to_css_with_parens_if_needed(c, dest, needs_parens(c, None))
      }
      MediaCondition::Operation { conditions, operator } => {
        let mut first = true;
        for condition in conditions {
          if !first {
            dest.write_char(' ')?;
            dest.write_str(match operator {
              Operator::And => "and",
              Operator::Or => "or",
            })?;
            dest.write_char(' ')?;
          }
          first = false;
          to_css_with_parens_if_needed(condition, dest, needs_parens(condition, Some(*operator)))?;
        }
        Ok(())
      }
    }
  }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum MediaFeatureComparison {
  Equal,
  GreaterThan,
  GreaterThanEqual,
  LessThan,
  LessThanEqual,
}

impl MediaFeatureComparison {
  fn negate(&self) -> Option<Self> {
    match self {
      MediaFeatureComparison::Equal => None,
      MediaFeatureComparison::GreaterThan => Some(MediaFeatureComparison::LessThanEqual),
      MediaFeatureComparison::GreaterThanEqual => Some(MediaFeatureComparison::LessThan),
      MediaFeatureComparison::LessThan => Some(MediaFeatureComparison::GreaterThanEqual),
      MediaFeatureComparison::LessThanEqual => Some(MediaFeatureComparison::GreaterThan),
    }
  }

  fn opposite(&self) -> Self {
    match self {
      MediaFeatureComparison::Equal => MediaFeatureComparison::Equal,
      MediaFeatureComparison::GreaterThan => MediaFeatureComparison::LessThan,
      MediaFeatureComparison::GreaterThanEqual => MediaFeatureComparison::LessThanEqual,
      MediaFeatureComparison::LessThan => MediaFeatureComparison::GreaterThan,
      MediaFeatureComparison::LessThanEqual => MediaFeatureComparison::GreaterThanEqual,
    }
  }

  fn as_str(&self) -> &'static str {
    match self {
      MediaFeatureComparison::Equal => "=",
      MediaFeatureComparison::GreaterThan => ">",
      MediaFeatureComparison::GreaterThanEqual => ">=",
      MediaFeatureComparison::LessThan => "<",
      MediaFeatureComparison::LessThanEqual => "<=",
    }
  }

  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    match input.next()? {
      Token::Delim('=') => Ok(MediaFeatureComparison::Equal),
      Token::Delim('>') => {
        if input.try_parse(|input| input.expect_delim('=')).is_ok() {
          Ok(MediaFeatureComparison::GreaterThanEqual)
        } else {
          Ok(MediaFeatureComparison::GreaterThan)
        }
      }
      Token::Delim('<') => {
        if input.try_parse(|input| input.expect_delim('=')).is_ok() {
          Ok(MediaFeatureComparison::LessThanEqual)
        } else {
          Ok(MediaFeatureComparison::LessThan)
        }
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum MediaFeatureName<'i> {
  Standard(Cow<'i, str>),
  Custom(DashedIdent<'i>),
  Unknown(Ident<'i>),
}

impl<'i> MediaFeatureName<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, (Self, Option<MediaFeatureComparison>)> {
    let ident = input.expect_ident()?;
    if ident.starts_with("--") {
      return Ok((MediaFeatureName::Custom(DashedIdent(ident)), None));
    }
    let lower = ident.to_ascii_lowercase();
    // Handle min-/max- prefixes for range features.
    let (name, cmp) = if let Some(rest) = lower.strip_prefix("min-") {
      (rest.to_string(), Some(MediaFeatureComparison::GreaterThanEqual))
    } else if let Some(rest) = lower.strip_prefix("max-") {
      (rest.to_string(), Some(MediaFeatureComparison::LessThanEqual))
    } else {
      (lower.clone(), None)
    };
    if cmp.is_some() {
      if is_range_feature(&name) {
        return Ok((MediaFeatureName::Standard(Cow::Owned(name)), cmp));
      } else if is_known_feature(&lower) {
        return Ok((MediaFeatureName::Standard(Cow::Owned(lower)), None));
      } else {
        return Ok((MediaFeatureName::Unknown(Ident(ident)), None));
      }
    }
    if is_known_feature(&lower) {
      Ok((MediaFeatureName::Standard(Cow::Owned(lower)), None))
    } else {
      Ok((MediaFeatureName::Unknown(Ident(ident)), None))
    }
  }

  fn is_range(&self) -> bool {
    match self {
      MediaFeatureName::Standard(name) => is_range_feature(name),
      _ => false,
    }
  }

  fn value_type(&self) -> ValueType {
    match self {
      MediaFeatureName::Standard(name) => feature_value_type(name),
      _ => ValueType::Unknown,
    }
  }
}

impl<'i> ToCss for MediaFeatureName<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      MediaFeatureName::Standard(name) => dest.write_str(name),
      MediaFeatureName::Custom(name) => name.to_css(dest),
      MediaFeatureName::Unknown(name) => dest.write_str(&name.0),
    }
  }
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum ValueType {
  Length,
  Number,
  Integer,
  Boolean,
  Resolution,
  Ratio,
  Ident,
  Unknown,
}

const RANGE_FEATURES: &[&str] = &[
  "width",
  "height",
  "aspect-ratio",
  "resolution",
  "color",
