  "inline-size",
  "block-size",
];

fn is_range_feature(name: &str) -> bool {
  RANGE_FEATURES.contains(&name)
}

const KNOWN_FEATURES: &[(&str, ValueType)] = &[
  ("width", ValueType::Length),
  ("height", ValueType::Length),
  ("aspect-ratio", ValueType::Ratio),
  ("orientation", ValueType::Ident),
  ("overflow-block", ValueType::Ident),
