  ("display-mode", ValueType::Ident),
  ("resolution", ValueType::Resolution),
  ("scan", ValueType::Ident),
  ("grid", ValueType::Boolean),
  ("update", ValueType::Ident),
  ("environment-blending", ValueType::Ident),
  ("color", ValueType::Integer),
  ("color-index", ValueType::Integer),
  ("monochrome", ValueType::Integer),
  ("color-gamut", ValueType::Ident),
  ("dynamic-range", ValueType::Ident),
  ("inverted-colors", ValueType::Ident),
  ("pointer", ValueType::Ident),
  ("hover", ValueType::Ident),
  ("any-pointer", ValueType::Ident),
  ("any-hover", ValueType::Ident),
  ("nav-controls", ValueType::Ident),
  ("video-color-gamut", ValueType::Ident),
  ("video-dynamic-range", ValueType::Ident),
  ("scripting", ValueType::Ident),
  ("prefers-reduced-motion", ValueType::Ident),
  ("prefers-reduced-transparency", ValueType::Ident),
  ("prefers-contrast", ValueType::Ident),
  ("forced-colors", ValueType::Ident),
  ("prefers-color-scheme", ValueType::Ident),
  ("prefers-reduced-data", ValueType::Ident),
  ("device-width", ValueType::Length),
  ("device-height", ValueType::Length),
  ("device-aspect-ratio", ValueType::Ratio),
  ("-webkit-device-pixel-ratio", ValueType::Number),
  ("-moz-device-pixel-ratio", ValueType::Number),
  ("inline-size", ValueType::Length),
  ("block-size", ValueType::Length),
];

fn is_known_feature(name: &str) -> bool {
  KNOWN_FEATURES.iter().any(|(n, _)| *n == name)
}

fn feature_value_type(name: &str) -> ValueType {
  KNOWN_FEATURES
    .iter()
    .find(|(n, _)| *n == name)
    .map(|(_, t)| *t)
    .unwrap_or(ValueType::Unknown)
}

#[derive(Clone, Debug, PartialEq)]
pub struct Ratio(pub f32, pub f32);

impl Ratio {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let first = parse_number(input)?;
    let second = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
      parse_number(input)?
    } else {
      1.0
    };
    Ok(Ratio(first, second))
  }
}

impl ToCss for Ratio {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    serialize_number(self.0, dest)?;
    if self.1 != 1.0 {
      dest.delim('/', false)?;
      serialize_number(self.1, dest)?;
    }
    Ok(())
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum MediaFeatureValue<'i> {
  Length(Length),
  Number(f32),
  Integer(i32),
  Boolean(bool),
  Resolution(Resolution),
  Ratio(Ratio),
  Ident(Ident<'i>),
  Env(EnvironmentVariable<'i>),
}

impl<'i> MediaFeatureValue<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>, ty: ValueType, options: &ParserOptions) -> ParseResult<'i, Self> {
    if let Ok(env) = input.try_parse(|input| {
      input.expect_function_matching("env")?;
      input.parse_nested_block(|input| EnvironmentVariable::parse_nested(input, options, 0))
    }) {
      return Ok(MediaFeatureValue::Env(env));
    }
    match ty {
      ValueType::Length => Ok(MediaFeatureValue::Length(Length::parse(input)?)),
      ValueType::Number => Ok(MediaFeatureValue::Number(parse_number(input)?)),
      ValueType::Integer => Ok(MediaFeatureValue::Integer(crate::values::number::parse_integer(input)?)),
      ValueType::Boolean => {
        let i = crate::values::number::parse_integer(input)?;
        if i != 0 && i != 1 {
          return Err(input.new_custom_error(ParserError::InvalidMediaQuery));
        }
        Ok(MediaFeatureValue::Boolean(i == 1))
      }
      ValueType::Resolution => Ok(MediaFeatureValue::Resolution(Resolution::parse(input)?)),
      ValueType::Ratio => Ok(MediaFeatureValue::Ratio(Ratio::parse(input)?)),
      ValueType::Ident => Ok(MediaFeatureValue::Ident(Ident::parse(input)?)),
      ValueType::Unknown => {
        // Ratios are ambiguous with numbers because the second param is optional (e.g. 2/1 == 2).
        // We require the / delimiter when parsing ratios so that 2/1 ends up as a ratio and 2 is
        // parsed as a number.
        if let Ok(ratio) = input.try_parse(|input| {
          let first = parse_number(input)?;
          input.expect_delim('/')?;
          let second = parse_number(input)?;
          Ok::<_, crate::parser::ParseError<ParserError>>(Ratio(first, second))
        }) {
          return Ok(MediaFeatureValue::Ratio(ratio));
        }
        // Parse number next so that unitless values are not parsed as lengths.
        if let Ok(num) = input.try_parse(|input| parse_number(input)) {
          return Ok(MediaFeatureValue::Number(num));
        }
        if let Ok(length) = input.try_parse(Length::parse) {
          return Ok(MediaFeatureValue::Length(length));
        }
        if let Ok(res) = input.try_parse(Resolution::parse) {
          return Ok(MediaFeatureValue::Resolution(res));
        }
        let ident = Ident::parse(input)?;
        Ok(MediaFeatureValue::Ident(ident))
      }
    }
  }
}

impl<'i> ToCss for MediaFeatureValue<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      MediaFeatureValue::Length(len) => len.to_css(dest),
      MediaFeatureValue::Number(num) => serialize_number(*num, dest),
      MediaFeatureValue::Integer(num) => write!(dest, "{}", num),
      MediaFeatureValue::Boolean(b) => {
        if *b {
          dest.write_char('1')
        } else {
          dest.write_char('0')
        }
      }
      MediaFeatureValue::Resolution(res) => res.to_css(dest),
      MediaFeatureValue::Ratio(ratio) => ratio.to_css(dest),
      MediaFeatureValue::Ident(id) => serialize_identifier(&id.0, dest),
      MediaFeatureValue::Env(env) => env.to_css(dest, false),
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum MediaFeature<'i> {
  Plain {
    name: MediaFeatureName<'i>,
    value: MediaFeatureValue<'i>,
  },
  Boolean {
    name: MediaFeatureName<'i>,
  },
  Range {
    name: MediaFeatureName<'i>,
    operator: MediaFeatureComparison,
    value: MediaFeatureValue<'i>,
  },
  Interval {
    name: MediaFeatureName<'i>,
    start: MediaFeatureValue<'i>,
    start_operator: MediaFeatureComparison,
    end: MediaFeatureValue<'i>,
    end_operator: MediaFeatureComparison,
  },
}

impl<'i> MediaFeature<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    if let Ok(res) = input.try_parse(|input| Self::parse_name_first(input, options)) {
      return Ok(res);
    }
    Self::parse_value_first(input, options)
  }

  fn parse_name_first<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let (name, legacy_op) = MediaFeatureName::parse(input)?;

    let operator = if input.try_parse(|input| input.expect_colon()).is_ok() {
      None
    } else {
      Some(MediaFeatureComparison::parse(input)?)
    };

    let value = MediaFeatureValue::parse(input, name.value_type(), options)?;
    if !input.is_exhausted() {
      return Err(input.new_custom_error(ParserError::InvalidMediaQuery));
    }

    if let Some(operator) = operator {
      if !name.is_range() {
        return Err(input.new_custom_error(ParserError::InvalidMediaQuery));
      }
      return Ok(MediaFeature::Range { name, operator, value });
    }

    if let Some(op) = legacy_op {
      return Ok(MediaFeature::Range {
        name,
        operator: op,
        value,
      });
    }

    Ok(MediaFeature::Plain { name, value })
  }

  fn parse_value_first<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    // Boolean feature: just a name.
    if let Ok(name) = input.try_parse(|input| {
      let (name, legacy) = MediaFeatureName::parse(input)?;
      if legacy.is_some() {
        return Err(input.new_custom_error::<ParserError, ParserError>(ParserError::InvalidMediaQuery));
      }
      input.expect_exhausted()?;
      Ok(name)
    }) {
      return Ok(MediaFeature::Boolean { name });
    }

    // Value-first range: <value> <op> <name> [<op> <value>]?
    let location = input.current_source_location();
    let first_value = MediaFeatureValue::parse(input, ValueType::Unknown, options)?;
    let first_op = MediaFeatureComparison::parse(input)?;
    let (name, legacy) = MediaFeatureName::parse(input)?;
    if legacy.is_some() || !name.is_range() {
      return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
    }

    // Re-parse the first value with the known type? We keep what we have, but convert
    // numbers to the appropriate type where possible.
    let first_value = coerce_value(first_value, name.value_type());

    if input.is_exhausted() {
      return Ok(MediaFeature::Range {
        name,
        operator: first_op.opposite(),
        value: first_value,
      });
    }

    let end_op = MediaFeatureComparison::parse(input)?;
    let end_value = MediaFeatureValue::parse(input, name.value_type(), options)?;
    if !input.is_exhausted() {
      return Err(input.new_custom_error(ParserError::InvalidMediaQuery));
    }

    // Both operators must be in the same direction.
    let same_direction = matches!(
      (first_op, end_op),
      (MediaFeatureComparison::LessThan | MediaFeatureComparison::LessThanEqual, MediaFeatureComparison::LessThan | MediaFeatureComparison::LessThanEqual)
        | (MediaFeatureComparison::GreaterThan | MediaFeatureComparison::GreaterThanEqual, MediaFeatureComparison::GreaterThan | MediaFeatureComparison::GreaterThanEqual)
    );
    if !same_direction {
      return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
    }

    Ok(MediaFeature::Interval {
      name,
      start: first_value,
      start_operator: first_op,
      end: end_value,
      end_operator: end_op,
    })
  }
}

fn coerce_value<'i>(value: MediaFeatureValue<'i>, ty: ValueType) -> MediaFeatureValue<'i> {
  match (value, ty) {
    (MediaFeatureValue::Number(n), ValueType::Length) => MediaFeatureValue::Length(Length::px(n)),
    (MediaFeatureValue::Number(n), ValueType::Integer) => MediaFeatureValue::Integer(n as i32),
    (MediaFeatureValue::Number(n), ValueType::Ratio) => MediaFeatureValue::Ratio(Ratio(n, 1.0)),
    (v, _) => v,
  }
}

impl<'i> ToCss for MediaFeature<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.write_char('(')?;
    match self {
      MediaFeature::Boolean { name } => {
        name.to_css(dest)?;
      }
      MediaFeature::Plain { name, value } => {
        name.to_css(dest)?;
        dest.delim(':', false)?;
        value.to_css(dest)?;
      }
      MediaFeature::Range { name, operator, value } => {
        // If range syntax is unsupported, use min/max prefix if possible.
        if dest.targets.should_compile(crate::compat::Feature::MediaRangeSyntax) {
          if let Some(prefix) = match operator {
            MediaFeatureComparison::GreaterThanEqual => Some("min-"),
            MediaFeatureComparison::LessThanEqual => Some("max-"),
            MediaFeatureComparison::Equal => Some(""),
            _ => None,
          } {
            dest.write_str(prefix)?;
            name.to_css(dest)?;
            dest.delim(':', false)?;
            value.to_css(dest)?;
            return dest.write_char(')');
          }
        }
        name.to_css(dest)?;
        dest.whitespace()?;
        dest.write_str(operator.as_str())?;
        dest.whitespace()?;
        value.to_css(dest)?;
      }
      MediaFeature::Interval {
        name,
        start,
        start_operator,
        end,
        end_operator,
      } => {
        if dest.targets.should_compile(crate::compat::Feature::MediaIntervalSyntax) {
          // Compile to two range features joined with "and".
          let a = MediaFeature::Range {
            name: name.clone(),
            operator: start_operator.opposite(),
            value: start.clone(),
          };
          let b = MediaFeature::Range {
            name: name.clone(),
            operator: *end_operator,
            value: end.clone(),
          };
          // Already wrote '(' — undo by writing inner differently.
          // We write the inner of a then close, then " and ", then b.
          match &a {
            MediaFeature::Range { name, operator, value } => {
              write_range_compiled(name, *operator, value, dest)?;
            }
            _ => unreachable!(),
          }
          dest.write_str(") and (")?;
          match &b {
            MediaFeature::Range { name, operator, value } => {
              write_range_compiled(name, *operator, value, dest)?;
            }
            _ => unreachable!(),
          }
          return dest.write_char(')');
        }
        start.to_css(dest)?;
        dest.whitespace()?;
        dest.write_str(start_operator.as_str())?;
        dest.whitespace()?;
        name.to_css(dest)?;
        dest.whitespace()?;
        dest.write_str(end_operator.as_str())?;
        dest.whitespace()?;
        end.to_css(dest)?;
      }
    }
    dest.write_char(')')
  }
}

fn write_range_compiled(
  name: &MediaFeatureName,
  operator: MediaFeatureComparison,
  value: &MediaFeatureValue,
  dest: &mut Printer,
) -> PrintResult {
  match operator {
    MediaFeatureComparison::GreaterThanEqual => {
      dest.write_str("min-")?;
      name.to_css(dest)?;
      dest.delim(':', false)?;
      value.to_css(dest)
    }
    MediaFeatureComparison::LessThanEqual => {
      dest.write_str("max-")?;
      name.to_css(dest)?;
      dest.delim(':', false)?;
      value.to_css(dest)
    }
    _ => {
      name.to_css(dest)?;
      dest.whitespace()?;
      dest.write_str(operator.as_str())?;
      dest.whitespace()?;
      value.to_css(dest)
    }
  }
}
