use crate::values::length::LengthPercentage;
use crate::values::percentage::{DimensionPercentage, Percentage};

#[derive(Clone, Debug, PartialEq)]
pub struct Position {
  pub x: HorizontalPosition,
  pub y: VerticalPosition,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum HorizontalPositionKeyword {
  Left,
  Right,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum VerticalPositionKeyword {
  Top,
  Bottom,
}

#[derive(Clone, Debug, PartialEq)]
pub enum PositionComponent<S> {
  Center,
  Length(LengthPercentage),
  Side { side: S, offset: Option<LengthPercentage> },
}

pub type HorizontalPosition = PositionComponent<HorizontalPositionKeyword>;
pub type VerticalPosition = PositionComponent<VerticalPositionKeyword>;

pub trait SideKeyword: Sized + Copy + PartialEq {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self>;
  fn as_str(&self) -> &'static str;
  fn is_start(&self) -> bool;
}

impl SideKeyword for HorizontalPositionKeyword {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "left" => Ok(HorizontalPositionKeyword::Left),
      "right" => Ok(HorizontalPositionKeyword::Right),
      _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
  fn as_str(&self) -> &'static str {
    match self {
      HorizontalPositionKeyword::Left => "left",
      HorizontalPositionKeyword::Right => "right",
    }
  }
  fn is_start(&self) -> bool {
    *self == HorizontalPositionKeyword::Left
  }
}

impl SideKeyword for VerticalPositionKeyword {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "top" => Ok(VerticalPositionKeyword::Top),
      "bottom" => Ok(VerticalPositionKeyword::Bottom),
      _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
  fn as_str(&self) -> &'static str {
    match self {
      VerticalPositionKeyword::Top => "top",
      VerticalPositionKeyword::Bottom => "bottom",
    }
  }
  fn is_start(&self) -> bool {
    *self == VerticalPositionKeyword::Top
  }
}

impl<S: SideKeyword> PositionComponent<S> {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|i| i.expect_ident_matching("center")).is_ok() {
      return Ok(PositionComponent::Center);
    }

    if let Ok(lp) = input.try_parse(|input| LengthPercentage::parse(input)) {
      if lp == DimensionPercentage::Percentage(Percentage(0.5)) {
        return Ok(PositionComponent::Center);
      }
      return Ok(PositionComponent::Length(lp));
    }

    let side = S::parse(input)?;
    let offset = input.try_parse(|input| LengthPercentage::parse(input)).ok();
    Ok(PositionComponent::Side { side, offset })
  }

  pub fn is_center(&self) -> bool {
    match self {
      PositionComponent::Center => true,
      PositionComponent::Length(DimensionPercentage::Percentage(p)) => p.0 == 0.5,
      _ => false,
    }
  }

  fn to_length_percentage(&self) -> Option<LengthPercentage> {
    match self {
      PositionComponent::Center => Some(LengthPercentage::percent(0.5)),
      PositionComponent::Length(l) => Some(l.clone()),
      PositionComponent::Side { side, offset: None } => {
        if side.is_start() {
          Some(LengthPercentage::zero())
        } else {
          Some(LengthPercentage::percent(1.0))
        }
      }
      PositionComponent::Side { side, offset: Some(o) } => {
        if side.is_start() {
          Some(o.clone())
        } else {
          None
        }
      }
    }
  }
}

impl<S: SideKeyword> ToCss for PositionComponent<S> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      PositionComponent::Center => dest.write_str("center"),
      PositionComponent::Length(l) => l.to_css(dest),
      PositionComponent::Side { side, offset } => {
        dest.write_str(side.as_str())?;
        if let Some(offset) = offset {
          dest.write_char(' ')?;
          offset.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

impl Position {
  pub fn center() -> Position {
    Position {
      x: PositionComponent::Center,
      y: PositionComponent::Center,
    }
  }

  pub fn is_center(&self) -> bool {
    self.x.is_center() && self.y.is_center()
  }

  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    match input.try_parse(HorizontalPosition::parse) {
      Ok(PositionComponent::Center) => {
        // Try parsing a vertical position next.
        if let Ok(y) = input.try_parse(VerticalPosition::parse) {
          return Ok(Position {
            x: PositionComponent::Center,
            y,
          });
        }

        // If it didn't work, assume the first actually represents a y position,
        // and the next is an x position. e.g. `center left` rather than `left center`.
        let x = input.try_parse(HorizontalPosition::parse).unwrap_or(PositionComponent::Center);
        let y = PositionComponent::Center;
        return Ok(Position { x, y });
      }
      Ok(x @ PositionComponent::Length(_)) => {
        // If we got a length as the first value, then this must be an x position,
        // and the next value (if any) must be a y position.
        if let Ok(y) = input.try_parse(VerticalPosition::parse) {
          return Ok(Position { x, y });
        }
        return Ok(Position {
          x,
          y: PositionComponent::Center,
        });
      }
      Ok(PositionComponent::Side { side, offset }) => {
        if let Ok(y) = input.try_parse(VerticalPosition::parse) {
          // 3 or 4 value syntax.
          match (&offset, &y) {
            (Some(_), PositionComponent::Length(_)) => {
              // `left 10px 20px` isn't valid.
              return Err(input.new_error_for_next_token());
            }
            _ => {}
          }
          return Ok(Position {
            x: PositionComponent::Side { side, offset },
            y,
          });
        }
        if let Some(offset) = offset {
          // 2 value syntax: `left 10px` → x: left, y: 10px
          let y = if offset == DimensionPercentage::Percentage(Percentage(0.5)) {
            PositionComponent::Center
          } else {
            PositionComponent::Length(offset)
          };
          return Ok(Position {
            x: PositionComponent::Side { side, offset: None },
            y,
          });
        }
        return Ok(Position {
          x: PositionComponent::Side { side, offset: None },
          y: PositionComponent::Center,
        });
      }
      _ => {}
    }

    // Otherwise, the first value must be a vertical position.
    let y = VerticalPosition::parse(input)?;
    match &y {
      PositionComponent::Side { .. } | PositionComponent::Center => {}
      PositionComponent::Length(_) => return Err(input.new_error_for_next_token()),
    }
    match y {
      PositionComponent::Side { side, offset: Some(offset) } => {
        // Must be followed by a horizontal position (3/4-value syntax).
        let x = HorizontalPosition::parse(input)?;
        if let PositionComponent::Length(_) = x {
          return Err(input.new_error_for_next_token());
        }
        Ok(Position {
          x,
          y: PositionComponent::Side { side, offset: Some(offset) },
        })
      }
      y => {
        let x = input.try_parse(HorizontalPosition::parse).unwrap_or(PositionComponent::Center);
        Ok(Position { x, y })
      }
    }
  }
}

impl ToCss for Position {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    use HorizontalPositionKeyword::*;
    use PositionComponent::*;
    use VerticalPositionKeyword::*;
    match (&self.x, &self.y) {
      (Center, Center) => dest.write_str("50%"),
      (Length(x), Center) => x.to_css(dest),
      (Center, Length(y)) => {
        dest.write_str("50% ")?;
        y.to_css(dest)
      }
      (Side { side: Left, offset: None }, Center) => dest.write_char('0'),
      (Side { side: Right, offset: None }, Center) => dest.write_str("100%"),
      (Center, Side { side, offset: None }) => dest.write_str(side.as_str()),
      (Center, Side { side: Top, offset: Some(yo) }) => {
        dest.write_str("50% ")?;
        yo.to_css(dest)
      }
      (Side { side: x, offset: None }, Side { side: y, offset: None }) => {
        let xl = self.x.to_length_percentage().unwrap();
        let yl = self.y.to_length_percentage().unwrap();
        let _ = (x, y);
        xl.to_css(dest)?;
        dest.write_char(' ')?;
        yl.to_css(dest)
      }
      (Side { side: Left, offset: Some(xo) }, Side { side: Top, offset: Some(yo) }) => {
        xo.to_css(dest)?;
        dest.write_char(' ')?;
        yo.to_css(dest)
      }
      (Side { side: Left, offset: Some(xo) }, Side { side: Top, offset: None }) => {
        xo.to_css(dest)?;
        dest.write_str(" 0")
      }
      (Side { side: Left, offset: None }, Side { side: Top, offset: Some(yo) }) => {
        dest.write_str("0 ")?;
        yo.to_css(dest)
      }
      (Side { side: Left, offset: Some(xo) }, Center) => xo.to_css(dest),
      (Side { side: Left, offset: None }, Length(y)) => {
        dest.write_str("0 ")?;
        y.to_css(dest)
      }
      (Length(x), Side { side: Top, offset: None }) => {
        x.to_css(dest)?;
        dest.write_str(" 0")
      }
      (x, y) => {
        x.to_css(dest)?;
        dest.write_char(' ')?;
        y.to_css(dest)
      }
    }
  }
}
