//! Rect values (4 sides).

use crate::error::ParseResult;
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::traits::Parse;

/// A generic value for a four-sided shorthand (top, right, bottom, left).
#[derive(Clone, Debug, PartialEq)]
pub struct Rect<T>(pub T, pub T, pub T, pub T);

impl<T: Clone> Rect<T> {
  pub fn new(first: T, second: T, third: T, fourth: T) -> Self {
    Rect(first, second, third, fourth)
  }

  pub fn all(v: T) -> Self {
    Rect(v.clone(), v.clone(), v.clone(), v)
  }
}

impl<'i, T: Parse<'i> + Clone> Rect<T> {
  pub fn parse_with<'t, F>(input: &mut Parser<'i, 't>, mut parse: F) -> ParseResult<'i, Self>
  where
    F: FnMut(&mut Parser<'i, 't>) -> ParseResult<'i, T>,
  {
    let first = parse(input)?;
    let second = if let Ok(second) = input.try_parse(|i| parse(i)) {
      second
    } else {
      // <first>
      return Ok(Self::new(first.clone(), first.clone(), first.clone(), first));
    };
    let third = if let Ok(third) = input.try_parse(|i| parse(i)) {
      third
    } else {
      // <first> <second>
      return Ok(Self::new(first.clone(), second.clone(), first, second));
    };
    let fourth = if let Ok(fourth) = input.try_parse(|i| parse(i)) {
      fourth
    } else {
      // <first> <second> <third>
      return Ok(Self::new(first, second.clone(), third, second));
    };
    // <first> <second> <third> <fourth>
    Ok(Self::new(first, second, third, fourth))
  }
}

impl<'i, T: Parse<'i> + Clone> Parse<'i> for Rect<T> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    Self::parse_with(input, T::parse)
  }
}

impl<T: ToCss + PartialEq> ToCss for Rect<T> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.0.to_css(dest)?;
    let same_vertical = self.0 == self.2;
    let same_horizontal = self.1 == self.3;
    if same_vertical && same_horizontal && self.0 == self.1 {
      return Ok(());
    }
    dest.write_str(" ")?;
    self.1.to_css(dest)?;
    if same_vertical && same_horizontal {
      return Ok(());
    }
    dest.write_str(" ")?;
    self.2.to_css(dest)?;
    if same_horizontal {
      return Ok(());
    }
    dest.write_str(" ")?;
    self.3.to_css(dest)
  }
}
