#[derive(Clone, Debug, PartialEq)]
pub enum Gradient {
  Linear(LinearGradient),
  RepeatingLinear(LinearGradient),
  Radial(RadialGradient),
  RepeatingRadial(RadialGradient),
  Conic(ConicGradient),
  RepeatingConic(ConicGradient),
  WebKitGradient(WebKitGradient),
}

impl Gradient {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let func = input.expect_function()?;
    let lower = func.to_ascii_lowercase();
    input.parse_nested_block(|input| match lower.as_str() {
      "linear-gradient" => Ok(Gradient::Linear(LinearGradient::parse(input, VendorPrefix::None)?)),
      "repeating-linear-gradient" => Ok(Gradient::RepeatingLinear(LinearGradient::parse(input, VendorPrefix::None)?)),
      "radial-gradient" => Ok(Gradient::Radial(RadialGradient::parse(input, VendorPrefix::None)?)),
      "repeating-radial-gradient" => Ok(Gradient::RepeatingRadial(RadialGradient::parse(input, VendorPrefix::None)?)),
      "conic-gradient" => Ok(Gradient::Conic(ConicGradient::parse(input)?)),
      "repeating-conic-gradient" => Ok(Gradient::RepeatingConic(ConicGradient::parse(input)?)),
      "-webkit-linear-gradient" => Ok(Gradient::Linear(LinearGradient::parse(input, VendorPrefix::WebKit)?)),
      "-webkit-repeating-linear-gradient" => Ok(Gradient::RepeatingLinear(LinearGradient::parse(input, VendorPrefix::WebKit)?)),
      "-webkit-radial-gradient" => Ok(Gradient::Radial(RadialGradient::parse(input, VendorPrefix::WebKit)?)),
      "-webkit-repeating-radial-gradient" => Ok(Gradient::RepeatingRadial(RadialGradient::parse(input, VendorPrefix::WebKit)?)),
      "-moz-linear-gradient" => Ok(Gradient::Linear(LinearGradient::parse(input, VendorPrefix::Moz)?)),
      "-moz-repeating-linear-gradient" => Ok(Gradient::RepeatingLinear(LinearGradient::parse(input, VendorPrefix::Moz)?)),
      "-moz-radial-gradient" => Ok(Gradient::Radial(RadialGradient::parse(input, VendorPrefix::Moz)?)),
      "-moz-repeating-radial-gradient" => Ok(Gradient::RepeatingRadial(RadialGradient::parse(input, VendorPrefix::Moz)?)),
      "-o-linear-gradient" => Ok(Gradient::Linear(LinearGradient::parse(input, VendorPrefix::O)?)),
      "-o-repeating-linear-gradient" => Ok(Gradient::RepeatingLinear(LinearGradient::parse(input, VendorPrefix::O)?)),
      "-o-radial-gradient" => Ok(Gradient::Radial(RadialGradient::parse(input, VendorPrefix::O)?)),
      "-o-repeating-radial-gradient" => Ok(Gradient::RepeatingRadial(RadialGradient::parse(input, VendorPrefix::O)?)),
      "-webkit-gradient" => Ok(Gradient::WebKitGradient(WebKitGradient::parse(input)?)),
      _ => Err(location.new_unexpected_token_error(Token::Ident(func.clone()))),
    })
  }

  pub fn get_vendor_prefix(&self) -> VendorPrefix {
    match self {
      Gradient::Linear(LinearGradient { vendor_prefix, .. })
      | Gradient::RepeatingLinear(LinearGradient { vendor_prefix, .. })
      | Gradient::Radial(RadialGradient { vendor_prefix, .. })
      | Gradient::RepeatingRadial(RadialGradient { vendor_prefix, .. }) => *vendor_prefix,
      Gradient::WebKitGradient(_) => VendorPrefix::WebKit,
      _ => VendorPrefix::None,
    }
  }
}

impl ToCss for Gradient {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let (f, prefix) = match self {
      Gradient::Linear(g) => ("linear-gradient(", g.vendor_prefix),
      Gradient::RepeatingLinear(g) => ("repeating-linear-gradient(", g.vendor_prefix),
      Gradient::Radial(g) => ("radial-gradient(", g.vendor_prefix),
      Gradient::RepeatingRadial(g) => ("repeating-radial-gradient(", g.vendor_prefix),
      Gradient::Conic(_) => ("conic-gradient(", VendorPrefix::None),
      Gradient::RepeatingConic(_) => ("repeating-conic-gradient(", VendorPrefix::None),
      Gradient::WebKitGradient(_) => ("-webkit-gradient(", VendorPrefix::None),
    };

    prefix.to_css(dest)?;
    dest.write_str(f)?;

    match self {
      Gradient::Linear(linear) | Gradient::RepeatingLinear(linear) => {
        linear.to_css(dest, linear.vendor_prefix != VendorPrefix::None)?;
      }
      Gradient::Radial(radial) | Gradient::RepeatingRadial(radial) => {
        radial.to_css(dest)?;
      }
      Gradient::Conic(conic) | Gradient::RepeatingConic(conic) => {
        conic.to_css(dest)?;
      }
      Gradient::WebKitGradient(g) => {
        g.to_css(dest)?;
      }
    }

    dest.write_char(')')
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct LinearGradient {
  pub vendor_prefix: VendorPrefix,
  pub direction: LineDirection,
  pub items: Vec<GradientItem<LengthPercentage>>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum LineDirection {
  Angle(Angle),
  Horizontal(HorizontalPositionKeyword),
  Vertical(VerticalPositionKeyword),
  Corner {
    horizontal: HorizontalPositionKeyword,
    vertical: VerticalPositionKeyword,
  },
}

impl LineDirection {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>, is_prefixed: bool) -> ParseResult<'i, Self> {
    // Spec allows unitless zero angles for gradients.
    // https://w3c.github.io/csswg-drafts/css-images-3/#linear-gradient-syntax
    if let Ok(angle) = input.try_parse(Angle::parse_with_unitless) {
      return Ok(LineDirection::Angle(angle));
    }

    if !is_prefixed {
      input.expect_ident_matching("to")?;
    }

    if let Ok(x) = input.try_parse(HorizontalPositionKeyword::parse) {
      if let Ok(y) = input.try_parse(VerticalPositionKeyword::parse) {
        return Ok(LineDirection::Corner { horizontal: x, vertical: y });
      }
      return Ok(LineDirection::Horizontal(x));
    }

    let y = VerticalPositionKeyword::parse(input)?;
    if let Ok(x) = input.try_parse(HorizontalPositionKeyword::parse) {
      return Ok(LineDirection::Corner { horizontal: x, vertical: y });
    }
    Ok(LineDirection::Vertical(y))
  }

  fn to_css(&self, dest: &mut Printer, is_prefixed: bool) -> PrintResult {
    match self {
      LineDirection::Angle(angle) => angle.to_css(dest),
      LineDirection::Horizontal(k) => {
        if dest.minify {
          match k {
            HorizontalPositionKeyword::Left => dest.write_str("270deg"),
            HorizontalPositionKeyword::Right => dest.write_str("90deg"),
          }
        } else {
          if !is_prefixed {
            dest.write_str("to ")?;
          }
          dest.write_str(k.as_str())
        }
      }
      LineDirection::Vertical(k) => {
        if dest.minify {
          match k {
            VerticalPositionKeyword::Top => dest.write_str("0deg"),
            VerticalPositionKeyword::Bottom => dest.write_str("180deg"),
          }
        } else {
          if !is_prefixed {
            dest.write_str("to ")?;
          }
          dest.write_str(k.as_str())
        }
      }
      LineDirection::Corner { horizontal, vertical } => {
        if !is_prefixed {
          dest.write_str("to ")?;
        }
        dest.write_str(vertical.as_str())?;
        dest.write_char(' ')?;
        dest.write_str(horizontal.as_str())
      }
    }
  }
}

impl LinearGradient {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>, vendor_prefix: VendorPrefix) -> ParseResult<'i, Self> {
    let direction = if let Ok(direction) = input.try_parse(|input| LineDirection::parse(input, vendor_prefix != VendorPrefix::None)) {
      input.expect_comma()?;
      direction
    } else {
      LineDirection::Vertical(VerticalPositionKeyword::Bottom)
    };
    let items = parse_items(input)?;
    Ok(LinearGradient {
      direction,
      items,
      vendor_prefix,
    })
  }

  fn to_css(&self, dest: &mut Printer, is_prefixed: bool) -> PrintResult {
    let angle = match &self.direction {
      LineDirection::Vertical(VerticalPositionKeyword::Bottom) => 180.0,
      LineDirection::Vertical(VerticalPositionKeyword::Top) => 0.0,
      LineDirection::Angle(angle) => angle.to_degrees(),
      _ => -1.0,
    };

    // We can omit `to bottom` or `180deg` because it is the default.
    if angle == 180.0 {
      serialize_items(&self.items, dest)
    } else if angle == 0.0 {
      // If we have `to top` or `0deg`, we can flip the gradient the other direction
      // and omit the direction.
      if let Some(items) = flip_items(&self.items) {
        serialize_items(&items, dest)
      } else {
        self.direction.to_css(dest, is_prefixed)?;
        dest.delim(',', false)?;
        serialize_items(&self.items, dest)
      }
    } else {
      self.direction.to_css(dest, is_prefixed)?;
      dest.delim(',', false)?;
      serialize_items(&self.items, dest)
    }
  }
}

fn flip_items(items: &[GradientItem<LengthPercentage>]) -> Option<Vec<GradientItem<LengthPercentage>>> {
  // All positions must be percentages (or none).
  let mut res = Vec::with_capacity(items.len());
  for item in items.iter().rev() {
    match item {
      GradientItem::Hint(DimensionPercentage::Percentage(p)) => {
        res.push(GradientItem::Hint(DimensionPercentage::Percentage(Percentage(1.0 - p.0))));
      }
      GradientItem::Hint(_) => return None,
      GradientItem::ColorStop(ColorStop { color, position }) => {
        let position = match position {
          None => None,
          Some(DimensionPercentage::Percentage(p)) => Some(DimensionPercentage::Percentage(Percentage(1.0 - p.0))),
          Some(_) => return None,
        };
        res.push(GradientItem::ColorStop(ColorStop {
          color: color.clone(),
          position,
        }));
      }
    }
  }
  Some(res)
}

#[derive(Clone, Debug, PartialEq)]
pub struct RadialGradient {
  pub vendor_prefix: VendorPrefix,
  pub shape: EndingShape,
  pub position: Position,
  pub items: Vec<GradientItem<LengthPercentage>>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum EndingShape {
  Circle(Circle),
  Ellipse(Ellipse),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Circle {
  Radius(Length),
  Extent(ShapeExtent),
}

#[derive(Clone, Debug, PartialEq)]
pub enum Ellipse {
  Size { x: LengthPercentage, y: LengthPercentage },
  Extent(ShapeExtent),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum ShapeExtent {
  ClosestSide,
  FarthestSide,
  ClosestCorner,
  FarthestCorner,
}

impl ShapeExtent {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let loc = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "closest-side" => Ok(ShapeExtent::ClosestSide),
      "farthest-side" => Ok(ShapeExtent::FarthestSide),
      "closest-corner" => Ok(ShapeExtent::ClosestCorner),
      "farthest-corner" => Ok(ShapeExtent::FarthestCorner),
      _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
    }
  }

  fn as_str(&self) -> &'static str {
    match self {
      ShapeExtent::ClosestSide => "closest-side",
      ShapeExtent::FarthestSide => "farthest-side",
      ShapeExtent::ClosestCorner => "closest-corner",
      ShapeExtent::FarthestCorner => "farthest-corner",
    }
  }
}

impl EndingShape {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    // Note: Ellipse::parse MUST run before Circle::parse for this to be correct.
    if let Ok(ellipse) = input.try_parse(Ellipse::parse) {
      return Ok(EndingShape::Ellipse(ellipse));
    }
    if let Ok(circle) = input.try_parse(Circle::parse) {
      return Ok(EndingShape::Circle(circle));
    }
    Err(input.new_error_for_next_token())
  }

  fn is_default(&self) -> bool {
    matches!(self, EndingShape::Ellipse(Ellipse::Extent(ShapeExtent::FarthestCorner)))
  }
}

impl ToCss for EndingShape {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      EndingShape::Circle(c) => c.to_css(dest),
      EndingShape::Ellipse(e) => e.to_css(dest),
    }
  }
}

impl Circle {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(extent) = input.try_parse(ShapeExtent::parse) {
      // The `circle` keyword is required. If it's not there, then it's an ellipse.
      input.expect_ident_matching("circle")?;
      return Ok(Circle::Extent(extent));
    }

    if let Ok(length) = input.try_parse(Length::parse) {
      // The `circle` keyword is optional if there is only a single length.
      // We are assuming here that Ellipse::parse ran first.
      let _ = input.try_parse(|input| input.expect_ident_matching("circle"));
      return Ok(Circle::Radius(length));
    }

    if input.try_parse(|input| input.expect_ident_matching("circle")).is_ok() {
      if let Ok(extent) = input.try_parse(ShapeExtent::parse) {
        return Ok(Circle::Extent(extent));
      }

      if let Ok(length) = input.try_parse(Length::parse) {
        return Ok(Circle::Radius(length));
      }

      // If only the `circle` keyword was given, default to `farthest-corner`.
      return Ok(Circle::Extent(ShapeExtent::FarthestCorner));
    }

    Err(input.new_error_for_next_token())
  }
}

impl ToCss for Circle {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Circle::Radius(r) => r.to_css(dest),
      Circle::Extent(extent) => {
        dest.write_str("circle")?;
        if *extent != ShapeExtent::FarthestCorner {
          dest.write_char(' ')?;
          dest.write_str(extent.as_str())?;
        }
        Ok(())
      }
    }
  }
}

impl Ellipse {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(extent) = input.try_parse(ShapeExtent::parse) {
      // The `ellipse` keyword is optional, but only if the `circle` keyword is not present.
      // If it is, then we'll re-parse as a circle.
      if input.try_parse(|input| input.expect_ident_matching("circle")).is_ok() {
        return Err(input.new_error_for_next_token());
      }
      let _ = input.try_parse(|input| input.expect_ident_matching("ellipse"));
      return Ok(Ellipse::Extent(extent));
    }

    if let Ok(x) = input.try_parse(LengthPercentage::parse) {
      let y = LengthPercentage::parse(input)?;
      // The `ellipse` keyword is optional if there are two lengths.
      let _ = input.try_parse(|input| input.expect_ident_matching("ellipse"));
      return Ok(Ellipse::Size { x, y });
    }

    if input.try_parse(|input| input.expect_ident_matching("ellipse")).is_ok() {
      if let Ok(extent) = input.try_parse(ShapeExtent::parse) {
        return Ok(Ellipse::Extent(extent));
      }

      if let Ok(x) = input.try_parse(LengthPercentage::parse) {
        let y = LengthPercentage::parse(input)?;
        return Ok(Ellipse::Size { x, y });
      }

      // Assume `farthest-corner` if only the `ellipse` keyword is present.
      return Ok(Ellipse::Extent(ShapeExtent::FarthestCorner));
    }

    Err(input.new_error_for_next_token())
  }
}

impl ToCss for Ellipse {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    // The `ellipse` keyword is optional, so we don't emit it.
    match self {
      Ellipse::Size { x, y } => {
        x.to_css(dest)?;
        dest.write_char(' ')?;
        y.to_css(dest)
      }
      Ellipse::Extent(extent) => dest.write_str(extent.as_str()),
    }
  }
}

impl RadialGradient {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>, vendor_prefix: VendorPrefix) -> ParseResult<'i, Self> {
    let shape = input.try_parse(EndingShape::parse).ok();
    let position = input
      .try_parse(|input| {
        input.expect_ident_matching("at")?;
        Position::parse(input)
      })
      .ok();

    if shape.is_some() || position.is_some() {
      input.expect_comma()?;
    }

    let items = parse_items(input)?;
    Ok(RadialGradient {
      shape: shape.unwrap_or(EndingShape::Ellipse(Ellipse::Extent(ShapeExtent::FarthestCorner))),
      position: position.unwrap_or(Position::center()),
      items,
      vendor_prefix,
    })
  }

  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if !self.shape.is_default() {
      self.shape.to_css(dest)?;
      if !self.position.is_center() {
        dest.write_char(' ')?;
      }
    }

    if !self.position.is_center() {
      dest.write_str("at ")?;
      self.position.to_css(dest)?;
    }

    if !self.shape.is_default() || !self.position.is_center() {
      dest.delim(',', false)?;
    }

    serialize_items(&self.items, dest)
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ConicGradient {
  pub angle: Angle,
  pub position: Position,
  pub items: Vec<GradientItem<AnglePercentage>>,
}

impl ConicGradient {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let angle = input.try_parse(|input| {
      input.expect_ident_matching("from")?;
      // Spec allows unitless zero angles for gradients.
      Angle::parse_with_unitless(input)
    });

    let position = input.try_parse(|input| {
      input.expect_ident_matching("at")?;
      Position::parse(input)
    });

    if angle.is_ok() || position.is_ok() {
      input.expect_comma()?;
    }

    let items = parse_items(input)?;
    Ok(ConicGradient {
      angle: angle.unwrap_or(Angle::Deg(0.0)),
      position: position.unwrap_or(Position::center()),
      items,
    })
  }

  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if !self.angle.is_zero() {
      dest.write_str("from ")?;
      self.angle.to_css(dest)?;

      if !self.position.is_center() {
        dest.write_char(' ')?;
      }
    }

    if !self.position.is_center() {
      dest.write_str("at ")?;
      self.position.to_css(dest)?;
    }

    if !self.angle.is_zero() || !self.position.is_center() {
      dest.delim(',', false)?;
    }

    serialize_items(&self.items, dest)
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ColorStop<D> {
  pub color: CssColor,
  pub position: Option<D>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum GradientItem<D> {
  ColorStop(ColorStop<D>),
  Hint(D),
}

pub trait GradientPosition: Clone + PartialEq + ToCss + std::fmt::Debug {
  fn parse_position<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self>;
  fn is_half(&self) -> bool;
}

impl GradientPosition for LengthPercentage {
  fn parse_position<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    LengthPercentage::parse(input)
  }
  fn is_half(&self) -> bool {
    matches!(self, DimensionPercentage::Percentage(p) if p.0 == 0.5)
  }
}

impl GradientPosition for AnglePercentage {
  fn parse_position<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    AnglePercentage::parse(input)
  }
  fn is_half(&self) -> bool {
    matches!(self, DimensionPercentage::Percentage(p) if p.0 == 0.5)
  }
}

fn parse_items<'i, 't, D: GradientPosition>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Vec<GradientItem<D>>> {
  let mut items = Vec::new();
  let mut seen_stop = false;

  loop {
    input.parse_until_before(crate::parser::Delimiter::Comma, |input| {
      if seen_stop {
        if let Ok(hint) = input.try_parse(D::parse_position) {
          seen_stop = false;
          items.push(GradientItem::Hint(hint));
          return Ok(());
        }
      }

      let stop = ColorStop::parse(input)?;

      if let Ok(position) = input.try_parse(D::parse_position) {
        let color = stop.color.clone();
        items.push(GradientItem::ColorStop(stop));

        items.push(GradientItem::ColorStop(ColorStop {
          color,
          position: Some(position),
        }))
      } else {
        items.push(GradientItem::ColorStop(stop));
      }

      seen_stop = true;
      Ok(())
    })?;

    match input.next() {
      Err(_) => break,
      Ok(Token::Comma) => continue,
      _ => unreachable!(),
    }
  }

  Ok(items)
}

impl<D: GradientPosition> ColorStop<D> {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let color = CssColor::parse(input)?;
    let position = input.try_parse(D::parse_position).ok();
    Ok(ColorStop { color, position })
  }
}

impl<D: GradientPosition> ToCss for ColorStop<D> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.color.to_css(dest)?;
    if let Some(position) = &self.position {
      dest.write_char(' ')?;
      position.to_css(dest)?;
    }
    Ok(())
  }
}

fn serialize_items<D: GradientPosition>(items: &[GradientItem<D>], dest: &mut Printer) -> PrintResult {
  let mut first = true;
  let mut last: Option<&GradientItem<D>> = None;
  for item in items {
    // Skip useless hints
    if let GradientItem::Hint(hint) = item {
      if hint.is_half() {
        continue;
      }
    }

    // Use double position stop if the last stop is the same color and all targets support it.
    if let Some(prev) = last {
      if let (
        GradientItem::ColorStop(ColorStop {
          position: Some(_),
          color,
        }),
        GradientItem::ColorStop(ColorStop {
          position: Some(prev_pos),
          color: prev_color,
        }),
      ) = (item, prev)
      {
        if color == prev_color && !dest.targets.should_compile(crate::compat::Feature::DoublePositionGradients) {
          dest.write_char(' ')?;
          if let GradientItem::ColorStop(ColorStop { position: Some(pos), .. }) = item {
            pos.to_css(dest)?;
          }
          let _ = prev_pos;
          last = None;
          continue;
        }
      }
    }

    if first {
      first = false;
    } else {
      dest.delim(',', false)?;
    }
    match item {
      GradientItem::ColorStop(stop) => stop.to_css(dest)?,
      GradientItem::Hint(hint) => hint.to_css(dest)?,
    }
    last = Some(item)
  }
  Ok(())
}

// ---------------------------------------------------------------------------
// Legacy -webkit-gradient()

#[derive(Clone, Debug, PartialEq)]
pub enum WebKitGradient {
  Linear {
    from: WebKitGradientPoint,
    to: WebKitGradientPoint,
    stops: Vec<WebKitColorStop>,
  },
  Radial {
    from: WebKitGradientPoint,
    r0: f32,
    to: WebKitGradientPoint,
    r1: f32,
    stops: Vec<WebKitColorStop>,
  },
}

#[derive(Clone, Debug, PartialEq)]
pub struct WebKitColorStop {
  pub color: CssColor,
  pub position: f32,
}

#[derive(Clone, Debug, PartialEq)]
pub struct WebKitGradientPoint {
  pub x: WebKitGradientPointComponent<HorizontalPositionKeyword>,
  pub y: WebKitGradientPointComponent<VerticalPositionKeyword>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum WebKitGradientPointComponent<S> {
  Center,
  Number(NumberOrPercentage),
  Side(S),
}

impl WebKitGradient {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    input.expect_comma()?;

    match ident.to_ascii_lowercase().as_str() {
      "linear" => {
        let from = WebKitGradientPoint::parse(input)?;
        input.expect_comma()?;
        let to = WebKitGradientPoint::parse(input)?;
        input.expect_comma()?;
        let stops = input.parse_comma_separated(WebKitColorStop::parse)?;
        Ok(WebKitGradient::Linear { from, to, stops })
      }
      "radial" => {
        let from = WebKitGradientPoint::parse(input)?;
        input.expect_comma()?;
        let r0 = parse_number(input)?;
        input.expect_comma()?;
        let to = WebKitGradientPoint::parse(input)?;
        input.expect_comma()?;
        let r1 = parse_number(input)?;
        input.expect_comma()?;
        let stops = input.parse_comma_separated(WebKitColorStop::parse)?;
        Ok(WebKitGradient::Radial { from, r0, to, r1, stops })
      }
      _ => Err(location.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
}

impl ToCss for WebKitGradient {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      WebKitGradient::Linear { from, to, stops } => {
        dest.write_str("linear")?;
        dest.delim(',', false)?;
        from.to_css(dest)?;
        dest.delim(',', false)?;
        to.to_css(dest)?;
        dest.delim(',', false)?;
        let mut first = true;
        for stop in stops {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          stop.to_css(dest)?;
        }
        Ok(())
      }
      WebKitGradient::Radial { from, r0, to, r1, stops } => {
        dest.write_str("radial")?;
        dest.delim(',', false)?;
        from.to_css(dest)?;
        dest.delim(',', false)?;
        serialize_number(*r0, dest)?;
        dest.delim(',', false)?;
        to.to_css(dest)?;
        dest.delim(',', false)?;
        serialize_number(*r1, dest)?;
        dest.delim(',', false)?;
        let mut first = true;
        for stop in stops {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          stop.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

impl WebKitColorStop {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let function = input.expect_function()?;
    input.parse_nested_block(|input| {
      let (position, color) = match function.to_ascii_lowercase().as_str() {
        "color-stop" => {
          let p = NumberOrPercentage::parse(input)?;
          input.expect_comma()?;
          (p.unit_value(), CssColor::parse(input)?)
        }
        "from" => (0.0, CssColor::parse(input)?),
        "to" => (1.0, CssColor::parse(input)?),
        _ => return Err(location.new_unexpected_token_error(Token::Ident(function.clone()))),
      };
      Ok(WebKitColorStop { color, position })
    })
  }
}

impl ToCss for WebKitColorStop {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.position == 0.0 {
      dest.write_str("from(")?;
      self.color.to_css(dest)?;
    } else if self.position == 1.0 {
      dest.write_str("to(")?;
      self.color.to_css(dest)?;
    } else {
      dest.write_str("color-stop(")?;
      serialize_number(self.position, dest)?;
      dest.delim(',', false)?;
      self.color.to_css(dest)?;
    }
    dest.write_char(')')
  }
}

impl WebKitGradientPoint {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let x = WebKitGradientPointComponent::parse(input)?;
    let y = WebKitGradientPointComponent::parse(input)?;
    Ok(WebKitGradientPoint { x, y })
  }
}

impl ToCss for WebKitGradientPoint {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.x.to_css(dest)?;
    dest.write_char(' ')?;
    self.y.to_css(dest)
  }
}

impl<S: SideKeyword> WebKitGradientPointComponent<S> {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|i| i.expect_ident_matching("center")).is_ok() {
      return Ok(WebKitGradientPointComponent::Center);
    }

    if let Ok(lp) = input.try_parse(NumberOrPercentage::parse) {
      return Ok(WebKitGradientPointComponent::Number(lp));
    }

    let keyword = S::parse(input)?;
    Ok(WebKitGradientPointComponent::Side(keyword))
  }
}

impl<S: SideKeyword> ToCss for WebKitGradientPointComponent<S> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      WebKitGradientPointComponent::Center => {
        if dest.minify {
          dest.write_str("50%")
        } else {
          dest.write_str("center")
        }
      }
      WebKitGradientPointComponent::Number(lp) => {
        if let NumberOrPercentage::Percentage(Percentage(p)) = lp {
          if *p == 0.0 {
            return dest.write_char('0');
          }
        }
        lp.to_css(dest)
      }
      WebKitGradientPointComponent::Side(s) => {
        if dest.minify {
          if s.is_start() {
            dest.write_char('0')
          } else {
            dest.write_str("100%")
          }
        } else {
          dest.write_str(s.as_str())
        }
      }
    }
  }
}

