//! Image values: urls, gradients, image-set.

use crate::error::{ParseResult, ParserError};
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::tokenizer::Token;
use crate::values::angle::{Angle, AnglePercentage};
use crate::values::color::CssColor;
use crate::values::length::{Length, LengthPercentage};
use crate::values::number::{serialize_number, parse_number};
use crate::values::percentage::{DimensionPercentage, Percentage, NumberOrPercentage};
use crate::values::position::{HorizontalPositionKeyword, Position, PositionComponent, VerticalPositionKeyword, SideKeyword};
use crate::values::resolution::Resolution;
use crate::values::string::CSSString;
use crate::values::url::Url;
use crate::vendor_prefix::VendorPrefix;

#[derive(Clone, Debug, PartialEq)]
pub enum Image<'i> {
  None,
  Url(Url<'i>),
  Gradient(Box<Gradient>),
  ImageSet(ImageSet<'i>),
}

impl<'i> Image<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(Image::None);
    }
    if let Ok(url) = input.try_parse(Url::parse) {
      return Ok(Image::Url(url));
    }
    if let Ok(grad) = input.try_parse(Gradient::parse) {
      return Ok(Image::Gradient(Box::new(grad)));
    }
    if let Ok(image_set) = input.try_parse(ImageSet::parse) {
      return Ok(Image::ImageSet(image_set));
    }
    Err(input.new_error_for_next_token())
  }

  pub fn has_vendor_prefix(&self) -> bool {
    match self {
      Image::Gradient(g) => g.get_vendor_prefix() != VendorPrefix::None,
      Image::ImageSet(s) => s.vendor_prefix != VendorPrefix::None,
      _ => false,
    }
  }
}

impl<'i> ToCss for Image<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Image::None => dest.write_str("none"),
      Image::Url(url) => url.to_css(dest),
      Image::Gradient(grad) => grad.to_css(dest),
      Image::ImageSet(image_set) => image_set.to_css(dest),
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct ImageSet<'i> {
  pub options: Vec<ImageSetOption<'i>>,
  pub vendor_prefix: VendorPrefix,
}

#[derive(Clone, Debug, PartialEq)]
pub struct ImageSetOption<'i> {
  pub image: Image<'i>,
  pub resolution: Resolution,
  pub file_type: Option<String>,
}

impl<'i> ImageSet<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let f = input.expect_function()?;
    let vendor_prefix = match f.to_ascii_lowercase().as_str() {
      "image-set" => VendorPrefix::None,
      "-webkit-image-set" => VendorPrefix::WebKit,
      _ => return Err(location.new_unexpected_token_error(Token::Ident(f))),
    };
    let options = input.parse_nested_block(|input| input.parse_comma_separated(|input| ImageSetOption::parse(input)))?;
    Ok(ImageSet { options, vendor_prefix })
  }
}

impl<'i> ImageSetOption<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let image = if let Ok(url) = input.try_parse(|input| input.expect_string()) {
      Image::Url(Url { url })
    } else {
      Image::parse(input)?
    };
    let mut resolution = None;
    let mut file_type = None;
    loop {
      if resolution.is_none() {
        if let Ok(r) = input.try_parse(Resolution::parse) {
          resolution = Some(r);
          continue;
        }
      }
      if file_type.is_none() {
        if let Ok(t) = input.try_parse(|input| {
          input.expect_function_matching("type")?;
          input.parse_nested_block(|input| input.expect_string().map(|s| s.to_string()).map_err(|e| e.into()))
        }) {
          file_type = Some(t);
          continue;
        }
      }
      break;
    }
    Ok(ImageSetOption {
      image,
      resolution: resolution.unwrap_or(Resolution::Dppx(1.0)),
      file_type,
    })
  }
}

impl<'i> ToCss for ImageSet<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.vendor_prefix.to_css(dest)?;
    dest.write_str("image-set(")?;
    let mut first = true;
    for option in &self.options {
      if first {
        first = false;
      } else {
        dest.delim(',', false)?;
      }
      // Use a string instead of url() when possible, as it is shorter and supported everywhere (except webkit prefixed).
      match &option.image {
        Image::Url(url) if self.vendor_prefix == VendorPrefix::None => {
          crate::printer::serialize_string(&url.url, dest)?;
        }
        img => img.to_css(dest)?,
      }
      dest.write_char(' ')?;
      option.resolution.to_css(dest)?;
      if let Some(file_type) = &option.file_type {
        dest.write_str(" type(")?;
        crate::printer::serialize_string(file_type, dest)?;
        dest.write_char(')')?;
      }
    }
    dest.write_char(')')
  }
}

