  MaxContent(VendorPrefix),
  FitContent(VendorPrefix),
  FitContentFunction(LengthPercentage),
  Stretch(VendorPrefix),
  Contain,
}

impl MaxSize {
  pub fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let res = input.try_parse(|input| {
      let location = input.current_source_location();
      let ident = input.expect_ident()?;
      match ident.to_ascii_lowercase().as_str() {
        "none" => Ok(MaxSize::None),
        "min-content" => Ok(MaxSize::MinContent(VendorPrefix::None)),
        "-webkit-min-content" => Ok(MaxSize::MinContent(VendorPrefix::WebKit)),
        "-moz-min-content" => Ok(MaxSize::MinContent(VendorPrefix::Moz)),
        "max-content" => Ok(MaxSize::MaxContent(VendorPrefix::None)),
        "-webkit-max-content" => Ok(MaxSize::MaxContent(VendorPrefix::WebKit)),
        "-moz-max-content" => Ok(MaxSize::MaxContent(VendorPrefix::Moz)),
        "stretch" => Ok(MaxSize::Stretch(VendorPrefix::None)),
        "-webkit-fill-available" => Ok(MaxSize::Stretch(VendorPrefix::WebKit)),
        "-moz-available" => Ok(MaxSize::Stretch(VendorPrefix::Moz)),
        "fit-content" => Ok(MaxSize::FitContent(VendorPrefix::None)),
        "-webkit-fit-content" => Ok(MaxSize::FitContent(VendorPrefix::WebKit)),
        "-moz-fit-content" => Ok(MaxSize::FitContent(VendorPrefix::Moz)),
        "contain" => Ok(MaxSize::Contain),
        _ => Err(location.new_unexpected_token_error(Token::Ident(ident))),
      }
    });

    if res.is_ok() {
      return res;
    }

    if let Ok(res) = input.try_parse(parse_fit_content) {
      return Ok(MaxSize::FitContentFunction(res));
    }

    let lp = LengthPercentage::parse(input)?;
    Ok(MaxSize::LengthPercentage(lp))
  }
}

impl ToCss for MaxSize {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    use MaxSize::*;
    match self {
      None => dest.write_str("none"),
      Contain => dest.write_str("contain"),
      MinContent(vp) => {
        vp.to_css(dest)?;
        dest.write_str("min-content")
      }
      MaxContent(vp) => {
        vp.to_css(dest)?;
        dest.write_str("max-content")
      }
      FitContent(vp) => {
        vp.to_css(dest)?;
        dest.write_str("fit-content")
      }
      Stretch(vp) => match *vp {
        VendorPrefix::None => dest.write_str("stretch"),
        VendorPrefix::WebKit => dest.write_str("-webkit-fill-available"),
        VendorPrefix::Moz => dest.write_str("-moz-available"),
        _ => unreachable!(),
      },
      FitContentFunction(l) => {
        dest.write_str("fit-content(")?;
        l.to_css(dest)?;
        dest.write_char(')')
      }
      LengthPercentage(l) => l.to_css(dest),
    }
  }
}

fn parse_fit_content<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, LengthPercentage> {
  input.expect_function_matching("fit-content")?;
  input.parse_nested_block(|input| LengthPercentage::parse(input))
}
