use crate::error::ParseResult;
use crate::parser::Parser;
use crate::properties::PropertyId;
use crate::values::token_list::{ParserOptions, TokenList, TokenOrValue};
use std::borrow::Cow;

/// A custom (unknown or `--*`) property.
#[derive(Clone, Debug, PartialEq)]
pub struct CustomProperty<'i> {
  pub name: CustomPropertyName<'i>,
  pub value: TokenList<'i>,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum CustomPropertyName<'i> {
  /// An author-defined CSS custom property (`--foo`).
  Custom(Cow<'i, str>),
  /// An unknown property name.
  Unknown(Cow<'i, str>),
}

impl<'i> CustomPropertyName<'i> {
  pub fn from(name: Cow<'i, str>) -> Self {
    if name.starts_with("--") {
      CustomPropertyName::Custom(name)
    } else {
      CustomPropertyName::Unknown(name)
    }
  }

  pub fn as_str(&self) -> &str {
    match self {
      CustomPropertyName::Custom(s) => s,
      CustomPropertyName::Unknown(s) => s,
    }
  }
}

impl<'i> CustomProperty<'i> {
  pub fn parse<'t>(name: CustomPropertyName<'i>, input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let value = input.parse_until_before(crate::parser::Delimiter::Bang, |input| TokenList::parse(input, options, 0))?;
    Ok(CustomProperty { name, value })
  }
}

/// A known property with an unparsed (raw token) value, e.g. containing var().
#[derive(Clone, Debug, PartialEq)]
pub struct UnparsedProperty<'i> {
  pub property_id: PropertyId<'i>,
  pub value: TokenList<'i>,
}

impl<'i> UnparsedProperty<'i> {
  pub fn parse<'t>(property_id: PropertyId<'i>, input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let value = input.parse_until_before(crate::parser::Delimiter::Bang, |input| TokenList::parse(input, options, 0))?;
    Ok(UnparsedProperty { property_id, value })
  }

  pub fn with_property_id(&self, property_id: PropertyId<'i>) -> UnparsedProperty<'i> {
    UnparsedProperty {
      property_id,
      value: self.value.clone(),
    }
  }

  /// Returns whether the value contains var() or env() references.
  pub fn has_var(&self) -> bool {
    self.value.0.iter().any(|t| matches!(t, TokenOrValue::Var(_) | TokenOrValue::Env(_)))
  }
}
