macro_rules! define_properties {
  (
    $(
      $name: literal: $property: ident ( $type: ty $(, $vp: ident )? ) $( [ $($prefix: ident),* ] )? ,
    )+
  ) => {
    /// A CSS property id.
    #[derive(Clone, Debug, PartialEq, Eq, Hash)]
    pub enum PropertyId<'i> {
      $(
        $property $( ( $vp ) )?,
      )+
      All,
      Custom(CustomPropertyName<'i>),
    }

    impl<'i> PropertyId<'i> {
      /// Parses a property id from a name.
      pub fn parse(name: Cow<'i, str>) -> PropertyId<'i> {
        let lower = name.to_ascii_lowercase();
        let (prefix, stripped) = VendorPrefix::parse_prefixed_name(&lower);
        macro_rules! get_allowed_prefixes {
          () => { VendorPrefix::None };
          ($($p: ident),*) => { VendorPrefix::empty() $(| VendorPrefix::$p)* | VendorPrefix::None };
        }
        match stripped {
          $(
            $name => {
              let allowed: VendorPrefix = get_allowed_prefixes!($($($prefix),*)?);
              if allowed.contains(prefix) {
                return define_properties!(@make_id $property $( $vp )? prefix);
              }
            }
          )+
          "all" if prefix == VendorPrefix::None => return PropertyId::All,
          _ => {}
        }
        PropertyId::Custom(CustomPropertyName::from(name))
      }

      /// Returns the property name without a prefix.
      pub fn name(&self) -> &str {
        match self {
          $(
            define_properties!(@pattern_id $property $( $vp )?) => $name,
          )+
          PropertyId::All => "all",
          PropertyId::Custom(name) => name.as_str(),
        }
      }

      /// Returns the vendor prefix for this property id.
      pub fn prefix(&self) -> VendorPrefix {
        match self {
          $(
            define_properties!(@prefix_arm $property $( $vp )?),
          )+
          _ => VendorPrefix::empty(),
        }
      }

      /// Returns the property id with the given vendor prefix (if prefixable).
      pub fn with_prefix(&self, prefix: VendorPrefix) -> PropertyId<'i> {
        match self {
          $(
            define_properties!(@with_prefix_arm $property $( $vp )? prefix),
          )+
          _ => self.clone(),
        }
      }

      pub fn to_css(&self, dest: &mut Printer) -> PrintResult {
        match self {
          PropertyId::Custom(name) => dest.write_str(name.as_str()),
          _ => {
            self.prefix().to_css(dest)?;
            dest.write_str(self.name())
          }
        }
      }
    }

    /// A CSS property.
    #[derive(Clone, Debug, PartialEq)]
    pub enum Property<'i> {
      $(
        $property($type $(, $vp )?),
      )+
      All(crate::properties::ui::CSSWideKeyword),
      Unparsed(UnparsedProperty<'i>),
      Custom(CustomProperty<'i>),
    }

    impl<'i> Property<'i> {
      /// Parses a property value for the given id.
      pub fn parse<'t>(property_id: PropertyId<'i>, input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Property<'i>> {
        let state = input.state();
        match &property_id {
          $(
            define_properties!(@pattern_id $property $( $vp )?) => {
              if let Ok(c) = <$type as Parse>::parse(input) {
                if input.expect_exhausted().is_ok() {
                  return Ok(define_properties!(@make_prop $property $( $vp )? property_id c));
                }
              }
            }
          )+
          PropertyId::All => {
            if let Ok(c) = <crate::properties::ui::CSSWideKeyword as Parse>::parse(input) {
              if input.expect_exhausted().is_ok() {
                return Ok(Property::All(c));
              }
            }
          }
          PropertyId::Custom(name) => {
            return Ok(Property::Custom(CustomProperty::parse(name.clone(), input, options)?));
          }
        }

        // If a value was unable to be parsed, treat as an unparsed property.
        // This is different from a custom property, handled below, in that the property name is known
        // and stored as an enum rather than a string. This lets property handlers more easily deal with it.
        // Ideally we'd only do this if var() or env() references were seen, but err on the safe side for now.
        input.reset(&state);
        return Ok(Property::Unparsed(UnparsedProperty::parse(property_id, input, options)?));
      }

      /// Returns the property id for this property.
      pub fn property_id(&self) -> PropertyId<'i> {
        match self {
          $(
            define_properties!(@pattern_prop $property $( $vp )?) => define_properties!(@make_id_from_prop $property $( $vp )?),
          )+
          Property::All(_) => PropertyId::All,
          Property::Unparsed(unparsed) => unparsed.property_id.clone(),
          Property::Custom(custom) => PropertyId::Custom(custom.name.clone()),
        }
      }

      /// Serializes the value of the property (without the name).
      pub fn value_to_css(&self, dest: &mut Printer) -> PrintResult {
        match self {
          $(
            define_properties!(@pattern_prop_val $property $( $vp )?) => val.to_css(dest),
          )+
          Property::All(keyword) => keyword.to_css(dest),
          Property::Unparsed(unparsed) => unparsed.value.to_css_internal(dest, false),
          Property::Custom(custom) => custom.value.to_css_internal(dest, true),
        }
      }

      /// Serializes the property with name and value.
      pub fn to_css(&self, dest: &mut Printer, important: bool) -> PrintResult {
        let property_id = self.property_id();
        let prefix = property_id.prefix();

        macro_rules! write_important {
          () => {
            if important {
              dest.whitespace()?;
              dest.write_str("!important")?;
            }
          };
        }

        if let Property::Custom(custom) = self {
          dest.write_str(custom.name.as_str())?;
          dest.write_char(':')?;
          // Preserve whitespace-only values exactly.
          let ws_only = custom.value.0.len() == 1
            && matches!(custom.value.0[0], crate::values::token_list::TokenOrValue::Token(crate::values::token_list::Token::WhiteSpace(_)));
          if !ws_only {
            dest.whitespace()?;
          }
          custom.value.to_css_internal(dest, true)?;
          write_important!();
          return Ok(());
        }

        if prefix.is_empty() || prefix == VendorPrefix::None {
          property_id.to_css(dest)?;
          dest.delim(':', false)?;
          self.value_to_css(dest)?;
          write_important!();
          return Ok(());
        }

        let mut first = true;
        for p in prefix.iter() {
          if first {
            first = false;
          } else {
            dest.write_char(';')?;
            dest.newline()?;
          }
          p.to_css(dest)?;
          dest.write_str(property_id.name())?;
          dest.delim(':', false)?;
          self.value_to_css(dest)?;
          write_important!();
        }
        Ok(())
      }
    }
  };

  // Helpers
  (@make_id $property: ident $vp: ident $prefix: ident) => { PropertyId::$property($prefix) };
  (@make_id $property: ident $prefix: ident) => { PropertyId::$property };
  (@pattern_id $property: ident $vp: ident) => { PropertyId::$property(_) };
  (@pattern_id $property: ident) => { PropertyId::$property };
  (@prefix_arm $property: ident $vp: ident) => { PropertyId::$property(p) => *p };
  (@prefix_arm $property: ident) => { PropertyId::$property => VendorPrefix::None };
  (@with_prefix_arm $property: ident $vp: ident $prefix: ident) => { PropertyId::$property(_) => PropertyId::$property($prefix) };
  (@with_prefix_arm $property: ident $prefix: ident) => { PropertyId::$property => PropertyId::$property };
  (@make_prop $property: ident $vp: ident $id: ident $c: ident) => { Property::$property($c, $id.prefix()) };
  (@make_prop $property: ident $id: ident $c: ident) => { Property::$property($c) };
  (@pattern_prop $property: ident $vp: ident) => { Property::$property(_, p) };
  (@pattern_prop $property: ident) => { Property::$property(_) };
  (@make_id_from_prop $property: ident $vp: ident) => { PropertyId::$property(*p) };
  (@make_id_from_prop $property: ident) => { PropertyId::$property };
  (@pattern_prop_val $property: ident $vp: ident) => { Property::$property(val, _) };
  (@pattern_prop_val $property: ident) => { Property::$property(val) };
}

