#[derive(Clone, Debug, PartialEq)]
pub enum JustifyItems {
  Normal,
  Stretch,
  BaselinePosition(BaselinePosition),
  SelfPosition {
    overflow: Option<OverflowPosition>,
    value: SelfPosition,
  },
  Left(Option<OverflowPosition>),
  Right(Option<OverflowPosition>),
  Legacy(Option<LegacyJustify>),
}

impl<'i> Parse<'i> for JustifyItems {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("normal")).is_ok() {
      return Ok(JustifyItems::Normal);
    }
    if input.try_parse(|input| input.expect_ident_matching("stretch")).is_ok() {
      return Ok(JustifyItems::Stretch);
    }
    if let Ok(val) = input.try_parse(BaselinePosition::parse_baseline) {
      return Ok(JustifyItems::BaselinePosition(val));
    }
    if input.try_parse(|input| input.expect_ident_matching("legacy")).is_ok() {
      let v = input.try_parse(LegacyJustify::parse).ok();
      return Ok(JustifyItems::Legacy(v));
    }
    if let Ok(v) = input.try_parse(LegacyJustify::parse) {
      if input.try_parse(|input| input.expect_ident_matching("legacy")).is_ok() {
        return Ok(JustifyItems::Legacy(Some(v)));
      }
      // Not legacy; re-parse below.
    }
    let overflow = input.try_parse(OverflowPosition::parse).ok();
    if let Ok(value) = input.try_parse(SelfPosition::parse) {
      return Ok(JustifyItems::SelfPosition { overflow, value });
    }
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "left" => Ok(JustifyItems::Left(overflow)),
      "right" => Ok(JustifyItems::Right(overflow)),
      _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(ident))),
    }
  }
}

