  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      JustifyItems::Normal => dest.write_str("normal"),
      JustifyItems::Stretch => dest.write_str("stretch"),
      JustifyItems::BaselinePosition(val) => val.to_css_baseline(dest),
      JustifyItems::SelfPosition { overflow, value } => {
        if let Some(overflow) = overflow {
          overflow.to_css(dest)?;
          dest.write_str(" ")?;
        }
        value.to_css(dest)
      }
      JustifyItems::Left(overflow) => {
        if let Some(overflow) = overflow {
          overflow.to_css(dest)?;
          dest.write_str(" ")?;
        }
        dest.write_str("left")
      }
      JustifyItems::Right(overflow) => {
        if let Some(overflow) = overflow {
          overflow.to_css(dest)?;
          dest.write_str(" ")?;
        }
        dest.write_str("right")
      }
      JustifyItems::Legacy(justify) => {
        dest.write_str("legacy")?;
        if let Some(justify) = justify {
          dest.write_str(" ")?;
          justify.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct PlaceItems {
  pub align: AlignItems,
  pub justify: JustifyItems,
}

impl<'i> Parse<'i> for PlaceItems {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let align = AlignItems::parse(input)?;
    let justify = match input.try_parse(JustifyItems::parse) {
      Ok(j) => j,
      Err(_) => match &align {
        AlignItems::Normal => JustifyItems::Normal,
        AlignItems::Stretch => JustifyItems::Stretch,
        AlignItems::BaselinePosition(p) => JustifyItems::BaselinePosition(*p),
        AlignItems::SelfPosition { overflow, value } => JustifyItems::SelfPosition {
          overflow: *overflow,
          value: *value,
        },
      },
    };
    Ok(PlaceItems { align, justify })
  }
}

impl ToCss for PlaceItems {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.align.to_css(dest)?;
    let is_equal = match &self.justify {
      JustifyItems::Normal => self.align == AlignItems::Normal,
      JustifyItems::Stretch => self.align == AlignItems::Stretch,
      JustifyItems::BaselinePosition(p) => matches!(&self.align, AlignItems::BaselinePosition(p2) if p == p2),
      JustifyItems::SelfPosition { overflow, value } => {
        matches!(&self.align, AlignItems::SelfPosition { overflow: o2, value: v2 } if overflow == o2 && value == v2)
      }
      _ => false,
    };
    if !is_equal {
      dest.write_str(" ")?;
      self.justify.to_css(dest)?;
    }
    Ok(())
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum GapValue {
  Normal,
