}

impl<'i> Parse<'i> for GapValue {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("normal")).is_ok() {
      return Ok(GapValue::Normal);
    }
    Ok(GapValue::LengthPercentage(LengthPercentage::parse(input)?))
  }
}

impl ToCss for GapValue {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      GapValue::Normal => dest.write_str("normal"),
      GapValue::LengthPercentage(l) => l.to_css(dest),
    }
  }
}

