  use crate::values::position::PositionComponent;
  Position {
    x: PositionComponent::Length(LengthPercentage::percent(0.0)),
    y: PositionComponent::Length(LengthPercentage::percent(0.0)),
  }
}

impl<'i> Parse<'i> for Background<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut color: Option<CssColor> = None;
    let mut position: Option<Position> = None;
    let mut size: Option<BackgroundSize> = None;
    let mut image: Option<Image> = None;
    let mut repeat: Option<BackgroundRepeat> = None;
    let mut attachment: Option<BackgroundAttachment> = None;
    let mut origin: Option<BackgroundOrigin> = None;
    let mut clip: Option<BackgroundClip> = None;

    loop {
      // TODO: only allowed on the last background.
      if color.is_none() {
        if let Ok(value) = input.try_parse(CssColor::parse) {
          color = Some(value);
          continue;
        }
      }

      if position.is_none() {
        if let Ok(value) = input.try_parse(Position::parse) {
          position = Some(value);

          size = input
            .try_parse(|input| {
              input.expect_delim('/')?;
              BackgroundSize::parse(input)
            })
            .ok();

          continue;
        }
      }

      if image.is_none() {
        if let Ok(value) = input.try_parse(Image::parse) {
          image = Some(value);
          continue;
        }
      }

      if repeat.is_none() {
        if let Ok(value) = input.try_parse(BackgroundRepeat::parse) {
          repeat = Some(value);
          continue;
        }
      }

      if attachment.is_none() {
        if let Ok(value) = input.try_parse(BackgroundAttachment::parse) {
          attachment = Some(value);
          continue;
        }
      }

      if origin.is_none() {
        if let Ok(value) = input.try_parse(BackgroundOrigin::parse) {
          origin = Some(value);
          continue;
        }
      }

      if clip.is_none() {
        if let Ok(value) = input.try_parse(BackgroundClip::parse) {
          clip = Some(value);
          continue;
        }
      }

      break;
    }

    if clip.is_none() {
      if let Some(origin) = origin {
        clip = Some(origin.into());
      }
    }

    if color.is_none() && position.is_none() && image.is_none() && repeat.is_none() && attachment.is_none() && origin.is_none() && clip.is_none() {
      return Err(input.new_error_for_next_token());
    }

    Ok(Background {
      image: image.unwrap_or(Image::None),
      color: color.unwrap_or(CssColor::transparent()),
      position: position.unwrap_or(default_position()),
      repeat: repeat.unwrap_or_default(),
      size: size.unwrap_or_default(),
      attachment: attachment.unwrap_or_default(),
      origin: origin.unwrap_or(BackgroundOrigin::PaddingBox),
      clip: clip.unwrap_or(BackgroundClip::BorderBox),
    })
  }
}

impl<'i> ToCss for Background<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut has_output = false;

    if self.color != CssColor::transparent() {
      self.color.to_css(dest)?;
      has_output = true;
    }

    if self.image != Image::None {
      if has_output {
        dest.write_str(" ")?;
      }
      self.image.to_css(dest)?;
      has_output = true;
    }

    if !position_is_default(&self.position) || self.size != BackgroundSize::default() {
      if has_output {
        dest.write_str(" ")?;
      }
      self.position.to_css(dest)?;

      if self.size != BackgroundSize::default() {
        dest.delim('/', true)?;
        self.size.to_css(dest)?;
      }

      has_output = true;
    }

    if self.repeat != BackgroundRepeat::default() {
      if has_output {
        dest.write_str(" ")?;
      }
      self.repeat.to_css(dest)?;
      has_output = true;
    }

    if self.attachment != BackgroundAttachment::default() {
      if has_output {
        dest.write_str(" ")?;
      }
      self.attachment.to_css(dest)?;
      has_output = true;
    }

    if self.origin != BackgroundOrigin::PaddingBox || self.clip != BackgroundClip::BorderBox {
      let print_origin = self.origin != BackgroundOrigin::PaddingBox
        || !(self.clip == BackgroundClip::BorderBox || self.clip == BackgroundClip::Text);
      if print_origin {
        if has_output {
          dest.write_str(" ")?;
        }
        self.origin.to_css(dest)?;
        has_output = true;
      }

      if self.clip != BackgroundClip::BorderBox || self.clip != BackgroundClip::from(self.origin) {
        if has_output {
          dest.write_str(" ")?;
        }
        self.clip.to_css(dest)?;
        has_output = true;
      }
    }

    // If nothing was output, then this is the initial value, e.g. `background: transparent`.
    // For shorter output, we can use `0 0` instead, which is also the initial value for the position.
    if !has_output {
      dest.write_str("0 0")?;
    }

    Ok(())
  }
}
