//! Filter effects.

use crate::error::ParseResult;
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::traits::Parse;
use crate::values::angle::Angle;
use crate::values::color::CssColor;
use crate::values::length::Length;
use crate::values::percentage::NumberOrPercentage;
use crate::values::url::Url;

#[derive(Clone, Debug, PartialEq)]
pub enum Filter<'i> {
  Blur(Length),
  Brightness(NumberOrPercentage),
  Contrast(NumberOrPercentage),
  Grayscale(NumberOrPercentage),
  HueRotate(Angle),
  Invert(NumberOrPercentage),
  Opacity(NumberOrPercentage),
  Saturate(NumberOrPercentage),
  Sepia(NumberOrPercentage),
  DropShadow(DropShadow),
  Url(Url<'i>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct DropShadow {
  pub color: CssColor,
  pub x_offset: Length,
  pub y_offset: Length,
  pub blur: Length,
}

impl<'i> Parse<'i> for Filter<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(url) = input.try_parse(Url::parse) {
      return Ok(Filter::Url(url));
    }

    let location = input.current_source_location();
    let function = input.expect_function()?;
    input.parse_nested_block(|input| {
      match function.to_ascii_lowercase().as_str() {
        "blur" => Ok(Filter::Blur(input.try_parse(Length::parse).unwrap_or(Length::zero()))),
        "brightness" => Ok(Filter::Brightness(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "contrast" => Ok(Filter::Contrast(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "grayscale" => Ok(Filter::Grayscale(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "hue-rotate" => {
          // Spec has an exception for unitless zero angles: https://github.com/w3c/fxtf-drafts/issues/228
          Ok(Filter::HueRotate(input.try_parse(Angle::parse_with_unitless).unwrap_or(Angle::Deg(0.0))))
        }
        "invert" => Ok(Filter::Invert(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "opacity" => Ok(Filter::Opacity(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "saturate" => Ok(Filter::Saturate(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "sepia" => Ok(Filter::Sepia(
          input.try_parse(NumberOrPercentage::parse).unwrap_or(NumberOrPercentage::Number(1.0)),
        )),
        "drop-shadow" => Ok(Filter::DropShadow(DropShadow::parse(input)?)),
        _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(function.clone()))),
      }
    })
  }
}

fn is_one(v: &NumberOrPercentage) -> bool {
  v.unit_value() == 1.0
}

impl<'i> ToCss for Filter<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    macro_rules! write_fn {
      ($name: literal, $v: expr, $default: expr) => {{
        dest.write_str($name)?;
        dest.write_char('(')?;
        if !$default {
          $v.to_css(dest)?;
        }
        dest.write_char(')')
      }};
    }
