    "ui-sans-serif": UISansSerif,
    "ui-monospace": UIMonospace,
    "ui-rounded": UIRounded,
    "-apple-system": AppleSystem,
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum FontFamily<'i> {
  Generic(GenericFontFamily),
  FamilyName(Cow<'i, str>),
}

impl<'i> Parse<'i> for FontFamily<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(value) = input.try_parse(|i| i.expect_string()) {
      return Ok(FontFamily::FamilyName(value));
    }

    if let Ok(value) = input.try_parse(GenericFontFamily::parse) {
      return Ok(FontFamily::Generic(value));
    }

    let value = input.expect_ident()?;
    let mut string: Option<String> = None;
    while let Ok(ident) = input.try_parse(|i| i.expect_ident()) {
      if string.is_none() {
        string = Some(value.to_string());
      }
      if let Some(string) = &mut string {
        string.push(' ');
        string.push_str(&ident);
      }
    }

    let value = if let Some(string) = string {
      Cow::Owned(string)
    } else {
      value
    };
    Ok(FontFamily::FamilyName(value))
  }
}

impl<'i> ToCss for FontFamily<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      FontFamily::Generic(val) => val.to_css(dest),
      FontFamily::FamilyName(val) => {
        // Generic family names such as sans-serif must be quoted if parsed as a string.
        // CSS wide keywords, as well as "default", must also be quoted.
        if !val.is_empty()
          && GenericFontFamily::from_str(val).is_none()
          && crate::properties::ui::CSSWideKeyword::from_str(val).is_none()
          && !val.eq_ignore_ascii_case("default")
        {
          let mut id = String::new();
          let mut first = true;
          for slice in val.split(' ') {
            if first {
              first = false;
            } else {
              id.push(' ');
            }
            serialize_identifier_to_string(slice, &mut id);
          }
          if id.len() < val.len() + 2 {
            return dest.write_str(&id);
          }
        }
        serialize_string(val, dest)
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum FontStyle {
  Normal,
  Italic,
  Oblique(Angle),
}

impl Default for FontStyle {
  fn default() -> FontStyle {
    FontStyle::Normal
  }
}

impl<'i> Parse<'i> for FontStyle {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "normal" => Ok(FontStyle::Normal),
      "italic" => Ok(FontStyle::Italic),
      "oblique" => {
        let angle = input.try_parse(Angle::parse).unwrap_or(Angle::Deg(14.0));
        Ok(FontStyle::Oblique(angle))
      }
      _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(ident))),
    }
  }
}

impl ToCss for FontStyle {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      FontStyle::Normal => dest.write_str("normal"),
      FontStyle::Italic => dest.write_str("italic"),
      FontStyle::Oblique(angle) => {
        dest.write_str("oblique")?;
        if *angle != Angle::Deg(14.0) {
          dest.write_char(' ')?;
          angle.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

