pub enum AnimationTimeline<'i> {
  Auto,
  None,
  DashedIdent(DashedIdent<'i>),
  Scroll(Cow<'i, str>),
  View(Cow<'i, str>),
}

impl<'i> Parse<'i> for AnimationTimeline<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("auto")).is_ok() {
      return Ok(AnimationTimeline::Auto);
    }
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(AnimationTimeline::None);
    }
    if let Ok(id) = input.try_parse(DashedIdent::parse) {
      return Ok(AnimationTimeline::DashedIdent(id));
    }
    let location = input.current_source_location();
    let f = input.expect_function()?;
    let lower = f.to_ascii_lowercase();
    let start = input.position();
    let contents = input.parse_nested_block(|input| {
      let start = input.position();
      while input.next().is_ok() {}
      Ok(input.slice_from(start).to_string())
    })?;
    let _ = start;
    match lower.as_str() {
      "scroll" => Ok(AnimationTimeline::Scroll(Cow::Owned(contents))),
      "view" => Ok(AnimationTimeline::View(Cow::Owned(contents))),
      _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(f))),
    }
  }
}

impl<'i> ToCss for AnimationTimeline<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      AnimationTimeline::Auto => dest.write_str("auto"),
      AnimationTimeline::None => dest.write_str("none"),
      AnimationTimeline::DashedIdent(id) => id.to_css(dest),
      AnimationTimeline::Scroll(s) => {
        dest.write_str("scroll(")?;
        dest.write_str(s.trim())?;
        dest.write_char(')')
      }
      AnimationTimeline::View(s) => {
        dest.write_str("view(")?;
        dest.write_str(s.trim())?;
        dest.write_char(')')
      }
    }
  }
