      AnimationRangeStart::Normal => AnimationRangeEnd::Normal,
      AnimationRangeStart::LengthPercentage(_) => AnimationRangeEnd::Normal,
      AnimationRangeStart::TimelineRange { name, .. } => AnimationRangeEnd::TimelineRange {
