    let omit_end = match (&self.start, &self.end) {
      (AnimationRangeStart::Normal, AnimationRangeEnd::Normal) => true,
      (AnimationRangeStart::LengthPercentage(_), AnimationRangeEnd::Normal) => true,
      (AnimationRangeStart::TimelineRange { name, .. }, AnimationRangeEnd::TimelineRange { name: n2, offset }) => {
        name == n2 && *offset == LengthPercentage::percent(1.0)
      }
      _ => false,
    };
    if !omit_end {
      dest.write_char(' ')?;
      self.end.to_css(dest)?;
    }
    Ok(())
  }
