          continue;
        }
      }
      if play_state.is_none() {
        if let Ok(value) = input.try_parse(AnimationPlayState::parse) {
          play_state = Some(value);
          continue;
        }
      }
      if name.is_none() {
        if let Ok(value) = input.try_parse(AnimationName::parse) {
          name = Some(value);
          continue;
        }
      }
      if timeline.is_none() {
        if let Ok(value) = input.try_parse(AnimationTimeline::parse) {
          timeline = Some(value);
          continue;
        }
      }
      break;
    }

    if name.is_none()
      && duration.is_none()
      && timing_function.is_none()
      && iteration_count.is_none()
      && direction.is_none()
      && play_state.is_none()
      && delay.is_none()
      && fill_mode.is_none()
      && timeline.is_none()
    {
      return Err(input.new_error_for_next_token());
    }

    Ok(Animation {
      name: name.unwrap_or(AnimationName::None),
