        return dest.write_str("none");
      }
      _ => {}
    }

    let mut has_output = false;
    macro_rules! space {
      () => {
        if has_output {
          dest.write_char(' ')?;
        }
        has_output = true;
      };
    }

    if !self.duration.is_zero() || !self.delay.is_zero() {
      space!();
      self.duration.to_css(dest)?;
    }

    if !self.timing_function.is_ease() {
      space!();
      self.timing_function.to_css(dest)?;
    }

    if !self.delay.is_zero() {
      space!();
      self.delay.to_css(dest)?;
    }

    if self.iteration_count != AnimationIterationCount::Number(1.0) {
      space!();
      self.iteration_count.to_css(dest)?;
    }

    if self.direction != AnimationDirection::Normal {
      space!();
      self.direction.to_css(dest)?;
    }

    if self.fill_mode != AnimationFillMode::None {
      space!();
      self.fill_mode.to_css(dest)?;
    }

    if self.play_state != AnimationPlayState::Running {
      space!();
      self.play_state.to_css(dest)?;
    }

    // Name is written last so that it doesn't conflict with keywords.
    space!();
    self.name.to_css(dest)?;

    if self.timeline != AnimationTimeline::Auto {
      space!();
      self.timeline.to_css(dest)?;
    }

    let _ = has_output;
    Ok(())
  }
}
