    self.bits == 0
  }
}

impl Default for TextDecorationLine {
  fn default() -> Self {
    TextDecorationLine::NONE
  }
}

impl<'i> Parse<'i> for TextDecorationLine {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut value = TextDecorationLine::NONE;
    let mut any = false;

    loop {
      let flag: Result<_, crate::parser::ParseError<crate::error::ParserError>> = input.try_parse(|input| {
        let location = input.current_source_location();
        let ident = input.expect_ident()?;
        Ok(match ident.to_ascii_lowercase().as_str() {
          "none" if value.bits == 0 => TextDecorationLine::NONE.bits,
          "underline" => TextDecorationLine::UNDERLINE,
          "overline" => TextDecorationLine::OVERLINE,
          "line-through" => TextDecorationLine::LINE_THROUGH,
          "blink" => TextDecorationLine::BLINK,
          "spelling-error" if value.bits == 0 => TextDecorationLine::SPELLING_ERROR,
          "grammar-error" if value.bits == 0 => TextDecorationLine::GRAMMAR_ERROR,
          _ => return Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(ident))),
        })
      });

      if let Ok(flag) = flag {
        value.bits |= flag;
        any = true;
        if flag == 0 || flag == TextDecorationLine::SPELLING_ERROR || flag == TextDecorationLine::GRAMMAR_ERROR {
          break;
        }
      } else {
        break;
      }
    }

    if !any {
      return Err(input.new_error_for_next_token());
    }

    Ok(value)
  }
}

