  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.bits == 0 {
      return dest.write_str("none");
    }
    if self.bits & TextDecorationLine::SPELLING_ERROR != 0 {
      return dest.write_str("spelling-error");
    }
    if self.bits & TextDecorationLine::GRAMMAR_ERROR != 0 {
      return dest.write_str("grammar-error");
    }
    let mut first = true;
    macro_rules! write {
      ($flag: expr, $str: expr) => {
        if self.bits & $flag != 0 {
          if first {
            first = false;
          } else {
            dest.write_char(' ')?;
          }
          dest.write_str($str)?;
        }
      };
    }
    write!(TextDecorationLine::UNDERLINE, "underline");
    write!(TextDecorationLine::OVERLINE, "overline");
    write!(TextDecorationLine::LINE_THROUGH, "line-through");
    write!(TextDecorationLine::BLINK, "blink");
    Ok(())
  }
