impl<'i> Parse<'i> for TextTransform {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut case = None;
    let mut other = TextTransformOther {
      full_width: false,
      full_size_kana: false,
