          other.full_width = true;
          any = true;
          continue;
        }
      }
      if !other.full_size_kana {
        if input.try_parse(|input| input.expect_ident_matching("full-size-kana")).is_ok() {
          other.full_size_kana = true;
          any = true;
          continue;
        }
      }
      break;
    }
    if !any {
      return Err(input.new_error_for_next_token());
    }
    Ok(TextTransform {
      case: case.unwrap_or(TextTransformCase::None),
