#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextDecorationLine {
  bits: u8,
}

impl TextDecorationLine {
  pub const NONE: TextDecorationLine = TextDecorationLine { bits: 0 };
  pub const UNDERLINE: u8 = 1;
  pub const OVERLINE: u8 = 2;
  pub const LINE_THROUGH: u8 = 4;
  pub const BLINK: u8 = 8;
  pub const SPELLING_ERROR: u8 = 16;
  pub const GRAMMAR_ERROR: u8 = 32;

  pub fn is_none(&self) -> bool {
    self.bits == 0
  }
}

impl Default for TextDecorationLine {
  fn default() -> Self {
    TextDecorationLine::NONE
  }
}

impl<'i> Parse<'i> for TextDecorationLine {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut value = TextDecorationLine::NONE;
    let mut any = false;

    loop {
      let flag: Result<_, crate::parser::ParseError<crate::error::ParserError>> = input.try_parse(|input| {
        let location = input.current_source_location();
        let ident = input.expect_ident()?;
        Ok(match ident.to_ascii_lowercase().as_str() {
          "none" if value.bits == 0 => TextDecorationLine::NONE.bits,
          "underline" => TextDecorationLine::UNDERLINE,
          "overline" => TextDecorationLine::OVERLINE,
          "line-through" => TextDecorationLine::LINE_THROUGH,
          "blink" => TextDecorationLine::BLINK,
          "spelling-error" if value.bits == 0 => TextDecorationLine::SPELLING_ERROR,
          "grammar-error" if value.bits == 0 => TextDecorationLine::GRAMMAR_ERROR,
          _ => return Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(ident))),
        })
      });

      if let Ok(flag) = flag {
        value.bits |= flag;
        any = true;
        if flag == 0 || flag == TextDecorationLine::SPELLING_ERROR || flag == TextDecorationLine::GRAMMAR_ERROR {
          break;
        }
      } else {
        break;
      }
    }

    if !any {
      return Err(input.new_error_for_next_token());
    }

    Ok(value)
  }
}

impl ToCss for TextDecorationLine {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.bits == 0 {
      return dest.write_str("none");
    }
    if self.bits & TextDecorationLine::SPELLING_ERROR != 0 {
      return dest.write_str("spelling-error");
    }
    if self.bits & TextDecorationLine::GRAMMAR_ERROR != 0 {
      return dest.write_str("grammar-error");
    }
    let mut first = true;
    macro_rules! write {
      ($flag: expr, $str: expr) => {
        if self.bits & $flag != 0 {
          if first {
            first = false;
          } else {
            dest.write_char(' ')?;
          }
          dest.write_str($str)?;
        }
      };
    }
    write!(TextDecorationLine::UNDERLINE, "underline");
    write!(TextDecorationLine::OVERLINE, "overline");
    write!(TextDecorationLine::LINE_THROUGH, "line-through");
    write!(TextDecorationLine::BLINK, "blink");
    Ok(())
  }
}

