#[derive(Clone, Debug, PartialEq)]
pub enum Symbol<'i> {
  String(Cow<'i, str>),
  Image(Image<'i>),
}

impl<'i> Parse<'i> for CounterStyle<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(predefined) = input.try_parse(PredefinedCounterStyle::parse) {
      return Ok(CounterStyle::Predefined(predefined));
    }

    if input.try_parse(|input| input.expect_function_matching("symbols")).is_ok() {
      return input.parse_nested_block(|input| {
        let t = input.try_parse(SymbolsType::parse).unwrap_or(SymbolsType::Symbolic);

        let mut symbols = Vec::new();
        while let Ok(s) = input.try_parse(|input| {
          if let Ok(img) = input.try_parse(Image::parse) {
            return Ok(Symbol::Image(img));
          }
          let s = input.expect_string()?;
          Ok::<_, crate::parser::ParseError<crate::error::ParserError>>(Symbol::String(s))
        }) {
          symbols.push(s);
        }

        Ok(CounterStyle::Symbols { system: t, symbols })
      });
    }

    let name = CustomIdent::parse(input)?;
    Ok(CounterStyle::Name(name))
  }
}

impl<'i> ToCss for CounterStyle<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      CounterStyle::Predefined(style) => style.to_css(dest),
      CounterStyle::Name(name) => name.to_css(dest),
      CounterStyle::Symbols { system, symbols } => {
        dest.write_str("symbols(")?;
        let mut needs_space = false;
        if *system != SymbolsType::Symbolic {
          system.to_css(dest)?;
          needs_space = true;
        }
        for symbol in symbols {
          if needs_space {
            dest.write_char(' ')?;
          }
          match symbol {
            Symbol::String(s) => crate::printer::serialize_string(s, dest)?,
            Symbol::Image(i) => i.to_css(dest)?,
          }
          needs_space = true;
        }
        dest.write_char(')')
      }
    }
  }
}

