#[derive(Clone, Debug, PartialEq)]
pub struct ListStyle<'i> {
  pub list_style_type: ListStyleType<'i>,
  pub image: Image<'i>,
  pub position: ListStylePosition,
}

impl<'i> Parse<'i> for ListStyle<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut position = None;
    let mut image = None;
    let mut list_style_type = None;
    let mut nones = 0;

    loop {
      // `none` is ambiguous - both list-style-image and list-style-type support it.
      if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
        nones += 1;
        if nones > 2 {
          return Err(input.new_error_for_next_token());
        }
        continue;
      }

      if image.is_none() {
        if let Ok(val) = input.try_parse(Image::parse) {
          image = Some(val);
          continue;
        }
      }

      if position.is_none() {
        if let Ok(val) = input.try_parse(ListStylePosition::parse) {
          position = Some(val);
          continue;
        }
      }

      if list_style_type.is_none() {
        if let Ok(val) = input.try_parse(ListStyleType::parse) {
          list_style_type = Some(val);
          continue;
        }
      }

      break;
    }

    // Assign the `none` to the opposite property from the one we have a value for.
    if nones >= 1 && list_style_type.is_none() {
      list_style_type = Some(ListStyleType::None);
    }
    if nones >= 1 && image.is_none() && (nones == 2 || list_style_type != Some(ListStyleType::None)) {
      image = Some(Image::None);
    }

    if nones == 0 && position.is_none() && image.is_none() && list_style_type.is_none() {
      return Err(input.new_error_for_next_token());
    }

    Ok(ListStyle {
      list_style_type: list_style_type.unwrap_or_default(),
      image: image.unwrap_or(Image::None),
      position: position.unwrap_or_default(),
    })
  }
}

impl<'i> ToCss for ListStyle<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut needs_space = false;
    if self.position != ListStylePosition::default() {
      self.position.to_css(dest)?;
      needs_space = true;
    }

    if self.image != Image::None {
      if needs_space {
        dest.write_char(' ')?;
      }
      self.image.to_css(dest)?;
      needs_space = true;
    }

    if self.list_style_type != ListStyleType::default() {
      if needs_space {
        dest.write_char(' ')?;
      }
      self.list_style_type.to_css(dest)?;
      needs_space = true;
    }

    if !needs_space {
      self.position.to_css(dest)?;
    }

    Ok(())
  }
}
