#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ColorScheme {
  pub light: bool,
  pub dark: bool,
  pub only: bool,
}

impl<'i> Parse<'i> for ColorScheme {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut res = ColorScheme {
      light: false,
      dark: false,
      only: false,
    };
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "normal" => return Ok(res),
      "only" => res.only = true,
      "light" => res.light = true,
      "dark" => res.dark = true,
      _ => return Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(ident))),
    }

    while let Ok(ident) = input.try_parse(|input| input.expect_ident()) {
      match ident.to_ascii_lowercase().as_str() {
        "normal" => return Err(input.new_custom_error(crate::error::ParserError::InvalidValue)),
        "only" => {
          // Only must be at the start or the end, not in the middle.
          if res.only {
            return Err(input.new_custom_error(crate::error::ParserError::InvalidValue));
          }
          res.only = true;
          return Ok(res);
        }
        "light" => res.light = true,
        "dark" => res.dark = true,
        _ => {}
      }
    }

    Ok(res)
  }
}

impl ToCss for ColorScheme {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if !self.light && !self.dark {
      return dest.write_str("normal");
    }
    if self.light {
      dest.write_str("light")?;
      if self.dark {
        dest.write_char(' ')?;
      }
    }
    if self.dark {
      dest.write_str("dark")?;
    }
    if self.only {
      dest.write_str(" only")?;
    }
    Ok(())
  }
}

/// The CSS modules `composes` property.
#[derive(Clone, Debug, PartialEq)]
pub struct Composes<'i> {
  pub names: Vec<Cow<'i, str>>,
  pub from: Option<Specifier<'i>>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Specifier<'i> {
  Global,
  File(Cow<'i, str>),
  SourceIndex(u32),
}

impl<'i> Parse<'i> for Composes<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut names = Vec::new();
    while let Ok(name) = input.try_parse(|input| {
      let loc = input.current_source_location();
      let ident = input.expect_ident()?;
      if ident.eq_ignore_ascii_case("from") {
        return Err(loc.new_unexpected_token_error::<crate::error::ParserError>(crate::tokenizer::Token::Ident(ident)));
      }
      Ok(ident)
    }) {
      names.push(name);
    }
    if names.is_empty() {
      return Err(input.new_error_for_next_token());
    }
    let from = if input.try_parse(|input| input.expect_ident_matching("from")).is_ok() {
      if let Ok(s) = input.try_parse(|input| input.expect_string()) {
        Some(Specifier::File(s))
      } else {
        input.expect_ident_matching("global")?;
        Some(Specifier::Global)
      }
    } else {
      None
    };
    Ok(Composes { names, from })
  }
}

impl<'i> ToCss for Composes<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut first = true;
    for name in &self.names {
      if first {
        first = false;
      } else {
        dest.write_char(' ')?;
      }
      crate::printer::serialize_identifier(name, dest)?;
    }
    if let Some(from) = &self.from {
      dest.write_str(" from ")?;
      match from {
        Specifier::Global => dest.write_str("global")?,
        Specifier::File(f) => crate::printer::serialize_string(f, dest)?,
        Specifier::SourceIndex(_) => {}
      }
    }
    Ok(())
  }
}
