        input.expect_comma()?;
        let max = TrackBreadth::parse(input)?;
        Ok(TrackSize::MinMax { min, max })
      });
    }

    input.expect_function_matching("fit-content")?;
    let len = input.parse_nested_block(|input| LengthPercentage::parse(input))?;
    Ok(TrackSize::FitContent(len))
  }
