          TrackListItem::TrackSize(size) => size.to_css(dest)?,
        }

        if items_index < self.line_names.len() && !self.line_names[items_index].is_empty() {
          dest.whitespace()?;
        }
      }

      first = false;
    }

    Ok(())
  }
