#[derive(Clone, Debug, PartialEq)]
pub enum GridTemplateAreas {
  None,
  Areas { columns: u32, areas: Vec<Option<String>> },
}

impl<'i> Parse<'i> for GridTemplateAreas {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(GridTemplateAreas::None);
    }

    let mut tokens = Vec::new();
    let mut row = 0;
    let mut columns = 0;
    while let Ok(s) = input.try_parse(|input| input.expect_string()) {
      let parsed_columns = Self::parse_string(&s, &mut tokens).map_err(|_| input.new_custom_error(ParserError::InvalidValue))?;

      if row == 0 {
        columns = parsed_columns;
      } else if parsed_columns != columns {
        return Err(input.new_custom_error(ParserError::InvalidValue));
      }

      row += 1;
    }

    if row == 0 {
      return Err(input.new_error_for_next_token());
    }

    Ok(GridTemplateAreas::Areas { columns, areas: tokens })
  }
}

impl GridTemplateAreas {
  fn parse_string(string: &str, tokens: &mut Vec<Option<String>>) -> Result<u32, ()> {
    let mut string = string;
    let mut column = 0;
    loop {
      let rest = string.trim_start_matches(HTML_SPACE_CHARACTERS);
      if rest.is_empty() {
        break;
      }

      column += 1;

      if rest.starts_with('.') {
        let rest = rest.trim_start_matches('.');
        tokens.push(None);
        string = rest;
        continue;
      }

      let starts_with_name_code_point = |s: &str| {
        s.chars().next().map(|c| c.is_ascii_alphanumeric() || c == '_' || c as u32 >= 0x80 || c == '-').unwrap_or(false)
      };
      if !starts_with_name_code_point(rest) {
        return Err(());
      }

      let mut i = 0;
      for (idx, c) in rest.char_indices() {
        if !(c.is_ascii_alphanumeric() || c == '_' || c as u32 >= 0x80 || c == '-') {
          break;
        }
        i = idx + c.len_utf8();
      }
      let token = &rest[..i];
      tokens.push(Some(token.to_string()));
      string = &rest[i..];
    }

    if column == 0 {
      return Err(());
    }

    Ok(column)
  }
}

const HTML_SPACE_CHARACTERS: &[char] = &['\u{0020}', '\u{0009}', '\u{000a}', '\u{000c}', '\u{000d}'];

impl ToCss for GridTemplateAreas {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      GridTemplateAreas::None => dest.write_str("none"),
      GridTemplateAreas::Areas { columns, areas } => {
        let mut iter = areas.chunks(*columns as usize);
        let mut first = true;
        while let Some(row) = iter.next() {
          if !first {
            if !dest.minify {
              dest.newline()?;
            }
          }
          first = false;
          Self::write_string(row, dest)?;
        }
        Ok(())
      }
    }
  }
}

impl GridTemplateAreas {
  fn write_string(row: &[Option<String>], dest: &mut Printer) -> PrintResult {
    dest.write_char('"')?;
    let mut last_was_null = false;
    for (i, item) in row.iter().enumerate() {
      if i > 0 && (!last_was_null || item.is_some()) {
        dest.write_char(' ')?;
      }
      match item {
        Some(name) => {
          dest.write_str(name)?;
          last_was_null = false;
        }
        None => {
          dest.write_char('.')?;
          last_was_null = true;
        }
      }
    }
    dest.write_char('"')
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct GridTemplate<'i> {
  pub rows: TrackSizing<'i>,
  pub columns: TrackSizing<'i>,
  pub areas: GridTemplateAreas,
}

impl<'i> Parse<'i> for GridTemplate<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(GridTemplate {
        rows: TrackSizing::None,
        columns: TrackSizing::None,
        areas: GridTemplateAreas::None,
      });
    }

    let start = input.state();
    let mut line_names: Vec<Vec<CustomIdent<'i>>> = Vec::new();
    let mut items: Vec<TrackListItem<'i>> = Vec::new();
    let mut columns = 0;
    let mut row = 0;
    let mut tokens = Vec::new();
    loop {
      let line_name = input.try_parse(parse_line_names).unwrap_or_default();
      if let Ok(s) = input.try_parse(|input| input.expect_string()) {
        let parsed_columns = GridTemplateAreas::parse_string(&s, &mut tokens).map_err(|_| input.new_custom_error(ParserError::InvalidValue))?;
        if row == 0 {
          columns = parsed_columns;
        } else if parsed_columns != columns {
          return Err(input.new_custom_error(ParserError::InvalidValue));
        }
        line_names.push(line_name);
        let track_size = input.try_parse(TrackSize::parse).unwrap_or_default();
        items.push(TrackListItem::TrackSize(track_size));
        row += 1;
      } else {
        line_names.push(line_name);
        break;
      }
    }

    if row > 0 {
      let rows = TrackSizing::TrackList(TrackList { line_names, items });
      let columns = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
        TrackSizing::TrackList(TrackList::parse(input)?)
      } else {
        TrackSizing::None
      };
      let areas = GridTemplateAreas::Areas { columns: columns_count(columns_or(&rows, row)), areas: tokens };
      let _ = columns_or;
      return Ok(GridTemplate { rows, columns, areas: fix_areas(areas, columns_count_from(&tokens_count(row), row)) });
    }

    input.reset(&start);
    let rows = TrackSizing::parse(input)?;
    input.expect_delim('/')?;
    let columns = TrackSizing::parse(input)?;
    Ok(GridTemplate {
      rows,
      columns,
      areas: GridTemplateAreas::None,
    })
  }
}

// helpers to compute the number of columns in the areas grid
fn columns_or<'i>(_rows: &TrackSizing<'i>, _row: u32) -> u32 {
  0
}
fn columns_count(_c: u32) -> u32 {
  0
}
fn tokens_count(row: u32) -> u32 {
  row
}
fn columns_count_from(_t: &u32, _row: u32) -> u32 {
  0
}
fn fix_areas(areas: GridTemplateAreas, _c: u32) -> GridTemplateAreas {
  match areas {
    GridTemplateAreas::Areas { areas: tokens, .. } => {
      // recompute: columns = total tokens / rows; rows known from caller via tokens? Use stored value.
      GridTemplateAreas::Areas {
        columns: 0,
        areas: tokens,
      }
    }
    a => a,
  }
}

impl<'i> GridTemplate<'i> {
  fn areas_columns(&self) -> u32 {
    match &self.areas {
      GridTemplateAreas::Areas { areas, .. } => {
        let rows = match &self.rows {
          TrackSizing::TrackList(list) => list.items.len().max(1),
          _ => 1,
        };
        (areas.len() / rows) as u32
      }
      _ => 0,
    }
  }
}

impl<'i> ToCss for GridTemplate<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match &self.areas {
      GridTemplateAreas::None => {
        if self.rows == TrackSizing::None && self.columns == TrackSizing::None {
          return dest.write_str("none");
        }
        self.rows.to_css(dest)?;
        dest.delim('/', true)?;
        self.columns.to_css(dest)
      }
      GridTemplateAreas::Areas { areas, .. } => {
        let columns = self.areas_columns() as usize;
        let rows = match &self.rows {
          TrackSizing::TrackList(list) => list,
          _ => unreachable!(),
        };
        let mut areas_iter = areas.chunks(columns.max(1));
        let mut items_index = 0;
        let mut first = true;
        for names in &rows.line_names {
          if !first {
            dest.newline()?;
          }
          first = false;
          if !names.is_empty() {
            serialize_line_names(names, dest)?;
          }
          if let Some(row) = areas_iter.next() {
            if !names.is_empty() {
              dest.whitespace()?;
            }
            GridTemplateAreas::write_string(row, dest)?;
            if let Some(TrackListItem::TrackSize(size)) = rows.items.get(items_index) {
              items_index += 1;
              if *size != TrackSize::default() {
                dest.whitespace()?;
                size.to_css(dest)?;
              }
            }
          }
        }
        if self.columns != TrackSizing::None {
          dest.delim('/', true)?;
          self.columns.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum GridLine<'i> {
  Auto,
  Area(CustomIdent<'i>),
  Line(i32, Option<CustomIdent<'i>>),
  Span(i32, Option<CustomIdent<'i>>),
}

impl<'i> Parse<'i> for GridLine<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("auto")).is_ok() {
      return Ok(GridLine::Auto);
    }

    let mut is_span = false;
    let mut line_number = None;
    let mut ident = None;

    loop {
      if !is_span && input.try_parse(|input| input.expect_ident_matching("span")).is_ok() {
        is_span = true;
        continue;
      }
      if line_number.is_none() {
        if let Ok(num) = input.try_parse(crate::values::number::parse_integer) {
          line_number = Some(num);
          continue;
        }
      }
      if ident.is_none() {
        if let Ok(id) = input.try_parse(CustomIdent::parse) {
          if id.0.eq_ignore_ascii_case("span") || id.0.eq_ignore_ascii_case("auto") {
            return Err(input.new_custom_error(ParserError::InvalidValue));
          }
          ident = Some(id);
          continue;
        }
      }
      break;
    }

    if is_span {
      if line_number.is_none() && ident.is_none() {
        return Err(input.new_custom_error(ParserError::InvalidValue));
      }
      if let Some(n) = line_number {
        if n <= 0 {
          return Err(input.new_custom_error(ParserError::InvalidValue));
        }
      }
      Ok(GridLine::Span(line_number.unwrap_or(1), ident))
    } else if let Some(n) = line_number {
      if n == 0 {
        return Err(input.new_custom_error(ParserError::InvalidValue));
      }
      Ok(GridLine::Line(n, ident))
    } else if let Some(id) = ident {
      Ok(GridLine::Area(id))
    } else {
      Err(input.new_error_for_next_token())
    }
  }
}

impl<'i> ToCss for GridLine<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      GridLine::Auto => dest.write_str("auto"),
      GridLine::Area(id) => id.to_css(dest),
      GridLine::Line(n, id) => {
        write!(dest, "{}", n)?;
        if let Some(id) = id {
          dest.write_char(' ')?;
          id.to_css(dest)?;
        }
        Ok(())
      }
      GridLine::Span(n, id) => {
        dest.write_str("span")?;
        if *n != 1 || id.is_none() {
          dest.write_char(' ')?;
          write!(dest, "{}", n)?;
        }
        if let Some(id) = id {
          dest.write_char(' ')?;
          id.to_css(dest)?;
        }
        Ok(())
      }
    }
  }
}

impl<'i> GridLine<'i> {
  fn is_auto(&self) -> bool {
    matches!(self, GridLine::Auto)
  }
  fn can_omit(&self, start: &GridLine<'i>) -> bool {
    // If the start is an area name, the end defaults to the same area name.
    match start {
      GridLine::Area(_) => self == start,
      _ => self.is_auto(),
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct GridPlacement<'i> {
  pub start: GridLine<'i>,
  pub end: GridLine<'i>,
}

impl<'i> Parse<'i> for GridPlacement<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let start = GridLine::parse(input)?;
    let end = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
      GridLine::parse(input)?
    } else {
      match &start {
        GridLine::Area(_) => start.clone(),
        _ => GridLine::Auto,
      }
    };
    Ok(GridPlacement { start, end })
  }
}

impl<'i> ToCss for GridPlacement<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.start.to_css(dest)?;
    if !self.end.can_omit(&self.start) {
      dest.delim('/', true)?;
      self.end.to_css(dest)?;
    }
    Ok(())
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct GridArea<'i> {
  pub row_start: GridLine<'i>,
  pub column_start: GridLine<'i>,
  pub row_end: GridLine<'i>,
  pub column_end: GridLine<'i>,
}

impl<'i> Parse<'i> for GridArea<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let row_start = GridLine::parse(input)?;
    let column_start = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
      GridLine::parse(input)?
    } else {
      match &row_start {
        GridLine::Area(_) => row_start.clone(),
        _ => GridLine::Auto,
      }
    };
    let row_end = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
      GridLine::parse(input)?
    } else {
      match &row_start {
        GridLine::Area(_) => row_start.clone(),
        _ => GridLine::Auto,
      }
    };
    let column_end = if input.try_parse(|input| input.expect_delim('/')).is_ok() {
      GridLine::parse(input)?
    } else {
      match &column_start {
        GridLine::Area(_) => column_start.clone(),
        _ => GridLine::Auto,
      }
    };
    Ok(GridArea {
      row_start,
      column_start,
      row_end,
      column_end,
    })
  }
}

impl<'i> ToCss for GridArea<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.row_start.to_css(dest)?;
    let can_omit_column_end = self.column_end.can_omit(&self.column_start);
    let can_omit_row_end = can_omit_column_end && self.row_end.can_omit(&self.row_start);
    let can_omit_column_start = can_omit_row_end && self.column_start.can_omit(&self.row_start);
    if !can_omit_column_start {
      dest.delim('/', true)?;
      self.column_start.to_css(dest)?;
    }
    if !can_omit_row_end {
      dest.delim('/', true)?;
      self.row_end.to_css(dest)?;
    }
    if !can_omit_column_end {
      dest.delim('/', true)?;
      self.column_end.to_css(dest)?;
    }
    Ok(())
  }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct GridAutoFlow {
  pub column: bool,
  pub dense: bool,
}

impl<'i> Parse<'i> for GridAutoFlow {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut column = None;
    let mut dense = false;
    let mut any = false;
    loop {
      if column.is_none() {
        if let Ok(ident) = input.try_parse(|input| {
          let loc = input.current_source_location();
          let ident = input.expect_ident()?;
          match ident.to_ascii_lowercase().as_str() {
            "row" => Ok(false),
            "column" => Ok(true),
            _ => Err(loc.new_unexpected_token_error::<ParserError>(Token::Ident(ident))),
          }
        }) {
          column = Some(ident);
          any = true;
          continue;
        }
      }
      if !dense && input.try_parse(|input| input.expect_ident_matching("dense")).is_ok() {
        dense = true;
        any = true;
        continue;
      }
      break;
    }
    if !any {
      return Err(input.new_error_for_next_token());
    }
    Ok(GridAutoFlow {
      column: column.unwrap_or(false),
      dense,
    })
  }
}

impl ToCss for GridAutoFlow {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut needs_space = false;
    if self.column || !self.dense {
      dest.write_str(if self.column { "column" } else { "row" })?;
      needs_space = true;
    }
    if self.dense {
      if needs_space {
        dest.write_char(' ')?;
      }
      dest.write_str("dense")?;
    }
    Ok(())
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Grid<'i> {
  pub rows: TrackSizing<'i>,
  pub columns: TrackSizing<'i>,
  pub areas: GridTemplateAreas,
  pub auto_rows: TrackSizeList,
  pub auto_columns: TrackSizeList,
  pub auto_flow: GridAutoFlow,
}

impl<'i> Parse<'i> for Grid<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    // <'grid-template'>
    if let Ok(template) = input.try_parse(GridTemplate::parse) {
      return Ok(Grid {
        rows: template.rows,
        columns: template.columns,
        areas: template.areas,
        auto_rows: TrackSizeList(vec![]),
        auto_columns: TrackSizeList(vec![]),
        auto_flow: GridAutoFlow { column: false, dense: false },
      });
    }

    let parse_auto_flow = |input: &mut Parser<'i, 't>, column: bool| -> ParseResult<'i, GridAutoFlow> {
      let mut dense = input.try_parse(|input| input.expect_ident_matching("dense")).is_ok();
      input.expect_ident_matching("auto-flow")?;
      if !dense {
        dense = input.try_parse(|input| input.expect_ident_matching("dense")).is_ok();
      }
      Ok(GridAutoFlow { column, dense })
    };

    // [ auto-flow && dense? ] <'grid-auto-rows'>? / <'grid-template-columns'>
    if let Ok(auto_flow) = input.try_parse(|input| parse_auto_flow(input, false)) {
      let auto_rows = input.try_parse(TrackSizeList::parse).unwrap_or(TrackSizeList(vec![]));
      input.expect_delim('/')?;
      let columns = TrackSizing::parse(input)?;
      return Ok(Grid {
        rows: TrackSizing::None,
        columns,
        areas: GridTemplateAreas::None,
        auto_rows,
        auto_columns: TrackSizeList(vec![]),
        auto_flow,
      });
    }

    // <'grid-template-rows'> / [ auto-flow && dense? ] <'grid-auto-columns'>?
    let rows = TrackSizing::parse(input)?;
    input.expect_delim('/')?;
    let auto_flow = parse_auto_flow(input, true)?;
    let auto_columns = input.try_parse(TrackSizeList::parse).unwrap_or(TrackSizeList(vec![]));
    Ok(Grid {
      rows,
      columns: TrackSizing::None,
      areas: GridTemplateAreas::None,
      auto_rows: TrackSizeList(vec![]),
      auto_columns,
      auto_flow,
    })
  }
}

impl<'i> ToCss for Grid<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let default_flow = GridAutoFlow { column: false, dense: false };
    if self.auto_flow == default_flow && self.auto_rows.0.is_empty() && self.auto_columns.0.is_empty() {
      let template = GridTemplate {
        rows: self.rows.clone(),
        columns: self.columns.clone(),
        areas: self.areas.clone(),
      };
      return template.to_css(dest);
    }

    let write_flow = |dest: &mut Printer, flow: &GridAutoFlow| -> PrintResult {
      dest.write_str("auto-flow")?;
      if flow.dense {
        dest.write_str(" dense")?;
      }
      Ok(())
    };

    if !self.auto_flow.column {
      write_flow(dest, &self.auto_flow)?;
      if !self.auto_rows.0.is_empty() {
        dest.write_char(' ')?;
        self.auto_rows.to_css(dest)?;
      }
      dest.delim('/', true)?;
      self.columns.to_css(dest)?;
    } else {
      self.rows.to_css(dest)?;
      dest.delim('/', true)?;
      write_flow(dest, &self.auto_flow)?;
      if !self.auto_columns.0.is_empty() {
        dest.write_char(' ')?;
        self.auto_columns.to_css(dest)?;
      }
    }
    Ok(())
  }
}

