//! Grid properties.

use crate::error::{ParseResult, ParserError};
use crate::parser::Parser;
use crate::printer::{PrintResult, Printer, ToCss};
use crate::tokenizer::Token;
use crate::traits::Parse;
use crate::values::ident::CustomIdent;
use crate::values::length::LengthPercentage;
use crate::values::number::serialize_number;
use std::borrow::Cow;

#[derive(Clone, Debug, PartialEq)]
pub enum TrackSizing<'i> {
  None,
  TrackList(TrackList<'i>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct TrackList<'i> {
  pub line_names: Vec<Vec<CustomIdent<'i>>>,
  pub items: Vec<TrackListItem<'i>>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum TrackListItem<'i> {
  TrackSize(TrackSize),
  TrackRepeat(TrackRepeat<'i>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum TrackSize {
  TrackBreadth(TrackBreadth),
  MinMax { min: TrackBreadth, max: TrackBreadth },
  FitContent(LengthPercentage),
}

impl Default for TrackSize {
  fn default() -> TrackSize {
    TrackSize::TrackBreadth(TrackBreadth::Auto)
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum TrackBreadth {
  Length(LengthPercentage),
  Flex(f32),
  MinContent,
  MaxContent,
  Auto,
}

#[derive(Clone, Debug, PartialEq)]
pub struct TrackRepeat<'i> {
  pub count: RepeatCount,
  pub line_names: Vec<Vec<CustomIdent<'i>>>,
  pub track_sizes: Vec<TrackSize>,
}

#[derive(Clone, Debug, PartialEq)]
pub enum RepeatCount {
  Number(i32),
  AutoFill,
  AutoFit,
}

impl<'i> Parse<'i> for TrackBreadth {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(len) = input.try_parse(LengthPercentage::parse) {
      return Ok(TrackBreadth::Length(len));
    }
    if let Ok(flex) = input.try_parse(parse_flex) {
      return Ok(TrackBreadth::Flex(flex));
    }
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "auto" => Ok(TrackBreadth::Auto),
      "min-content" => Ok(TrackBreadth::MinContent),
      "max-content" => Ok(TrackBreadth::MaxContent),
      _ => Err(location.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
}

fn parse_flex<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, f32> {
  let location = input.current_source_location();
  match input.next()? {
    Token::Dimension { value, ref unit, .. } if unit.eq_ignore_ascii_case("fr") && value >= 0.0 => Ok(value),
    t => Err(location.new_unexpected_token_error(t)),
  }
}

impl ToCss for TrackBreadth {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      TrackBreadth::Auto => dest.write_str("auto"),
      TrackBreadth::MinContent => dest.write_str("min-content"),
      TrackBreadth::MaxContent => dest.write_str("max-content"),
      TrackBreadth::Length(len) => len.to_css(dest),
      TrackBreadth::Flex(flex) => crate::values::number::serialize_dimension(*flex, "fr", dest),
    }
  }
}

impl<'i> Parse<'i> for TrackSize {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(breadth) = input.try_parse(TrackBreadth::parse) {
      return Ok(TrackSize::TrackBreadth(breadth));
    }

    if input.try_parse(|input| input.expect_function_matching("minmax")).is_ok() {
      return input.parse_nested_block(|input| {
        let min = TrackBreadth::parse(input)?;
        input.expect_comma()?;
        let max = TrackBreadth::parse(input)?;
        Ok(TrackSize::MinMax { min, max })
      });
    }

    input.expect_function_matching("fit-content")?;
    let len = input.parse_nested_block(|input| LengthPercentage::parse(input))?;
    Ok(TrackSize::FitContent(len))
  }
}

impl ToCss for TrackSize {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      TrackSize::TrackBreadth(breadth) => breadth.to_css(dest),
      TrackSize::MinMax { min, max } => {
        dest.write_str("minmax(")?;
        min.to_css(dest)?;
        dest.delim(',', false)?;
        max.to_css(dest)?;
        dest.write_char(')')
      }
      TrackSize::FitContent(len) => {
        dest.write_str("fit-content(")?;
        len.to_css(dest)?;
        dest.write_char(')')
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct TrackSizeList(pub Vec<TrackSize>);

impl<'i> Parse<'i> for TrackSizeList {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut res = Vec::new();
    while let Ok(size) = input.try_parse(TrackSize::parse) {
      res.push(size)
    }
    if res.is_empty() {
      return Err(input.new_error_for_next_token());
    }
    Ok(TrackSizeList(res))
  }
}

impl ToCss for TrackSizeList {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.0.is_empty() {
      return dest.write_str("auto");
    }
    let mut first = true;
    for item in &self.0 {
      if first {
        first = false;
      } else {
        dest.write_char(' ')?;
      }
      item.to_css(dest)?;
    }
    Ok(())
  }
}

fn parse_line_names<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Vec<CustomIdent<'i>>> {
  input.expect_square_bracket_block()?;
  input.parse_nested_block(|input| {
    let mut values = vec![];
    while let Ok(ident) = input.try_parse(CustomIdent::parse) {
      values.push(ident)
    }
    Ok(values)
  })
}

fn serialize_line_names(names: &[CustomIdent], dest: &mut Printer) -> PrintResult {
  dest.write_char('[')?;
  let mut first = true;
  for name in names {
    if first {
      first = false;
    } else {
      dest.write_char(' ')?;
    }
    name.to_css(dest)?;
  }
  dest.write_char(']')
}

impl<'i> Parse<'i> for TrackList<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut line_names = Vec::new();
    let mut items = Vec::new();

    loop {
      let line_name = input.try_parse(parse_line_names).unwrap_or_default();
      line_names.push(line_name);

      if let Ok(track_size) = input.try_parse(TrackSize::parse) {
        items.push(TrackListItem::TrackSize(track_size));
      } else if let Ok(repeat) = input.try_parse(TrackRepeat::parse) {
        items.push(TrackListItem::TrackRepeat(repeat))
      } else {
        break;
      }
    }

    if items.is_empty() {
      return Err(input.new_error_for_next_token());
    }

    Ok(TrackList { line_names, items })
  }
}

impl<'i> ToCss for TrackList<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut items_index = 0;
    let mut first = true;

    for names in &self.line_names {
      if !names.is_empty() {
        serialize_line_names(names, dest)?;
      }

      if items_index < self.items.len() {
        let item = &self.items[items_index];
        items_index += 1;

        // Whitespace is required if there are no line names.
        if !names.is_empty() {
          dest.whitespace()?;
        } else if !first {
          dest.write_char(' ')?;
        }

        match item {
          TrackListItem::TrackRepeat(repeat) => repeat.to_css(dest)?,
          TrackListItem::TrackSize(size) => size.to_css(dest)?,
        }

        if items_index < self.line_names.len() && !self.line_names[items_index].is_empty() {
          dest.whitespace()?;
        }
      }

      first = false;
    }

    Ok(())
  }
}

impl<'i> Parse<'i> for TrackRepeat<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    input.expect_function_matching("repeat")?;
    input.parse_nested_block(|input| {
      let count = RepeatCount::parse(input)?;
      input.expect_comma()?;

      let mut line_names = Vec::new();
      let mut track_sizes = Vec::new();

      loop {
        let line_name = input.try_parse(parse_line_names).unwrap_or_default();
        line_names.push(line_name);

        if let Ok(track_size) = input.try_parse(TrackSize::parse) {
          track_sizes.push(track_size)
        } else {
          break;
        }
      }

      Ok(TrackRepeat {
        count,
        line_names,
        track_sizes,
      })
    })
  }
}

impl<'i> ToCss for TrackRepeat<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.write_str("repeat(")?;
    self.count.to_css(dest)?;
    dest.delim(',', false)?;

    let mut track_sizes_index = 0;
    let mut first = true;
    for names in &self.line_names {
      if !names.is_empty() {
        serialize_line_names(names, dest)?;
      }

      if track_sizes_index < self.track_sizes.len() {
        let size = &self.track_sizes[track_sizes_index];
        track_sizes_index += 1;

        if !names.is_empty() {
          dest.whitespace()?;
        } else if !first {
          dest.write_char(' ')?;
        }

        size.to_css(dest)?;

        if track_sizes_index < self.line_names.len() && !self.line_names[track_sizes_index].is_empty() {
          dest.whitespace()?;
        }
      }

      first = false;
    }

    dest.write_char(')')
  }
}

impl<'i> Parse<'i> for RepeatCount {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(num) = input.try_parse(crate::values::number::parse_integer) {
      return Ok(RepeatCount::Number(num));
    }
    let location = input.current_source_location();
    let ident = input.expect_ident()?;
    match ident.to_ascii_lowercase().as_str() {
      "auto-fill" => Ok(RepeatCount::AutoFill),
      "auto-fit" => Ok(RepeatCount::AutoFit),
      _ => Err(location.new_unexpected_token_error(Token::Ident(ident))),
    }
  }
}

