  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      RepeatCount::AutoFill => dest.write_str("auto-fill"),
      RepeatCount::AutoFit => dest.write_str("auto-fit"),
      RepeatCount::Number(num) => write!(dest, "{}", num),
