#[derive(Clone, Debug, PartialEq)]
pub enum BasicShape {
  Inset(InsetRect),
  Circle(Circle),
  Ellipse(Ellipse),
  Polygon(Polygon),
  Path(String),
}

#[derive(Clone, Debug, PartialEq)]
pub struct InsetRect {
  pub rect: Rect<LengthPercentage>,
  pub radius: crate::properties::border_radius::BorderRadius,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Circle {
  pub radius: ShapeRadius,
  pub position: Position,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Ellipse {
  pub radius_x: ShapeRadius,
  pub radius_y: ShapeRadius,
  pub position: Position,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Polygon {
  pub fill_rule: ShapeFillRule,
  pub points: Vec<(LengthPercentage, LengthPercentage)>,
}

fn default_radius() -> crate::properties::border_radius::BorderRadius {
  let zero = LengthPercentage::zero();
  crate::properties::border_radius::BorderRadius {
    top_left: Size2D(zero.clone(), zero.clone()),
    top_right: Size2D(zero.clone(), zero.clone()),
    bottom_right: Size2D(zero.clone(), zero.clone()),
    bottom_left: Size2D(zero.clone(), zero),
  }
}

impl<'i> Parse<'i> for BasicShape {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    let f = input.expect_function()?;
    let lower = f.to_ascii_lowercase();
    input.parse_nested_block(|input| match lower.as_str() {
      "inset" => {
        let rect = Rect::parse(input)?;
        let radius = if input.try_parse(|input| input.expect_ident_matching("round")).is_ok() {
          crate::properties::border_radius::BorderRadius::parse(input)?
        } else {
          default_radius()
        };
        Ok(BasicShape::Inset(InsetRect { rect, radius }))
      }
      "circle" => {
        let radius = input.try_parse(ShapeRadius::parse).unwrap_or_default();
        let position = if input.try_parse(|input| input.expect_ident_matching("at")).is_ok() {
          Position::parse(input)?
        } else {
          Position::center()
        };
        Ok(BasicShape::Circle(Circle { radius, position }))
      }
      "ellipse" => {
        let (x, y) = if let Ok(x) = input.try_parse(ShapeRadius::parse) {
          let y = ShapeRadius::parse(input)?;
          (x, y)
        } else {
          (ShapeRadius::ClosestSide, ShapeRadius::ClosestSide)
        };
        let position = if input.try_parse(|input| input.expect_ident_matching("at")).is_ok() {
          Position::parse(input)?
        } else {
          Position::center()
        };
        Ok(BasicShape::Ellipse(Ellipse {
          radius_x: x,
          radius_y: y,
          position,
        }))
      }
      "polygon" => {
        let fill_rule = input.try_parse(ShapeFillRule::parse);
        if fill_rule.is_ok() {
          input.expect_comma()?;
        }
        let points = input.parse_comma_separated(|input| {
          let x = LengthPercentage::parse(input)?;
          let y = LengthPercentage::parse(input)?;
          Ok((x, y))
        })?;
        Ok(BasicShape::Polygon(Polygon {
          fill_rule: fill_rule.unwrap_or(ShapeFillRule::NonZero),
          points,
        }))
      }
      "path" => {
        let fill_rule = input.try_parse(ShapeFillRule::parse);
        if fill_rule.is_ok() {
          input.expect_comma()?;
        }
        let s = input.expect_string()?;
        let mut out = String::new();
        if let Ok(fr) = fill_rule {
          if fr == ShapeFillRule::EvenOdd {
            out.push_str("evenodd,");
          }
        }
        let mut st = String::new();
        crate::printer::serialize_string_to_string(&s, &mut st);
        out.push_str(&st);
        Ok(BasicShape::Path(out))
      }
      _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(f.clone()))),
    })
  }
}

impl ToCss for BasicShape {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      BasicShape::Inset(rect) => {
        dest.write_str("inset(")?;
        rect.rect.to_css(dest)?;
        if rect.radius != default_radius() {
          dest.write_str(" round ")?;
          rect.radius.to_css(dest)?;
        }
        dest.write_char(')')
      }
      BasicShape::Circle(circle) => {
        dest.write_str("circle(")?;
        let mut has_output = false;
        if circle.radius != ShapeRadius::default() {
          circle.radius.to_css(dest)?;
          has_output = true;
        }
        if !circle.position.is_center() {
          if has_output {
            dest.write_char(' ')?;
          }
          dest.write_str("at ")?;
          circle.position.to_css(dest)?;
        }
        dest.write_char(')')
      }
      BasicShape::Ellipse(ellipse) => {
        dest.write_str("ellipse(")?;
        let mut has_output = false;
        if ellipse.radius_x != ShapeRadius::default() || ellipse.radius_y != ShapeRadius::default() {
          ellipse.radius_x.to_css(dest)?;
          dest.write_char(' ')?;
          ellipse.radius_y.to_css(dest)?;
          has_output = true;
        }
        if !ellipse.position.is_center() {
          if has_output {
            dest.write_char(' ')?;
          }
          dest.write_str("at ")?;
          ellipse.position.to_css(dest)?;
        }
        dest.write_char(')')
      }
      BasicShape::Polygon(poly) => {
        dest.write_str("polygon(")?;
        if poly.fill_rule != ShapeFillRule::NonZero {
          poly.fill_rule.to_css(dest)?;
          dest.delim(',', false)?;
        }
        let mut first = true;
        for (x, y) in &poly.points {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          x.to_css(dest)?;
          dest.write_char(' ')?;
          y.to_css(dest)?;
        }
        dest.write_char(')')
      }
      BasicShape::Path(s) => {
        dest.write_str("path(")?;
        dest.write_str(s)?;
        dest.write_char(')')
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum ClipPath<'i> {
  None,
  Url(Url<'i>),
  Shape { shape: Box<BasicShape>, reference_box: GeometryBox },
  Box(GeometryBox),
}

impl<'i> Parse<'i> for ClipPath<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(url) = input.try_parse(Url::parse) {
      return Ok(ClipPath::Url(url));
    }

    if let Ok(shape) = input.try_parse(BasicShape::parse) {
      let b = input.try_parse(GeometryBox::parse).unwrap_or_default();
      return Ok(ClipPath::Shape {
        shape: Box::new(shape),
        reference_box: b,
      });
    }

    if let Ok(b) = input.try_parse(GeometryBox::parse) {
      if let Ok(shape) = input.try_parse(BasicShape::parse) {
        return Ok(ClipPath::Shape {
          shape: Box::new(shape),
          reference_box: b,
        });
      }
      return Ok(ClipPath::Box(b));
    }

    input.expect_ident_matching("none")?;
    Ok(ClipPath::None)
  }
}

impl<'i> ToCss for ClipPath<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      ClipPath::None => dest.write_str("none"),
      ClipPath::Url(url) => url.to_css(dest),
      ClipPath::Shape { shape, reference_box } => {
        shape.to_css(dest)?;
        if *reference_box != GeometryBox::default() {
          dest.write_char(' ')?;
          reference_box.to_css(dest)?;
        }
        Ok(())
      }
      ClipPath::Box(b) => b.to_css(dest),
    }
  }
}

