#[derive(Clone, Debug, PartialEq)]
pub struct Mask<'i> {
  pub image: Image<'i>,
  pub position: Position,
  pub size: BackgroundSize,
  pub repeat: BackgroundRepeat,
  pub clip: MaskClip,
  pub origin: GeometryBox,
  pub composite: MaskComposite,
  pub mode: MaskMode,
}

impl<'i> Parse<'i> for Mask<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut image: Option<Image> = None;
    let mut position: Option<Position> = None;
    let mut size: Option<BackgroundSize> = None;
    let mut repeat: Option<BackgroundRepeat> = None;
    let mut clip: Option<MaskClip> = None;
    let mut origin: Option<GeometryBox> = None;
    let mut composite: Option<MaskComposite> = None;
    let mut mode: Option<MaskMode> = None;

    loop {
      if image.is_none() {
        if let Ok(value) = input.try_parse(Image::parse) {
          image = Some(value);
          continue;
        }
      }

      if position.is_none() {
        if let Ok(value) = input.try_parse(Position::parse) {
          position = Some(value);
          size = input
            .try_parse(|input| {
              input.expect_delim('/')?;
              BackgroundSize::parse(input)
            })
            .ok();
          continue;
        }
      }

      if repeat.is_none() {
        if let Ok(value) = input.try_parse(BackgroundRepeat::parse) {
          repeat = Some(value);
          continue;
        }
      }

      if origin.is_none() {
        if let Ok(value) = input.try_parse(GeometryBox::parse) {
          origin = Some(value);
          continue;
        }
      }

      if clip.is_none() {
        if let Ok(value) = input.try_parse(MaskClip::parse) {
          clip = Some(value);
          continue;
        }
      }

      if composite.is_none() {
        if let Ok(value) = input.try_parse(MaskComposite::parse) {
          composite = Some(value);
          continue;
        }
      }

      if mode.is_none() {
        if let Ok(value) = input.try_parse(MaskMode::parse) {
          mode = Some(value);
          continue;
        }
      }

      break;
    }

    if clip.is_none() {
      if let Some(origin) = origin {
        clip = Some(MaskClip::GeometryBox(origin));
      }
    }

    if image.is_none() && position.is_none() && repeat.is_none() && origin.is_none() && clip.is_none() && composite.is_none() && mode.is_none() {
      return Err(input.new_error_for_next_token());
    }

    Ok(Mask {
      image: image.unwrap_or(Image::None),
      position: position.unwrap_or(crate::properties::background::default_position()),
      repeat: repeat.unwrap_or_default(),
      size: size.unwrap_or_default(),
      origin: origin.unwrap_or(GeometryBox::BorderBox),
      clip: clip.unwrap_or(MaskClip::GeometryBox(GeometryBox::BorderBox)),
      composite: composite.unwrap_or_default(),
      mode: mode.unwrap_or_default(),
    })
  }
}

impl<'i> ToCss for Mask<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.image.to_css(dest)?;

    if !crate::properties::background::position_is_default(&self.position) || self.size != BackgroundSize::default() {
      dest.write_char(' ')?;
      self.position.to_css(dest)?;

      if self.size != BackgroundSize::default() {
        dest.delim('/', true)?;
        self.size.to_css(dest)?;
      }
    }

    if self.repeat != BackgroundRepeat::default() {
      dest.write_char(' ')?;
      self.repeat.to_css(dest)?;
    }

    if self.origin != GeometryBox::BorderBox || self.clip != MaskClip::GeometryBox(GeometryBox::BorderBox) {
      dest.write_char(' ')?;
      self.origin.to_css(dest)?;

      if self.clip != MaskClip::GeometryBox(self.origin) {
        dest.write_char(' ')?;
        self.clip.to_css(dest)?;
      }
    }

    if self.composite != MaskComposite::default() {
      dest.write_char(' ')?;
      self.composite.to_css(dest)?;
    }

    if self.mode != MaskMode::default() {
      dest.write_char(' ')?;
      self.mode.to_css(dest)?;
    }

    Ok(())
  }
}

