        "scaley" => Ok(Transform::ScaleY(NumberOrPercentage::parse(input)?)),
        "scalez" => Ok(Transform::ScaleZ(NumberOrPercentage::parse(input)?)),
        "scale3d" => {
          let x = NumberOrPercentage::parse(input)?;
