        "rotatex" => Ok(Transform::RotateX(Angle::parse_with_unitless(input)?)),
        "rotatey" => Ok(Transform::RotateY(Angle::parse_with_unitless(input)?)),
        "rotatez" => Ok(Transform::RotateZ(Angle::parse_with_unitless(input)?)),
        "rotate3d" => {
          let x = f32::parse(input)?;
          input.expect_comma()?;
          let y = f32::parse(input)?;
          input.expect_comma()?;
          let z = f32::parse(input)?;
          input.expect_comma()?;
          let angle = Angle::parse_with_unitless(input)?;
          Ok(Transform::Rotate3d(x, y, z, angle))
        }
        "skew" => {
          let x = Angle::parse_with_unitless(input)?;
          if input.try_parse(|input| input.expect_comma()).is_ok() {
            let y = Angle::parse_with_unitless(input)?;
            Ok(Transform::Skew(x, y))
          } else {
            Ok(Transform::Skew(x, Angle::Deg(0.0)))
          }
        }
        "skewx" => Ok(Transform::SkewX(Angle::parse_with_unitless(input)?)),
        "skewy" => Ok(Transform::SkewY(Angle::parse_with_unitless(input)?)),
        "perspective" => Ok(Transform::Perspective(Length::parse(input)?)),
        _ => Err(location.new_unexpected_token_error(crate::tokenizer::Token::Ident(function.clone()))),
      }
    })
  }
}

fn write_angle(angle: &Angle, dest: &mut Printer) -> PrintResult {
  if angle.is_zero() {
    dest.write_char('0')
  } else {
    angle.to_css(dest)
  }
}

impl ToCss for Transform {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    use Transform::*;
    match self {
      Translate(x, y) => {
        if dest.minify && x.is_zero() && !y.is_zero() {
          dest.write_str("translateY(")?;
          y.to_css(dest)?;
        } else {
          dest.write_str("translate(")?;
          x.to_css(dest)?;
          if !y.is_zero() {
            dest.delim(',', false)?;
            y.to_css(dest)?;
          }
        }
        dest.write_char(')')
      }
      TranslateX(x) => {
        dest.write_str(if dest.minify { "translate(" } else { "translateX(" })?;
        x.to_css(dest)?;
        dest.write_char(')')
      }
      TranslateY(y) => {
        dest.write_str("translateY(")?;
        y.to_css(dest)?;
        dest.write_char(')')
      }
      TranslateZ(z) => {
        dest.write_str("translateZ(")?;
        z.to_css(dest)?;
        dest.write_char(')')
      }
      Translate3d(x, y, z) => {
        if dest.minify && !x.is_zero() && y.is_zero() && z.is_zero() {
          dest.write_str("translate(")?;
          x.to_css(dest)?;
        } else if dest.minify && x.is_zero() && !y.is_zero() && z.is_zero() {
          dest.write_str("translateY(")?;
          y.to_css(dest)?;
        } else if dest.minify && x.is_zero() && y.is_zero() && !z.is_zero() {
          dest.write_str("translateZ(")?;
          z.to_css(dest)?;
        } else if dest.minify && z.is_zero() {
          dest.write_str("translate(")?;
          x.to_css(dest)?;
          dest.delim(',', false)?;
          y.to_css(dest)?;
        } else {
          dest.write_str("translate3d(")?;
          x.to_css(dest)?;
          dest.delim(',', false)?;
          y.to_css(dest)?;
          dest.delim(',', false)?;
          z.to_css(dest)?;
        }
        dest.write_char(')')
      }
      Scale(x, y) => {
        if dest.minify && x.unit_value() == 1.0 && y.unit_value() != 1.0 {
          dest.write_str("scaleY(")?;
          y.to_css(dest)?;
        } else if dest.minify && x.unit_value() != 1.0 && y.unit_value() == 1.0 {
          dest.write_str("scaleX(")?;
          x.to_css(dest)?;
        } else {
          dest.write_str("scale(")?;
          x.to_css(dest)?;
          if y != x {
            dest.delim(',', false)?;
            y.to_css(dest)?;
          }
        }
        dest.write_char(')')
      }
      ScaleX(x) => {
        dest.write_str("scaleX(")?;
        x.to_css(dest)?;
        dest.write_char(')')
      }
      ScaleY(y) => {
        dest.write_str("scaleY(")?;
        y.to_css(dest)?;
        dest.write_char(')')
      }
      ScaleZ(z) => {
        dest.write_str("scaleZ(")?;
        z.to_css(dest)?;
        dest.write_char(')')
      }
      Scale3d(x, y, z) => {
        if dest.minify && z.unit_value() == 1.0 {
          if x.unit_value() != 1.0 && y.unit_value() == 1.0 {
            dest.write_str("scaleX(")?;
            x.to_css(dest)?;
          } else if x.unit_value() == 1.0 && y.unit_value() != 1.0 {
            dest.write_str("scaleY(")?;
            y.to_css(dest)?;
          } else {
            dest.write_str("scale(")?;
            x.to_css(dest)?;
            if y != x {
              dest.delim(',', false)?;
              y.to_css(dest)?;
            }
          }
        } else if dest.minify && x.unit_value() == 1.0 && y.unit_value() == 1.0 && z.unit_value() != 1.0 {
          dest.write_str("scaleZ(")?;
          z.to_css(dest)?;
        } else {
          dest.write_str("scale3d(")?;
          x.to_css(dest)?;
          dest.delim(',', false)?;
          y.to_css(dest)?;
          dest.delim(',', false)?;
          z.to_css(dest)?;
        }
        dest.write_char(')')
      }
      Rotate(angle) => {
        dest.write_str("rotate(")?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      RotateX(angle) => {
        dest.write_str("rotateX(")?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      RotateY(angle) => {
        dest.write_str("rotateY(")?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      RotateZ(angle) => {
        dest.write_str(if dest.minify { "rotate(" } else { "rotateZ(" })?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      Rotate3d(x, y, z, angle) => {
        if dest.minify && *x == 1.0 && *y == 0.0 && *z == 0.0 {
          dest.write_str("rotateX(")?;
          write_angle(angle, dest)?;
        } else if dest.minify && *x == 0.0 && *y == 1.0 && *z == 0.0 {
          dest.write_str("rotateY(")?;
          write_angle(angle, dest)?;
        } else if dest.minify && *x == 0.0 && *y == 0.0 && *z == 1.0 {
          dest.write_str("rotate(")?;
          write_angle(angle, dest)?;
        } else {
          dest.write_str("rotate3d(")?;
          serialize_number(*x, dest)?;
          dest.delim(',', false)?;
          serialize_number(*y, dest)?;
          dest.delim(',', false)?;
          serialize_number(*z, dest)?;
          dest.delim(',', false)?;
          write_angle(angle, dest)?;
        }
        dest.write_char(')')
      }
      Skew(x, y) => {
        if dest.minify && x.is_zero() && !y.is_zero() {
          dest.write_str("skewY(")?;
          write_angle(y, dest)?;
        } else {
          dest.write_str("skew(")?;
          write_angle(x, dest)?;
          if !y.is_zero() {
            dest.delim(',', false)?;
            write_angle(y, dest)?;
          }
        }
        dest.write_char(')')
      }
      SkewX(angle) => {
        dest.write_str(if dest.minify { "skew(" } else { "skewX(" })?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      SkewY(angle) => {
        dest.write_str("skewY(")?;
        write_angle(angle, dest)?;
        dest.write_char(')')
      }
      Perspective(len) => {
        dest.write_str("perspective(")?;
        len.to_css(dest)?;
        dest.write_char(')')
      }
      Matrix(m) => {
        dest.write_str("matrix(")?;
        for (i, v) in m.iter().enumerate() {
          if i > 0 {
            dest.delim(',', false)?;
          }
          serialize_number(*v, dest)?;
        }
        dest.write_char(')')
      }
      Matrix3d(m) => {
        dest.write_str("matrix3d(")?;
        for (i, v) in m.iter().enumerate() {
          if i > 0 {
            dest.delim(',', false)?;
          }
          serialize_number(*v, dest)?;
        }
        dest.write_char(')')
      }
    }
  }
}

