  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Translate {
  None,
  XYZ { x: LengthPercentage, y: LengthPercentage, z: Length },
}

impl<'i> Parse<'i> for Translate {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(Translate::None);
    }
    let x = LengthPercentage::parse(input)?;
    let y = input.try_parse(LengthPercentage::parse);
    let z = if y.is_ok() { input.try_parse(Length::parse).ok() } else { None };
    Ok(Translate::XYZ {
      x,
      y: y.unwrap_or(LengthPercentage::zero()),
      z: z.unwrap_or(Length::zero()),
    })
  }
}

impl ToCss for Translate {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Translate::None => dest.write_str("none"),
      Translate::XYZ { x, y, z } => {
        x.to_css(dest)?;
        if !y.is_zero() || !z.is_zero() {
          dest.write_char(' ')?;
          y.to_css(dest)?;
          if !z.is_zero() {
            dest.write_char(' ')?;
            z.to_css(dest)?;
          }
        }
        Ok(())
      }
    }
  }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Rotate {
  pub x: f32,
  pub y: f32,
  pub z: f32,
  pub angle: Angle,
}

impl<'i> Parse<'i> for Rotate {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(Rotate {
        x: 0.0,
        y: 0.0,
        z: 1.0,
        angle: Angle::Deg(0.0),
      });
    }

    let angle = input.try_parse(Angle::parse);
    let (x, y, z) = input
      .try_parse(|input| {
        let loc = input.current_source_location();
        let ident = input.try_parse(|input| input.expect_ident());
        if let Ok(ident) = ident {
          match ident.to_ascii_lowercase().as_str() {
            "x" => return Ok((1.0, 0.0, 0.0)),
            "y" => return Ok((0.0, 1.0, 0.0)),
            "z" => return Ok((0.0, 0.0, 1.0)),
            _ => return Err(loc.new_unexpected_token_error::<crate::error::ParserError>(crate::tokenizer::Token::Ident(ident))),
          }
        }
        let x = f32::parse(input)?;
        let y = f32::parse(input)?;
        let z = f32::parse(input)?;
        Ok((x, y, z))
      })
      .unwrap_or((0.0, 0.0, 1.0));
    let angle = match angle {
      Ok(a) => a,
      Err(_) => Angle::parse(input)?,
    };
    Ok(Rotate { x, y, z, angle })
  }
}

impl ToCss for Rotate {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.x == 0.0 && self.y == 0.0 && self.z == 1.0 {
      if self.angle.is_zero() {
        return dest.write_str("none");
      }
      return self.angle.to_css(dest);
    }
    if self.x == 1.0 && self.y == 0.0 && self.z == 0.0 {
      dest.write_str("x ")?;
    } else if self.x == 0.0 && self.y == 1.0 && self.z == 0.0 {
      dest.write_str("y ")?;
    } else {
      serialize_number(self.x, dest)?;
      dest.write_char(' ')?;
      serialize_number(self.y, dest)?;
      dest.write_char(' ')?;
      serialize_number(self.z, dest)?;
      dest.write_char(' ')?;
    }
    self.angle.to_css(dest)
  }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Scale {
  None,
  XYZ { x: NumberOrPercentage, y: NumberOrPercentage, z: NumberOrPercentage },
}

impl<'i> Parse<'i> for Scale {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("none")).is_ok() {
      return Ok(Scale::None);
    }
    let x = NumberOrPercentage::parse(input)?;
    let y = input.try_parse(NumberOrPercentage::parse);
    let z = if y.is_ok() { input.try_parse(NumberOrPercentage::parse).ok() } else { None };
    Ok(Scale::XYZ {
      y: y.unwrap_or(x.clone()),
      x,
      z: z.unwrap_or(NumberOrPercentage::Number(1.0)),
    })
  }
}

impl ToCss for Scale {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Scale::None => dest.write_str("none"),
      Scale::XYZ { x, y, z } => {
        x.to_css(dest)?;
        if y != x || z.unit_value() != 1.0 {
          dest.write_char(' ')?;
          y.to_css(dest)?;
          if z.unit_value() != 1.0 {
            dest.write_char(' ')?;
            z.to_css(dest)?;
          }
        }
        Ok(())
      }
    }
  }
}

