        | Ok(crate::tokenizer::Token::WhiteSpace(..))
        | Ok(crate::tokenizer::Token::Semicolon)
        | Ok(crate::tokenizer::Token::Comment(..)) => continue,
        Ok(crate::tokenizer::Token::AtKeyword(name)) => {
          // Invalid at rule in declaration list.
          let err: crate::parser::ParseError<ParserError> =
            input.new_error(crate::parser::BasicParseErrorKind::AtRuleInvalid(name.clone()));
          // Consume the at rule
          let _: Result<(), crate::parser::ParseError<ParserError>> =
            input.parse_until_after(Delimiter::Semicolon | Delimiter::CurlyBracketBlock, |_| Ok(()));
          if options.error_recovery {
            warnings.push(crate::error::Error::from_parse_error(err, filename.to_string()));
            continue;
          }
          return Err(err);
        }
        Ok(crate::tokenizer::Token::Ident(name)) => {
          let result = input.parse_until_after(Delimiter::Semicolon, |input| {
            input.expect_colon()?;
            parse_declaration(name, input, &mut block.declarations, &mut block.important_declarations, options)
          });
          if let Err(err) = result {
            if options.error_recovery {
              warnings.push(crate::error::Error::from_parse_error(err, filename.to_string()));
              continue;
            }
            return Err(err);
          }
        }
        Ok(token) => {
          let err: crate::parser::ParseError<ParserError> = start.source_location().new_unexpected_token_error(token.clone());
          let _: Result<(), crate::parser::ParseError<ParserError>> = input.parse_until_after(Delimiter::Semicolon, |_| Ok(()));
          if options.error_recovery {
            warnings.push(crate::error::Error::from_parse_error(err, filename.to_string()));
            continue;
          }
          return Err(err);
        }
      }
    }
    Ok(block)
  }

  pub fn to_css_block(&self, dest: &mut Printer) -> PrintResult {
    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();

    let mut i = 0;
    let len = self.len();

    macro_rules! write {
      ($decls: expr, $important: literal) => {
        for decl in &$decls {
          dest.newline()?;
          decl.to_css(dest, $important)?;
          if i != len - 1 || !dest.minify {
            dest.write_char(';')?;
          }
          i += 1;
        }
      };
    }

    write!(self.declarations, false);
    write!(self.important_declarations, true);

    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }

  /// Writes declarations without braces (used in style rules).
  pub fn to_css_declarations(&self, dest: &mut Printer, has_more: bool) -> PrintResult {
    let mut i = 0;
    let len = self.len();
    macro_rules! write {
      ($decls: expr, $important: literal) => {
        for decl in &$decls {
          dest.newline()?;
          decl.to_css(dest, $important)?;
          if i != len - 1 || !dest.minify || has_more {
            dest.write_char(';')?;
          }
          i += 1;
        }
      };
    }
    write!(self.declarations, false);
    write!(self.important_declarations, true);
    Ok(())
  }

  pub fn minify(
    &mut self,
    handler: &mut DeclarationHandler<'i>,
    important_handler: &mut DeclarationHandler<'i>,
    context: &mut PropertyHandlerContext,
  ) {
    macro_rules! handle {
      ($decls: expr, $handler: expr) => {
        for decl in $decls.iter() {
          let handled = $handler.handle_property(decl, context);
          if !handled {
            $handler.decls.push(decl.clone());
          }
        }
      };
    }

    handle!(self.important_declarations, important_handler);
    handle!(self.declarations, handler);

    handler.finalize(context);
    important_handler.finalize(context);
    self.important_declarations = std::mem::take(&mut important_handler.decls);
    self.declarations = std::mem::take(&mut handler.decls);
  }
}

pub fn parse_declaration<'i, 't>(
  name: Cow<'i, str>,
  input: &mut Parser<'i, 't>,
  declarations: &mut DeclarationList<'i>,
  important_declarations: &mut DeclarationList<'i>,
  options: &ParserOptions,
) -> ParseResult<'i, ()> {
  let property_id = PropertyId::parse(name);
  let property = input.parse_until_before(Delimiter::Bang, |input| Property::parse(property_id, input, options))?;
  let important = input
    .try_parse(|input| {
      input.expect_delim('!')?;
      input.expect_ident_matching("important")
    })
    .is_ok();
  input.expect_exhausted()?;
  if important {
    important_declarations.push(property)
  } else {
    declarations.push(property)
  }
  Ok(())
}
