// ---------------------------------------------------------------------------
// Rect-style side handlers (margin, padding, inset, scroll-margin, scroll-padding)

#[derive(PartialEq, Clone, Copy)]
enum Category {
  Physical,
  Logical,
}

macro_rules! side_handler {
  ($name: ident, $top: ident, $bottom: ident, $left: ident, $right: ident, $block_start: ident, $block_end: ident, $inline_start: ident, $inline_end: ident, $block: ident, $inline: ident, $shorthand: ident, $shorthand_flushes: expr) => {
    #[derive(Default)]
    pub struct $name<'i> {
      top: Option<LengthPercentageOrAuto>,
      bottom: Option<LengthPercentageOrAuto>,
      left: Option<LengthPercentageOrAuto>,
      right: Option<LengthPercentageOrAuto>,
      block_start: Option<LengthPercentageOrAuto>,
      block_end: Option<LengthPercentageOrAuto>,
      inline_start: Option<LengthPercentageOrAuto>,
      inline_end: Option<LengthPercentageOrAuto>,
      has_any: bool,
      category: Option<Category>,
      _p: std::marker::PhantomData<&'i ()>,
    }

    impl<'i> PropertyHandler<'i> for $name<'i> {
      fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
        use Property::*;

        macro_rules! prop {
          ($key: ident, $val: expr, $cat: expr) => {{
            if self.category.is_some() && self.category != Some($cat) {
              self.flush(dest, context);
            }
            self.$key = Some($val.clone());
            self.category = Some($cat);
            self.has_any = true;
          }};
        }

        match property {
          $top(val) => prop!(top, val, Category::Physical),
          $bottom(val) => prop!(bottom, val, Category::Physical),
          $left(val) => prop!(left, val, Category::Physical),
          $right(val) => prop!(right, val, Category::Physical),
          $block_start(val) => prop!(block_start, val, Category::Logical),
          $block_end(val) => prop!(block_end, val, Category::Logical),
          $inline_start(val) => prop!(inline_start, val, Category::Logical),
          $inline_end(val) => prop!(inline_end, val, Category::Logical),
          $block(val) => {
            prop!(block_start, val.0, Category::Logical);
            prop!(block_end, val.1, Category::Logical);
          }
          $inline(val) => {
            prop!(inline_start, val.0, Category::Logical);
            prop!(inline_end, val.1, Category::Logical);
          }
          $shorthand(val) => {
            if $shorthand_flushes {
              self.flush(dest, context);
            }
            prop!(top, val.0, Category::Physical);
            prop!(right, val.1, Category::Physical);
            prop!(bottom, val.2, Category::Physical);
            prop!(left, val.3, Category::Physical);
          }
          Unparsed(val) if matches!(
            val.property_id,
            PropertyId::$top | PropertyId::$bottom | PropertyId::$left | PropertyId::$right |
            PropertyId::$block_start | PropertyId::$block_end | PropertyId::$inline_start | PropertyId::$inline_end |
            PropertyId::$block | PropertyId::$inline | PropertyId::$shorthand
          ) => {
            self.flush(dest, context);
            dest.push(property.clone());
          }
          _ => return false,
        }
        true
      }

      fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
        self.flush(dest, context);
      }
    }

    impl<'i> $name<'i> {
      fn flush(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
        if !self.has_any {
          return;
        }
        self.has_any = false;
        self.category = None;

        let top = std::mem::take(&mut self.top);
        let bottom = std::mem::take(&mut self.bottom);
        let left = std::mem::take(&mut self.left);
        let right = std::mem::take(&mut self.right);
        let block_start = std::mem::take(&mut self.block_start);
        let block_end = std::mem::take(&mut self.block_end);
        let inline_start = std::mem::take(&mut self.inline_start);
        let inline_end = std::mem::take(&mut self.inline_end);

        if let (Some(top), Some(right), Some(bottom), Some(left)) = (&top, &right, &bottom, &left) {
          dest.push(Property::$shorthand(Rect::new(top.clone(), right.clone(), bottom.clone(), left.clone())));
        } else {
          if let Some(val) = top {
            dest.push(Property::$top(val));
          }
          if let Some(val) = bottom {
            dest.push(Property::$bottom(val));
          }
          if let Some(val) = left {
            dest.push(Property::$left(val));
          }
          if let Some(val) = right {
            dest.push(Property::$right(val));
          }
        }

        if let (Some(start), Some(end)) = (&block_start, &block_end) {
          dest.push(Property::$block(Size2D(start.clone(), end.clone())));
        } else {
          if let Some(val) = block_start {
            dest.push(Property::$block_start(val));
          }
          if let Some(val) = block_end {
            dest.push(Property::$block_end(val));
          }
        }

        if let (Some(start), Some(end)) = (&inline_start, &inline_end) {
          dest.push(Property::$inline(Size2D(start.clone(), end.clone())));
        } else {
          if let Some(val) = inline_start {
            dest.push(Property::$inline_start(val));
          }
          if let Some(val) = inline_end {
            dest.push(Property::$inline_end(val));
          }
        }
      }
    }
  };
}

