// ---------------------------------------------------------------------------
// Overflow handler

#[derive(Default)]
pub struct OverflowHandler {
  x: Option<OverflowKeyword>,
  y: Option<OverflowKeyword>,
  text_overflow: Option<(TextOverflow, VendorPrefix)>,
}

impl<'i> PropertyHandler<'i> for OverflowHandler {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    match property {
      Property::Overflow(o) => {
        self.x = Some(o.x);
        self.y = Some(o.y);
      }
      Property::OverflowX(x) => self.x = Some(*x),
      Property::OverflowY(y) => self.y = Some(*y),
      Property::TextOverflow(t, vp) => {
        if let Some((existing, prefix)) = &mut self.text_overflow {
          if existing == t {
            *prefix |= *vp;
          } else {
            *existing = t.clone();
            *prefix = *vp;
          }
        } else {
          self.text_overflow = Some((t.clone(), *vp));
        }
      }
      Property::Unparsed(u) if matches!(u.property_id, PropertyId::Overflow | PropertyId::OverflowX | PropertyId::OverflowY | PropertyId::TextOverflow(_)) => {
        self.finalize(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    let x = std::mem::take(&mut self.x);
    let y = std::mem::take(&mut self.y);
    match (x, y) {
      (Some(x), Some(y)) => {
        if x == y || !context.targets.should_compile(crate::compat::Feature::OverflowShorthand) {
          dest.push(Property::Overflow(Overflow { x, y }));
        } else {
          dest.push(Property::OverflowX(x));
          dest.push(Property::OverflowY(y));
        }
      }
      (Some(x), None) => dest.push(Property::OverflowX(x)),
      (None, Some(y)) => dest.push(Property::OverflowY(y)),
      _ => {}
    }
    if let Some((t, vp)) = std::mem::take(&mut self.text_overflow) {
      let vp = context.targets.prefixes(vp, crate::prefixes::Feature::Resize);
      let _ = vp;
      dest.push(Property::TextOverflow(t, self_prefix_or(vp_fix(vp))));
    }
  }
}

fn vp_fix(vp: VendorPrefix) -> VendorPrefix {
  vp
}
fn self_prefix_or(vp: VendorPrefix) -> VendorPrefix {
  if vp.is_empty() {
    VendorPrefix::None
  } else {
    vp
  }
}

// ---------------------------------------------------------------------------
// Prefix handler: properties that are deduped in place, merging prefixes.

pub struct PrefixHandler {
  /// Indices into dest for each property (keyed by unprefixed property name).
  indices: Vec<(String, usize)>,
}

impl Default for PrefixHandler {
  fn default() -> Self {
    PrefixHandler { indices: Vec::new() }
  }
}

fn is_prefix_handler_property(id: &PropertyId) -> bool {
  matches!(
    id,
    PropertyId::BoxSizing(_)
      | PropertyId::ClipPath(_)
      | PropertyId::Filter(_)
      | PropertyId::BackdropFilter(_)
      | PropertyId::UserSelect(_)
      | PropertyId::Appearance(_)
      | PropertyId::Hyphens(_)
      | PropertyId::TabSize(_)
      | PropertyId::TextSizeAdjust(_)
      | PropertyId::BackfaceVisibility(_)
      | PropertyId::Perspective(_)
      | PropertyId::PerspectiveOrigin(_)
      | PropertyId::BoxDecorationBreak(_)
      | PropertyId::TextAlignLast(_)
      | PropertyId::TextDecorationSkipInk(_)
      | PropertyId::TextEmphasisPosition(_)
      | PropertyId::TransformStyle(_)
      | PropertyId::Translate
      | PropertyId::Rotate
      | PropertyId::Scale
      | PropertyId::MaskType
      | PropertyId::MaskBorderSource
      | PropertyId::MaskBorderMode
      | PropertyId::MaskBorderSlice
      | PropertyId::MaskBorderWidth
      | PropertyId::MaskBorderOutset
      | PropertyId::MaskBorderRepeat
      | PropertyId::MaskBorder
      | PropertyId::WebKitMaskComposite
      | PropertyId::WebKitMaskSourceType(_)
      | PropertyId::WebKitMaskBoxImage(_)
      | PropertyId::WebKitMaskBoxImageSource(_)
      | PropertyId::WebKitMaskBoxImageSlice(_)
      | PropertyId::WebKitMaskBoxImageWidth(_)
      | PropertyId::WebKitMaskBoxImageOutset(_)
      | PropertyId::WebKitMaskBoxImageRepeat(_)
  )
}

impl<'i> PropertyHandler<'i> for PrefixHandler {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    let id = property.property_id();
    if !is_prefix_handler_property(&id) {
      return false;
    }
    if let Property::Unparsed(_) = property {
      return false;
    }
    let name = id.name().to_string();
    let vp = id.prefix();
    if let Some((_, index)) = self.indices.iter().find(|(n, _)| *n == name) {
      let index = *index;
      if index < dest.len() {
        let existing = &dest[index];
        let ep = existing.property_id().prefix();
        if existing.property_id().name() == name {
          if values_equal(existing, property) {
            dest[index] = with_prefix(property, ep | vp);
            return true;
          } else if ep.contains(vp) || ep == vp {
            dest[index] = property.clone();
            return true;
          }
        }
      }
    }
    let _ = context;
    self.indices.retain(|(n, _)| *n != name);
    self.indices.push((name, dest.len()));
    dest.push(property.clone());
    true
  }

  fn finalize(&mut self, _dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    self.indices.clear();
  }
}

// ---------------------------------------------------------------------------
// Fallback handler: color-ish properties deduped in place.

pub struct FallbackHandler {
  indices: Vec<(PropertyId<'static>, usize)>,
}

impl Default for FallbackHandler {
  fn default() -> Self {
    FallbackHandler { indices: Vec::new() }
  }
}

fn is_fallback_property(id: &PropertyId) -> bool {
  matches!(
    id,
    PropertyId::Color
      | PropertyId::Fill
      | PropertyId::Stroke
      | PropertyId::CaretColor
      | PropertyId::Caret
      | PropertyId::TextShadow
      | PropertyId::BorderImageSource
      | PropertyId::ListStyleImage
  )
}

impl<'i> PropertyHandler<'i> for FallbackHandler {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) -> bool {
    let id = property.property_id();
    if !is_fallback_property(&id) {
      return false;
    }
    let id_static: PropertyId<'static> = unsafe { std::mem::transmute(id.clone()) };
    if let Some((_, index)) = self.indices.iter().find(|(n, _)| *n == id_static) {
      let index = *index;
      if index < dest.len() && dest[index].property_id() == id {
        dest[index] = property.clone();
        return true;
      }
    }
    self.indices.retain(|(n, _)| *n != id_static);
    self.indices.push((id_static, dest.len()));
    dest.push(property.clone());
    true
  }

  fn finalize(&mut self, _dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    self.indices.clear();
  }
}

// ---------------------------------------------------------------------------
// Background handler

#[derive(Default)]
pub struct BackgroundHandler<'i> {
  color: Option<CssColor>,
  images: Option<SmallVecLike<Image<'i>>>,
  x_positions: Option<SmallVecLike<crate::values::position::HorizontalPosition>>,
  y_positions: Option<SmallVecLike<crate::values::position::VerticalPosition>>,
  repeats: Option<SmallVecLike<BackgroundRepeat>>,
  sizes: Option<SmallVecLike<BackgroundSize>>,
  attachments: Option<SmallVecLike<BackgroundAttachment>>,
  origins: Option<SmallVecLike<BackgroundOrigin>>,
  clips: Option<(SmallVecLike<BackgroundClip>, VendorPrefix)>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for BackgroundHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    match property {
      Property::BackgroundColor(val) => {
        self.color = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundImage(val) => {
        self.images = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundPosition(val) => {
        self.x_positions = Some(SmallVecLike(val.0.iter().map(|p| p.x.clone()).collect()));
        self.y_positions = Some(SmallVecLike(val.0.iter().map(|p| p.y.clone()).collect()));
        self.has_any = true;
      }
      Property::BackgroundPositionX(val) => {
        self.x_positions = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundPositionY(val) => {
        self.y_positions = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundRepeat(val) => {
        self.repeats = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundSize(val) => {
        self.sizes = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundAttachment(val) => {
        self.attachments = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundOrigin(val) => {
        self.origins = Some(val.clone());
        self.has_any = true;
      }
      Property::BackgroundClip(val, vp) => {
        if let Some((existing, prefix)) = &mut self.clips {
          if existing == val {
            *prefix |= *vp;
          } else {
            self.flush(dest, context);
            self.clips = Some((val.clone(), *vp));
          }
        } else {
          self.clips = Some((val.clone(), *vp));
        }
        self.has_any = true;
      }
      Property::Background(val) => {
        self.color = Some(val.0.last().map(|b| b.color.clone()).unwrap_or(CssColor::transparent()));
        self.images = Some(SmallVecLike(val.0.iter().map(|b| b.image.clone()).collect()));
        self.x_positions = Some(SmallVecLike(val.0.iter().map(|b| b.position.x.clone()).collect()));
        self.y_positions = Some(SmallVecLike(val.0.iter().map(|b| b.position.y.clone()).collect()));
        self.repeats = Some(SmallVecLike(val.0.iter().map(|b| b.repeat.clone()).collect()));
        self.sizes = Some(SmallVecLike(val.0.iter().map(|b| b.size.clone()).collect()));
        self.attachments = Some(SmallVecLike(val.0.iter().map(|b| b.attachment.clone()).collect()));
        self.origins = Some(SmallVecLike(val.0.iter().map(|b| b.origin.clone()).collect()));
        self.clips = Some((SmallVecLike(val.0.iter().map(|b| b.clip.clone()).collect()), VendorPrefix::None));
        self.has_any = true;
      }
      Property::Unparsed(val) if is_background_property(&val.property_id) => {
        self.flush(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    self.flush(dest, context);
  }
}

fn is_background_property(id: &PropertyId) -> bool {
  matches!(
    id,
    PropertyId::BackgroundColor
      | PropertyId::BackgroundImage
      | PropertyId::BackgroundPosition
      | PropertyId::BackgroundPositionX
      | PropertyId::BackgroundPositionY
      | PropertyId::BackgroundRepeat
      | PropertyId::BackgroundSize
      | PropertyId::BackgroundAttachment
      | PropertyId::BackgroundOrigin
      | PropertyId::BackgroundClip(_)
      | PropertyId::Background
  )
}

impl<'i> BackgroundHandler<'i> {
  fn flush(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;

    let color = std::mem::take(&mut self.color);
    let mut images = std::mem::take(&mut self.images);
    let mut x_positions = std::mem::take(&mut self.x_positions);
    let mut y_positions = std::mem::take(&mut self.y_positions);
    let mut repeats = std::mem::take(&mut self.repeats);
    let mut sizes = std::mem::take(&mut self.sizes);
    let mut attachments = std::mem::take(&mut self.attachments);
    let mut origins = std::mem::take(&mut self.origins);
    let mut clips = std::mem::take(&mut self.clips);

    if let (
      Some(color),
      Some(images_),
      Some(x_positions_),
      Some(y_positions_),
      Some(repeats_),
      Some(sizes_),
      Some(attachments_),
      Some(origins_),
      Some((clips_, clip_prefix)),
    ) = (&color, &images, &x_positions, &y_positions, &repeats, &sizes, &attachments, &origins, &clips)
    {
      let len = images_.0.len();
      if x_positions_.0.len() == len
        && y_positions_.0.len() == len
        && repeats_.0.len() == len
        && sizes_.0.len() == len
        && attachments_.0.len() == len
        && origins_.0.len() == len
        && clips_.0.len() == len
        && (*clip_prefix == VendorPrefix::None || clip_prefix.contains(VendorPrefix::None))
      {
        let backgrounds: Vec<Background<'i>> = (0..len)
          .map(|i| Background {
            color: if i == len - 1 { color.clone() } else { CssColor::transparent() },
            image: images_.0[i].clone(),
            position: Position {
              x: x_positions_.0[i].clone(),
              y: y_positions_.0[i].clone(),
            },
            repeat: repeats_.0[i].clone(),
            size: sizes_.0[i].clone(),
            attachment: attachments_.0[i].clone(),
            origin: origins_.0[i].clone(),
            clip: clips_.0[i].clone(),
          })
          .collect();
        dest.push(Property::Background(SmallVecLike(backgrounds)));
        // If the clip prefix includes webkit in addition to none, output the prefixed version separately.
        if *clip_prefix != VendorPrefix::None {
          let mut p = *clip_prefix;
          p.remove(VendorPrefix::None);
          dest.push(Property::BackgroundClip(clips_.clone(), p));
        }
        images = None;
        x_positions = None;
        y_positions = None;
        repeats = None;
        sizes = None;
        attachments = None;
        origins = None;
        clips = None;
        return;
      }
    }

    if let Some(color) = color {
      dest.push(Property::BackgroundColor(color));
    }
    if let Some(images) = images {
      dest.push(Property::BackgroundImage(images));
    }
    match (x_positions, y_positions) {
      (Some(x), Some(y)) if x.0.len() == y.0.len() => {
        dest.push(Property::BackgroundPosition(SmallVecLike(
          x.0.into_iter().zip(y.0.into_iter()).map(|(x, y)| Position { x, y }).collect(),
        )));
      }
      (x, y) => {
        if let Some(x) = x {
          dest.push(Property::BackgroundPositionX(x));
        }
        if let Some(y) = y {
          dest.push(Property::BackgroundPositionY(y));
        }
      }
    }
    if let Some(repeats) = repeats {
      dest.push(Property::BackgroundRepeat(repeats));
    }
    if let Some(sizes) = sizes {
      dest.push(Property::BackgroundSize(sizes));
    }
    if let Some(attachments) = attachments {
      dest.push(Property::BackgroundAttachment(attachments));
    }
    if let Some(origins) = origins {
      dest.push(Property::BackgroundOrigin(origins));
    }
    if let Some((clips, prefix)) = clips {
      dest.push(Property::BackgroundClip(clips, prefix));
    }
  }
}

// ---------------------------------------------------------------------------
// Border handler

#[derive(Default, Clone)]
struct BorderSide {
  width: Option<BorderSideWidth>,
  style: Option<LineStyle>,
  color: Option<CssColor>,
}

impl BorderSide {
  fn is_complete(&self) -> bool {
    self.width.is_some() && self.style.is_some() && self.color.is_some()
  }
  fn to_border(&self) -> Border {
    Border {
      width: self.width.clone().unwrap(),
      style: self.style.clone().unwrap(),
      color: self.color.clone().unwrap(),
    }
  }
  fn set(&mut self, b: &Border) {
    self.width = Some(b.width.clone());
    self.style = Some(b.style.clone());
    self.color = Some(b.color.clone());
  }
  fn is_empty(&self) -> bool {
    self.width.is_none() && self.style.is_none() && self.color.is_none()
  }
}

#[derive(Default)]
pub struct BorderHandler<'i> {
  top: BorderSide,
  bottom: BorderSide,
  left: BorderSide,
  right: BorderSide,
  block_start: BorderSide,
  block_end: BorderSide,
  inline_start: BorderSide,
  inline_end: BorderSide,
  category: Option<Category>,
  has_any: bool,
  // Border radius & image: simple last-wins
  radius: Option<(BorderRadius, VendorPrefix)>,
  radius_corners: Vec<Property<'i>>,
  image: Vec<Property<'i>>,
  spacing: Option<Property<'i>>,
}

fn is_border_property(id: &PropertyId) -> bool {
  let name = id.name();
  name.starts_with("border") && !name.starts_with("border-image") && !name.contains("radius") && name != "border-spacing"
}

fn is_border_image_property(id: &PropertyId) -> bool {
  id.name().starts_with("border-image")
}

fn is_border_radius_property(id: &PropertyId) -> bool {
  let n = id.name();
  n.starts_with("border") && n.ends_with("radius")
}

impl<'i> PropertyHandler<'i> for BorderHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    use Property::*;

    macro_rules! set {
      ($side: ident, $field: ident, $val: expr, $cat: expr) => {{
        if self.category.is_some() && self.category != Some($cat) {
          self.flush_borders(dest, context);
        }
        self.$side.$field = Some($val.clone());
        self.category = Some($cat);
        self.has_any = true;
      }};
    }
    macro_rules! set_side {
      ($side: ident, $val: expr, $cat: expr) => {{
        if self.category.is_some() && self.category != Some($cat) {
          self.flush_borders(dest, context);
        }
        self.$side.set($val);
        self.category = Some($cat);
        self.has_any = true;
      }};
    }

    match property {
      BorderTopColor(v) => set!(top, color, v, Category::Physical),
      BorderBottomColor(v) => set!(bottom, color, v, Category::Physical),
      BorderLeftColor(v) => set!(left, color, v, Category::Physical),
      BorderRightColor(v) => set!(right, color, v, Category::Physical),
      BorderBlockStartColor(v) => set!(block_start, color, v, Category::Logical),
      BorderBlockEndColor(v) => set!(block_end, color, v, Category::Logical),
      BorderInlineStartColor(v) => set!(inline_start, color, v, Category::Logical),
      BorderInlineEndColor(v) => set!(inline_end, color, v, Category::Logical),
      BorderTopStyle(v) => set!(top, style, v, Category::Physical),
      BorderBottomStyle(v) => set!(bottom, style, v, Category::Physical),
      BorderLeftStyle(v) => set!(left, style, v, Category::Physical),
      BorderRightStyle(v) => set!(right, style, v, Category::Physical),
      BorderBlockStartStyle(v) => set!(block_start, style, v, Category::Logical),
      BorderBlockEndStyle(v) => set!(block_end, style, v, Category::Logical),
      BorderInlineStartStyle(v) => set!(inline_start, style, v, Category::Logical),
      BorderInlineEndStyle(v) => set!(inline_end, style, v, Category::Logical),
      BorderTopWidth(v) => set!(top, width, v, Category::Physical),
      BorderBottomWidth(v) => set!(bottom, width, v, Category::Physical),
      BorderLeftWidth(v) => set!(left, width, v, Category::Physical),
      BorderRightWidth(v) => set!(right, width, v, Category::Physical),
      BorderBlockStartWidth(v) => set!(block_start, width, v, Category::Logical),
      BorderBlockEndWidth(v) => set!(block_end, width, v, Category::Logical),
      BorderInlineStartWidth(v) => set!(inline_start, width, v, Category::Logical),
      BorderInlineEndWidth(v) => set!(inline_end, width, v, Category::Logical),
      BorderColor(v) => {
        set!(top, color, v.0, Category::Physical);
        set!(right, color, v.1, Category::Physical);
        set!(bottom, color, v.2, Category::Physical);
        set!(left, color, v.3, Category::Physical);
      }
      BorderStyle(v) => {
        set!(top, style, v.0, Category::Physical);
        set!(right, style, v.1, Category::Physical);
        set!(bottom, style, v.2, Category::Physical);
        set!(left, style, v.3, Category::Physical);
      }
      BorderWidth(v) => {
        set!(top, width, v.0, Category::Physical);
        set!(right, width, v.1, Category::Physical);
        set!(bottom, width, v.2, Category::Physical);
        set!(left, width, v.3, Category::Physical);
      }
      BorderBlockColor(v) => {
        set!(block_start, color, v.0, Category::Logical);
        set!(block_end, color, v.1, Category::Logical);
      }
      BorderBlockStyle(v) => {
        set!(block_start, style, v.0, Category::Logical);
        set!(block_end, style, v.1, Category::Logical);
      }
      BorderBlockWidth(v) => {
        set!(block_start, width, v.0, Category::Logical);
        set!(block_end, width, v.1, Category::Logical);
      }
      BorderInlineColor(v) => {
        set!(inline_start, color, v.0, Category::Logical);
        set!(inline_end, color, v.1, Category::Logical);
      }
      BorderInlineStyle(v) => {
        set!(inline_start, style, v.0, Category::Logical);
        set!(inline_end, style, v.1, Category::Logical);
      }
      BorderInlineWidth(v) => {
        set!(inline_start, width, v.0, Category::Logical);
        set!(inline_end, width, v.1, Category::Logical);
      }
      Border(v) => {
        set_side!(top, v, Category::Physical);
        set_side!(bottom, v, Category::Physical);
        set_side!(left, v, Category::Physical);
        set_side!(right, v, Category::Physical);
      }
      BorderTop(v) => set_side!(top, v, Category::Physical),
      BorderBottom(v) => set_side!(bottom, v, Category::Physical),
      BorderLeft(v) => set_side!(left, v, Category::Physical),
      BorderRight(v) => set_side!(right, v, Category::Physical),
      BorderBlockStart(v) => set_side!(block_start, v, Category::Logical),
      BorderBlockEnd(v) => set_side!(block_end, v, Category::Logical),
      BorderInlineStart(v) => set_side!(inline_start, v, Category::Logical),
      BorderInlineEnd(v) => set_side!(inline_end, v, Category::Logical),
      BorderBlock(v) => {
        set_side!(block_start, v, Category::Logical);
        set_side!(block_end, v, Category::Logical);
      }
      BorderInline(v) => {
        set_side!(inline_start, v, Category::Logical);
        set_side!(inline_end, v, Category::Logical);
      }
      BorderRadius(v, vp) => {
        self.radius = Some((v.clone(), *vp));
        self.radius_corners.clear();
      }
      BorderTopLeftRadius(..) | BorderTopRightRadius(..) | BorderBottomLeftRadius(..) | BorderBottomRightRadius(..)
      | BorderStartStartRadius(..) | BorderStartEndRadius(..) | BorderEndStartRadius(..) | BorderEndEndRadius(..) => {
        let id = property.property_id();
        if let Some(existing) = self.radius_corners.iter_mut().find(|p| p.property_id().with_prefix(VendorPrefix::None) == id.with_prefix(VendorPrefix::None)) {
          *existing = merge_prefixed(existing, property);
        } else {
          self.radius_corners.push(property.clone());
        }
      }
      BorderImage(..) | BorderImageSource(..) | BorderImageSlice(..) | BorderImageWidth(..) | BorderImageOutset(..) | BorderImageRepeat(..) => {
        let id = property.property_id();
        if let BorderImage(..) = property {
          self.image.clear();
        }
        if let Some(existing) = self.image.iter_mut().find(|p| p.property_id().with_prefix(VendorPrefix::None) == id.with_prefix(VendorPrefix::None)) {
          *existing = merge_prefixed(existing, property);
        } else {
          self.image.push(property.clone());
        }
      }
      BorderSpacing(_) => {
        self.spacing = Some(property.clone());
      }
      Unparsed(val) if is_border_property(&val.property_id) => {
        self.flush_borders(dest, context);
        dest.push(property.clone());
      }
      Unparsed(val) if is_border_image_property(&val.property_id) => {
        self.flush_image(dest);
        dest.push(property.clone());
      }
      Unparsed(val) if is_border_radius_property(&val.property_id) => {
        self.flush_radius(dest);
        dest.push(property.clone());
      }
      Unparsed(val) if val.property_id == PropertyId::BorderSpacing => {
        if let Some(s) = self.spacing.take() {
          dest.push(s);
        }
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    if let Some(s) = self.spacing.take() {
      dest.push(s);
    }
    self.flush_borders(dest, context);
    self.flush_image(dest);
    self.flush_radius(dest);
  }
}

impl<'i> BorderHandler<'i> {
  fn flush_image(&mut self, dest: &mut DeclarationList<'i>) {
    for p in std::mem::take(&mut self.image) {
      dest.push(p);
    }
  }

  fn flush_radius(&mut self, dest: &mut DeclarationList<'i>) {
    if let Some((mut radius, vp)) = self.radius.take() {
      // Apply corner overrides
      for p in std::mem::take(&mut self.radius_corners) {
        match p {
          Property::BorderTopLeftRadius(v, _) => radius.top_left = v,
          Property::BorderTopRightRadius(v, _) => radius.top_right = v,
          Property::BorderBottomLeftRadius(v, _) => radius.bottom_left = v,
          Property::BorderBottomRightRadius(v, _) => radius.bottom_right = v,
          other => dest.push(other),
        }
      }
      dest.push(Property::BorderRadius(radius, vp));
    } else {
      let corners = std::mem::take(&mut self.radius_corners);
      let find = |id: fn(&Property<'i>) -> bool| corners.iter().find(|p| id(p));
      let tl = find(|p| matches!(p, Property::BorderTopLeftRadius(..)));
      let tr = find(|p| matches!(p, Property::BorderTopRightRadius(..)));
      let bl = find(|p| matches!(p, Property::BorderBottomLeftRadius(..)));
      let br = find(|p| matches!(p, Property::BorderBottomRightRadius(..)));
      if let (
        Some(Property::BorderTopLeftRadius(tl, p1)),
        Some(Property::BorderTopRightRadius(tr, p2)),
        Some(Property::BorderBottomLeftRadius(bl, p3)),
        Some(Property::BorderBottomRightRadius(br, p4)),
      ) = (tl, tr, bl, br)
      {
        if p1 == p2 && p2 == p3 && p3 == p4 {
          dest.push(Property::BorderRadius(
            BorderRadius {
              top_left: tl.clone(),
              top_right: tr.clone(),
              bottom_right: br.clone(),
              bottom_left: bl.clone(),
            },
            *p1,
          ));
          for p in corners {
            if !matches!(
              p,
              Property::BorderTopLeftRadius(..) | Property::BorderTopRightRadius(..) | Property::BorderBottomLeftRadius(..) | Property::BorderBottomRightRadius(..)
            ) {
              dest.push(p);
            }
          }
          return;
        }
      }
      // Output in canonical order
      let order = |p: &Property<'i>| match p {
        Property::BorderTopLeftRadius(..) => 0,
        Property::BorderTopRightRadius(..) => 1,
        Property::BorderBottomRightRadius(..) => 2,
        Property::BorderBottomLeftRadius(..) => 3,
        Property::BorderStartStartRadius(..) => 4,
        Property::BorderStartEndRadius(..) => 5,
        Property::BorderEndStartRadius(..) => 6,
        Property::BorderEndEndRadius(..) => 7,
        _ => 8,
      };
      let mut corners = corners;
      corners.sort_by_key(|p| order(p));
      for p in corners {
        dest.push(p);
      }
    }
  }

  fn flush_borders(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    self.category = None;

    let top = std::mem::take(&mut self.top);
    let bottom = std::mem::take(&mut self.bottom);
    let left = std::mem::take(&mut self.left);
    let right = std::mem::take(&mut self.right);
    let block_start = std::mem::take(&mut self.block_start);
    let block_end = std::mem::take(&mut self.block_end);
    let inline_start = std::mem::take(&mut self.inline_start);
    let inline_end = std::mem::take(&mut self.inline_end);

    flush_physical(dest, [top, bottom, left, right]);
    flush_logical(dest, block_start, block_end, true);
    flush_logical(dest, inline_start, inline_end, false);
  }
}

fn flush_logical<'i>(dest: &mut DeclarationList<'i>, start: BorderSide, end: BorderSide, is_block: bool) {
  use Property::*;
  if start.is_empty() && end.is_empty() {
    return;
  }
  if start.is_complete() && end.is_complete() && start.to_border() == end.to_border() {
    dest.push(if is_block { BorderBlock(start.to_border()) } else { BorderInline(start.to_border()) });
    return;
  }
  // group shorthands
  let mut start = start;
  let mut end = end;
  if let (Some(a), Some(b)) = (&start.style, &end.style) {
    dest.push(if is_block { BorderBlockStyle(Size2D(a.clone(), b.clone())) } else { BorderInlineStyle(Size2D(a.clone(), b.clone())) });
    start.style = None;
    end.style = None;
  }
  if let (Some(a), Some(b)) = (&start.width, &end.width) {
    dest.push(if is_block { BorderBlockWidth(Size2D(a.clone(), b.clone())) } else { BorderInlineWidth(Size2D(a.clone(), b.clone())) });
    start.width = None;
    end.width = None;
  }
  if let (Some(a), Some(b)) = (&start.color, &end.color) {
    dest.push(if is_block { BorderBlockColor(Size2D(a.clone(), b.clone())) } else { BorderInlineColor(Size2D(a.clone(), b.clone())) });
    start.color = None;
    end.color = None;
  }
  for (side, is_start) in [(start, true), (end, false)] {
    if side.is_complete() {
      dest.push(match (is_block, is_start) {
        (true, true) => BorderBlockStart(side.to_border()),
        (true, false) => BorderBlockEnd(side.to_border()),
        (false, true) => BorderInlineStart(side.to_border()),
        (false, false) => BorderInlineEnd(side.to_border()),
      });
      continue;
    }
    if let Some(s) = side.style {
      dest.push(match (is_block, is_start) {
        (true, true) => BorderBlockStartStyle(s),
        (true, false) => BorderBlockEndStyle(s),
        (false, true) => BorderInlineStartStyle(s),
        (false, false) => BorderInlineEndStyle(s),
      });
    }
    if let Some(w) = side.width {
      dest.push(match (is_block, is_start) {
        (true, true) => BorderBlockStartWidth(w),
        (true, false) => BorderBlockEndWidth(w),
        (false, true) => BorderInlineStartWidth(w),
        (false, false) => BorderInlineEndWidth(w),
      });
    }
    if let Some(c) = side.color {
      dest.push(match (is_block, is_start) {
        (true, true) => BorderBlockStartColor(c),
        (true, false) => BorderBlockEndColor(c),
        (false, true) => BorderInlineStartColor(c),
        (false, false) => BorderInlineEndColor(c),
      });
    }
  }
}

/// sides: [top, bottom, left, right]
fn flush_physical<'i>(dest: &mut DeclarationList<'i>, sides: [BorderSide; 4]) {
  use Property::*;
  if sides.iter().all(|s| s.is_empty()) {
    return;
  }
  let [top, bottom, left, right] = sides;

  if top.is_complete() && bottom.is_complete() && left.is_complete() && right.is_complete() {
    let borders = [top.to_border(), bottom.to_border(), left.to_border(), right.to_border()];
    if borders.iter().all(|b| *b == borders[0]) {
      dest.push(Border(borders[0].clone()));
      return;
    }

    // Find the most common value.
    let mut best: Option<(usize, usize)> = None; // (index, count)
    for i in 0..4 {
      let count = borders.iter().filter(|b| **b == borders[i]).count();
      if best.map_or(true, |(_, c)| count > c) {
        best = Some((i, count));
      }
    }
    let (best_idx, best_count) = best.unwrap();
    let side_props: [fn(Border) -> Property<'i>; 4] = [BorderTop, BorderBottom, BorderLeft, BorderRight];
    if best_count < 2 {
      for i in 0..4 {
        dest.push(side_props[i](borders[i].clone()));
      }
      return;
    }

    let common = borders[best_idx].clone();
    dest.push(Border(common.clone()));

    // Determine diffs
    let mut full_sides = Vec::new();
    let mut width_diff = Vec::new();
    let mut style_diff = Vec::new();
    let mut color_diff = Vec::new();
    for i in 0..4 {
      let b = &borders[i];
      let mut diffs = 0;
      if b.width != common.width {
        diffs += 1;
      }
      if b.style != common.style {
        diffs += 1;
      }
      if b.color != common.color {
        diffs += 1;
      }
      if diffs >= 2 {
        full_sides.push(i);
      } else if diffs == 1 {
        if b.width != common.width {
          width_diff.push(i);
        } else if b.style != common.style {
          style_diff.push(i);
        } else {
          color_diff.push(i);
        }
      }
    }

    // Physical order for rects: top, right, bottom, left -> indices in our array: top=0, right=3, bottom=1, left=2
    let rect_of = |f: &dyn Fn(&Border) -> Property<'i>| {
      let _ = f;
    };
    let _ = rect_of;

    let mut emitted: Vec<(usize, Property<'i>)> = Vec::new(); // (sort key, property)
    for &i in &full_sides {
      emitted.push((i, side_props[i](borders[i].clone())));
    }
    macro_rules! group {
      ($diff: ident, $field: ident, $rect: ident, $top: ident, $bottom: ident, $left: ident, $right: ident) => {
        if $diff.len() >= 2 {
          emitted.push((
            $diff[0],
            $rect(Rect::new(
              borders[0].$field.clone(),
              borders[3].$field.clone(),
              borders[1].$field.clone(),
              borders[2].$field.clone(),
            )),
          ));
        } else if $diff.len() == 1 {
          let i = $diff[0];
          let v = borders[i].$field.clone();
          emitted.push((
            i,
            match i {
              0 => $top(v),
              1 => $bottom(v),
              2 => $left(v),
              _ => $right(v),
            },
          ));
        }
      };
    }
    group!(width_diff, width, BorderWidth, BorderTopWidth, BorderBottomWidth, BorderLeftWidth, BorderRightWidth);
    group!(style_diff, style, BorderStyle, BorderTopStyle, BorderBottomStyle, BorderLeftStyle, BorderRightStyle);
    group!(color_diff, color, BorderColor, BorderTopColor, BorderBottomColor, BorderLeftColor, BorderRightColor);
    emitted.sort_by_key(|(k, _)| *k);
    for (_, p) in emitted {
      dest.push(p);
    }
    return;
  }

  // Not all complete: group shorthands first (style, width, color), then per side.
  let mut sides = [top, bottom, left, right];
  if sides.iter().all(|s| s.style.is_some()) {
    dest.push(BorderStyle(Rect::new(
      sides[0].style.take().unwrap(),
      sides[3].style.take().unwrap(),
      sides[1].style.take().unwrap(),
      sides[2].style.take().unwrap(),
    )));
  }
  if sides.iter().all(|s| s.width.is_some()) {
    dest.push(BorderWidth(Rect::new(
      sides[0].width.take().unwrap(),
      sides[3].width.take().unwrap(),
      sides[1].width.take().unwrap(),
      sides[2].width.take().unwrap(),
    )));
  }
  if sides.iter().all(|s| s.color.is_some()) {
    dest.push(BorderColor(Rect::new(
      sides[0].color.take().unwrap(),
      sides[3].color.take().unwrap(),
      sides[1].color.take().unwrap(),
      sides[2].color.take().unwrap(),
    )));
  }
  let side_props: [fn(Border) -> Property<'i>; 4] = [BorderTop, BorderBottom, BorderLeft, BorderRight];
  let style_props: [fn(LineStyle) -> Property<'i>; 4] = [BorderTopStyle, BorderBottomStyle, BorderLeftStyle, BorderRightStyle];
  let width_props: [fn(BorderSideWidth) -> Property<'i>; 4] = [BorderTopWidth, BorderBottomWidth, BorderLeftWidth, BorderRightWidth];
  let color_props: [fn(CssColor) -> Property<'i>; 4] = [BorderTopColor, BorderBottomColor, BorderLeftColor, BorderRightColor];
  for i in 0..4 {
    let side = &sides[i];
    if side.is_complete() {
      dest.push(side_props[i](side.to_border()));
      continue;
    }
    if let Some(s) = &side.style {
      dest.push(style_props[i](s.clone()));
    }
    if let Some(w) = &side.width {
      dest.push(width_props[i](w.clone()));
    }
    if let Some(c) = &side.color {
      dest.push(color_props[i](c.clone()));
    }
  }
}

