#[derive(Default)]
pub struct OutlineHandler {
  width: Option<BorderSideWidth>,
  style: Option<OutlineStyle>,
  color: Option<CssColor>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for OutlineHandler {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    match property {
      Property::OutlineWidth(v) => {
        self.width = Some(v.clone());
        self.has_any = true;
      }
      Property::OutlineStyle(v) => {
        self.style = Some(v.clone());
        self.has_any = true;
      }
      Property::OutlineColor(v) => {
        self.color = Some(v.clone());
        self.has_any = true;
      }
      Property::Outline(v) => {
        self.width = Some(v.width.clone());
        self.style = Some(v.style.clone());
        self.color = Some(v.color.clone());
        self.has_any = true;
      }
      Property::Unparsed(u) if matches!(u.property_id, PropertyId::Outline | PropertyId::OutlineWidth | PropertyId::OutlineStyle | PropertyId::OutlineColor) => {
        self.finalize(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    let width = self.width.take();
    let style = self.style.take();
    let color = self.color.take();
    if let (Some(width), Some(style), Some(color)) = (&width, &style, &color) {
      dest.push(Property::Outline(Outline {
        width: width.clone(),
        style: style.clone(),
        color: color.clone(),
      }));
      return;
    }
    if let Some(s) = style {
      dest.push(Property::OutlineStyle(s));
    }
    if let Some(w) = width {
      dest.push(Property::OutlineWidth(w));
    }
    if let Some(c) = color {
      dest.push(Property::OutlineColor(c));
    }
  }
}

