// Font handler

#[derive(Default)]
pub struct FontHandler<'i> {
  family: Option<Vec<FontFamily<'i>>>,
  size: Option<FontSize>,
  style: Option<FontStyle>,
  weight: Option<FontWeight>,
  stretch: Option<FontStretch>,
  line_height: Option<LineHeight>,
  variant_caps: Option<FontVariantCaps>,
  system: Option<SystemFont>,
  other: Vec<Property<'i>>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for FontHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    macro_rules! set {
      ($field: ident, $val: expr) => {{
        self.$field = Some($val.clone());
        self.has_any = true;
      }};
    }
    match property {
      Property::FontFamily(v) => set!(family, v),
      Property::FontSize(v) => set!(size, v),
      Property::FontStyle(v) => set!(style, v),
      Property::FontWeight(v) => set!(weight, v),
      Property::FontStretch(v) => set!(stretch, v),
      Property::LineHeight(v) => set!(line_height, v),
      Property::FontVariantCaps(v) => set!(variant_caps, v),
      Property::Font(v) => match v {
        Font::System(s) => {
          self.flush(dest, context);
          self.system = Some(*s);
          self.has_any = true;
        }
        Font::Font {
          family,
          size,
          style,
          weight,
          stretch,
          line_height,
          variant_caps,
        } => {
          self.system = None;
          set!(family, family);
          set!(size, size);
          set!(style, style);
          set!(weight, weight);
          set!(stretch, stretch);
          set!(line_height, line_height);
          set!(variant_caps, variant_caps);
        }
      },
      Property::VerticalAlign(_) | Property::FontPalette(_) => {
        let id = property.property_id();
        if let Some(existing) = self.other.iter_mut().find(|p| p.property_id() == id) {
          *existing = property.clone();
        } else {
          self.other.push(property.clone());
        }
        self.has_any = true;
      }
      Property::Unparsed(u)
        if matches!(
          u.property_id,
          PropertyId::FontFamily
            | PropertyId::FontSize
            | PropertyId::FontStyle
            | PropertyId::FontWeight
            | PropertyId::FontStretch
            | PropertyId::LineHeight
            | PropertyId::FontVariantCaps
            | PropertyId::Font
            | PropertyId::VerticalAlign
            | PropertyId::FontPalette
        ) =>
      {
        self.flush(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    self.flush(dest, context);
  }
}

impl<'i> FontHandler<'i> {
  fn flush(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;

    if let Some(system) = self.system.take() {
      dest.push(Property::Font(Font::System(system)));
    }

    let family = self.family.take();
    let size = self.size.take();
    let style = self.style.take();
    let weight = self.weight.take();
    let stretch = self.stretch.take();
    let line_height = self.line_height.take();
    let variant_caps = self.variant_caps.take();

    if let (Some(family), Some(size), Some(style), Some(weight), Some(stretch), Some(line_height), Some(variant_caps)) =
      (&family, &size, &style, &weight, &stretch, &line_height, &variant_caps)
    {
      dest.push(Property::Font(Font::Font {
        family: family.clone(),
        size: size.clone(),
        style: style.clone(),
        weight: weight.clone(),
        stretch: stretch.clone(),
        line_height: line_height.clone(),
        variant_caps: *variant_caps,
      }));
    } else {
      if let Some(v) = family {
        dest.push(Property::FontFamily(v));
      }
      if let Some(v) = size {
        dest.push(Property::FontSize(v));
      }
      if let Some(v) = style {
        dest.push(Property::FontStyle(v));
      }
      if let Some(v) = weight {
        dest.push(Property::FontWeight(v));
      }
      if let Some(v) = stretch {
        dest.push(Property::FontStretch(v));
      }
      if let Some(v) = line_height {
        dest.push(Property::LineHeight(v));
      }
      if let Some(v) = variant_caps {
        dest.push(Property::FontVariantCaps(v));
      }
    }

    for p in std::mem::take(&mut self.other) {
      dest.push(p);
    }
  }
}

