// Text decoration handler

#[derive(Default)]
pub struct TextDecorationHandler<'i> {
  line: Option<(TextDecorationLine, VendorPrefix)>,
  thickness: Option<TextDecorationThickness>,
  style: Option<(TextDecorationStyle, VendorPrefix)>,
  color: Option<(CssColor, VendorPrefix)>,
  emphasis_style: Option<(TextEmphasisStyle<'i>, VendorPrefix)>,
  emphasis_color: Option<(CssColor, VendorPrefix)>,
  other: Vec<Property<'i>>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for TextDecorationHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    macro_rules! set_prefixed {
      ($field: ident, $val: expr, $vp: expr) => {{
        if let Some((existing, prefix)) = &mut self.$field {
          if *existing == *$val {
            *prefix |= *$vp;
          } else {
            *existing = $val.clone();
            *prefix = *$vp;
          }
        } else {
          self.$field = Some(($val.clone(), *$vp));
        }
        self.has_any = true;
      }};
    }
    match property {
      Property::TextDecorationLine(v, vp) => set_prefixed!(line, v, vp),
      Property::TextDecorationThickness(v) => {
        self.thickness = Some(v.clone());
        self.has_any = true;
      }
      Property::TextDecorationStyle(v, vp) => set_prefixed!(style, v, vp),
      Property::TextDecorationColor(v, vp) => set_prefixed!(color, v, vp),
      Property::TextDecoration(v, vp) => {
        set_prefixed!(line, &v.line, vp);
        self.thickness = Some(v.thickness.clone());
        set_prefixed!(style, &v.style, vp);
        set_prefixed!(color, &v.color, vp);
      }
      Property::TextEmphasisStyle(v, vp) => set_prefixed!(emphasis_style, v, vp),
      Property::TextEmphasisColor(v, vp) => set_prefixed!(emphasis_color, v, vp),
      Property::TextEmphasis(v, vp) => {
        set_prefixed!(emphasis_style, &v.style, vp);
        set_prefixed!(emphasis_color, &v.color, vp);
      }
      Property::TextAlign(_) | Property::TextTransform(_) | Property::WhiteSpace(_) | Property::WordBreak(_) | Property::LineBreak(_)
      | Property::OverflowWrap(_) | Property::WordWrap(_) | Property::TextJustify(_) | Property::WordSpacing(_) | Property::LetterSpacing(_)
      | Property::TextIndent(_) | Property::TextShadow(_) => {
        // These are not handled by lightningcss' text handler (pushed directly).
        return false;
      }
      Property::Unparsed(u)
        if matches!(
          u.property_id,
          PropertyId::TextDecorationLine(_)
            | PropertyId::TextDecorationThickness
            | PropertyId::TextDecorationStyle(_)
            | PropertyId::TextDecorationColor(_)
            | PropertyId::TextDecoration(_)
            | PropertyId::TextEmphasisStyle(_)
            | PropertyId::TextEmphasisColor(_)
            | PropertyId::TextEmphasis(_)
        ) =>
      {
        self.finalize(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    let line = self.line.take();
    let thickness = self.thickness.take();
    let style = self.style.take();
    let color = self.color.take();
    let emphasis_style = self.emphasis_style.take();
    let emphasis_color = self.emphasis_color.take();

    match (&line, &thickness, &style, &color) {
      (Some((l, lp)), Some(t), Some((s, sp)), Some((c, cp))) if lp == sp && sp == cp => {
        dest.push(Property::TextDecoration(
          TextDecoration {
            line: *l,
            thickness: t.clone(),
            style: *s,
            color: c.clone(),
          },
          *lp,
        ));
      }
      _ => {
        if let Some((l, p)) = line {
          dest.push(Property::TextDecorationLine(l, p));
        }
        if let Some(t) = thickness {
          dest.push(Property::TextDecorationThickness(t));
        }
        if let Some((s, p)) = style {
          dest.push(Property::TextDecorationStyle(s, p));
        }
        if let Some((c, p)) = color {
          dest.push(Property::TextDecorationColor(c, p));
        }
      }
    }

    match (&emphasis_style, &emphasis_color) {
      (Some((s, sp)), Some((c, cp))) if sp == cp => {
        dest.push(Property::TextEmphasis(
          TextEmphasis {
            style: s.clone(),
            color: c.clone(),
          },
          *sp,
        ));
      }
      _ => {
        if let Some((s, p)) = emphasis_style {
          dest.push(Property::TextEmphasisStyle(s, p));
        }
        if let Some((c, p)) = emphasis_color {
          dest.push(Property::TextEmphasisColor(c, p));
        }
      }
    }

    for p in std::mem::take(&mut self.other) {
      dest.push(p);
    }
  }
}

