#[derive(Default)]
pub struct AnimationHandler<'i> {
  names: Option<(SmallVecLike<crate::properties::animation::AnimationName<'i>>, VendorPrefix)>,
  durations: Option<(SmallVecLike<crate::values::time::Time>, VendorPrefix)>,
  timing_functions: Option<(SmallVecLike<crate::values::easing::EasingFunction>, VendorPrefix)>,
  iteration_counts: Option<(SmallVecLike<crate::properties::animation::AnimationIterationCount>, VendorPrefix)>,
  directions: Option<(SmallVecLike<crate::properties::animation::AnimationDirection>, VendorPrefix)>,
  play_states: Option<(SmallVecLike<crate::properties::animation::AnimationPlayState>, VendorPrefix)>,
  delays: Option<(SmallVecLike<crate::values::time::Time>, VendorPrefix)>,
  fill_modes: Option<(SmallVecLike<crate::properties::animation::AnimationFillMode>, VendorPrefix)>,
  timelines: Option<SmallVecLike<crate::properties::animation::AnimationTimeline<'i>>>,
  other: Vec<Property<'i>>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for AnimationHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    macro_rules! set {
      ($field: ident, $val: expr, $vp: expr) => {{
        if let Some((existing, prefix)) = &mut self.$field {
          if *existing == *$val {
            *prefix |= *$vp;
          } else {
            self.flush(dest, context);
            self.$field = Some(($val.clone(), *$vp));
          }
        } else {
          self.$field = Some(($val.clone(), *$vp));
        }
        self.has_any = true;
      }};
    }
    match property {
      Property::AnimationName(v, vp) => set!(names, v, vp),
      Property::AnimationDuration(v, vp) => set!(durations, v, vp),
      Property::AnimationTimingFunction(v, vp) => set!(timing_functions, v, vp),
      Property::AnimationIterationCount(v, vp) => set!(iteration_counts, v, vp),
      Property::AnimationDirection(v, vp) => set!(directions, v, vp),
      Property::AnimationPlayState(v, vp) => set!(play_states, v, vp),
      Property::AnimationDelay(v, vp) => set!(delays, v, vp),
      Property::AnimationFillMode(v, vp) => set!(fill_modes, v, vp),
      Property::AnimationTimeline(v) => {
        self.timelines = Some(v.clone());
        self.has_any = true;
      }
      Property::AnimationComposition(_) | Property::AnimationRangeStart(_) | Property::AnimationRangeEnd(_) | Property::AnimationRange(_) => {
        let id = property.property_id();
        if let Some(existing) = self.other.iter_mut().find(|p| p.property_id() == id) {
          *existing = property.clone();
        } else {
          self.other.push(property.clone());
        }
        self.has_any = true;
      }
      Property::Animation(v, vp) => {
        let names = SmallVecLike(v.0.iter().map(|a| a.name.clone()).collect());
        let durations = SmallVecLike(v.0.iter().map(|a| a.duration).collect());
        let timing_functions = SmallVecLike(v.0.iter().map(|a| a.timing_function.clone()).collect());
        let iteration_counts = SmallVecLike(v.0.iter().map(|a| a.iteration_count.clone()).collect());
        let directions = SmallVecLike(v.0.iter().map(|a| a.direction).collect());
        let play_states = SmallVecLike(v.0.iter().map(|a| a.play_state).collect());
        let delays = SmallVecLike(v.0.iter().map(|a| a.delay).collect());
        let fill_modes = SmallVecLike(v.0.iter().map(|a| a.fill_mode).collect());
        let timelines = SmallVecLike(v.0.iter().map(|a| a.timeline.clone()).collect());
        set!(names, &names, vp);
        set!(durations, &durations, vp);
        set!(timing_functions, &timing_functions, vp);
        set!(iteration_counts, &iteration_counts, vp);
        set!(directions, &directions, vp);
        set!(play_states, &play_states, vp);
        set!(delays, &delays, vp);
        set!(fill_modes, &fill_modes, vp);
        self.timelines = Some(timelines);
      }
      Property::Unparsed(u) if u.property_id.name().starts_with("animation") => {
        self.flush(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    self.flush(dest, context);
  }
}

impl<'i> AnimationHandler<'i> {
  fn flush(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    let names = self.names.take();
    let durations = self.durations.take();
    let timing_functions = self.timing_functions.take();
    let iteration_counts = self.iteration_counts.take();
    let directions = self.directions.take();
    let play_states = self.play_states.take();
    let delays = self.delays.take();
    let fill_modes = self.fill_modes.take();
    let timelines = self.timelines.take();

    if let (Some((n, np)), Some((d, dp)), Some((t, tp)), Some((ic, icp)), Some((dir, dirp)), Some((ps, psp)), Some((dl, dlp)), Some((fm, fmp))) =
      (&names, &durations, &timing_functions, &iteration_counts, &directions, &play_states, &delays, &fill_modes)
    {
      let len = n.0.len();
      let prefixes_equal = np == dp && dp == tp && tp == icp && icp == dirp && dirp == psp && psp == dlp && dlp == fmp;
      let lens_equal = d.0.len() == len
        && t.0.len() == len
        && ic.0.len() == len
        && dir.0.len() == len
        && ps.0.len() == len
        && dl.0.len() == len
        && fm.0.len() == len
        && timelines.as_ref().map_or(true, |tl| tl.0.len() == len);
      if prefixes_equal && lens_equal {
        let animations: Vec<Animation<'i>> = (0..len)
          .map(|i| Animation {
            name: n.0[i].clone(),
            duration: d.0[i],
            timing_function: t.0[i].clone(),
            iteration_count: ic.0[i].clone(),
            direction: dir.0[i],
            play_state: ps.0[i],
            delay: dl.0[i],
            fill_mode: fm.0[i],
            timeline: timelines
              .as_ref()
              .map(|tl| tl.0[i].clone())
              .unwrap_or(crate::properties::animation::AnimationTimeline::Auto),
          })
          .collect();
        dest.push(Property::Animation(SmallVecLike(animations), *np));
        for p in std::mem::take(&mut self.other) {
          dest.push(p);
        }
        return;
      }
    }

    if let Some((v, p)) = names {
      dest.push(Property::AnimationName(v, p));
    }
    if let Some((v, p)) = durations {
      dest.push(Property::AnimationDuration(v, p));
    }
    if let Some((v, p)) = timing_functions {
      dest.push(Property::AnimationTimingFunction(v, p));
    }
    if let Some((v, p)) = iteration_counts {
      dest.push(Property::AnimationIterationCount(v, p));
    }
    if let Some((v, p)) = directions {
      dest.push(Property::AnimationDirection(v, p));
    }
    if let Some((v, p)) = play_states {
      dest.push(Property::AnimationPlayState(v, p));
    }
    if let Some((v, p)) = delays {
      dest.push(Property::AnimationDelay(v, p));
    }
    if let Some((v, p)) = fill_modes {
      dest.push(Property::AnimationFillMode(v, p));
    }
    if let Some(v) = timelines {
      dest.push(Property::AnimationTimeline(v));
    }
    for p in std::mem::take(&mut self.other) {
      dest.push(p);
    }
  }
}

