// ---------------------------------------------------------------------------
// Generic "last wins" handler for a fixed ordered set of properties.

macro_rules! simple_handler {
  ($name: ident, [ $( $prop: ident ),* $(,)? ]) => {
    #[derive(Default)]
    pub struct $name<'i> {
      props: Vec<Property<'i>>,
    }

    impl<'i> PropertyHandler<'i> for $name<'i> {
      fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
        let id = property.property_id();
        let matches_id = |id: &PropertyId| matches!(id, $( PropertyId::$prop { .. } )|*);
        if let Property::Unparsed(_) = property {
          if matches_id(&id) {
            self.finalize(dest, context);
            dest.push(property.clone());
            return true;
          }
          return false;
        }
        if !matches_id(&id) {
          return false;
        }
        // Replace existing value with the same property id (ignoring prefix) in state.
        if let Some(existing) = self.props.iter_mut().find(|p| p.property_id().with_prefix(VendorPrefix::None) == id.with_prefix(VendorPrefix::None)) {
          *existing = merge_prefixed(existing, property);
        } else {
          self.props.push(property.clone());
        }
        true
      }

      fn finalize(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
        // Output in fixed order.
        let mut props = std::mem::take(&mut self.props);
        $(
          if let Some(pos) = props.iter().position(|p| matches!(p.property_id(), PropertyId::$prop { .. })) {
            dest.push(props.remove(pos));
          }
        )*
        for p in props {
          dest.push(p);
        }
      }
    }
  };
}

/// Merges vendor prefixes when the values are equal; otherwise the new property wins.
fn merge_prefixed<'i>(existing: &Property<'i>, new: &Property<'i>) -> Property<'i> {
  let ep = existing.property_id().prefix();
  let np = new.property_id().prefix();
  if ep != np && !ep.is_empty() && !np.is_empty() {
    // Compare values by serializing
    if values_equal(existing, new) {
      return with_prefix(new, ep | np);
    }
  }
  new.clone()
}

fn values_equal(a: &Property, b: &Property) -> bool {
  let mut sa = String::new();
  let mut sb = String::new();
  {
    let mut pa = crate::printer::Printer::new(&mut sa, true, Targets::default());
    let _ = a.value_to_css(&mut pa);
  }
  {
    let mut pb = crate::printer::Printer::new(&mut sb, true, Targets::default());
    let _ = b.value_to_css(&mut pb);
  }
  sa == sb
}

pub fn with_prefix<'i>(p: &Property<'i>, prefix: VendorPrefix) -> Property<'i> {
  // Re-parse via serialization to change the prefix (generic approach).
  let id = p.property_id().with_prefix(prefix);
  let mut s = String::new();
  {
    let mut printer = crate::printer::Printer::new(&mut s, false, Targets::default());
    let _ = p.value_to_css(&mut printer);
  }
  let leaked: &'static str = Box::leak(s.into_boxed_str());
  let mut input = crate::parser::ParserInput::new(leaked);
  let mut parser = crate::parser::Parser::new(&mut input);
  let options = crate::values::token_list::ParserOptions {
    error_recovery: false,
    custom_media: false,
    css_modules: false,
  };
  let id_static: PropertyId<'static> = unsafe { std::mem::transmute(id) };
  match Property::parse(id_static, &mut parser, &options) {
    Ok(prop) => unsafe { std::mem::transmute(prop) },
    Err(_) => p.clone(),
  }
}

