  justify_items: Option<JustifyItems>,
  row_gap: Option<GapValue>,
  column_gap: Option<GapValue>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for AlignHandler {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    macro_rules! set_prefixed {
      ($field: ident, $val: expr, $vp: expr) => {{
        if let Some((existing, prefix)) = &mut self.$field {
          if *existing == *$val {
            *prefix |= *$vp;
          } else {
            *existing = $val.clone();
            *prefix = *$vp;
          }
        } else {
          self.$field = Some(($val.clone(), *$vp));
        }
        self.has_any = true;
      }};
    }
    match property {
      Property::AlignContent(v, vp) => set_prefixed!(align_content, v, vp),
      Property::JustifyContent(v, vp) => set_prefixed!(justify_content, v, vp),
      Property::PlaceContent(v) => {
        set_prefixed!(align_content, &v.align, &VendorPrefix::None);
        set_prefixed!(justify_content, &v.justify, &VendorPrefix::None);
      }
      Property::AlignSelf(v, vp) => set_prefixed!(align_self, v, vp),
      Property::JustifySelf(v) => {
        self.justify_self = Some(v.clone());
        self.has_any = true;
      }
      Property::PlaceSelf(v) => {
        set_prefixed!(align_self, &v.align, &VendorPrefix::None);
        self.justify_self = Some(v.justify.clone());
      }
      Property::AlignItems(v, vp) => set_prefixed!(align_items, v, vp),
      Property::JustifyItems(v) => {
        self.justify_items = Some(v.clone());
        self.has_any = true;
      }
      Property::PlaceItems(v) => {
        set_prefixed!(align_items, &v.align, &VendorPrefix::None);
        self.justify_items = Some(v.justify.clone());
      }
      Property::RowGap(v) => {
        self.row_gap = Some(v.clone());
        self.has_any = true;
      }
      Property::ColumnGap(v) => {
        self.column_gap = Some(v.clone());
        self.has_any = true;
      }
      Property::Gap(v) => {
        self.row_gap = Some(v.row.clone());
        self.column_gap = Some(v.column.clone());
        self.has_any = true;
      }
      Property::Unparsed(u)
        if matches!(
          u.property_id,
          PropertyId::AlignContent(_)
            | PropertyId::JustifyContent(_)
            | PropertyId::PlaceContent
            | PropertyId::AlignSelf(_)
            | PropertyId::JustifySelf
            | PropertyId::PlaceSelf
            | PropertyId::AlignItems(_)
            | PropertyId::JustifyItems
            | PropertyId::PlaceItems
            | PropertyId::RowGap
            | PropertyId::ColumnGap
            | PropertyId::Gap
        ) =>
      {
        self.finalize(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    let align_content = self.align_content.take();
    let justify_content = self.justify_content.take();
    let align_self = self.align_self.take();
    let justify_self = self.justify_self.take();
    let align_items = self.align_items.take();
    let justify_items = self.justify_items.take();
    let row_gap = self.row_gap.take();
    let column_gap = self.column_gap.take();

    match (&align_content, &justify_content) {
      (Some((a, ap)), Some((j, jp))) if *ap == VendorPrefix::None && *jp == VendorPrefix::None => {
        dest.push(Property::PlaceContent(PlaceContent {
          align: a.clone(),
          justify: j.clone(),
        }));
      }
      _ => {
        if let Some((a, p)) = align_content {
          dest.push(Property::AlignContent(a, p));
        }
        if let Some((j, p)) = justify_content {
          dest.push(Property::JustifyContent(j, p));
        }
      }
    }

    match (&align_self, &justify_self) {
      (Some((a, ap)), Some(j)) if *ap == VendorPrefix::None => {
        dest.push(Property::PlaceSelf(PlaceSelf {
          align: a.clone(),
          justify: j.clone(),
        }));
      }
      _ => {
        if let Some((a, p)) = align_self {
          dest.push(Property::AlignSelf(a, p));
        }
        if let Some(j) = justify_self {
          dest.push(Property::JustifySelf(j));
        }
      }
    }

    match (&align_items, &justify_items) {
      (Some((a, ap)), Some(j)) if *ap == VendorPrefix::None => {
        dest.push(Property::PlaceItems(PlaceItems {
          align: a.clone(),
          justify: j.clone(),
        }));
      }
      _ => {
        if let Some((a, p)) = align_items {
          dest.push(Property::AlignItems(a, p));
        }
        if let Some(j) = justify_items {
          dest.push(Property::JustifyItems(j));
        }
      }
    }

    match (&row_gap, &column_gap) {
      (Some(r), Some(c)) => dest.push(Property::Gap(Gap {
        row: r.clone(),
        column: c.clone(),
      })),
      _ => {
        if let Some(r) = row_gap {
          dest.push(Property::RowGap(r));
        }
        if let Some(c) = column_gap {
          dest.push(Property::ColumnGap(c));
        }
      }
    }
  }
}

