#[derive(Default)]
pub struct TransitionHandler<'i> {
  properties: Option<(SmallVecLike<PropertyId<'i>>, VendorPrefix)>,
  durations: Option<(SmallVecLike<crate::values::time::Time>, VendorPrefix)>,
  delays: Option<(SmallVecLike<crate::values::time::Time>, VendorPrefix)>,
  timing_functions: Option<(SmallVecLike<crate::values::easing::EasingFunction>, VendorPrefix)>,
  has_any: bool,
}

impl<'i> PropertyHandler<'i> for TransitionHandler<'i> {
  fn handle_property(&mut self, property: &Property<'i>, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) -> bool {
    macro_rules! set {
      ($field: ident, $val: expr, $vp: expr) => {{
        if let Some((existing, prefix)) = &mut self.$field {
          if *existing == *$val {
            *prefix |= *$vp;
          } else {
            self.flush(dest, context);
            self.$field = Some(($val.clone(), *$vp));
          }
        } else {
          self.$field = Some(($val.clone(), *$vp));
        }
        self.has_any = true;
      }};
    }
    match property {
      Property::TransitionProperty(v, vp) => set!(properties, v, vp),
      Property::TransitionDuration(v, vp) => set!(durations, v, vp),
      Property::TransitionDelay(v, vp) => set!(delays, v, vp),
      Property::TransitionTimingFunction(v, vp) => set!(timing_functions, v, vp),
      Property::Transition(v, vp) => {
        let properties = SmallVecLike(v.0.iter().map(|t| t.property.clone()).collect());
        let durations = SmallVecLike(v.0.iter().map(|t| t.duration).collect());
        let delays = SmallVecLike(v.0.iter().map(|t| t.delay).collect());
        let timing_functions = SmallVecLike(v.0.iter().map(|t| t.timing_function.clone()).collect());
        set!(properties, &properties, vp);
        set!(durations, &durations, vp);
        set!(delays, &delays, vp);
        set!(timing_functions, &timing_functions, vp);
      }
      Property::Unparsed(u)
        if matches!(
          u.property_id,
          PropertyId::TransitionProperty(_)
            | PropertyId::TransitionDuration(_)
            | PropertyId::TransitionDelay(_)
            | PropertyId::TransitionTimingFunction(_)
            | PropertyId::Transition(_)
        ) =>
      {
        self.flush(dest, context);
        dest.push(property.clone());
      }
      _ => return false,
    }
    true
  }

  fn finalize(&mut self, dest: &mut DeclarationList<'i>, context: &mut PropertyHandlerContext) {
    self.flush(dest, context);
  }
}

impl<'i> TransitionHandler<'i> {
  fn flush(&mut self, dest: &mut DeclarationList<'i>, _context: &mut PropertyHandlerContext) {
    if !self.has_any {
      return;
    }
    self.has_any = false;
    let properties = self.properties.take();
    let durations = self.durations.take();
    let delays = self.delays.take();
    let timing_functions = self.timing_functions.take();

    if let (Some((p, pp)), Some((d, dp)), Some((dl, dlp)), Some((t, tp))) = (&properties, &durations, &delays, &timing_functions) {
      let len = p.0.len();
      if pp == dp && dp == dlp && dlp == tp && d.0.len() == len && dl.0.len() == len && t.0.len() == len {
        let transitions: Vec<Transition<'i>> = (0..len)
          .map(|i| Transition {
            property: p.0[i].clone(),
            duration: d.0[i],
            delay: dl.0[i],
            timing_function: t.0[i].clone(),
          })
          .collect();
        dest.push(Property::Transition(SmallVecLike(transitions), *pp));
        return;
      }
    }

    if let Some((v, p)) = properties {
      dest.push(Property::TransitionProperty(v, p));
    }
    if let Some((v, p)) = durations {
      dest.push(Property::TransitionDuration(v, p));
    }
    if let Some((v, p)) = delays {
      dest.push(Property::TransitionDelay(v, p));
    }
    if let Some((v, p)) = timing_functions {
      dest.push(Property::TransitionTimingFunction(v, p));
    }
  }
}

