impl<'i> DeclarationHandler<'i> {
  pub fn new() -> Self {
    Self::default()
  }

  pub fn handle_property(&mut self, property: &Property<'i>, context: &mut PropertyHandlerContext) -> bool {
    let dest = &mut self.decls;
    self.background.handle_property(property, dest, context)
      || self.border.handle_property(property, dest, context)
      || self.outline.handle_property(property, dest, context)
      || self.flex.handle_property(property, dest, context)
      || self.grid.handle_property(property, dest, context)
      || self.align.handle_property(property, dest, context)
      || self.size.handle_property(property, dest, context)
      || self.margin.handle_property(property, dest, context)
      || self.padding.handle_property(property, dest, context)
      || self.scroll_margin.handle_property(property, dest, context)
      || self.scroll_padding.handle_property(property, dest, context)
      || self.font.handle_property(property, dest, context)
      || self.text.handle_property(property, dest, context)
      || self.list.handle_property(property, dest, context)
      || self.transition.handle_property(property, dest, context)
      || self.animation.handle_property(property, dest, context)
      || self.display.handle_property(property, dest, context)
      || self.position.handle_property(property, dest, context)
      || self.inset.handle_property(property, dest, context)
