      || self.container.handle_property(property, dest, context)
      || self.color_scheme.handle_property(property, dest, context)
      || self.fallback.handle_property(property, dest, context)
      || self.prefix.handle_property(property, dest, context)
      || self.direction.handle_property(property, dest, context)
  }

  pub fn finalize(&mut self, context: &mut PropertyHandlerContext) {
    let dest = &mut self.decls;
    self.direction.finalize(dest, context);
    self.background.finalize(dest, context);
    self.border.finalize(dest, context);
    self.outline.finalize(dest, context);
    self.flex.finalize(dest, context);
    self.grid.finalize(dest, context);
    self.align.finalize(dest, context);
    self.size.finalize(dest, context);
    self.margin.finalize(dest, context);
    self.padding.finalize(dest, context);
    self.scroll_margin.finalize(dest, context);
    self.scroll_padding.finalize(dest, context);
    self.font.finalize(dest, context);
    self.text.finalize(dest, context);
    self.list.finalize(dest, context);
    self.transition.finalize(dest, context);
    self.animation.finalize(dest, context);
    self.display.finalize(dest, context);
    self.position.finalize(dest, context);
    self.inset.finalize(dest, context);
    self.overflow.finalize(dest, context);
    self.transform.finalize(dest, context);
    self.box_shadow.finalize(dest, context);
    self.mask.finalize(dest, context);
    self.container.finalize(dest, context);
    self.color_scheme.finalize(dest, context);
    self.fallback.finalize(dest, context);
    self.prefix.finalize(dest, context);
  }
}

