  Unknown(Cow<'i, str>, TokenList<'i>),
}

fn to_location(state: &ParserState) -> Location {
  let loc = state.source_location();
  Location {
    source_index: 0,
    line: loc.line,
    column: loc.column,
  }
}

/// Parses a stylesheet's top-level rules.
pub fn parse_stylesheet<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ParseContext<'_, 'i>) -> ParseResult<'i, CssRuleList<'i>> {
  let mut rules = Vec::new();
  let mut state = State::Start;
  let mut any_rule_so_far = false;

  loop {
    input.skip_cdc_and_cdo();
    let start = input.state();
    let next_byte = match input.next_byte() {
      Some(b) => b,
      None => break,
    };

    let at_keyword = if next_byte == b'@' {
      match input.next_including_whitespace_and_comments() {
        Ok(Token::AtKeyword(name)) => Some(name),
        _ => {
          input.reset(&start);
          None
        }
      }
    } else {
      None
    };

    let result = if let Some(name) = at_keyword {
      let first_stylesheet_rule = !any_rule_so_far;
      any_rule_so_far = true;
      if first_stylesheet_rule && name.eq_ignore_ascii_case("charset") {
        let delimiters = Delimiter::Semicolon | Delimiter::CurlyBracketBlock;
        let _: Result<(), ParseError<ParserError>> = input.parse_until_after(delimiters, |_| Ok(()));
        continue;
      }
      parse_at_rule(&start, name, input, ctx, &mut state, true, false)
    } else {
      any_rule_so_far = true;
      state = State::Body;
      parse_qualified_rule(&start, input, ctx, false, Delimiter::CurlyBracketBlock)
    };

    match result {
      Ok(rule) => rules.push(rule),
      Err(err) => {
        if ctx.options.error_recovery {
          ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
          continue;
        }
        return Err(err);
      }
    }
  }

  Ok(CssRuleList(rules))
}

fn parse_at_rule<'i, 't>(
  start: &ParserState,
  name: Cow<'i, str>,
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  state: &mut State,
  top_level: bool,
  in_style_rule: bool,
) -> ParseResult<'i, CssRule<'i>> {
  let delimiters = Delimiter::Semicolon | Delimiter::CurlyBracketBlock;
  let result = input.parse_until_before(delimiters, |input| parse_at_rule_prelude(name.clone(), input, ctx, *state, top_level, in_style_rule));
  match result {
    Ok(prelude) => {
      let loc = to_location(start);
      match input.next() {
        Ok(Token::Semicolon) | Err(_) => rule_without_block(prelude, loc, state, top_level, in_style_rule)
          .map_err(|()| input.new_unexpected_token_error(Token::Semicolon)),
        Ok(Token::CurlyBracketBlock) => {
          if top_level {
            *state = State::Body;
          }
          input.parse_nested_block(|input| parse_at_rule_block(prelude, loc, input, ctx, in_style_rule))
        }
        Ok(_) => unreachable!(),
      }
    }
    Err(error) => {
      match input.next() {
        Ok(Token::CurlyBracketBlock) | Ok(Token::Semicolon) | Err(_) => {}
        _ => unreachable!(),
      };
      Err(error)
    }
  }
}

fn parse_at_rule_prelude<'i, 't>(
  name: Cow<'i, str>,
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  state: State,
  top_level: bool,
  in_style_rule: bool,
) -> ParseResult<'i, AtRulePrelude<'i>> {
  let lower = name.to_ascii_lowercase();
  let options = ctx.options;

  if top_level {
    match lower.as_str() {
      "import" => {
        if state > State::Imports {
          return Err(input.new_custom_error(ParserError::UnexpectedImportRule));
        }
        let url_string = input.expect_url_or_string()?;
        let layer = if input.try_parse(|input| input.expect_ident_matching("layer")).is_ok() {
          Some(None)
        } else if input.try_parse(|input| input.expect_function_matching("layer")).is_ok() {
          let name = input.parse_nested_block(LayerName::parse).map(|name| Some(name))?;
          Some(name)
        } else {
          None
        };
        let supports = if input.try_parse(|input| input.expect_function_matching("supports")).is_ok() {
          Some(input.parse_nested_block(|input| {
            input
              .try_parse(SupportsCondition::parse)
              .or_else(|_| SupportsCondition::parse_declaration(input))
          })?)
        } else {
          None
        };
        let media = MediaList::parse(input, options)?;
        return Ok(AtRulePrelude::Import(url_string, media, supports, layer));
      }
      "namespace" => {
        if state > State::Namespaces {
          return Err(input.new_custom_error(ParserError::UnexpectedNamespaceRule));
        }
        let prefix = input.try_parse(|input| input.expect_ident()).ok();
        let namespace = input.expect_url_or_string()?;
        return Ok(AtRulePrelude::Namespace(prefix, namespace));
      }
      "charset" => {
        input.expect_string()?;
        return Ok(AtRulePrelude::Charset);
      }
      "custom-media" if options.custom_media => {
        let name = DashedIdent::parse(input)?;
        let media = MediaList::parse(input, options)?;
        return Ok(AtRulePrelude::CustomMedia(name, media));
      }
      "property" => {
        let name = DashedIdent::parse(input)?;
        return Ok(AtRulePrelude::Property(name));
      }
      _ => {}
    }
  }

  match lower.as_str() {
    "media" => {
      let media = MediaList::parse(input, options)?;
      Ok(AtRulePrelude::Media(media))
    }
    "supports" => {
      let cond = SupportsCondition::parse(input)?;
      Ok(AtRulePrelude::Supports(cond))
    }
    "font-face" => Ok(AtRulePrelude::FontFace),
    "font-palette-values" => {
      let name = DashedIdent::parse(input)?;
      Ok(AtRulePrelude::FontPaletteValues(name))
    }
    "font-feature-values" => {
      let names = input.parse_comma_separated(crate::properties::font::FontFamily::parse)?;
      Ok(AtRulePrelude::FontFeatureValues(names))
    }
    "counter-style" => {
      let name = CustomIdent::parse(input)?;
      Ok(AtRulePrelude::CounterStyle(name))
    }
    "viewport" | "-ms-viewport" => {
      let prefix = if lower.starts_with("-ms") {
        VendorPrefix::Ms
      } else {
        VendorPrefix::None
      };
      Ok(AtRulePrelude::Viewport(prefix))
    }
    "keyframes" | "-webkit-keyframes" | "-moz-keyframes" | "-o-keyframes" | "-ms-keyframes" => {
      let prefix = if lower.starts_with("-webkit-") {
        VendorPrefix::WebKit
      } else if lower.starts_with("-moz-") {
        VendorPrefix::Moz
      } else if lower.starts_with("-o-") {
        VendorPrefix::O
      } else if lower.starts_with("-ms-") {
        VendorPrefix::Ms
      } else {
        VendorPrefix::None
      };
      let name = KeyframesName::parse(input)?;
      Ok(AtRulePrelude::Keyframes(name, prefix))
    }
    "page" => {
      let selectors = input
        .try_parse(|input| input.parse_comma_separated(PageSelector::parse))
        .unwrap_or_default();
      Ok(AtRulePrelude::Page(selectors))
    }
    "-moz-document" => {
      input.expect_function_matching("url-prefix")?;
      input.parse_nested_block(|input| {
        if let Ok(..) = input.try_parse(|input| input.expect_string()) {
          // we only support `url-prefix()`
        }
        input.expect_exhausted()?;
        Ok(())
      })?;
      Ok(AtRulePrelude::MozDocument)
    }
    "layer" => {
      let names = match input.parse_comma_separated(LayerName::parse) {
        Ok(names) => names,
        Err(ParseError {
          kind: ParseErrorKind::Basic(BasicParseErrorKind::EndOfInput),
          ..
        }) => Vec::new(),
        Err(e) => return Err(e),
      };
      Ok(AtRulePrelude::Layer(names))
    }
    "property" => {
      let name = DashedIdent::parse(input)?;
      Ok(AtRulePrelude::Property(name))
    }
    "container" => {
      let name = input.try_parse(crate::properties::contain::parse_container_name).ok();
      let condition = crate::supports::ContainerCondition::parse(input, options)?;
      Ok(AtRulePrelude::Container(name, condition))
    }
    "scope" => {
      let selector_parser = SelectorParser {
        default_namespace: None,
        is_nesting_allowed: true,
        options,
        warnings: Some(ctx.warnings),
        filename: ctx.filename,
      };
      let scope_start = if input.try_parse(|input| input.expect_parenthesis_block()).is_ok() {
        Some(input.parse_nested_block(|input| {
          SelectorList::parse(&selector_parser, input, ParseErrorRecovery::IgnoreInvalidSelector, NestingRequirement::None)
        })?)
      } else {
        None
      };
      let scope_end = if input.try_parse(|input| input.expect_ident_matching("to")).is_ok() {
        input.expect_parenthesis_block()?;
        Some(input.parse_nested_block(|input| {
          SelectorList::parse(&selector_parser, input, ParseErrorRecovery::IgnoreInvalidSelector, NestingRequirement::None)
        })?)
      } else {
        None
      };
      Ok(AtRulePrelude::Scope(scope_start, scope_end))
    }
    "starting-style" => Ok(AtRulePrelude::StartingStyle),
    "view-transition" => Ok(AtRulePrelude::ViewTransition),
    "nest" if in_style_rule => {
      ctx
        .warnings
        .borrow_mut()
        .push(Error::from_parse_error(input.new_custom_error(ParserError::DeprecatedNestRule), ctx.filename.to_string()));
      let selector_parser = SelectorParser {
        default_namespace: None,
        is_nesting_allowed: true,
        options,
        warnings: Some(ctx.warnings),
        filename: ctx.filename,
      };
      let selectors = SelectorList::parse(&selector_parser, input, ParseErrorRecovery::DiscardList, NestingRequirement::Contained)?;
      Ok(AtRulePrelude::Nest(selectors))
    }
    _ => Ok(AtRulePrelude::Unknown(name, TokenList::parse(input, options, 0)?)),
  }
}

fn rule_without_block<'i>(
  prelude: AtRulePrelude<'i>,
  loc: Location,
  state: &mut State,
  top_level: bool,
  in_style_rule: bool,
) -> Result<CssRule<'i>, ()> {
  match prelude {
    AtRulePrelude::Import(url, media, supports, layer) => {
      *state = State::Imports;
      Ok(CssRule::Import(ImportRule {
        url,
        layer,
        supports,
        media,
        loc,
      }))
    }
    AtRulePrelude::Namespace(prefix, url) => {
      *state = State::Namespaces;
      Ok(CssRule::Namespace(NamespaceRule { prefix, url, loc }))
    }
    AtRulePrelude::CustomMedia(name, query) => {
      *state = State::Body;
      Ok(CssRule::CustomMedia(CustomMediaRule { name, query, loc }))
    }
    AtRulePrelude::Layer(names) => {
      if top_level {
        if *state <= State::Layers {
          *state = State::Layers;
        } else {
          *state = State::Body;
        }
      }
      if in_style_rule || names.is_empty() {
        return Err(());
      }
      Ok(CssRule::LayerStatement(LayerStatementRule { names, loc }))
    }
    AtRulePrelude::Charset => Ok(CssRule::Ignored),
    AtRulePrelude::Unknown(name, prelude) => Ok(CssRule::Unknown(UnknownAtRule {
      name,
      prelude,
      block: None,
      loc,
    })),
    _ => Err(()),
  }
}

fn parse_at_rule_block<'i, 't>(
  prelude: AtRulePrelude<'i>,
  loc: Location,
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  in_style_rule: bool,
) -> ParseResult<'i, CssRule<'i>> {
  let options = ctx.options;
  match prelude {
    AtRulePrelude::FontFace => {
      let properties = parse_font_face(input, ctx)?;
      Ok(CssRule::FontFace(FontFaceRule { properties, loc }))
    }
    AtRulePrelude::FontPaletteValues(name) => {
      let declarations = parse_declaration_block(input, ctx)?;
      Ok(CssRule::FontPaletteValues(GenericBlockRule {
        name: Cow::Borrowed("font-palette-values"),
        prelude: name,
        declarations,
        loc,
      }))
    }
    AtRulePrelude::FontFeatureValues(name) => {
      let mut rules = Vec::new();
      loop {
        input.skip_whitespace();
        let start = input.state();
        match input.next_including_whitespace_and_comments() {
          Err(_) => break,
          Ok(Token::AtKeyword(name)) => {
            let delimiters = Delimiter::Semicolon | Delimiter::CurlyBracketBlock;
            let _: Result<(), ParseError<ParserError>> = input.parse_until_before(delimiters, |_| Ok(()));
            match input.next() {
              Ok(Token::CurlyBracketBlock) => {
                let decls = input.parse_nested_block(|input| parse_declaration_block(input, ctx))?;
                rules.push((name, decls));
              }
              _ => {}
            }
          }
          Ok(Token::Semicolon) | Ok(Token::WhiteSpace(_)) | Ok(Token::Comment(_)) | Ok(Token::CloseCurlyBracket) => continue,
          Ok(_) => {
            input.reset(&start);
            let _: Result<(), ParseError<ParserError>> =
              input.parse_until_after(Delimiter::Semicolon | Delimiter::CurlyBracketBlock, |_| Ok(()));
          }
        }
      }
      Ok(CssRule::FontFeatureValues(FontFeatureValuesRule { name, rules, loc }))
    }
    AtRulePrelude::CounterStyle(name) => Ok(CssRule::CounterStyle(CounterStyleRule {
      name,
      declarations: parse_declaration_block(input, ctx)?,
      loc,
    })),
    AtRulePrelude::Media(query) => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::Media(MediaRule { query, rules, loc }))
    }
    AtRulePrelude::Supports(condition) => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::Supports(SupportsRule { condition, rules, loc }))
    }
    AtRulePrelude::Container(name, condition) => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::Container(ContainerRule {
        name,
        condition,
        rules,
        loc,
      }))
    }
    AtRulePrelude::Scope(scope_start, scope_end) => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::Scope(ScopeRule {
        scope_start,
        scope_end,
        rules,
        loc,
      }))
    }
    AtRulePrelude::Viewport(vendor_prefix) => Ok(CssRule::Viewport(ViewportRule {
      vendor_prefix,
      declarations: parse_declaration_block(input, ctx)?,
      loc,
    })),
    AtRulePrelude::Keyframes(name, vendor_prefix) => {
      let keyframes = parse_keyframes(input, ctx)?;
      Ok(CssRule::Keyframes(KeyframesRule {
        name,
        keyframes,
        vendor_prefix,
        loc,
      }))
    }
    AtRulePrelude::Page(selectors) => {
      let rule = parse_page_rule(selectors, input, ctx, loc)?;
      Ok(CssRule::Page(rule))
    }
    AtRulePrelude::MozDocument => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::MozDocument(MozDocumentRule { rules, loc }))
    }
    AtRulePrelude::Layer(names) => {
      let name = if names.is_empty() {
        None
      } else if names.len() == 1 {
        names.into_iter().next()
      } else {
        return Err(input.new_error(BasicParseErrorKind::AtRuleBodyInvalid));
      };
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::LayerBlock(LayerBlockRule { name, rules, loc }))
    }
    AtRulePrelude::Property(name) => Ok(CssRule::Property(parse_property_rule(name, input, options, loc)?)),
    AtRulePrelude::StartingStyle => {
      let rules = parse_style_block(input, ctx, in_style_rule)?;
      Ok(CssRule::StartingStyle(StartingStyleRule { rules, loc }))
    }
    AtRulePrelude::ViewTransition => Ok(CssRule::ViewTransition(ViewTransitionRule {
      declarations: parse_declaration_block(input, ctx)?,
      loc,
    })),
    AtRulePrelude::Nest(selectors) => {
      let (declarations, rules) = parse_nested(input, ctx, true)?;
      Ok(CssRule::Nesting(NestingRule {
        style: StyleRule {
          selectors,
          vendor_prefix: VendorPrefix::empty(),
          declarations,
          rules,
          loc,
        },
        loc,
      }))
    }
    AtRulePrelude::Unknown(name, prelude) => Ok(CssRule::Unknown(UnknownAtRule {
      name,
      prelude,
      block: Some(TokenList::parse(input, options, 0)?),
      loc,
    })),
    AtRulePrelude::Import(..) | AtRulePrelude::Namespace(..) | AtRulePrelude::CustomMedia(..) | AtRulePrelude::Charset => {
      Err(input.new_error(BasicParseErrorKind::AtRuleBodyInvalid))
    }
  }
}

fn parse_declaration_block<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ParseContext<'_, 'i>) -> ParseResult<'i, DeclarationBlock<'i>> {
  let mut warnings = Vec::new();
  let res = DeclarationBlock::parse(input, ctx.options, &mut warnings, ctx.filename);
  ctx.warnings.borrow_mut().extend(warnings);
  res
}

fn parse_qualified_rule<'i, 't>(
  start: &ParserState,
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  in_style_rule: bool,
  delimiters: crate::parser::Delimiters,
) -> ParseResult<'i, CssRule<'i>> {
  let prelude = input.parse_until_before(delimiters, |input| {
    let selector_parser = SelectorParser {
      default_namespace: None,
      is_nesting_allowed: true,
      options: ctx.options,
      warnings: Some(ctx.warnings),
      filename: ctx.filename,
    };
    let requirement = if in_style_rule {
      NestingRequirement::Implicit
    } else {
      NestingRequirement::None
    };
    if in_style_rule {
      SelectorList::parse_relative(&selector_parser, input, ParseErrorRecovery::DiscardList, requirement)
    } else {
      SelectorList::parse(&selector_parser, input, ParseErrorRecovery::DiscardList, requirement)
    }
  });
  input.expect_curly_bracket_block()?;
  // Do this here so that we consume the `{` even if the prelude is `Err`.
  let selectors = prelude?;
  let loc = to_location(start);
  input.parse_nested_block(|input| {
    let (declarations, rules) = parse_nested(input, ctx, true)?;
    Ok(CssRule::Style(StyleRule {
      selectors,
      vendor_prefix: VendorPrefix::empty(),
      declarations,
      rules,
      loc,
    }))
  })
}

/// Parses a block that may contain declarations and nested rules.
fn parse_nested<'i, 't>(
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  is_style_rule: bool,
) -> ParseResult<'i, (DeclarationBlock<'i>, CssRuleList<'i>)> {
  let mut declarations = DeclarationBlock::new();
  let mut rules: Vec<CssRule<'i>> = Vec::new();
  let mut state = State::Body;

  loop {
    input.skip_whitespace();
    let start = input.state();
    match input.next_including_whitespace_and_comments() {
      Err(_) => break,
      Ok(Token::CloseCurlyBracket) | Ok(Token::WhiteSpace(..)) | Ok(Token::Semicolon) | Ok(Token::Comment(..)) => continue,
      Ok(Token::AtKeyword(name)) => {
        let result = parse_at_rule(&start, name, input, ctx, &mut state, false, is_style_rule);
        match result {
          Ok(rule) => rules.push(rule),
          Err(err) => {
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
              continue;
            }
            return Err(err);
          }
        }
      }
      Ok(Token::Ident(name)) if is_style_rule => {
        let result = {
          let decls: &mut DeclarationBlock<'i> = if rules.is_empty() {
            &mut declarations
          } else {
            if !matches!(rules.last(), Some(CssRule::NestedDeclarations(_))) {
              rules.push(CssRule::NestedDeclarations(NestedDeclarationsRule {
                declarations: DeclarationBlock::new(),
                loc: to_location(&start),
              }));
            }
            match rules.last_mut() {
              Some(CssRule::NestedDeclarations(r)) => &mut r.declarations,
              _ => unreachable!(),
            }
          };
          let (d, i) = (&mut decls.declarations, &mut decls.important_declarations);
          crate::parser::parse_until_after(input, Delimiter::Semicolon, crate::parser::ParseUntilErrorBehavior::Stop, |input| {
            input.expect_colon()?;
            crate::declaration::parse_declaration(name, input, d, i, ctx.options)
          })
        };
        if result.is_err() {
          input.reset(&start);
          // We ignore the resulting error here. The property declaration parse error
          // is likely to be more relevant.
          if let Ok(qual) = parse_qualified_rule(&start, input, ctx, is_style_rule, Delimiter::Semicolon | Delimiter::CurlyBracketBlock) {
            rules.push(qual);
            continue;
          }
        }
        if let Err(err) = result {
          // Remove empty nested declarations rule if added
          if let Some(CssRule::NestedDeclarations(r)) = rules.last() {
            if r.declarations.is_empty() {
              rules.pop();
            }
          }
          if ctx.options.error_recovery {
            ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
            continue;
          }
          return Err(err);
        }
      }
      Ok(_) => {
        input.reset(&start);
        let delimiters = if is_style_rule {
          Delimiter::Semicolon | Delimiter::CurlyBracketBlock
        } else {
          Delimiter::CurlyBracketBlock
        };
        let result = parse_qualified_rule(&start, input, ctx, is_style_rule, delimiters);
        match result {
          Ok(rule) => rules.push(rule),
          Err(err) => {
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
              continue;
            }
            return Err(err);
          }
        }
      }
    }
  }

  Ok((declarations, CssRuleList(rules)))
}

fn parse_style_block<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ParseContext<'_, 'i>, in_style_rule: bool) -> ParseResult<'i, CssRuleList<'i>> {
  let (declarations, mut rules) = parse_nested(input, ctx, in_style_rule)?;
  if !declarations.is_empty() {
    // Declarations directly inside a nested at-rule within a style rule.
    rules.0.insert(
      0,
      CssRule::NestedDeclarations(NestedDeclarationsRule {
        declarations,
        loc: Location::default(),
      }),
    );
  }
  Ok(rules)
}

fn parse_keyframes<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ParseContext<'_, 'i>) -> ParseResult<'i, Vec<Keyframe<'i>>> {
  let mut keyframes = Vec::new();
  loop {
    input.skip_whitespace();
    let start = input.state();
    match input.next_including_whitespace_and_comments() {
      Err(_) => break,
      Ok(Token::CloseCurlyBracket) | Ok(Token::WhiteSpace(..)) | Ok(Token::Semicolon) | Ok(Token::Comment(..)) => continue,
      Ok(Token::AtKeyword(name)) => {
        let err: ParseError<ParserError> = input.new_error(BasicParseErrorKind::AtRuleInvalid(name));
        let _: Result<(), ParseError<ParserError>> =
          input.parse_until_after(Delimiter::Semicolon | Delimiter::CurlyBracketBlock, |_| Ok(()));
        if ctx.options.error_recovery {
          ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
          continue;
        }
        return Err(err);
      }
      Ok(_) => {
        input.reset(&start);
        let selectors = input.parse_until_before(Delimiter::CurlyBracketBlock, |input| {
          input.parse_comma_separated(|input| {
            let loc = input.current_source_location();
            match input.next()? {
              Token::Percentage { unit_value, .. } => Ok(KeyframeSelector::Percentage(crate::values::percentage::Percentage(unit_value))),
              Token::Ident(ref ident) if ident.eq_ignore_ascii_case("from") => Ok(KeyframeSelector::From),
              Token::Ident(ref ident) if ident.eq_ignore_ascii_case("to") => Ok(KeyframeSelector::To),
              t => Err(loc.new_unexpected_token_error(t)),
            }
          })
        });
        let block_res = input.expect_curly_bracket_block();
        match (selectors, block_res) {
          (Ok(selectors), Ok(())) => {
            let declarations = input.parse_nested_block(|input| parse_declaration_block(input, ctx))?;
            keyframes.push(Keyframe { selectors, declarations });
          }
          (Err(e), _) => {
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(e, ctx.filename.to_string()));
              // consume block
              if input.next_byte() == Some(b'{') {
                let _ = input.expect_curly_bracket_block();
                let _: Result<(), ParseError<ParserError>> = input.parse_nested_block(|_| Ok(()));
              }
              continue;
            }
            return Err(e);
          }
          (_, Err(e)) => {
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(e.into(), ctx.filename.to_string()));
              continue;
            }
            return Err(e.into());
          }
        }
      }
    }
  }
  Ok(keyframes)
}

fn parse_page_rule<'i, 't>(
  selectors: Vec<PageSelector<'i>>,
  input: &mut Parser<'i, 't>,
  ctx: &ParseContext<'_, 'i>,
  loc: Location,
) -> ParseResult<'i, PageRule<'i>> {
  let mut declarations = DeclarationBlock::new();
  let mut rules = Vec::new();
  loop {
    input.skip_whitespace();
    let start = input.state();
    match input.next_including_whitespace_and_comments() {
      Err(_) => break,
      Ok(Token::CloseCurlyBracket) | Ok(Token::WhiteSpace(..)) | Ok(Token::Semicolon) | Ok(Token::Comment(..)) => continue,
      Ok(Token::AtKeyword(name)) => {
        let lower = name.to_ascii_lowercase();
        let valid = matches!(
          lower.as_str(),
          "top-left-corner" | "top-left" | "top-center" | "top-right" | "top-right-corner" | "bottom-left-corner" | "bottom-left"
            | "bottom-center" | "bottom-right" | "bottom-right-corner" | "left-top" | "left-middle" | "left-bottom" | "right-top"
            | "right-middle" | "right-bottom"
        );
        let _: Result<(), ParseError<ParserError>> = input.parse_until_before(Delimiter::Semicolon | Delimiter::CurlyBracketBlock, |_| Ok(()));
        match input.next() {
          Ok(Token::CurlyBracketBlock) => {
            let margin_loc = to_location(&start);
            let decls = input.parse_nested_block(|input| parse_declaration_block(input, ctx))?;
            if valid {
              rules.push(PageMarginRule {
                margin_box: Cow::Owned(lower),
                declarations: decls,
                loc: margin_loc,
              });
            } else {
              let err: ParseError<ParserError> = start.source_location().new_custom_error(ParserError::AtRuleInvalid(name.clone()));
              if ctx.options.error_recovery {
                ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
              } else {
                return Err(err);
              }
            }
          }
          _ => {
            let err: ParseError<ParserError> = start.source_location().new_custom_error(ParserError::AtRuleInvalid(name.clone()));
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
            } else {
              return Err(err);
            }
          }
        }
      }
      Ok(Token::Ident(name)) => {
        let result = input.parse_until_after(Delimiter::Semicolon, |input| {
          input.expect_colon()?;
          crate::declaration::parse_declaration(
            name,
            input,
            &mut declarations.declarations,
            &mut declarations.important_declarations,
            ctx.options,
          )
        });
        if let Err(err) = result {
          if ctx.options.error_recovery {
            ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
            continue;
          }
          return Err(err);
        }
      }
      Ok(token) => {
        let err: ParseError<ParserError> = start.source_location().new_unexpected_token_error(token.clone());
        let _: Result<(), ParseError<ParserError>> = input.parse_until_after(Delimiter::Semicolon, |_| Ok(()));
        if ctx.options.error_recovery {
          ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
          continue;
        }
        return Err(err);
      }
    }
  }
  Ok(PageRule {
    selectors,
    declarations,
    rules,
    loc,
  })
}

fn parse_property_rule<'i, 't>(
  name: DashedIdent<'i>,
  input: &mut Parser<'i, 't>,
  options: &ParserOptions,
  loc: Location,
) -> ParseResult<'i, PropertyRule<'i>> {
  let mut syntax = None;
  let mut inherits = None;
  let mut initial_value = None;

  loop {
    input.skip_whitespace();
    let start = input.state();
    match input.next_including_whitespace_and_comments() {
      Err(_) => break,
      Ok(Token::CloseCurlyBracket) | Ok(Token::WhiteSpace(..)) | Ok(Token::Semicolon) | Ok(Token::Comment(..)) => continue,
      Ok(Token::Ident(ident)) => {
        let result: ParseResult<'i, ()> = input.parse_until_after(Delimiter::Semicolon, |input| {
          input.expect_colon()?;
          match ident.to_ascii_lowercase().as_str() {
            "syntax" => {
              let s = input.expect_string()?;
              syntax = Some(s);
            }
            "inherits" => {
              let loc = input.current_source_location();
              let id = input.expect_ident()?;
              inherits = Some(match id.to_ascii_lowercase().as_str() {
                "true" => true,
                "false" => false,
                _ => return Err(loc.new_unexpected_token_error(Token::Ident(id))),
              });
            }
            "initial-value" => {
              let tokens = TokenList::parse(input, options, 0)?;
              initial_value = Some(tokens);
            }
            _ => return Err(input.new_custom_error(ParserError::InvalidDeclaration)),
          }
          Ok(())
        });
        if result.is_err() {
          return Err(input.new_custom_error(ParserError::AtRuleBodyInvalid));
        }
      }
      Ok(_) => {
        input.reset(&start);
        return Err(input.new_custom_error(ParserError::AtRuleBodyInvalid));
      }
    }
  }

  // `syntax` and `inherits` are always required.
  if let (Some(syntax), Some(inherits)) = (syntax, inherits) {
    // `initial-value` is required unless the syntax is a universal definition.
    if syntax.trim() != "*" && initial_value.is_none() {
      return Err(input.new_custom_error(ParserError::AtRuleBodyInvalid));
    }
    return Ok(PropertyRule {
      name,
      syntax,
      inherits,
      initial_value,
      loc,
    });
  }

  Err(input.new_custom_error(ParserError::AtRuleBodyInvalid))
}

fn parse_font_face<'i, 't>(input: &mut Parser<'i, 't>, ctx: &ParseContext<'_, 'i>) -> ParseResult<'i, Vec<FontFaceProperty<'i>>> {
  let mut properties = Vec::new();
  loop {
    input.skip_whitespace();
    let start = input.state();
    match input.next_including_whitespace_and_comments() {
      Err(_) => break,
      Ok(Token::CloseCurlyBracket) | Ok(Token::WhiteSpace(..)) | Ok(Token::Semicolon) | Ok(Token::Comment(..)) => continue,
      Ok(Token::Ident(name)) => {
        let result: ParseResult<'i, FontFaceProperty<'i>> = input.parse_until_after(Delimiter::Semicolon, |input| {
          input.expect_colon()?;
          let state = input.state();
          let lower = name.to_ascii_lowercase();
          macro_rules! property {
            ($t: ty, $variant: ident) => {{
              if let Ok(v) = input.try_parse(<$t as crate::traits::Parse>::parse) {
                if input.expect_exhausted().is_ok() {
                  return Ok(FontFaceProperty {
                    name: name.clone(),
                    value: FontFaceValue::$variant(v),
                  });
                }
              }
              input.reset(&state);
            }};
          }
          match lower.as_str() {
            "src" => {
              if let Ok(sources) = input.try_parse(|input| input.parse_comma_separated(Source::parse)) {
                if input.expect_exhausted().is_ok() {
                  return Ok(FontFaceProperty {
                    name: name.clone(),
                    value: FontFaceValue::Src(sources),
                  });
                }
              }
              input.reset(&state);
            }
            "font-family" => property!(crate::properties::font::FontFamily, FontFamily),
            "font-style" => property!(crate::properties::font::FontStyle, FontStyle),
            "font-weight" => {
              if let Ok(first) = input.try_parse(<crate::properties::font::FontWeight as crate::traits::Parse>::parse) {
                let second = input.try_parse(<crate::properties::font::FontWeight as crate::traits::Parse>::parse).ok();
                if input.expect_exhausted().is_ok() {
                  return Ok(FontFaceProperty {
                    name: name.clone(),
                    value: FontFaceValue::FontWeight(first, second),
                  });
                }
              }
              input.reset(&state);
            }
            "font-stretch" => {
              if let Ok(first) = input.try_parse(<crate::properties::font::FontStretch as crate::traits::Parse>::parse) {
                let second = input.try_parse(<crate::properties::font::FontStretch as crate::traits::Parse>::parse).ok();
                if input.expect_exhausted().is_ok() {
                  return Ok(FontFaceProperty {
                    name: name.clone(),
                    value: FontFaceValue::FontStretch(first, second),
                  });
                }
              }
              input.reset(&state);
            }
            "unicode-range" => {
              if let Ok(ranges) = input.try_parse(|input| input.parse_comma_separated(UnicodeRange::parse)) {
                if input.expect_exhausted().is_ok() {
                  return Ok(FontFaceProperty {
                    name: name.clone(),
                    value: FontFaceValue::UnicodeRange(ranges),
                  });
                }
              }
              input.reset(&state);
            }
            _ => {}
          }
          let custom = crate::properties::custom::CustomProperty::parse(
            crate::properties::custom::CustomPropertyName::from(name.clone()),
            input,
            ctx.options,
          )?;
          Ok(FontFaceProperty {
            name: name.clone(),
            value: FontFaceValue::Custom(custom),
          })
        });
        match result {
          Ok(p) => properties.push(p),
          Err(err) => {
            if ctx.options.error_recovery {
              ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
              continue;
            }
            return Err(err);
          }
        }
      }
      Ok(token) => {
        let err: ParseError<ParserError> = start.source_location().new_unexpected_token_error(token.clone());
        let _: Result<(), ParseError<ParserError>> = input.parse_until_after(Delimiter::Semicolon, |_| Ok(()));
        if ctx.options.error_recovery {
          ctx.warnings.borrow_mut().push(Error::from_parse_error(err, ctx.filename.to_string()));
          continue;
        }
        return Err(err);
      }
    }
  }
  Ok(properties)
}

impl<'i> Source<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if let Ok(url) = input.try_parse(UrlSource::parse) {
      return Ok(Source::Url(url));
    }
    input.expect_function_matching("local")?;
    let local = input.parse_nested_block(crate::properties::font::FontFamily::parse)?;
    Ok(Source::Local(local))
  }
}

impl<'i> UrlSource<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let url = crate::values::url::Url::parse(input)?;
    let format = if input.try_parse(|input| input.expect_function_matching("format")).is_ok() {
      Some(input.parse_nested_block(|input| {
        let s = input.expect_ident_or_string()?;
        Ok(s)
      })?)
    } else {
      None
    };
    let tech = if input.try_parse(|input| input.expect_function_matching("tech")).is_ok() {
      input.parse_nested_block(|input| input.parse_comma_separated(|input| input.expect_ident().map_err(|e| e.into())))?
    } else {
      Vec::new()
    };
    Ok(UrlSource { url, format, tech })
  }
}

impl UnicodeRange {
  fn parse<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    // Parse the raw text of a unicode range token sequence.
    let loc = input.current_source_location();
    let start_pos = input.position();
    // Consume tokens until a comma or end.
    let mut text = String::new();
    loop {
      let state = input.state();
      match input.next_including_whitespace() {
        Ok(Token::WhiteSpace(_)) => {
          if text.is_empty() {
            continue;
          }
          input.reset(&state);
          break;
        }
        Ok(_) => {
          text = input.slice_from(start_pos).trim().to_string();
        }
        Err(_) => break,
      }
    }
    let text = text.trim().to_string();
    let lower = text.to_ascii_lowercase();
    if !lower.starts_with("u+") {
      return Err(loc.new_custom_error(ParserError::InvalidValue));
    }
    let body = &lower[2..];
    let (start, end) = if let Some(idx) = body.find('-') {
      let s = u32::from_str_radix(&body[..idx], 16).map_err(|_| loc.new_custom_error(ParserError::InvalidValue))?;
      let e = u32::from_str_radix(&body[idx + 1..], 16).map_err(|_| loc.new_custom_error(ParserError::InvalidValue))?;
      (s, e)
    } else if body.contains('?') {
      let s = u32::from_str_radix(&body.replace('?', "0"), 16).map_err(|_| loc.new_custom_error(ParserError::InvalidValue))?;
      let e = u32::from_str_radix(&body.replace('?', "f"), 16).map_err(|_| loc.new_custom_error(ParserError::InvalidValue))?;
      (s, e)
    } else {
      let s = u32::from_str_radix(body, 16).map_err(|_| loc.new_custom_error(ParserError::InvalidValue))?;
      (s, s)
    };
    if body.is_empty() || start > end || end > 0x10FFFF {
      return Err(loc.new_custom_error(ParserError::InvalidValue));
    }
    Ok(UnicodeRange { start, end })
  }
}

impl ToCss for UnicodeRange {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    // Attempt to optimize the range to use question mark syntax.
    if self.start != self.end {
      // Find the first hex digit that differs between the start and end values.
      let mut shift = 24;
      let mut mask = 0xf << shift;
      while shift > 0 {
        let c1 = self.start & mask;
        let c2 = self.end & mask;
        if c1 != c2 {
          break;
        }
        mask = mask >> 4;
        shift -= 4;
      }

      // Get the remainder of the value. This must be 0x0 to 0xf for the rest
      // of the value to use the question mark syntax.
      shift += 4;
      let remainder_mask = (1 << shift) - 1;
      let start_remainder = self.start & remainder_mask;
      let end_remainder = self.end & remainder_mask;

      if start_remainder == 0 && end_remainder == remainder_mask {
        let start = (self.start & !remainder_mask) >> shift;
        if start != 0 {
          write!(dest, "U+{:X}", start)?;
        } else {
          dest.write_str("U+")?;
        }

        while shift > 0 {
          dest.write_char('?')?;
          shift -= 4;
        }

        return Ok(());
      }
    }

    write!(dest, "U+{:X}", self.start)?;
    if self.end != self.start {
      write!(dest, "-{:X}", self.end)?;
    }
    Ok(())
  }
}

impl<'i> LayerName<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let mut parts = Vec::new();
    let ident = input.expect_ident()?;
    parts.push(ident);

    loop {
      let name = input.try_parse(|input| {
        input.expect_delim('.')?;
        input.expect_ident()
      });
      match name {
        Ok(name) => parts.push(name),
        Err(_) => break,
      }
    }

    Ok(LayerName(parts))
  }
}

impl<'i> ToCss for LayerName<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut first = true;
    for name in &self.0 {
      if first {
        first = false;
      } else {
        dest.write_char('.')?;
      }
      serialize_identifier(name, dest)?;
    }
    Ok(())
  }
}

impl<'i> KeyframesName<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    match input.next()? {
      Token::Ident(ref s) => {
        // CSS-wide keywords without quotes throws an error.
        match s.to_ascii_lowercase().as_str() {
          "none" | "initial" | "inherit" | "unset" | "default" | "revert" | "revert-layer" => {
            Err(input.new_unexpected_token_error(Token::Ident(s.clone())))
          }
          _ => Ok(KeyframesName::Ident(CustomIdent(s.clone()))),
        }
      }
      Token::QuotedString(ref s) => Ok(KeyframesName::Custom(s.clone())),
      t => Err(input.new_unexpected_token_error(t)),
    }
  }
}

impl<'i> ToCss for KeyframesName<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      KeyframesName::Ident(ident) => ident.to_css(dest),
      KeyframesName::Custom(s) => {
        // Make sure to quote strings, even if they are valid custom idents, as none/initial etc. are not.
        let lower = s.to_ascii_lowercase();
        if matches!(lower.as_str(), "none" | "initial" | "inherit" | "unset" | "default" | "revert" | "revert-layer") {
          serialize_string(s, dest)
        } else {
          dest.write_ident(s, true)
        }
      }
    }
  }
}

impl<'i> PageSelector<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let name = input.try_parse(|input| input.expect_ident()).ok();
    let mut pseudo_classes = vec![];

    loop {
      // Whitespace is not allowed between pseudo classes
      let state = input.state();
      match input.next_including_whitespace() {
        Ok(Token::Colon) => {
          let loc = input.current_source_location();
          let ident = input.expect_ident()?;
          let pc = match ident.to_ascii_lowercase().as_str() {
            "left" => PagePseudoClass::Left,
            "right" => PagePseudoClass::Right,
            "first" => PagePseudoClass::First,
            "blank" => PagePseudoClass::Blank,
            _ => return Err(loc.new_unexpected_token_error(Token::Ident(ident))),
          };
          pseudo_classes.push(pc);
        }
        _ => {
          input.reset(&state);
          break;
        }
      }
    }

    Ok(PageSelector { name, pseudo_classes })
  }
}

impl<'i> ToCss for PageSelector<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if let Some(name) = &self.name {
      serialize_identifier(name, dest)?;
    }
    for pc in &self.pseudo_classes {
      dest.write_char(':')?;
      dest.write_str(match pc {
        PagePseudoClass::Left => "left",
        PagePseudoClass::Right => "right",
        PagePseudoClass::First => "first",
        PagePseudoClass::Blank => "blank",
      })?;
    }
    Ok(())
  }
}

// ---------------------------------------------------------------------------
// Minification

pub struct MinifyContext<'a, 'i> {
  pub targets: crate::targets::Targets,
  pub handler: &'a mut DeclarationHandler<'i>,
  pub important_handler: &'a mut DeclarationHandler<'i>,
  pub handler_context: &'a mut PropertyHandlerContext,
}

impl<'i> CssRuleList<'i> {
  pub fn minify(&mut self, context: &mut MinifyContext<'_, 'i>, parent_is_unused: bool) {
    let mut rules: Vec<CssRule<'i>> = Vec::new();
    for mut rule in self.0.drain(..) {
      match &mut rule {
        CssRule::Keyframes(keyframes) => {
          keyframes.minify(context);
          // Merge adjacent keyframes with the same name and prefix? (skip)
        }
        CssRule::Media(media) => {
          if let Some(CssRule::Media(last_rule)) = rules.last_mut() {
            if last_rule.query == media.query {
              last_rule.rules.0.extend(media.rules.0.drain(..));
              last_rule.rules.minify(context, parent_is_unused);
              continue;
            }
          }
          media.rules.minify(context, parent_is_unused);
          if media.rules.0.is_empty() || media.query.never_matches() {
            continue;
          }
          if media.query.always_matches() {
            rules.extend(media.rules.0.drain(..));
            continue;
          }
        }
        CssRule::Supports(supports) => {
          if let Some(CssRule::Supports(last_rule)) = rules.last_mut() {
            if last_rule.condition == supports.condition {
              last_rule.rules.0.extend(supports.rules.0.drain(..));
              last_rule.rules.minify(context, parent_is_unused);
              continue;
            }
          }
          supports.rules.minify(context, parent_is_unused);
          if supports.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::Container(container) => {
          if let Some(CssRule::Container(last_rule)) = rules.last_mut() {
            if last_rule.name == container.name && last_rule.condition == container.condition {
              last_rule.rules.0.extend(container.rules.0.drain(..));
              last_rule.rules.minify(context, parent_is_unused);
              continue;
            }
          }
          container.rules.minify(context, parent_is_unused);
          if container.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::LayerBlock(layer) => {
          if let Some(CssRule::LayerBlock(last_rule)) = rules.last_mut() {
            if last_rule.name == layer.name {
              last_rule.rules.0.extend(layer.rules.0.drain(..));
              last_rule.rules.minify(context, parent_is_unused);
              continue;
            }
          }
          layer.rules.minify(context, parent_is_unused);
          if layer.rules.0.is_empty() && layer.name.is_none() {
            continue;
          }
        }
        CssRule::LayerStatement(statement) => {
          // Merge into a following layer block? Handled by splitting below.
          // If the previous rule is a layer statement, merge names.
          if let Some(CssRule::LayerStatement(last)) = rules.last_mut() {
            last.names.extend(statement.names.drain(..));
            continue;
          }
        }
        CssRule::Scope(scope) => {
          scope.rules.minify(context, parent_is_unused);
          if scope.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::StartingStyle(s) => {
          s.rules.minify(context, parent_is_unused);
          if s.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::MozDocument(doc) => {
          doc.rules.minify(context, parent_is_unused);
        }
        CssRule::Style(style) => {
          style.minify(context, parent_is_unused);

          // Merge with previous rules.
          if let Some(CssRule::Style(last_style_rule)) = rules.last_mut() {
            // Merge declarations if the selectors are equivalent, and both are compatible with all targets.
            if style.selectors == last_style_rule.selectors
              && crate::selector::is_compatible(&style.selectors.0, context.targets)
              && crate::selector::is_compatible(&last_style_rule.selectors.0, context.targets)
              && style.rules.0.is_empty()
              && last_style_rule.rules.0.is_empty()
            {
              last_style_rule.declarations.declarations.extend(style.declarations.declarations.drain(..));
              last_style_rule
                .declarations
                .important_declarations
                .extend(style.declarations.important_declarations.drain(..));
              last_style_rule.declarations.minify(context.handler, context.important_handler, context.handler_context);
              continue;
            } else if style.declarations == last_style_rule.declarations && style.rules.0.is_empty() && last_style_rule.rules.0.is_empty() {
              // If both selectors are potentially vendor prefixable, and they are
              // equivalent minus prefixes, add the prefix to the last rule.
              if !style.vendor_prefix.is_empty()
                && !last_style_rule.vendor_prefix.is_empty()
                && crate::selector::is_equivalent(&style.selectors.0, &last_style_rule.selectors.0)
              {
                last_style_rule.vendor_prefix |= style.vendor_prefix;
                continue;
              }

              // Append the selectors to the last rule if the declarations are the same, and all selectors are compatible.
              if crate::selector::is_compatible(&style.selectors.0, context.targets)
                && crate::selector::is_compatible(&last_style_rule.selectors.0, context.targets)
              {
                last_style_rule.selectors.0.extend(style.selectors.0.drain(..));
                continue;
              }
            }
          }

          if style.declarations.is_empty() && style.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::Nesting(nesting) => {
          nesting.style.minify(context, parent_is_unused);
          if nesting.style.declarations.is_empty() && nesting.style.rules.0.is_empty() {
            continue;
          }
        }
        CssRule::NestedDeclarations(decls) => {
          decls.declarations.minify(context.handler, context.important_handler, context.handler_context);
          if decls.declarations.is_empty() {
            continue;
          }
        }
        CssRule::CounterStyle(_) | CssRule::FontFace(_) | CssRule::Page(_) | CssRule::Viewport(_) | CssRule::Property(_) | CssRule::ViewTransition(_)
        | CssRule::FontPaletteValues(_) | CssRule::FontFeatureValues(_) => {}
        CssRule::Ignored => continue,
        _ => {}
      }

      rules.push(rule);
    }

    // Handle layer statements followed by layer blocks: `@layer a, b; @layer a {}` -> `@layer a {} @layer b;`
    let mut i = 0;
    while i < rules.len() {
      if let CssRule::LayerStatement(statement) = &rules[i] {
        if i + 1 < rules.len() {
          if let CssRule::LayerBlock(block) = &rules[i + 1] {
            if let Some(name) = &block.name {
              if statement.names.first() == Some(name) {
                let mut names = statement.names.clone();
                names.remove(0);
                let loc = statement.loc;
                rules.remove(i);
                if names.is_empty() {
                  continue;
                }
                rules.insert(i + 1, CssRule::LayerStatement(LayerStatementRule { names, loc }));
              }
            }
          }
        }
      }
      i += 1;
    }

    self.0 = rules;
  }
}

impl<'i> StyleRule<'i> {
  pub fn minify(&mut self, context: &mut MinifyContext<'_, 'i>, parent_is_unused: bool) {
    self
      .declarations
      .minify(context.handler, context.important_handler, context.handler_context);

    if !self.rules.0.is_empty() {
      self.rules.minify(context, parent_is_unused);
    }

    self.vendor_prefix = crate::selector::get_prefix(&self.selectors);
  }
}

impl<'i> KeyframesRule<'i> {
  fn minify(&mut self, context: &mut MinifyContext<'_, 'i>) {
    for keyframe in &mut self.keyframes {
      keyframe
        .declarations
        .minify(context.handler, context.important_handler, context.handler_context);
    }
  }
}

// ---------------------------------------------------------------------------
// Printing

impl<'i> ToCss for CssRuleList<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut first = true;
    let mut last_without_block = false;

    for rule in &self.0 {
      if let CssRule::Ignored = &rule {
        continue;
      }

      if first {
        first = false;
      } else {
        if !dest.minify
          && !(last_without_block && matches!(rule, CssRule::Import(..) | CssRule::Namespace(..) | CssRule::LayerStatement(..)))
        {
          dest.write_char('\n')?;
        }
        dest.newline()?;
      }
      rule.to_css(dest)?;
      last_without_block = matches!(rule, CssRule::Import(..) | CssRule::Namespace(..) | CssRule::LayerStatement(..));
    }

    Ok(())
  }
}

impl<'i> ToCss for CssRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      CssRule::Media(media) => media.to_css(dest),
      CssRule::Import(import) => import.to_css(dest),
      CssRule::Style(style) => style.to_css(dest),
      CssRule::FontFace(font_face) => font_face.to_css(dest),
      CssRule::FontPaletteValues(f) => {
        dest.add_mapping(f.loc);
        dest.write_char('@')?;
        dest.write_str(&f.name)?;
        dest.write_char(' ')?;
        f.prelude.to_css(dest)?;
        f.declarations.to_css_block(dest)
      }
      CssRule::FontFeatureValues(f) => f.to_css(dest),
      CssRule::CounterStyle(counter_style) => {
        dest.add_mapping(counter_style.loc);
        dest.write_str("@counter-style ")?;
        counter_style.name.to_css(dest)?;
        counter_style.declarations.to_css_block(dest)
      }
      CssRule::Keyframes(keyframes) => keyframes.to_css(dest),
      CssRule::Page(font_face) => font_face.to_css(dest),
      CssRule::Supports(supports) => supports.to_css(dest),
      CssRule::Namespace(namespace) => namespace.to_css(dest),
      CssRule::MozDocument(rule) => {
        dest.add_mapping(rule.loc);
        dest.write_str("@-moz-document url-prefix()")?;
        dest.whitespace()?;
        dest.write_char('{')?;
        dest.indent();
        dest.newline()?;
        rule.rules.to_css(dest)?;
        dest.dedent();
        dest.newline()?;
        dest.write_char('}')
      }
      CssRule::Nesting(nesting) => {
        dest.add_mapping(nesting.loc);
        nesting.style.to_css(dest)
      }
      CssRule::NestedDeclarations(decls) => {
        dest.add_mapping(decls.loc);
        decls.declarations.to_css_declarations(dest, false)
      }
      CssRule::Viewport(viewport) => {
        dest.add_mapping(viewport.loc);
        dest.write_char('@')?;
        viewport.vendor_prefix.to_css(dest)?;
        dest.write_str("viewport")?;
        viewport.declarations.to_css_block(dest)
      }
      CssRule::CustomMedia(custom_media) => {
        dest.add_mapping(custom_media.loc);
        dest.write_str("@custom-media ")?;
        custom_media.name.to_css(dest)?;
        dest.write_char(' ')?;
        custom_media.query.to_css(dest)?;
        dest.write_char(';')
      }
      CssRule::LayerStatement(layer) => {
        dest.add_mapping(layer.loc);
        dest.write_str("@layer ")?;
        let mut first = true;
        for name in &layer.names {
          if first {
            first = false;
          } else {
            dest.delim(',', false)?;
          }
          name.to_css(dest)?;
        }
        dest.write_char(';')
      }
      CssRule::LayerBlock(layer) => {
        dest.add_mapping(layer.loc);
        dest.write_str("@layer")?;
        if let Some(name) = &layer.name {
          dest.write_char(' ')?;
          name.to_css(dest)?;
        }
        dest.whitespace()?;
        dest.write_char('{')?;
        dest.indent();
        dest.newline()?;
        layer.rules.to_css(dest)?;
        dest.dedent();
        dest.newline()?;
        dest.write_char('}')
      }
      CssRule::Property(property) => property.to_css(dest),
      CssRule::StartingStyle(rule) => {
        dest.add_mapping(rule.loc);
        dest.write_str("@starting-style")?;
        dest.whitespace()?;
        dest.write_char('{')?;
        dest.indent();
        dest.newline()?;
        rule.rules.to_css(dest)?;
        dest.dedent();
        dest.newline()?;
        dest.write_char('}')
      }
      CssRule::Container(container) => {
        dest.add_mapping(container.loc);
        dest.write_str("@container ")?;
        if let Some(name) = &container.name {
          name.to_css(dest)?;
          dest.write_char(' ')?;
        }
        container.condition.to_css(dest)?;
        dest.whitespace()?;
        dest.write_char('{')?;
        dest.indent();
        dest.newline()?;
        container.rules.to_css(dest)?;
        dest.dedent();
        dest.newline()?;
        dest.write_char('}')
      }
      CssRule::Scope(scope) => {
        dest.add_mapping(scope.loc);
        dest.write_str("@scope")?;
        dest.whitespace()?;
        if let Some(scope_start) = &scope.scope_start {
          dest.write_char('(')?;
          scope_start.to_css(dest)?;
          dest.write_char(')')?;
          dest.whitespace()?;
        }
        if let Some(scope_end) = &scope.scope_end {
          if dest.minify {
            dest.write_char(' ')?;
          }
          dest.write_str("to (")?;
          scope_end.to_css(dest)?;
          dest.write_char(')')?;
          dest.whitespace()?;
        }
        dest.write_char('{')?;
        dest.indent();
        dest.newline()?;
        scope.rules.to_css(dest)?;
        dest.dedent();
        dest.newline()?;
        dest.write_char('}')
      }
      CssRule::ViewTransition(rule) => {
        dest.add_mapping(rule.loc);
        dest.write_str("@view-transition")?;
        rule.declarations.to_css_block(dest)
      }
      CssRule::Unknown(unknown) => unknown.to_css(dest),
      CssRule::Ignored => Ok(()),
    }
  }
}

impl<'i> ToCss for MediaRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@media ")?;
    self.query.to_css(dest)?;
    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();
    dest.newline()?;
    self.rules.to_css(dest)?;
    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for SupportsRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@supports ")?;
    self.condition.to_css(dest)?;
    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();
    dest.newline()?;
    self.rules.to_css(dest)?;
    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for ImportRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@import ")?;
    serialize_string(&self.url, dest)?;

    if let Some(layer) = &self.layer {
      dest.write_str(" layer")?;
      if let Some(name) = layer {
        dest.write_char('(')?;
        name.to_css(dest)?;
        dest.write_char(')')?;
      }
    }

    if let Some(supports) = &self.supports {
      dest.write_str(" supports")?;
      if matches!(supports, SupportsCondition::Declaration { .. }) {
        supports.to_css(dest)?;
      } else {
        dest.write_char('(')?;
        supports.to_css(dest)?;
        dest.write_char(')')?;
      }
    }
    if !self.media.media_queries.is_empty() {
      dest.write_char(' ')?;
      self.media.to_css(dest)?;
    }
    dest.write_str(";")
  }
}

impl<'i> ToCss for NamespaceRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@namespace ")?;
    if let Some(prefix) = &self.prefix {
      serialize_identifier(prefix, dest)?;
      dest.write_char(' ')?;
    }
    serialize_string(&self.url, dest)?;
    dest.write_char(';')
  }
}

impl<'i> ToCss for StyleRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    if self.vendor_prefix.is_empty() {
      self.to_css_base(dest)
    } else {
      let mut first_rule = true;
      for prefix in self.vendor_prefix.iter() {
        if first_rule {
          first_rule = false;
        } else {
          if !dest.minify {
            dest.write_char('\n')?; // no indent
          }
          dest.newline()?;
        }
        dest.vendor_prefix = prefix.bits();
        self.to_css_base(dest)?;
      }
      dest.vendor_prefix = 0;
      Ok(())
    }
  }
}

impl<'i> StyleRule<'i> {
  fn to_css_base(&self, dest: &mut Printer) -> PrintResult {
    // If supported, or there are no targets, preserve nesting. Otherwise, write nested rules after parent.
    let supports_nesting = self.rules.0.is_empty() || !dest.targets.should_compile(crate::compat::Feature::Nesting);
    let len = self.declarations.len();
    let has_declarations = supports_nesting || len > 0 || self.rules.0.is_empty();

    if has_declarations {
      dest.add_mapping(self.loc);
      self.selectors.to_css(dest)?;
      dest.whitespace()?;
      dest.write_char('{')?;
      dest.indent();

      let mut i = 0;
      macro_rules! write {
        ($decls: expr, $important: literal) => {
          for decl in &$decls {
            dest.newline()?;
            decl.to_css(dest, $important)?;
            if i != len - 1 || !dest.minify || (supports_nesting && !self.rules.0.is_empty()) {
              dest.write_char(';')?;
            }
            i += 1;
          }
        };
      }

      write!(self.declarations.declarations, false);
      write!(self.declarations.important_declarations, true);
    }

    let mut newline = true;
    if supports_nesting && !self.rules.0.is_empty() {
      if has_declarations {
        if len > 0 && !dest.minify {
          dest.write_char('\n')?;
        }
        dest.newline()?;
      }
      newline = false;
      dest.with_context(&self.selectors, |dest| self.rules.to_css(dest))?;
    }

    if has_declarations {
      dest.dedent();
      dest.newline()?;
      dest.write_char('}')?;
    }

    if !supports_nesting && !self.rules.0.is_empty() {
      if has_declarations {
        if !dest.minify {
          dest.write_char('\n')?;
        }
        dest.newline()?;
      }
      let _ = newline;
      dest.with_context(&self.selectors, |dest| self.rules.to_css(dest))?;
    }

    Ok(())
  }
}

impl<'i> ToCss for KeyframesRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut first_rule = true;
    for prefix in self.vendor_prefix.or_none().iter() {
      if first_rule {
        first_rule = false;
      } else {
        if !dest.minify {
          dest.write_char('\n')?;
        }
        dest.newline()?;
      }
      dest.add_mapping(self.loc);
      dest.write_char('@')?;
      prefix.to_css(dest)?;
      dest.write_str("keyframes ")?;
      self.name.to_css(dest)?;
      dest.whitespace()?;
      dest.write_char('{')?;
      dest.indent();
      let mut first = true;
      for keyframe in &self.keyframes {
        if first {
          first = false;
        } else if !dest.minify {
          dest.write_char('\n')?;
        }
        dest.newline()?;
        keyframe.to_css(dest)?;
      }
      dest.dedent();
      dest.newline()?;
      dest.write_char('}')?;
    }
    Ok(())
  }
}

impl<'i> ToCss for Keyframe<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    let mut first = true;
    for selector in &self.selectors {
      if !first {
        dest.delim(',', false)?;
      }
      first = false;
      match selector {
        KeyframeSelector::Percentage(p) => {
          if dest.minify && p.0 == 1.0 {
            dest.write_str("to")?;
          } else {
            p.to_css(dest)?;
          }
        }
        KeyframeSelector::From => {
          if dest.minify {
            dest.write_str("0%")?;
          } else {
            dest.write_str("from")?;
          }
        }
        KeyframeSelector::To => dest.write_str("to")?,
      }
    }
    self.declarations.to_css_block(dest)
  }
}

impl<'i> ToCss for FontFaceRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@font-face")?;
    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();
    let len = self.properties.len();
    for (i, prop) in self.properties.iter().enumerate() {
      dest.newline()?;
      prop.to_css(dest)?;
      if i != len - 1 || !dest.minify {
        dest.write_char(';')?;
      }
    }
    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for FontFaceProperty<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match &self.value {
      FontFaceValue::Custom(custom) => {
        dest.write_str(custom.name.as_str())?;
        dest.delim(':', false)?;
        custom.value.to_css_internal(dest, true)
      }
      value => {
        let name = match value {
          FontFaceValue::Src(_) => "src",
          FontFaceValue::FontFamily(_) => "font-family",
          FontFaceValue::FontStyle(_) => "font-style",
          FontFaceValue::FontWeight(..) => "font-weight",
          FontFaceValue::FontStretch(..) => "font-stretch",
          FontFaceValue::UnicodeRange(_) => "unicode-range",
          FontFaceValue::Custom(_) => unreachable!(),
        };
        dest.write_str(name)?;
        dest.delim(':', false)?;
        match value {
          FontFaceValue::Src(sources) => {
            let mut first = true;
            for s in sources {
              if first {
                first = false;
              } else {
                dest.delim(',', false)?;
              }
              s.to_css(dest)?;
            }
            Ok(())
          }
          FontFaceValue::FontFamily(f) => f.to_css(dest),
          FontFaceValue::FontStyle(f) => f.to_css(dest),
          FontFaceValue::FontWeight(a, b) => {
            a.to_css(dest)?;
            if let Some(b) = b {
              if b != a {
                dest.write_char(' ')?;
                b.to_css(dest)?;
              }
            }
            Ok(())
          }
          FontFaceValue::FontStretch(a, b) => {
            a.to_css(dest)?;
            if let Some(b) = b {
              if b != a {
                dest.write_char(' ')?;
                b.to_css(dest)?;
              }
            }
            Ok(())
          }
          FontFaceValue::UnicodeRange(ranges) => {
            let mut first = true;
            for r in ranges {
              if first {
                first = false;
              } else {
                dest.delim(',', false)?;
              }
              r.to_css(dest)?;
            }
            Ok(())
          }
          FontFaceValue::Custom(_) => unreachable!(),
        }
      }
    }
  }
}

impl<'i> ToCss for Source<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      Source::Url(url) => url.to_css(dest),
      Source::Local(local) => {
        dest.write_str("local(")?;
        local.to_css(dest)?;
        dest.write_char(')')
      }
    }
  }
}

impl<'i> ToCss for UrlSource<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    self.url.to_css(dest)?;
    if let Some(format) = &self.format {
      dest.whitespace()?;
      dest.write_str("format(")?;
      serialize_string(format, dest)?;
      dest.write_char(')')?;
    }
    if !self.tech.is_empty() {
      dest.whitespace()?;
      dest.write_str("tech(")?;
      let mut first = true;
      for t in &self.tech {
        if first {
          first = false;
        } else {
          dest.delim(',', false)?;
        }
        serialize_identifier(t, dest)?;
      }
      dest.write_char(')')?;
    }
    Ok(())
  }
}

impl<'i> ToCss for FontFeatureValuesRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@font-feature-values ")?;
    let mut first = true;
    for name in &self.name {
      if first {
        first = false;
      } else {
        dest.delim(',', false)?;
      }
      name.to_css(dest)?;
    }
    dest.whitespace()?;
    dest.write_char('{')?;
    // Note: the original prints nested rules without indentation.
    for (name, decls) in &self.rules {
      dest.newline()?;
      dest.write_char('@')?;
      dest.write_str(name)?;
      dest.write_char('{')?;
      dest.indent();
      let len = decls.len();
      let mut i = 0;
      for (decl, important) in decls.iter() {
        dest.newline()?;
        decl.to_css(dest, important)?;
        if i != len - 1 || !dest.minify {
          dest.write_char(';')?;
        }
        i += 1;
      }
      dest.dedent();
      dest.newline()?;
      dest.write_char('}')?;
    }
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for PageRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@page")?;
    if let Some(first) = self.selectors.first() {
      // Space is only required if the first selector has a name.
      if !dest.minify || first.name.is_some() {
        dest.write_char(' ')?;
      }
      let mut first = true;
      for selector in &self.selectors {
        if first {
          first = false;
        } else {
          dest.delim(',', false)?;
        }
        selector.to_css(dest)?;
      }
    }

    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();

    let mut i = 0;
    let len = self.declarations.len() + self.rules.len();

    macro_rules! write {
      ($decls: expr, $important: literal) => {
        for decl in &$decls {
          dest.newline()?;
          decl.to_css(dest, $important)?;
          if i != len - 1 || !dest.minify {
            dest.write_char(';')?;
          }
          i += 1;
        }
      };
    }

    write!(self.declarations.declarations, false);
    write!(self.declarations.important_declarations, true);

    if !self.rules.is_empty() {
      if !dest.minify && self.declarations.len() > 0 {
        dest.write_char('\n')?;
      }
      dest.newline()?;

      let mut first = true;
      for rule in &self.rules {
        if first {
          first = false;
        } else {
          if !dest.minify {
            dest.write_char('\n')?;
          }
          dest.newline()?;
        }
        dest.add_mapping(rule.loc);
        dest.write_char('@')?;
        dest.write_str(&rule.margin_box)?;
        rule.declarations.to_css_block(dest)?;
      }
    }

    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for PropertyRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_str("@property ")?;
    self.name.to_css(dest)?;
    dest.whitespace()?;
    dest.write_char('{')?;
    dest.indent();
    dest.newline()?;

    dest.write_str("syntax:")?;
    dest.whitespace()?;
    serialize_string(&self.syntax, dest)?;
    dest.write_char(';')?;
    dest.newline()?;

    dest.write_str("inherits:")?;
    dest.whitespace()?;
    match self.inherits {
      true => dest.write_str("true")?,
      false => dest.write_str("false")?,
    }

    if let Some(initial_value) = &self.initial_value {
      dest.write_char(';')?;
      dest.newline()?;

      dest.write_str("initial-value:")?;
      dest.whitespace()?;
      initial_value.to_css_internal(dest, false)?;

      if !dest.minify {
        dest.write_char(';')?;
      }
    }

    dest.dedent();
    dest.newline()?;
    dest.write_char('}')
  }
}

impl<'i> ToCss for UnknownAtRule<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    dest.add_mapping(self.loc);
    dest.write_char('@')?;
    dest.write_str(&self.name)?;

    if !self.prelude.is_empty() {
      dest.write_char(' ')?;
      self.prelude.to_css_internal(dest, false)?;
    }

    if let Some(block) = &self.block {
      dest.whitespace()?;
      dest.write_char('{')?;
      dest.indent();
      dest.newline()?;
      block.to_css_internal(dest, false)?;
      dest.dedent();
      dest.newline()?;
      dest.write_char('}')
    } else {
      dest.write_char(';')
    }
  }
}
