// Container queries

#[derive(Clone, Debug, PartialEq)]
pub enum ContainerCondition<'i> {
  Feature(crate::media_query::MediaFeature<'i>),
  Not(Box<ContainerCondition<'i>>),
  Operation {
    conditions: Vec<ContainerCondition<'i>>,
    operator: crate::media_query::Operator,
  },
  Style(StyleQuery<'i>),
}

#[derive(Clone, Debug, PartialEq)]
pub enum StyleQuery<'i> {
  Feature(crate::properties::Property<'i>),
  Not(Box<StyleQuery<'i>>),
  Operation {
    conditions: Vec<StyleQuery<'i>>,
    operator: crate::media_query::Operator,
  },
}

impl<'i> ContainerCondition<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    Self::parse_with_flags(input, options, true)
  }

  fn parse_with_flags<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions, allow_or: bool) -> ParseResult<'i, Self> {
    use crate::media_query::Operator;
    let location = input.current_source_location();
    let first_condition = Self::parse_parens_or_function(input, options)?;
    let operator = match input.try_parse(parse_operator) {
      Ok(op) => op,
      Err(..) => return Ok(first_condition),
    };

    if !allow_or && operator == Operator::Or {
      return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
    }

    let mut conditions = vec![first_condition, Self::parse_parens_or_function(input, options)?];
    loop {
      if let Ok(op) = input.try_parse(parse_operator) {
        if op != operator {
          return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
        }
        conditions.push(Self::parse_parens_or_function(input, options)?);
      } else {
        return Ok(ContainerCondition::Operation { conditions, operator });
      }
    }
  }

  fn parse_parens_or_function<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    match input.next()? {
      Token::ParenthesisBlock => input.parse_nested_block(|input| {
        if let Ok(inner) = input.try_parse(|i| Self::parse_with_flags(i, options, true)) {
          return Ok(inner);
        }
        Ok(ContainerCondition::Feature(crate::media_query::MediaFeature::parse(input, options)?))
      }),
      Token::Function(ref f) if f.eq_ignore_ascii_case("style") => {
        let query = input.parse_nested_block(|input| StyleQuery::parse(input, options))?;
        Ok(ContainerCondition::Style(query))
      }
      Token::Ident(ref ident) if ident.eq_ignore_ascii_case("not") => {
        let inner = Self::parse_parens_or_function(input, options)?;
        Ok(ContainerCondition::Not(Box::new(inner)))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }
}

fn parse_operator<'i, 't>(input: &mut Parser<'i, 't>) -> ParseResult<'i, crate::media_query::Operator> {
  let loc = input.current_source_location();
  let ident = input.expect_ident()?;
  match ident.to_ascii_lowercase().as_str() {
    "and" => Ok(crate::media_query::Operator::And),
    "or" => Ok(crate::media_query::Operator::Or),
    _ => Err(loc.new_unexpected_token_error(Token::Ident(ident))),
  }
}

impl<'i> StyleQuery<'i> {
  fn parse<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    use crate::media_query::Operator;
    let location = input.current_source_location();
    let first = Self::parse_parens(input, options)?;
    let operator = match input.try_parse(parse_operator) {
      Ok(op) => op,
      Err(..) => return Ok(first),
    };
    let mut conditions = vec![first, Self::parse_parens(input, options)?];
    loop {
      if let Ok(op) = input.try_parse(parse_operator) {
        if op != operator {
          return Err(location.new_custom_error(ParserError::InvalidMediaQuery));
        }
        conditions.push(Self::parse_parens(input, options)?);
      } else {
        let _ = Operator::And;
        return Ok(StyleQuery::Operation { conditions, operator });
      }
    }
  }

  fn parse_parens<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let location = input.current_source_location();
    match input.next()? {
      Token::ParenthesisBlock => input.parse_nested_block(|input| {
        if let Ok(inner) = input.try_parse(|i| Self::parse(i, options)) {
          return Ok(inner);
        }
        Self::parse_feature(input, options)
      }),
      Token::Ident(ref ident) if ident.eq_ignore_ascii_case("not") => {
        let inner = Self::parse_parens(input, options)?;
        Ok(StyleQuery::Not(Box::new(inner)))
      }
      t => Err(location.new_unexpected_token_error(t)),
    }
  }

  fn parse_feature<'t>(input: &mut Parser<'i, 't>, options: &ParserOptions) -> ParseResult<'i, Self> {
    let property_id = PropertyId::parse(input.expect_ident()?);
    input.expect_colon()?;
    input.skip_whitespace();
    let feature = input.parse_until_before(Delimiter::Bang, |input| crate::properties::Property::parse(property_id, input, options))?;
    let _ = input.try_parse(|input| crate::parser::parse_important(input));
    input.expect_exhausted()?;
    Ok(StyleQuery::Feature(feature))
  }
}

impl<'i> ToCss for ContainerCondition<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      ContainerCondition::Feature(f) => f.to_css(dest),
      ContainerCondition::Not(c) => {
        dest.write_str("not ")?;
        let needs_parens = !matches!(**c, ContainerCondition::Feature(_) | ContainerCondition::Style(_));
        if needs_parens {
          dest.write_char('(')?;
        }
        c.to_css(dest)?;
        if needs_parens {
          dest.write_char(')')?;
        }
        Ok(())
      }
      ContainerCondition::Operation { conditions, operator } => {
        let mut first = true;
        for condition in conditions {
          if !first {
            dest.write_char(' ')?;
            dest.write_str(match operator {
              crate::media_query::Operator::And => "and",
              crate::media_query::Operator::Or => "or",
            })?;
            dest.write_char(' ')?;
          }
          first = false;
          let needs_parens = match condition {
            ContainerCondition::Not(_) => true,
            ContainerCondition::Operation { operator: op, .. } => op != operator,
            _ => false,
          };
          if needs_parens {
            dest.write_char('(')?;
          }
          condition.to_css(dest)?;
          if needs_parens {
            dest.write_char(')')?;
          }
        }
        Ok(())
      }
      ContainerCondition::Style(query) => {
        dest.write_str("style(")?;
        query.to_css(dest)?;
        dest.write_char(')')
      }
    }
  }
}

