//! @supports and @container conditions.

use crate::error::{ParseResult, ParserError};
use crate::parser::{Delimiter, Parser};
use crate::printer::{PrintResult, Printer, ToCss};
use crate::properties::PropertyId;
use crate::tokenizer::Token;
use crate::values::token_list::ParserOptions;
use crate::vendor_prefix::VendorPrefix;
use std::borrow::Cow;

#[derive(Clone, Debug, PartialEq)]
pub enum SupportsCondition<'i> {
  Not(Box<SupportsCondition<'i>>),
  And(Vec<SupportsCondition<'i>>),
  Or(Vec<SupportsCondition<'i>>),
  Declaration { property_id: PropertyId<'i>, value: Cow<'i, str> },
  Selector(Cow<'i, str>),
  Unknown(Cow<'i, str>),
}

impl<'i> SupportsCondition<'i> {
  pub fn parse<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    if input.try_parse(|input| input.expect_ident_matching("not")).is_ok() {
      let in_parens = Self::parse_in_parens(input)?;
      return Ok(SupportsCondition::Not(Box::new(in_parens)));
    }

    let in_parens = Self::parse_in_parens(input)?;
    let mut expected_type = None;
    let mut conditions = Vec::new();
    let mut seen_declarations: Vec<(usize, PropertyId<'i>, Cow<'i, str>)> = Vec::new();

    loop {
      let condition = input.try_parse(|input| {
        let location = input.current_source_location();
        let s = input.expect_ident()?;
        let found_type = match s.to_ascii_lowercase().as_str() {
          "and" => 1,
          "or" => 2,
          _ => return Err(location.new_unexpected_token_error::<ParserError>(Token::Ident(s))),
        };

        if let Some(expected) = expected_type {
          if found_type != expected {
            return Err(location.new_unexpected_token_error(Token::Ident(s)));
          }
        } else {
          expected_type = Some(found_type);
        }

        Self::parse_in_parens(input)
      });

      if let Ok(condition) = condition {
        if conditions.is_empty() {
          conditions.push(in_parens.clone());
          if let SupportsCondition::Declaration { property_id, value } = &in_parens {
            seen_declarations.push((0, property_id.with_prefix(VendorPrefix::None), value.clone()));
          }
        }

        if let SupportsCondition::Declaration { property_id, value } = &condition {
          // Merge multiple declarations with the same property id (minus prefix) and value together.
          let property_id = property_id.with_prefix(VendorPrefix::None);
          if let Some((index, _, _)) = seen_declarations.iter().find(|(_, id, v)| *id == property_id && v == value) {
            let index = *index;
            if let SupportsCondition::Declaration { property_id: cur_id, .. } = &mut conditions[index] {
              *cur_id = cur_id.with_prefix(VendorPrefix::None);
            }
            continue;
          }
          seen_declarations.push((conditions.len(), property_id, value.clone()));
        }

        conditions.push(condition)
      } else {
        break;
      }
    }

    match expected_type {
      Some(1) => {
        if conditions.len() == 1 {
          Ok(conditions.pop().unwrap())
        } else {
          Ok(SupportsCondition::And(conditions))
        }
      }
      Some(2) => {
        if conditions.len() == 1 {
          Ok(conditions.pop().unwrap())
        } else {
          Ok(SupportsCondition::Or(conditions))
        }
      }
      _ => Ok(in_parens),
    }
  }

  fn parse_in_parens<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    input.skip_whitespace();
    let location = input.current_source_location();
    let pos = input.position();
    match input.next()? {
      Token::Function(ref f) => {
        match f.to_ascii_lowercase().as_str() {
          "selector" => {
            let res = input.try_parse(|input| {
              input.parse_nested_block(|input| {
                let pos = input.position();
                input.expect_no_error_token()?;
                Ok::<_, crate::parser::ParseError<ParserError>>(SupportsCondition::Selector(Cow::Borrowed(input.slice_from(pos))))
              })
            });
            if res.is_ok() {
              return res;
            }
          }
          _ => {}
        }
      }
      Token::ParenthesisBlock => {
        let res = input.try_parse(|input| {
          input.parse_nested_block(|input| {
            if let Ok(condition) = input.try_parse(SupportsCondition::parse) {
              return Ok(condition);
            }

            Self::parse_declaration(input)
          })
        });
        if res.is_ok() {
          return res;
        }
      }
      t => return Err(location.new_unexpected_token_error(t)),
    };

    input.parse_nested_block(|input| input.expect_no_error_token().map_err(|err| err.into()))?;
    Ok(SupportsCondition::Unknown(Cow::Borrowed(input.slice_from(pos))))
  }

  pub fn parse_declaration<'t>(input: &mut Parser<'i, 't>) -> ParseResult<'i, Self> {
    let property_id = PropertyId::parse(input.expect_ident()?);
    input.expect_colon()?;
    input.skip_whitespace();
    let pos = input.position();
    input.expect_no_error_token()?;
    Ok(SupportsCondition::Declaration {
      property_id,
      value: Cow::Borrowed(input.slice_from(pos).trim_end()),
    })
  }

  fn needs_parens(&self, parent: &SupportsCondition) -> bool {
    match self {
      SupportsCondition::Not(_) => true,
      SupportsCondition::And(_) => !matches!(parent, SupportsCondition::And(_)),
      SupportsCondition::Or(_) => !matches!(parent, SupportsCondition::Or(_)),
      _ => false,
    }
  }

  fn to_css_with_parens_if_needed(&self, dest: &mut Printer, needs_parens: bool) -> PrintResult {
    if needs_parens {
      dest.write_char('(')?;
    }
    self.to_css(dest)?;
    if needs_parens {
      dest.write_char(')')?;
    }
    Ok(())
  }
}

impl<'i> ToCss for SupportsCondition<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      SupportsCondition::Not(condition) => {
        dest.write_str("not ")?;
        condition.to_css_with_parens_if_needed(dest, condition.needs_parens(self))
      }
      SupportsCondition::And(conditions) => {
        let mut first = true;
        for condition in conditions {
          if first {
            first = false;
          } else {
            dest.write_str(" and ")?;
          }
          condition.to_css_with_parens_if_needed(dest, condition.needs_parens(self))?;
        }
        Ok(())
      }
      SupportsCondition::Or(conditions) => {
        let mut first = true;
        for condition in conditions {
          if first {
            first = false;
          } else {
            dest.write_str(" or ")?;
          }
          condition.to_css_with_parens_if_needed(dest, condition.needs_parens(self))?;
        }
        Ok(())
      }
      SupportsCondition::Declaration { property_id, value } => {
        dest.write_char('(')?;

        let prefix = property_id.prefix().or_none();
        if prefix != VendorPrefix::None {
          dest.write_char('(')?;
        }

        let name = property_id.name();
        let mut first = true;
        for p in prefix.iter() {
          if first {
            first = false;
          } else {
            dest.write_str(") or (")?;
          }

          p.to_css(dest)?;
          dest.write_str(name)?;
          dest.delim(':', false)?;
          dest.write_str(value)?;
        }

        if prefix != VendorPrefix::None {
          dest.write_char(')')?;
        }
        dest.write_char(')')
      }
      SupportsCondition::Selector(sel) => {
        dest.write_str("selector(")?;
        dest.write_str(sel)?;
        dest.write_char(')')
      }
      SupportsCondition::Unknown(unknown) => dest.write_str(unknown),
    }
  }
}

