        query.to_css(dest)?;
        dest.write_char(')')
      }
    }
  }
}

impl<'i> ToCss for StyleQuery<'i> {
  fn to_css(&self, dest: &mut Printer) -> PrintResult {
    match self {
      StyleQuery::Feature(p) => p.to_css(dest, false),
      StyleQuery::Not(c) => {
        dest.write_str("not ")?;
        let needs_parens = !matches!(**c, StyleQuery::Feature(_));
        if needs_parens {
          dest.write_char('(')?;
        }
        c.to_css(dest)?;
        if needs_parens {
          dest.write_char(')')?;
        }
        Ok(())
      }
      StyleQuery::Operation { conditions, operator } => {
        let mut first = true;
        for condition in conditions {
          if !first {
            dest.write_char(' ')?;
            dest.write_str(match operator {
              crate::media_query::Operator::And => "and",
              crate::media_query::Operator::Or => "or",
            })?;
            dest.write_char(' ')?;
          }
          first = false;
          let needs_parens = match condition {
            StyleQuery::Not(_) => true,
            StyleQuery::Operation { operator: op, .. } => op != operator,
            StyleQuery::Feature(_) => true,
          };
          if needs_parens {
            dest.write_char('(')?;
          }
          condition.to_css(dest)?;
          if needs_parens {
            dest.write_char(')')?;
          }
        }
        Ok(())
      }
    }
  }
}
