//! Minimal source map generation.

use crate::rules::Location;

pub struct SourceMapBuilder {
  pub mappings: Vec<(u32, u32, u32, u32)>, // generated line, generated col, source line, source col
}

impl SourceMapBuilder {
  pub fn new() -> Self {
    SourceMapBuilder { mappings: Vec::new() }
  }

  pub fn add_mapping(&mut self, line: u32, col: u32, loc: Location) {
    self.mappings.push((line, col, loc.line, loc.column.saturating_sub(1)));
  }

  pub fn to_json(&self, sources: &[String], contents: &[String]) -> String {
    let mut out = String::new();
    out.push_str("{\"version\":3,\"mappings\":\"");
    out.push_str(&self.encode_mappings());
    out.push_str("\",\"sources\":[");
    for (i, s) in sources.iter().enumerate() {
      if i > 0 {
        out.push(',');
      }
      out.push_str(&json_string(s));
    }
    out.push_str("],\"sourcesContent\":[");
    for (i, s) in contents.iter().enumerate() {
      if i > 0 {
        out.push(',');
      }
      out.push_str(&json_string(s));
    }
    out.push_str("],\"names\":[]}");
    out
  }

  fn encode_mappings(&self) -> String {
    let mut out = String::new();
    let mut prev_gen_line = 0u32;
    let mut prev_gen_col = 0i64;
    let mut prev_src_line = 0i64;
    let mut prev_src_col = 0i64;
    let mut first_in_line = true;
    let mut sorted = self.mappings.clone();
    sorted.sort_by_key(|m| (m.0, m.1));
    sorted.dedup_by_key(|m| (m.0, m.1));
    for (gen_line, gen_col, src_line, src_col) in sorted {
      while prev_gen_line < gen_line {
        out.push(';');
        prev_gen_line += 1;
        prev_gen_col = 0;
        first_in_line = true;
      }
      if !first_in_line {
        out.push(',');
      }
      first_in_line = false;
      vlq(&mut out, gen_col as i64 - prev_gen_col);
      prev_gen_col = gen_col as i64;
      vlq(&mut out, 0);
      vlq(&mut out, src_line as i64 - prev_src_line);
      prev_src_line = src_line as i64;
      vlq(&mut out, src_col as i64 - prev_src_col);
      prev_src_col = src_col as i64;
    }
    out
  }
}

fn vlq(out: &mut String, value: i64) {
  const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let mut v = if value < 0 { ((-value) << 1) | 1 } else { value << 1 } as u64;
  loop {
    let mut digit = (v & 31) as u8;
    v >>= 5;
    if v > 0 {
      digit |= 32;
    }
    out.push(CHARS[digit as usize] as char);
    if v == 0 {
      break;
    }
  }
}

pub fn json_string(s: &str) -> String {
  let mut out = String::from("\"");
  for c in s.chars() {
    match c {
      '"' => out.push_str("\\\""),
      '\\' => out.push_str("\\\\"),
      '\n' => out.push_str("\\n"),
      '\r' => out.push_str("\\r"),
      '\t' => out.push_str("\\t"),
      '\u{08}' => out.push_str("\\b"),
      '\u{0c}' => out.push_str("\\f"),
      c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
      c => out.push(c),
    }
  }
  out.push('"');
  out
}
