fn parse_args() -> CliArgs {
  let mut args = CliArgs::default();
  let argv: Vec<String> = std::env::args().skip(1).collect();
  let mut i = 0;
  let mut only_positional = false;
  let mut provided: Vec<&'static str> = Vec::new();
  while i < argv.len() {
    let arg = &argv[i];
    if only_positional || !arg.starts_with('-') || arg == "-" {
      args.input_files.push(arg.clone());
      i += 1;
      continue;
    }
    if arg == "--" {
      only_positional = true;
      i += 1;
      continue;
    }
    let (name, inline_value) = if arg.starts_with("--") {
      match arg.find('=') {
        Some(idx) => (arg[..idx].to_string(), Some(arg[idx + 1..].to_string())),
        None => (arg.clone(), None),
      }
    } else {
      (arg.clone(), None)
    };
    macro_rules! value {
      ($display: expr) => {{
        if let Some(v) = inline_value.clone() {
          v
        } else {
          i += 1;
          if i >= argv.len() {
            clap_error(&format!("The argument '{}' requires a value but none was supplied", $display), false);
          }
          argv[i].clone()
        }
      }};
    }
    match name.as_str() {
      "-h" | "--help" => {
        print!("{}", HELP);
        std::process::exit(0);
      }
      "-V" | "--version" => {
        println!("lightningcss 1.0.0-alpha.70");
        std::process::exit(0);
      }
      "-m" | "--minify" => {
        args.minify = true;
        provided.push("--minify");
      }
      "--nesting" => args.nesting = true,
      "--custom-media" => args.custom_media = true,
      "--css-modules-dashed-idents" => args.css_modules_dashed_idents = true,
      "--sourcemap" => {
        args.sourcemap = true;
        provided.push("--sourcemap");
      }
      "--browserslist" => args.browserslist = true,
      "--error-recovery" => args.error_recovery = true,
      "--bundle" => args.bundle = true,
      "--css-modules" => {
        if let Some(v) = inline_value.clone() {
          args.css_modules = Some(Some(v));
        } else if i + 1 < argv.len() && !argv[i + 1].starts_with('-') {
          i += 1;
          args.css_modules = Some(Some(argv[i].clone()));
        } else {
          args.css_modules = Some(None);
        }
      }
      "--css-modules-pattern" => {
        let v = value!("--css-modules-pattern <CSS_MODULES_PATTERN>");
        args.css_modules_pattern = Some(v);
      }
      "-o" | "--output-file" => {
        let v = value!("--output-file <OUTPUT_FILE>");
        args.output_file = Some(v);
      }
      "-d" | "--output-dir" => {
        let v = value!("--output-dir <OUTPUT_DIR>");
        args.output_dir = Some(v);
      }
      "-t" | "--targets" => {
        let v = value!("--targets <TARGETS>");
        args.targets.push(v);
      }
      _ => {
        // Combined short flags like -mo?
        if !arg.starts_with("--") && arg.len() > 2 {
          let chars: Vec<char> = arg[1..].chars().collect();
          let mut ok = true;
          for c in &chars {
            if !matches!(c, 'm' | 'h' | 'V') {
              ok = false;
            }
          }
          if ok {
            for c in chars {
              match c {
                'm' => args.minify = true,
                'h' => {
                  print!("{}", HELP);
                  std::process::exit(0);
                }
                'V' => {
                  println!("lightningcss 1.0.0-alpha.70");
                  std::process::exit(0);
                }
                _ => {}
              }
            }
            i += 1;
            continue;
          }
        }
        eprintln!(
          "error: Found argument '{}' which wasn't expected, or isn't valid in this context",
          arg
        );
        eprintln!();
        eprintln!("\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`", arg, arg);
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable [OPTIONS] [INPUT_FILE]...");
        eprintln!();
        eprintln!("For more information try --help");
        std::process::exit(2);
      }
    }
    i += 1;
  }

  if args.sourcemap && args.output_file.is_none() && args.output_dir.is_none() {
    eprintln!("error: The following required arguments were not provided:");
    eprintln!("    <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>");
    eprintln!();
    eprintln!("USAGE:");
    let mut usage = String::from("    executable");
    for p in &provided {
      usage.push(' ');
      usage.push_str(p);
    }
    usage.push_str(" <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>> <INPUT_FILE>...");
    eprintln!("{}", usage);
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
  }

  args
}

struct SourceFile {
  source: String,
  filename: String,
}

fn main() -> Result<(), std::io::Error> {
  let cli_args = parse_args();

  let sources = if cli_args.input_files.is_empty() {
    let mut source = String::new();
    std::io::stdin().read_to_string(&mut source)?;
    vec![SourceFile {
      source,
      filename: format!("stdin-{}", std::process::id()),
    }]
  } else {
    let mut v = Vec::new();
    for f in &cli_args.input_files {
      let source = std::fs::read_to_string(f)?;
      v.push(SourceFile {
        source,
        filename: f.clone(),
      });
    }
    v
  };

  if sources.len() > 1 {
    if cli_args.output_dir.is_none() {
      if cli_args.output_file.is_some() {
        eprintln!("Cannot use the --output-file option with multiple inputs. Use --output-dir instead.");
      } else {
        eprintln!("Cannot output to stdout with multiple inputs. Use --output-dir instead.");
      }
      std::process::exit(1);
    }
  }

  let targets = if cli_args.browserslist {
    // Browserslist config discovery is not supported; use defaults query.
    Some(browserslist::resolve(&["defaults".to_string()]).unwrap())
  } else if !cli_args.targets.is_empty() {
    let res = browserslist::resolve(&cli_args.targets);
    Some(match res {
      Ok(t) => t,
      Err(e) => {
        // Mirror the original panic location.
        panic_at_191(e);
      }
    })
  } else {
    None
  };
  let targets = targets::Targets::new(targets);

  for source in &sources {
    let options = values::token_list::ParserOptions {
      error_recovery: cli_args.error_recovery,
      custom_media: cli_args.custom_media,
      css_modules: cli_args.css_modules.is_some(),
    };
    let filename = source.filename.clone();
    let res = stylesheet::StyleSheet::parse(&source.source, &filename, &options);
    let mut stylesheet = match res {
      Ok(s) => s,
      Err(e) => panic_at_187(e),
    };

    for warning in &stylesheet.warnings {
      eprintln!("{}", warning);
    }

    stylesheet.minify(targets);

    let mut source_map = if cli_args.sourcemap {
      Some(sourcemap::SourceMapBuilder::new())
    } else {
      None
    };

    let mut css_module = cli_args.css_modules.as_ref().map(|_| css_modules::CssModule {
      config: css_modules::Config {
        custom_idents: true,
        dashed_idents: cli_args.css_modules_dashed_idents,
        pattern: cli_args.css_modules_pattern.clone(),
      },
      hash: css_modules::hash_filename(&filename),
      exports: Vec::new(),
    });

    let mut code = match stylesheet.to_css(cli_args.minify, targets, source_map.as_mut(), css_module.as_mut()) {
      Ok(c) => c,
      Err(e) => {
        eprintln!("{:?}", e);
        std::process::exit(1);
      }
    };

    let output_path = if let Some(dir) = &cli_args.output_dir {
      let name = Path::new(&source.filename).file_name().map(|n| n.to_os_string()).unwrap_or_default();
      Some(PathBuf::from(dir).join(name))
    } else {
      cli_args.output_file.as_ref().map(PathBuf::from)
    };

    if let Some(map) = &source_map {
      if let Some(path) = &output_path {
        let map_path = format!("{}.map", path.to_string_lossy());
        let json = map.to_json(&[source.filename.clone()], &[source.source.clone()]);
        code.push_str(&format!("\n/*# sourceMappingURL={} */\n", map_path));
        std::fs::write(&map_path, json)?;
      }
    }

    if let Some(path) = output_path {
      if let Some(cm) = &css_module {
        let json_path = match &cli_args.css_modules {
          Some(Some(p)) => PathBuf::from(p),
          _ => PathBuf::from(format!("{}.json", path.to_string_lossy())),
        };
        std::fs::write(json_path, css_modules::exports_json(cm))?;
      }
      std::fs::write(&path, code)?;
    } else if let Some(cm) = &css_module {
      println!("{{\"code\":{},\"exports\":{}}}", sourcemap::json_string(&code), css_modules::exports_json(cm));
    } else {
      let stdout = std::io::stdout();
      let mut lock = stdout.lock();
      let _ = lock.write_all(code.as_bytes());
      let _ = lock.write_all(b"\n");
    }
  }

  Ok(())
}

#[inline(never)]
fn panic_at_187(e: error::Error<error::ParserError>) -> ! {
  // The original binary panics here with `.unwrap()` on the parse result.
  let msg = format!("called `Result::unwrap()` on an `Err` value: {:?}", e);
  crate::panic_with_location(&msg, "src/main.rs", 187, 45);
}

#[inline(never)]
fn panic_at_191(e: String) -> ! {
  let msg = format!("called `Result::unwrap()` on an `Err` value: {}", e);
  crate::panic_with_location(&msg, "src/main.rs", 191, 56);
}

pub fn panic_with_location(msg: &str, file: &str, line: u32, col: u32) -> ! {
  let tid = std::process::id();
  eprintln!();
  eprintln!("thread 'main' ({}) panicked at {}:{}:{}:", tid, file, line, col);
  eprintln!("{}", msg);
  eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
  std::process::abort();
}
