pub fn hash_filename(filename: &str) -> String {
  use std::hash::{Hash, Hasher};
  let mut hasher = std::collections::hash_map::DefaultHasher::new();
  filename.hash(&mut hasher);
  let v = hasher.finish() as u32;
  let bytes = v.to_le_bytes();
  const ALPHA: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  let mut out = String::new();
  let n = ((bytes[0] as u32) << 16) | ((bytes[1] as u32) << 8) | bytes[2] as u32;
  out.push(ALPHA[((n >> 18) & 63) as usize] as char);
  out.push(ALPHA[((n >> 12) & 63) as usize] as char);
  out.push(ALPHA[((n >> 6) & 63) as usize] as char);
  out.push(ALPHA[(n & 63) as usize] as char);
  let n = (bytes[3] as u32) << 16;
  out.push(ALPHA[((n >> 18) & 63) as usize] as char);
  out.push(ALPHA[((n >> 12) & 63) as usize] as char);
  out
}

pub fn exports_json(cm: &CssModule) -> String {
  let mut exports = cm.exports.clone();
  exports.sort_by(|a, b| a.0.cmp(&b.0));
  let mut out = String::from("{");
  for (i, (k, v)) in exports.iter().enumerate() {
    if i > 0 {
      out.push(',');
    }
    out.push_str(&crate::sourcemap::json_string(k));
    out.push_str(":{\"composes\":[],\"isReferenced\":false,\"name\":");
    out.push_str(&crate::sourcemap::json_string(v));
    out.push('}');
  }
  out.push('}');
  out
}
