//! Minimal browserslist query resolution.

use crate::targets::{version, Browsers};

/// Resolves browserslist queries into browser targets.
pub fn resolve(queries: &[String]) -> Result<Browsers, String> {
  let mut browsers = Browsers::default();
  let mut any = false;
  for query in queries {
    for q in query.split(',') {
      let q = q.trim();
      if q.is_empty() {
        continue;
      }
      let lower = q.to_ascii_lowercase();
      if lower == "defaults" {
        // Approximation of browserslist defaults (> 0.5%, last 2 versions, Firefox ESR, not dead).
        set_min(&mut browsers.chrome, version(109, 0, 0));
        set_min(&mut browsers.edge, version(126, 0, 0));
        set_min(&mut browsers.firefox, version(115, 0, 0));
        set_min(&mut browsers.safari, version(16, 6, 0));
        set_min(&mut browsers.ios_saf, version(16, 6, 0));
        set_min(&mut browsers.opera, version(109, 0, 0));
        set_min(&mut browsers.android, version(126, 0, 0));
        set_min(&mut browsers.samsung, version(24, 0, 0));
        any = true;
        continue;
      }
      let mut parts = lower.split_whitespace();
      let name = parts.next().ok_or_else(|| "Nom(\"\")".to_string())?;
      let ver = parts.next();
      let (name, ver) = match (name, ver) {
        (n, Some(v)) => (n, v),
        _ => return Err("Nom(\"\")".to_string()),
      };
      let v = parse_version(ver).ok_or_else(|| "Nom(\"\")".to_string())?;
      let slot = match name {
        "chrome" | "and_chr" | "chromeandroid" => &mut browsers.chrome,
        "edge" => &mut browsers.edge,
        "firefox" | "ff" | "and_ff" => &mut browsers.firefox,
        "ie" | "ie_mob" => &mut browsers.ie,
        "ios_saf" | "ios" => &mut browsers.ios_saf,
        "opera" | "op_mob" => &mut browsers.opera,
        "safari" => &mut browsers.safari,
        "samsung" => &mut browsers.samsung,
        "android" => &mut browsers.android,
        _ => return Err("Nom(\"\")".to_string()),
      };
      set_min(slot, v);
      any = true;
    }
  }
  if !any {
    return Err("Nom(\"\")".to_string());
  }
  Ok(browsers)
}

fn set_min(slot: &mut Option<u32>, v: u32) {
  match slot {
    Some(existing) if *existing <= v => {}
    _ => *slot = Some(v),
  }
}

fn parse_version(s: &str) -> Option<u32> {
  let s = s.split('-').next().unwrap_or(s);
  let mut parts = s.split('.');
  let major: u32 = parts.next()?.parse().ok()?;
  let minor: u32 = parts.next().map(|p| p.parse().unwrap_or(0)).unwrap_or(0);
  let patch: u32 = parts.next().map(|p| p.parse().unwrap_or(0)).unwrap_or(0);
  Some(version(major, minor, patch))
}
