#!/bin/bash
# Compare all corpus files, print summary of diff line counts
cd /tmp/corpus
total=0; fail=0
for f in *.css; do
  for mode in "" "-m"; do
    total=$((total+1))
    exp=$(timeout 10 /workspace/.orig/executable "$f" $mode 2>&1; echo "exit=$?")
    act=$(timeout 10 /workspace/executable "$f" $mode 2>&1; echo "exit=$?")
    if [ "$exp" != "$act" ]; then
      fail=$((fail+1))
      n=$(diff <(echo "$exp") <(echo "$act") | grep -c '^[<>]')
      echo "DIFF $f $mode: $n lines"
    fi
  done
done
echo "total=$total fail=$fail"
EOF
