            if self.category.is_some() && self.category != Some(Category::Logical) {
              self.flush(dest, context);
            }
            self.$key = Some(Slot::Typed($val.clone()));
            self.category = Some(Category::Logical);
            self.has_any = true;
          }};
        }
        macro_rules! logical_unparsed {
          ($key: ident) => {{
            if self.category.is_some() && self.category != Some(Category::Logical) {
              self.flush(dest, context);
            }
            if self.$key.is_some() {
              self.flush(dest, context);
            }
            self.$key = Some(Slot::Unparsed(property.clone()));
            self.category = Some(Category::Logical);
            self.has_any = true;
          }};
        }

        match property {
          $top(val) => prop!(top, val, Category::Physical),
          $bottom(val) => prop!(bottom, val, Category::Physical),
          $left(val) => prop!(left, val, Category::Physical),
          $right(val) => prop!(right, val, Category::Physical),
          $block_start(val) => logical!(block_start, val),
          $block_end(val) => logical!(block_end, val),
          $inline_start(val) => logical!(inline_start, val),
          $inline_end(val) => logical!(inline_end, val),
          $block(val) => {
