            dest.push(Property::$bottom(val));
          }
          if let Some(val) = left {
            dest.push(Property::$left(val));
          }
          if let Some(val) = right {
            dest.push(Property::$right(val));
          }
        }

        macro_rules! logical_out {
          ($start: expr, $end: expr, $short: ident, $start_prop: ident, $end_prop: ident) => {
            match (&$start, &$end) {
              (Some(Slot::Typed(a)), Some(Slot::Typed(b))) => {
