/// A list of (value, prefix) entries where equal values merge their prefixes.
struct PrefixedEntries<T> {
  entries: Vec<(T, VendorPrefix)>,
}

impl<T: PartialEq + Clone> Default for PrefixedEntries<T> {
  fn default() -> Self {
    PrefixedEntries { entries: Vec::new() }
  }
}

impl<T: PartialEq + Clone> PrefixedEntries<T> {
  fn set(&mut self, val: &T, vp: VendorPrefix) {
    if let Some((_, prefix)) = self.entries.iter_mut().find(|(v, _)| v == val) {
      *prefix |= vp;
      return;
    }
    // Replace an entry with a prefix that already includes this prefix.
    if let Some(entry) = self.entries.iter_mut().find(|(_, p)| p.contains(vp)) {
      if entry.1 == vp {
        entry.0 = val.clone();
        return;
      }
    }
    self.entries.push((val.clone(), vp));
  }

  fn is_empty(&self) -> bool {
    self.entries.is_empty()
  }

  fn take(&mut self) -> Vec<(T, VendorPrefix)> {
    std::mem::take(&mut self.entries)
  }

  /// Returns the single unprefixed value if that's all there is.
